// ============================================================================
// Types & Interfaces
// ============================================================================

export interface LineChartDataPoint {
  x: string | number | Date
  y: number
  [key: string]: unknown
}

export interface LineChartSeries {
  name: string
  data: LineChartDataPoint[]
  color?: string
  strokeWidth?: number
  strokeDasharray?: string
  showDots?: boolean
  dotSize?: number
}

export interface LineChartProps extends BaseChartProps {
  /** Data series to display */
  data: LineChartSeries[]
  /** X-axis label */
  xAxisLabel?: string
  /** Y-axis label */
  yAxisLabel?: string
  /** Line curve interpolation */
  curve?: "linear" | "monotone" | "cardinal" | "step" | "natural" | "basis"
  /** Show data points */
  showDots?: boolean
  /** Dot radius */
  dotSize?: number
  /** Line stroke width */
  strokeWidth?: number
  /** X-axis data type */
  xType?: "category" | "number" | "time"
  /** Chart variant */
  variant?: "default" | "smooth" | "multi" | "stock" | "sparkline"
  /** Show area fill under lines */
  showArea?: boolean
  /** Area fill opacity */
  areaOpacity?: number
  /** Show crosshair on hover */
  showCrosshair?: boolean
  /** Y-axis value formatter */
  yAxisFormatter?: (value: number) => string
  /** Chart title (for stock variant) */
  title?: string
  /** Chart subtitle */
  subtitle?: string
  /** Line color (for single series) */
  color?: string
  /** Animate on load */
  animate?: boolean
  /** Show data labels on dots */
  showDataLabels?: boolean
  /** Show Y axis */
  showYAxis?: boolean
}

// ============================================================================
// Constants
// ============================================================================

const curveMap = {
  linear: curveLinear,
  monotone: curveMonotoneX,
  cardinal: curveCardinal,
  step: curveStep,
  natural: curveNatural,
  basis: curveBasis,
}

// Default colors for multi-line variant — a validated categorical palette
// (fixed hue order, never cycled) exposed as theme-aware CSS variables so
// light/dark each get surface-tuned steps. See --chart-series-* in globals.css.
const MULTI_LINE_COLORS = [
  "var(--chart-series-1)",
  "var(--chart-series-2)",
  "var(--chart-series-3)",
  "var(--chart-series-4)",
  "var(--chart-series-5)",
  "var(--chart-series-6)",
  "var(--chart-series-7)",
  "var(--chart-series-8)",
]

// ============================================================================
// Helper Functions
// ============================================================================

function formatDateAxis(date: Date): string {
  const months = [
    "Jan",
    "Feb",
    "Mar",
    "Apr",
    "May",
    "Jun",
    "Jul",
    "Aug",
    "Sep",
    "Oct",
    "Nov",
    "Dec",
  ]
  return `${months[date.getMonth()]} ${date.getDate()}`
}

function defaultYFormatter(value: number): string {
  if (value >= 1000000) return `${(value / 1000000).toFixed(1)}M`
  if (value >= 1000) return `${(value / 1000).toFixed(1)}K`
  return value.toFixed(0)
}

// ============================================================================
// Component
// ============================================================================

export function LineChart({
  data,
  config,
  className,
  width = 600,
  height = 400,
  margin: marginProp,
  showGrid: showGridProp,
  showTooltip = true,
  showLegend: showLegendProp,
  legendPosition = "right",
  xAxisLabel,
  yAxisLabel,
  curve: curveProp,
  showDots: showDotsProp,
  dotSize = 4,
  strokeWidth: strokeWidthProp,
  xType = "category",
  variant = "default",
  showArea: showAreaProp,
  areaOpacity = 0.15,
  showCrosshair: showCrosshairProp,
  yAxisFormatter,
  title,
  subtitle,
  color,
  animate = false,
  showDataLabels: showDataLabelsProp,
  showYAxis: showYAxisProp,
}: LineChartProps) {
  const svgRef = React.useRef<SVGSVGElement>(null)
  const [hoveredPoint, setHoveredPoint] = React.useState<{
    seriesIndex: number
    pointIndex: number
    point: LineChartDataPoint
    x: number
    y: number
  } | null>(null)
  // Legend highlight: click a series to emphasize it (others fade but stay
  // drawn), hover to preview — Plotly-style. `focused` = hover ?? selection.
  const highlight = useSeriesHighlight()
  const [crosshairX, setCrosshairX] = React.useState<number | null>(null)
  const [zoomDomain, setZoomDomain] = React.useState<[number, number] | null>(
    null
  )
  const isZoomed = zoomDomain !== null

  // Variant-specific defaults
  const getVariantDefaults = () => {
    switch (variant) {
      case "smooth":
        return {
          curve: "natural" as const,
          showDots: false,
          strokeWidth: 2,
          showArea: false,
          showLegend: false,
          showGrid: false,
          showCrosshair: true,
          showDataLabels: false,
          showYAxis: false,
          margin: { top: 20, right: 20, bottom: 40, left: 20 },
        }
      case "multi":
        return {
          curve: "monotone" as const,
          showDots: false,
          strokeWidth: 2,
          showArea: false,
          showLegend: true,
          showGrid: true,
          showCrosshair: true,
          showDataLabels: false,
          showYAxis: true,
          margin: { top: 20, right: 20, bottom: 40, left: 60 },
        }
      case "stock":
        return {
          curve: "linear" as const,
          showDots: false,
          strokeWidth: 1.5,
          showArea: false,
          showLegend: false,
          showGrid: true,
          showCrosshair: true,
          showDataLabels: false,
          showYAxis: true,
          margin: { top: 60, right: 20, bottom: 50, left: 70 },
        }
      case "sparkline":
        return {
          curve: "monotone" as const,
          showDots: false,
          strokeWidth: 1.5,
          showArea: true,
          showLegend: false,
          showGrid: false,
          showTooltip: false,
          showDataLabels: false,
          showYAxis: false,
          margin: { top: 5, right: 5, bottom: 5, left: 5 },
        }
      default:
        return {
          curve: "natural" as const,
          showDots: true,
          strokeWidth: 2,
          showArea: false,
          showLegend: false,
          showGrid: false,
          showCrosshair: false,
          showDataLabels: true,
          showYAxis: false,
          margin: { top: 40, right: 30, bottom: 50, left: 30 },
        }
    }
  }

  const defaults = getVariantDefaults()
  const margin = marginProp ?? defaults.margin
  const showDots = showDotsProp ?? defaults.showDots
  const strokeWidth = strokeWidthProp ?? defaults.strokeWidth
  const curve = curveProp ?? defaults.curve
  const showArea = showAreaProp ?? defaults.showArea
  const showGrid = showGridProp ?? defaults.showGrid
  const showLegend = showLegendProp ?? defaults.showLegend
  const showCrosshair = showCrosshairProp ?? defaults.showCrosshair
  const showDataLabels = showDataLabelsProp ?? defaults.showDataLabels
  const showYAxis = showYAxisProp ?? defaults.showYAxis

  const innerWidth = width - margin.left - margin.right
  const innerHeight = height - margin.top - margin.bottom

  // Full (unzoomed) points establish the stable category order and index
  // range that drag-to-zoom windows are computed against.
  const fullPoints = data.flatMap((series) => series.data)
  const fullCategories = React.useMemo(
    () => [...new Set(fullPoints.map((d) => String(d.x)))],
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [data]
  )

  // Apply the active zoom window (if any) by filtering each series down
  // to the selected x-range — for xType="category" the range is a pair of
  // indices into `fullCategories`, otherwise it's raw x values.
  const plotData = React.useMemo((): LineChartSeries[] => {
    if (!zoomDomain) return data
    const [lo, hi] = zoomDomain
    if (xType === "category") {
      const selected = new Set(fullCategories.slice(lo, hi + 1))
      return data.map((series) => ({
        ...series,
        data: series.data.filter((d) => selected.has(String(d.x))),
      }))
    }
    return data.map((series) => ({
      ...series,
      data: series.data.filter((d) => {
        const v =
          xType === "time"
            ? new Date(d.x as string | Date).getTime()
            : (d.x as number)
        return v >= lo && v <= hi
      }),
    }))
  }, [data, zoomDomain, xType, fullCategories])

  // Flatten currently-visible data points for scales
  const allPoints = plotData.flatMap((series) => series.data)

  // X Scale
  const xScale = React.useMemo(() => {
    if (xType === "number") {
      const xValues = allPoints.map((d) => d.x as number)
      return scaleLinear()
        .domain([Math.min(...xValues), Math.max(...xValues)])
        .range([0, innerWidth])
    }
    if (xType === "time") {
      const xValues = allPoints.map((d) =>
        new Date(d.x as string | Date).getTime()
      )
      return scaleTime()
        .domain([
          new Date(Math.min(...xValues)),
          new Date(Math.max(...xValues)),
        ])
        .range([0, innerWidth])
    }
    // Category
    const categories = zoomDomain
      ? fullCategories.slice(zoomDomain[0], zoomDomain[1] + 1)
      : fullCategories
    return scaleBand().domain(categories).range([0, innerWidth]).padding(0)
  }, [allPoints, innerWidth, xType, zoomDomain, fullCategories])

  // Y Scale
  const yScale = React.useMemo(() => {
    const yValues = allPoints.map((d) => d.y)
    const yMin = Math.min(...yValues)
    const yMax = Math.max(...yValues)
    const padding = (yMax - yMin) * 0.1

    // For stock variant, don't include 0 in domain
    if (variant === "stock" || variant === "sparkline") {
      return scaleLinear()
        .domain([yMin - padding, yMax + padding])
        .range([innerHeight, 0])
        .nice()
    }

    return scaleLinear()
      .domain([Math.min(0, yMin - padding), yMax + padding])
      .range([innerHeight, 0])
      .nice()
  }, [allPoints, innerHeight, variant])

  // Get X position
  const getX = (point: LineChartDataPoint): number => {
    if (xType === "number") {
      return (xScale as ReturnType<typeof scaleLinear<number, number>>)(
        point.x as number
      ) as number
    }
    if (xType === "time") {
      return (xScale as ReturnType<typeof scaleTime<number, number>>)(
        new Date(point.x as string | Date)
      ) as number
    }
    const bandScale = xScale as ReturnType<typeof scaleBand<string>>
    return (bandScale(String(point.x)) ?? 0) + bandScale.bandwidth() / 2
  }

  // Drag-to-zoom: converts the pixel drag range into a data-domain range
  // and narrows the view to it. Re-zooming while already zoomed narrows
  // further (inverted against the current, already-zoomed scale).
  const zoom = useChartZoom({
    svgRef,
    marginLeft: margin.left,
    innerWidth,
    disabled: variant === "sparkline",
    onZoom: ({ x0, x1 }) => {
      if (xType === "category") {
        const [start, end] = getBandScaleIndexRange(
          xScale as ReturnType<typeof scaleBand<string>>,
          x0,
          x1
        )
        const currentOffset = zoomDomain ? zoomDomain[0] : 0
        setZoomDomain([currentOffset + start, currentOffset + end])
        return
      }
      const scale = xScale as ReturnType<
        typeof scaleLinear<number, number> | typeof scaleTime<number, number>
      >
      const lo = scale.invert(x0)
      const hi = scale.invert(x1)
      const loVal = lo instanceof Date ? lo.getTime() : (lo as number)
      const hiVal = hi instanceof Date ? hi.getTime() : (hi as number)
      const hasPointsInRange = allPoints.some((d) => {
        const v =
          xType === "time"
            ? new Date(d.x as string | Date).getTime()
            : (d.x as number)
        return v >= loVal && v <= hiVal
      })
      if (hasPointsInRange) setZoomDomain([loVal, hiVal])
    },
    onReset: () => setZoomDomain(null),
  })

  // Generate line path
  const lineFn = line<LineChartDataPoint>()
    .x((d) => getX(d))
    .y((d) => yScale(d.y))
    .curve(curveMap[curve])

  // Generate area path
  const areaFn = area<LineChartDataPoint>()
    .x((d) => getX(d))
    .y0(innerHeight)
    .y1((d) => yScale(d.y))
    .curve(curveMap[curve])

  // Get series color
  const getSeriesColor = (series: LineChartSeries, index: number): string => {
    if (series.color) return series.color
    if (color && data.length === 1) return color
    const configColor = config?.[series.name]?.color
    if (configColor) return configColor
    if (variant === "smooth") return "var(--chart-3)"
    return MULTI_LINE_COLORS[index % MULTI_LINE_COLORS.length]
  }

  // Legend items
  const legendItems: LegendItem[] = data.map((series, i) => ({
    name: series.name,
    color: getSeriesColor(series, i),
  }))

  // Y-axis formatter
  const formatYValue = yAxisFormatter ?? defaultYFormatter

  // Handle mouse move for crosshair
  const handleMouseMove = (e: React.MouseEvent<SVGSVGElement>) => {
    if (!showCrosshair) return
    const svg = svgRef.current
    if (!svg) return

    const pt = svg.createSVGPoint()
    pt.x = e.clientX
    pt.y = e.clientY
    const ctm = svg.getScreenCTM()
    if (!ctm) return

    const svgPoint = pt.matrixTransform(ctm.inverse())
    const x = svgPoint.x - margin.left

    if (x >= 0 && x <= innerWidth) {
      setCrosshairX(x)
    }
  }

  const handleMouseLeave = () => {
    setCrosshairX(null)
    setHoveredPoint(null)
  }

  const handleSvgMouseMove = (e: React.MouseEvent<SVGSVGElement>) => {
    handleMouseMove(e)
    zoom.handlers.onMouseMove(e)
  }

  const handleSvgMouseLeave = (e: React.MouseEvent<SVGSVGElement>) => {
    handleMouseLeave()
    zoom.handlers.onMouseLeave(e)
  }

  // Find closest point to crosshair (skips series that are empty in the
  // current zoom window; keeps the array index-aligned with
  // `data`/`plotData` so callers can index by seriesIndex directly.
  // Highlighted-but-dimmed series stay in the tooltip — they're faded, not
  // hidden)
  const getClosestPoints = React.useCallback(() => {
    if (crosshairX === null) return null

    return data.map((series, seriesIndex) => {
      const plotSeries = plotData[seriesIndex]
      if (!plotSeries || plotSeries.data.length === 0) {
        return null
      }

      let closestPoint = plotSeries.data[0]
      let closestDist = Infinity
      let closestIdx = 0

      plotSeries.data.forEach((point, idx) => {
        const dist = Math.abs(getX(point) - crosshairX)
        if (dist < closestDist) {
          closestDist = dist
          closestPoint = point
          closestIdx = idx
        }
      })

      return { point: closestPoint, index: closestIdx, seriesIndex }
    })
  }, [crosshairX, data, plotData, getX])

  const closestPoints = getClosestPoints()

  return (
    <ChartContainer config={config} className={cn("relative", className)}>
      {/* Title for stock variant */}
      {variant === "stock" && title && (
        <div className="absolute top-0 left-0 z-10 px-4 pt-2 pb-4">
          <div className="text-foreground text-sm font-semibold">{title}</div>
          {subtitle && (
            <div className="text-muted-foreground mt-0.5 text-xs">
              {subtitle}
            </div>
          )}
        </div>
      )}

      {/* Plot + legend layout — legend sits on `legendPosition` side, click
          a series to highlight it (others fade), click again to restore */}
      <ChartLegendLayout
        position={legendPosition}
        show={showLegend && data.length > 1}
        legend={
          <ChartLegend
            items={legendItems}
            position={legendPosition}
            onItemHover={highlight.setHovered}
            onItemClick={highlight.toggle}
            isItemActive={highlight.isActive}
          />
        }
      >
        <svg
          ref={svgRef}
          viewBox={`0 0 ${width} ${height}`}
          className="h-full w-full flex-1 select-none"
          onMouseMove={handleSvgMouseMove}
          onMouseLeave={handleSvgMouseLeave}
          onMouseDown={zoom.handlers.onMouseDown}
          onMouseUp={zoom.handlers.onMouseUp}
          onDoubleClick={zoom.handlers.onDoubleClick}
        >
          {/* Gradient definitions for area fill */}
          <defs>
            {data.map((series, idx) => {
              const seriesColor = getSeriesColor(series, idx)
              return (
                <linearGradient
                  key={`gradient-${idx}`}
                  id={`area-gradient-${idx}`}
                  x1="0"
                  y1="0"
                  x2="0"
                  y2="1"
                >
                  <stop
                    offset="0%"
                    stopColor={seriesColor}
                    stopOpacity={areaOpacity * 2}
                  />
                  <stop offset="100%" stopColor={seriesColor} stopOpacity={0} />
                </linearGradient>
              )
            })}
          </defs>

          <g transform={`translate(${margin.left}, ${margin.top})`}>
            {/* Invisible background for mouse events */}
            <rect
              width={innerWidth}
              height={innerHeight}
              fill="transparent"
              className="cursor-crosshair"
            />

            {/* Drag-to-zoom selection rectangle */}
            <ChartZoomSelectionRect
              range={zoom.dragRange}
              height={innerHeight}
            />

            {/* Grid */}
            {showGrid && (
              <>
                <ChartHorizontalGrid scale={yScale} width={innerWidth} />
                {variant === "stock" && xType === "time" && (
                  <ChartVerticalGrid
                    scale={
                      xScale as unknown as {
                        ticks: (count?: number) => unknown[];
                        (value: unknown): number
                      }
                    }
                    height={innerHeight}
                  />
                )}
              </>
            )}

            {/* Crosshair */}
            {showCrosshair && crosshairX !== null && (
              <line
                x1={crosshairX}
                y1={0}
                x2={crosshairX}
                y2={innerHeight}
                stroke="var(--border)"
                strokeWidth={1}
                strokeDasharray="4,4"
              />
            )}

            {/* Areas */}
            {showArea &&
              data.map((series, seriesIndex) => {
                const plotSeries = plotData[seriesIndex]
                const isHovered = highlight.isActive(series.name)

                return (
                  <path
                    key={`area-${series.name}`}
                    d={areaFn(plotSeries.data) ?? ""}
                    fill={`url(#area-gradient-${seriesIndex})`}
                    className={cn(
                      "transition-opacity duration-200",
                      !isHovered && "opacity-30"
                    )}
                  />
                )
              })}

            {/* Lines */}
            {data.map((series, seriesIndex) => {
              const plotSeries = plotData[seriesIndex]
              const seriesColor = getSeriesColor(series, seriesIndex)
              const isHovered = highlight.isActive(series.name)

              return (
                <g key={series.name}>
                  {/* Invisible hit area for better mouse interaction */}
                  <path
                    d={lineFn(plotSeries.data) ?? ""}
                    fill="none"
                    stroke="transparent"
                    strokeWidth={20}
                    className="cursor-pointer"
                    style={{ pointerEvents: "stroke" }}
                  />
                  {/* Visible Line */}
                  <path
                    d={lineFn(plotSeries.data) ?? ""}
                    fill="none"
                    stroke={seriesColor}
                    strokeWidth={series.strokeWidth ?? strokeWidth}
                    strokeDasharray={series.strokeDasharray}
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    style={{ pointerEvents: "none" }}
                    className={cn(
                      "transition-opacity duration-200",
                      !isHovered && "opacity-30",
                      animate && "animate-draw"
                    )}
                  />

                  {/* Dots */}
                  {(series.showDots ?? showDots) &&
                    plotSeries.data.map((point, pointIndex) => (
                      <circle
                        key={pointIndex}
                        cx={getX(point)}
                        cy={yScale(point.y)}
                        r={
                          hoveredPoint?.seriesIndex === seriesIndex &&
                          hoveredPoint?.pointIndex === pointIndex
                            ? (series.dotSize ?? dotSize) * 1.5
                            : (series.dotSize ?? dotSize)
                        }
                        fill={seriesColor}
                        className={cn(
                          "cursor-pointer transition-all duration-200",
                          !isHovered && "opacity-30"
                        )}
                        onMouseEnter={() =>
                          setHoveredPoint({
                            seriesIndex,
                            pointIndex,
                            point,
                            x: getX(point),
                            y: yScale(point.y),
                          })
                        }
                        onMouseLeave={() => setHoveredPoint(null)}
                      />
                    ))}

                  {/* Data Labels */}
                  {showDataLabels &&
                    plotSeries.data.map((point, pointIndex) => {
                      const x = getX(point)
                      const y = yScale(point.y)
                      // Position label above or below based on surrounding points
                      const prevY =
                        pointIndex > 0
                          ? yScale(plotSeries.data[pointIndex - 1].y)
                          : y
                      const nextY =
                        pointIndex < plotSeries.data.length - 1
                          ? yScale(plotSeries.data[pointIndex + 1].y)
                          : y
                      const isLocalMin = y > prevY && y > nextY
                      const labelY = isLocalMin ? y + 20 : y - 12

                      return (
                        <text
                          key={`label-${pointIndex}`}
                          x={x}
                          y={labelY}
                          textAnchor="middle"
                          className="fill-muted-foreground text-xs font-medium"
                          style={{ pointerEvents: "none" }}
                        >
                          {Math.round(point.y)}
                        </text>
                      )
                    })}

                  {/* Crosshair dots */}
                  {showCrosshair && closestPoints?.[seriesIndex] && (
                    <circle
                      cx={getX(closestPoints[seriesIndex]!.point)}
                      cy={yScale(closestPoints[seriesIndex]!.point.y)}
                      r={5}
                      fill="var(--background)"
                      stroke={seriesColor}
                      strokeWidth={2}
                      className={cn(!isHovered && "opacity-30")}
                    />
                  )}
                </g>
              )
            })}

            {/* X Axis */}
            {variant !== "sparkline" && (
              <ChartAxis
                scale={xScale}
                orientation="bottom"
                transform={`translate(0, ${innerHeight})`}
                label={xAxisLabel}
                tickFormat={
                  xType === "time"
                    ? (d) => formatDateAxis(d as Date)
                    : undefined
                }
              />
            )}

            {/* Y Axis */}
            {variant !== "sparkline" && showYAxis && (
              <ChartAxis
                scale={yScale}
                orientation="left"
                label={yAxisLabel}
                tickFormat={(d) => formatYValue(d as number)}
              />
            )}
          </g>
        </svg>

        {/* Crosshair Tooltip */}
        {showCrosshair && crosshairX !== null && closestPoints && (
          <div
            className="pointer-events-none absolute z-50"
            style={{
              left: margin.left + crosshairX + 15,
              top: margin.top + 10,
            }}
          >
            <div className="border-border/50 bg-background rounded-lg border px-3 py-2 text-xs shadow-xl">
              {(() => {
                const headPoint = closestPoints.find((cp) => cp !== null)?.point
                if (!headPoint) return null
                return (
                  <div className="text-muted-foreground mb-1.5 font-medium">
                    {xType === "time"
                      ? formatDateAxis(new Date(headPoint.x as string | Date))
                      : String(headPoint.x)}
                  </div>
                )
              })()}
              {closestPoints.map(
                (cp, idx) =>
                  cp && (
                    <div
                      key={idx}
                      className={cn(
                        "flex items-center gap-2 transition-opacity",
                        highlight.isDimmed(data[idx].name) && "opacity-40"
                      )}
                    >
                      <div
                        className="h-2.5 w-2.5 rounded-full"
                        style={{
                          backgroundColor: getSeriesColor(data[idx], idx),
                        }}
                      />
                      <span className="text-muted-foreground">
                        {data[idx].name}:
                      </span>
                      <span className="font-medium">
                        {formatYValue(cp.point.y)}
                      </span>
                    </div>
                  )
              )}
            </div>
          </div>
        )}

        {/* Standard Tooltip */}
        {showTooltip && !showCrosshair && hoveredPoint && (
          <div
            className="pointer-events-none absolute z-50"
            style={{
              left: margin.left + hoveredPoint.x + 10,
              top: margin.top + hoveredPoint.y - 10,
            }}
          >
            <div className="border-border/50 bg-background rounded-lg border px-2.5 py-1.5 text-xs shadow-xl">
              {data.length > 1 && (
                <div
                  className="mb-1 font-medium"
                  style={{
                    color: getSeriesColor(
                      data[hoveredPoint.seriesIndex],
                      hoveredPoint.seriesIndex
                    ),
                  }}
                >
                  {data[hoveredPoint.seriesIndex].name}
                </div>
              )}
              <div className="text-muted-foreground">
                {String(hoveredPoint.point.x)}
              </div>
              <div className="font-medium">
                {formatYValue(hoveredPoint.point.y)}
              </div>
            </div>
          </div>
        )}

        <ChartZoomResetButton
          visible={isZoomed}
          onReset={() => setZoomDomain(null)}
        />
      </ChartLegendLayout>
    </ChartContainer>
  )
}

"use client"

import * as React from "react"
import {
  Bar,
  CartesianGrid,
  Cell,
  LabelList,
  BarChart as RechartsBarChart,
  Rectangle,
  ReferenceLine,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts"

import { cn } from "@/lib/utils"

import {
  chartActiveTick,
  chartActiveValueLabel,
  chartTagLabel,
  resolveReferenceValue,
  type ChartLabelRenderer,
} from "../chart-annotations"
import { ChartLegendLayout, useSeriesHighlight } from "../chart-legend"
import {
  chartPatternDefs,
  patternFill,
  useChartPatternIds,
} from "../chart-patterns"
import {
  autoTickInterval,
  ChartPlotArea,
  resolveResponsive,
  useCategoryLayout,
  useChartSize,
  type CategoryChartLayoutProps,
  type Responsive,
} from "../chart-responsive"
import {
  useChartTheme,
  type ChartPatternKind,
  type ChartTagVariant,
  type ChartTickVariant,
} from "../chart-theme"
import {
  ChartWindowSelectionOverlay,
  ChartZoomControls,
  useChartWindow,
} from "../chart-zoom"

// ============================================
// Bar Chart
// ============================================

export interface BarChartDataPoint {
  label: string
  value: number
  fill?: string
  [key: string]: unknown
}

/** Horizontal marker across the plot — a target, a budget, an average. */
export interface BarChartReferenceLine {
  /** A literal value, or a statistic computed over the plotted values. */
  value: number | "avg" | "min" | "max"
  /** Text for the label, or your own renderer. Omit for a bare line. */
  label?: string | ChartLabelRenderer
  /** Shape of that label. Defaults to the chart theme. */
  labelVariant?: ChartTagVariant
  color?: string
  strokeDasharray?: string
  labelSide?: "left" | "right"
}

export interface BarChartProps extends CategoryChartLayoutProps {
  data: BarChartDataPoint[]
  className?: string
  color?: string
  showGrid?: boolean
  showTooltip?: boolean
  showLabel?: boolean
  labelPosition?:
    | "top"
    | "center"
    | "bottom"
    | "inside"
    | "left"
    | "right"
    | "insideLeft"
    | "insideRight"
  valueFormatter?: (value: number) => string
  labelFormatter?: (label: string) => string
  layout?: "vertical" | "horizontal"
  /**
   * Plotly-style alias for `layout`, where "horizontal" means horizontal
   * *bars*. `layout` names the axis instead, so the two are inverted — this
   * exists because chart payloads generated from Plotly figures speak the
   * former and were silently landing on the wrong orientation.
   */
  orientation?: "vertical" | "horizontal"
  barRadius?: number
  /** Space for the value axis, px. Responsive: a 48px gutter is an eighth
   *  of a phone screen. */
  yAxisWidth?: Responsive<number>

  // ---- Framing -------------------------------------------------------
  xAxisLabel?: string
  yAxisLabel?: string
  showXAxis?: boolean
  showYAxis?: boolean
  /**
   * Categories skipped between drawn ticks. Defaults to whatever keeps
   * labels from colliding at the measured width; `0` forces every tick.
   */
  xAxisInterval?: number | "preserveStart" | "preserveEnd" | "preserveStartEnd"

  // ---- Emphasis ------------------------------------------------------
  /** Bar(s) to keep vivid; every other bar drops to `mutedColor`. */
  activeIndex?: number | number[] | null
  /** Same, addressed by category — the form a JSON payload can express. */
  activeLabel?: string | null
  mutedColor?: string
  /** Texture over emphasised bars. Defaults to the chart theme. */
  pattern?: ChartPatternKind
  /** Texture over de-emphasised bars. Defaults to the chart theme. */
  mutedPattern?: ChartPatternKind
  patternColor?: string
  mutedPatternColor?: string
  /** Print the value above the emphasised bars only. */
  showActiveValue?: boolean
  /** How the active category's tick is marked. Defaults to the theme. */
  activeTickVariant?: ChartTickVariant

  // ---- Annotation ----------------------------------------------------
  referenceLine?: BarChartReferenceLine | number | "avg" | "min" | "max" | null
}

export function BarChart({
  data,
  className,
  color = "var(--chart-3)",
  showGrid = true,
  showTooltip = true,
  showLabel = false,
  labelPosition,
  valueFormatter = (value) => `${value}`,
  labelFormatter = (label) => label,
  layout = "horizontal",
  orientation,
  barRadius,
  aspectRatio = 2,
  minHeight = 180,
  overflow = "compress",
  minCategorySize = 32,
  zoomable = true,
  wheelZoom = false,
  showZoomControls = true,
  yAxisWidth,
  xAxisLabel,
  yAxisLabel,
  showXAxis = true,
  showYAxis = true,
  xAxisInterval,
  activeIndex = null,
  activeLabel = null,
  mutedColor,
  pattern,
  mutedPattern,
  patternColor,
  mutedPatternColor,
  showActiveValue = false,
  activeTickVariant,
  referenceLine = null,
}: BarChartProps) {
  const theme = useChartTheme({
    barRadius,
    mutedColor,
    activePattern: pattern,
    mutedPattern,
    activeTickVariant,
  })

  // `orientation` wins when given: it is the more explicit of the two, and
  // the only one a Plotly-derived payload sets.
  const isVertical = orientation
    ? orientation === "horizontal"
    : layout === "vertical"

  const { ref: sizeRef, width: containerWidth } = useChartSize<HTMLDivElement>()
  const layoutBox = useCategoryLayout({
    count: data.length,
    containerWidth,
    aspectRatio,
    minHeight,
    overflow,
    minCategorySize,
    // Horizontal bars stack their categories down the screen, so it is the
    // height that has to grow, not the width.
    axis: isVertical ? "y" : "x",
  })

  const resolvedYAxisWidth = resolveResponsive(
    yAxisWidth,
    containerWidth,
    containerWidth && containerWidth < 420 ? 36 : 48
  )

  const zoom = useChartWindow({
    length: data.length,
    orientation: isVertical ? "y" : "x",
    // Scrolling already owns the pointer; two ways to move the same axis
    // just fight each other.
    disabled: !zoomable || layoutBox.scrolls,
    wheelZoom,
    insetStart: isVertical ? resolvedYAxisWidth + 10 : resolvedYAxisWidth + 10,
    insetEnd: 10,
  })
  const displayData = zoom.slice(data)

  // Layout-aware default. For horizontal bars (`layout="vertical"` per
  // Recharts' convention) the natural label spot is to the RIGHT of the
  // bar end — "top" places labels above each row, which overlaps the
  // bar in the row above when bars are tightly packed. For vertical
  // bars, "top" remains the sensible default.
  const effectiveLabelPosition = labelPosition ?? (isVertical ? "right" : "top")

  const patternIds = useChartPatternIds("bar-on", "bar-off")

  // Which bars stay vivid. `null` means "all of them" — no emphasis asked
  // for, so nothing is dimmed.
  const activeSet = React.useMemo(() => {
    const indices = new Set<number>()
    if (typeof activeIndex === "number") indices.add(activeIndex)
    else if (Array.isArray(activeIndex))
      activeIndex.forEach((i) => indices.add(i))
    if (activeLabel != null) {
      displayData.forEach((d, i) => {
        if (d.label === activeLabel) indices.add(i)
      })
    }
    return indices.size ? indices : null
  }, [activeIndex, activeLabel, displayData])

  const hasEmphasis =
    activeSet !== null ||
    theme.activePattern !== "none" ||
    theme.mutedPattern !== "none"

  /** Per-bar fill: an explicit datum colour wins, then emphasis, then the
   *  chart colour — each optionally wearing its pattern. */
  const fillFor = (entry: BarChartDataPoint | undefined, index: number) => {
    if (entry && typeof entry.fill === "string" && entry.fill) return entry.fill
    const on = activeSet === null || activeSet.has(index)
    return on
      ? patternFill(color, theme.activePattern, patternIds["bar-on"])
      : patternFill(theme.mutedColor, theme.mutedPattern, patternIds["bar-off"])
  }

  // A custom `shape` keeps emphasis out of `<Cell>`, which recharts
  // mis-positions in horizontal-bar mode (see the Cell comment below).
  const barShape = hasEmphasis
    ? (props: unknown) => {
        // Recharts types this callback's argument as `unknown`; the runtime
        // shape is the bar's layout props merged with its datum.
        const bar = props as React.ComponentProps<typeof Rectangle> & {
          payload?: BarChartDataPoint
          index?: number
        }
        return (
          <Rectangle {...bar} fill={fillFor(bar.payload, bar.index ?? -1)} />
        )
      }
    : undefined

  const reference = React.useMemo(() => {
    if (referenceLine == null) return null
    const spec: BarChartReferenceLine =
      typeof referenceLine === "object"
        ? referenceLine
        : { value: referenceLine }
    const resolved = resolveReferenceValue(
      spec.value,
      displayData.map((d) => Number(d.value))
    )
    return resolved == null ? null : { ...spec, resolved }
  }, [referenceLine, displayData])

  // Bars sit on the baseline, so only the far corners should round —
  // rounding all four notches the bar where it meets the axis. Negative
  // values flip which end is "far", so those fall back to a plain radius.
  const hasNegative = displayData.some((d) => Number(d.value) < 0)
  const r = theme.barRadius
  const cornerRadius: number | [number, number, number, number] = hasNegative
    ? r
    : isVertical
      ? [0, r, r, 0]
      : [r, r, 0, 0]

  const marksActiveTick = activeLabel != null
  const tickInterval =
    xAxisInterval ??
    autoTickInterval(
      displayData.length,
      layoutBox.plotWidth - resolvedYAxisWidth
    )

  return (
    <div ref={sizeRef} className={cn("group/chart relative w-full", className)}>
      <div className="relative" {...zoom.bind}>
        <ChartPlotArea layout={layoutBox}>
          <ResponsiveContainer width="100%" height={layoutBox.plotHeight}>
            <RechartsBarChart
              data={displayData}
              layout={isVertical ? "vertical" : "horizontal"}
              margin={{
                top: (showLabel || showActiveValue) && !isVertical ? 24 : 10,
                // Horizontal bars with end-of-bar labels need real space at
                // the right edge — the default 10px clips multi-digit
                // values. Bump only in the (showLabel ∧ horizontal-bars)
                // case so vertical-bar charts aren't penalised.
                right: showLabel && isVertical ? 80 : 10,
                left: yAxisLabel ? 20 : 10,
                bottom: xAxisLabel ? 56 : 40,
              }}
            >
              {chartPatternDefs([
                {
                  id: patternIds["bar-on"],
                  kind: theme.activePattern,
                  background: color,
                  color: patternColor ?? "rgba(255,255,255,0.34)",
                },
                {
                  id: patternIds["bar-off"],
                  kind: theme.mutedPattern,
                  background: theme.mutedColor,
                  color:
                    mutedPatternColor ??
                    "color-mix(in oklab, var(--muted-foreground) 22%, transparent)",
                },
              ])}

              {showGrid && (
                <CartesianGrid
                  strokeDasharray={theme.gridDash || undefined}
                  vertical={true}
                  horizontal={true}
                  stroke="hsl(var(--border))"
                  strokeOpacity={theme.gridOpacity}
                />
              )}

              {/* CRITICAL: render each axis as a SEPARATE conditional slot
                  instead of wrapping in a `<>...</>` fragment. Recharts
                  iterates BarChart's children via React.Children.forEach,
                  which does NOT recurse into fragments — wrapping the
                  axes in a fragment caused recharts to miss them entirely
                  and collapse all bars to a single Y-position (the long-
                  running "1 bar visible" failure mode for horizontal-bar
                  mode). Each `{cond && <Axis/>}` is one direct-child slot
                  React enumerates correctly. */}
              {isVertical && (
                <YAxis
                  dataKey="label"
                  type="category"
                  hide={!showYAxis}
                  axisLine={false}
                  tickLine={false}
                  tick={{ fontSize: theme.tickFontSize }}
                  tickFormatter={labelFormatter}
                  width={resolvedYAxisWidth}
                  interval={layoutBox.scrolls ? 0 : undefined}
                  label={
                    yAxisLabel
                      ? {
                          value: yAxisLabel,
                          angle: -90,
                          position: "insideLeft",
                          fill: "var(--muted-foreground)",
                          fontSize: theme.tickFontSize,
                        }
                      : undefined
                  }
                />
              )}
              {isVertical && (
                <XAxis
                  type="number"
                  hide={!showXAxis}
                  axisLine={false}
                  tickLine={false}
                  tick={{ fontSize: theme.tickFontSize }}
                  tickFormatter={valueFormatter}
                  label={
                    xAxisLabel
                      ? {
                          value: xAxisLabel,
                          position: "insideBottom",
                          offset: -12,
                          fill: "var(--muted-foreground)",
                          fontSize: theme.tickFontSize,
                        }
                      : undefined
                  }
                />
              )}
              {!isVertical && (
                <XAxis
                  dataKey="label"
                  hide={!showXAxis}
                  axisLine={false}
                  tickLine={false}
                  tick={
                    marksActiveTick
                      ? chartActiveTick(activeLabel, {
                          variant: theme.activeTickVariant,
                          fontSize: theme.tickFontSize,
                          background: theme.activeTickBackground,
                          foreground: theme.activeTickForeground,
                          formatter: labelFormatter,
                        })
                      : { fontSize: theme.tickFontSize }
                  }
                  tickFormatter={marksActiveTick ? undefined : labelFormatter}
                  tickMargin={marksActiveTick ? 4 : 8}
                  interval={tickInterval}
                  label={
                    xAxisLabel
                      ? {
                          value: xAxisLabel,
                          position: "insideBottom",
                          offset: -12,
                          fill: "var(--muted-foreground)",
                          fontSize: theme.tickFontSize,
                        }
                      : undefined
                  }
                />
              )}
              {!isVertical && (
                <YAxis
                  hide={!showYAxis}
                  axisLine={false}
                  tickLine={false}
                  tick={{ fontSize: theme.tickFontSize }}
                  tickFormatter={valueFormatter}
                  width={resolvedYAxisWidth}
                  label={
                    yAxisLabel
                      ? {
                          value: yAxisLabel,
                          angle: -90,
                          position: "insideLeft",
                          fill: "var(--muted-foreground)",
                          fontSize: theme.tickFontSize,
                        }
                      : undefined
                  }
                />
              )}

              {showTooltip && (
                <Tooltip
                  cursor={{
                    fill: "hsl(var(--muted-foreground))",
                    opacity: 0.08,
                  }}
                  content={({ active, payload, label }) => {
                    if (!active || !payload?.length) return null
                    return (
                      <div className="bg-background rounded-lg border px-3 py-2 shadow-lg">
                        <p className="text-foreground text-sm font-medium">
                          {labelFormatter(label)}
                        </p>
                        <p
                          className="text-sm"
                          style={{ color: payload[0]?.color || color }}
                        >
                          {valueFormatter(payload[0]?.value as number)}
                        </p>
                      </div>
                    )
                  }}
                />
              )}

              {reference && (
                <ReferenceLine
                  {...(isVertical
                    ? { x: reference.resolved }
                    : { y: reference.resolved })}
                  stroke={reference.color ?? "var(--muted-foreground)"}
                  strokeDasharray={reference.strokeDasharray ?? "2 6"}
                  ifOverflow="extendDomain"
                  label={
                    typeof reference.label === "function"
                      ? reference.label
                      : reference.label
                        ? chartTagLabel(reference.label, {
                            variant:
                              reference.labelVariant ?? theme.tagVariant,
                            side: reference.labelSide ?? "left",
                            background: theme.tagBackground,
                            foreground: theme.tagForeground,
                          })
                        : undefined
                  }
                />
              )}

              {/* Per-row Cell children only when at least one data point
                  specifies its own `fill`. With Cells present unconditionally,
                  recharts' horizontal-bar mode (`layout="vertical"`)
                  collapses every bar's Y-position to row 0 — the second
                  prong of the long-running "1 bar visible" failure mode
                  (the first being the Fragment-wrapped axes). When all
                  bars share the Bar's `fill` prop (the common case),
                  omitting Cells lets recharts position each row correctly.
                  Emphasis and patterns go through `shape` for the same
                  reason: one child, no per-row Cells. */}
              {displayData.some((d) => typeof d.fill === "string" && d.fill) ? (
                <Bar
                  dataKey="value"
                  fill={color}
                  radius={cornerRadius}
                  maxBarSize={theme.maxBarSize}
                  shape={barShape}
                  isAnimationActive={theme.animate}
                  animationDuration={theme.animationDuration}
                >
                  {displayData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.fill || color} />
                  ))}
                  {showLabel && (
                    <LabelList
                      dataKey="value"
                      position={effectiveLabelPosition}
                      offset={
                        effectiveLabelPosition === "right" ||
                        effectiveLabelPosition === "left"
                          ? 6
                          : undefined
                      }
                      formatter={valueFormatter}
                      className="fill-foreground text-xs"
                    />
                  )}
                  {showActiveValue && (
                    <LabelList
                      dataKey="value"
                      content={chartActiveValueLabel(
                        (i) => activeSet === null || activeSet.has(i),
                        valueFormatter
                      )}
                    />
                  )}
                </Bar>
              ) : (
                <Bar
                  dataKey="value"
                  fill={color}
                  radius={cornerRadius}
                  maxBarSize={theme.maxBarSize}
                  shape={barShape}
                  isAnimationActive={theme.animate}
                  animationDuration={theme.animationDuration}
                >
                  {showLabel && (
                    <LabelList
                      dataKey="value"
                      position={effectiveLabelPosition}
                      offset={
                        effectiveLabelPosition === "right" ||
                        effectiveLabelPosition === "left"
                          ? 6
                          : undefined
                      }
                      formatter={valueFormatter}
                      className="fill-foreground text-xs"
                    />
                  )}
                  {showActiveValue && (
                    <LabelList
                      dataKey="value"
                      content={chartActiveValueLabel(
                        (i) => activeSet === null || activeSet.has(i),
                        valueFormatter
                      )}
                    />
                  )}
                </Bar>
              )}
            </RechartsBarChart>
          </ResponsiveContainer>
        </ChartPlotArea>

        <ChartWindowSelectionOverlay
          selection={zoom.selection}
          orientation={isVertical ? "y" : "x"}
          insetStart={resolvedYAxisWidth + 10}
          insetEnd={10}
        />
      </div>

      {showZoomControls && !layoutBox.scrolls && zoomable && (
        <ChartZoomControls
          onZoomIn={zoom.zoomIn}
          onZoomOut={zoom.zoomOut}
          onReset={zoom.reset}
          isZoomed={zoom.isZoomed}
        />
      )}
    </div>
  )
}

// ============================================
// Multi Bar Chart (Grouped/Stacked)
// ============================================

export interface MultiBarChartSeries {
  name: string
  dataKey: string
  color: string
  stackId?: string
}

export interface MultiBarChartDataPoint {
  label: string
  [key: string]: string | number
}

export interface MultiBarChartProps extends CategoryChartLayoutProps {
  data: MultiBarChartDataPoint[]
  series: MultiBarChartSeries[]
  className?: string
  showGrid?: boolean
  showTooltip?: boolean
  showLegend?: boolean
  /** Side the legend sits on. A side legend eats width a narrow container
   *  doesn't have, so it falls to the bottom below `md` by default. */
  legendPosition?: Responsive<"top" | "bottom" | "left" | "right">
  valueFormatter?: (value: number) => string
  labelFormatter?: (label: string) => string
  layout?: "vertical" | "horizontal"
  orientation?: "vertical" | "horizontal"
  barRadius?: number
  yAxisWidth?: Responsive<number>
  xAxisInterval?: number | "preserveStart" | "preserveEnd" | "preserveStartEnd"
}

export function MultiBarChart({
  data,
  series,
  className,
  showGrid = true,
  showTooltip = true,
  showLegend = true,
  legendPosition = { base: "bottom", md: "right" },
  valueFormatter = (value) => `${value}`,
  labelFormatter = (label) => label,
  layout = "horizontal",
  orientation,
  barRadius = 4,
  aspectRatio = 2,
  minHeight = 180,
  overflow = "compress",
  minCategorySize = 44,
  zoomable = true,
  wheelZoom = false,
  showZoomControls = true,
  yAxisWidth,
  xAxisInterval,
}: MultiBarChartProps) {
  const isVertical = orientation
    ? orientation === "horizontal"
    : layout === "vertical"

  const { ref: sizeRef, width: containerWidth } = useChartSize<HTMLDivElement>()
  const layoutBox = useCategoryLayout({
    count: data.length,
    containerWidth,
    aspectRatio,
    minHeight,
    overflow,
    minCategorySize,
    axis: isVertical ? "y" : "x",
  })
  const resolvedLegendPosition = resolveResponsive(
    legendPosition,
    containerWidth,
    "right"
  )
  const resolvedYAxisWidth = resolveResponsive(
    yAxisWidth,
    containerWidth,
    containerWidth && containerWidth < 420 ? 36 : 48
  )

  const zoom = useChartWindow({
    length: data.length,
    orientation: isVertical ? "y" : "x",
    disabled: !zoomable || layoutBox.scrolls,
    wheelZoom,
    insetStart: resolvedYAxisWidth + 10,
    insetEnd: 10,
  })
  const displayData = zoom.slice(data)

  // Legend highlight: click a series to emphasize it (others fade but stay
  // drawn so the grouped-bar layout never shifts), hover to preview.
  const highlight = useSeriesHighlight()
  const tickInterval =
    xAxisInterval ??
    autoTickInterval(
      displayData.length,
      layoutBox.plotWidth - resolvedYAxisWidth
    )

  return (
    <div ref={sizeRef} className={cn("group/chart relative w-full", className)}>
      <ChartLegendLayout
        position={resolvedLegendPosition}
        show={showLegend && series.length > 1}
        legend={
          <div
            className={cn(
              "flex gap-3",
              resolvedLegendPosition === "left" ||
                resolvedLegendPosition === "right"
                ? "flex-col items-start"
                : "flex-wrap items-center justify-center",
              resolvedLegendPosition === "top" && "pb-4",
              resolvedLegendPosition === "bottom" && "pt-4",
              resolvedLegendPosition === "left" && "pr-4",
              resolvedLegendPosition === "right" && "pl-4"
            )}
          >
            {series.map((s) => (
              <button
                key={s.dataKey}
                type="button"
                onClick={() => highlight.toggle(s.name)}
                onMouseEnter={() => highlight.setHovered(s.name)}
                onMouseLeave={() => highlight.setHovered(null)}
                className={cn(
                  "flex items-center gap-2 text-sm transition-opacity hover:opacity-80",
                  !highlight.isActive(s.name) && "opacity-40"
                )}
              >
                <div
                  className="size-3 rounded-sm"
                  style={{ backgroundColor: s.color }}
                />
                <span className="text-muted-foreground">{s.name}</span>
              </button>
            ))}
          </div>
        }
      >
        <div className="relative w-full flex-1" {...zoom.bind}>
          <ChartPlotArea layout={layoutBox}>
            <ResponsiveContainer width="100%" height={layoutBox.plotHeight}>
              <RechartsBarChart
                data={displayData}
                layout={isVertical ? "vertical" : "horizontal"}
                margin={{ top: 10, right: 10, left: 10, bottom: 40 }}
              >
                {showGrid && (
                  <CartesianGrid
                    strokeDasharray="3 3"
                    vertical={true}
                    horizontal={true}
                    stroke="hsl(var(--border))"
                    strokeOpacity={0.5}
                  />
                )}

                {/* CRITICAL: render each axis as a SEPARATE conditional slot
                    instead of wrapping in a `<>...</>` fragment. Recharts
                    iterates BarChart's children via React.Children.forEach,
                    which does NOT recurse into fragments — wrapping the
                    axes in a fragment caused recharts to miss them entirely
                    and collapse all bars to a single Y-position. */}
                {isVertical && (
                  <YAxis
                    dataKey="label"
                    type="category"
                    axisLine={false}
                    tickLine={false}
                    tick={{ fontSize: 12 }}
                    tickFormatter={labelFormatter}
                    width={resolvedYAxisWidth}
                    interval={layoutBox.scrolls ? 0 : undefined}
                  />
                )}
                {isVertical && (
                  <XAxis
                    type="number"
                    axisLine={false}
                    tickLine={false}
                    tick={{ fontSize: 12 }}
                    tickFormatter={valueFormatter}
                  />
                )}
                {!isVertical && (
                  <XAxis
                    dataKey="label"
                    axisLine={false}
                    tickLine={false}
                    tick={{ fontSize: 12 }}
                    tickFormatter={labelFormatter}
                    tickMargin={8}
                    interval={tickInterval}
                  />
                )}
                {!isVertical && (
                  <YAxis
                    axisLine={false}
                    tickLine={false}
                    tick={{ fontSize: 12 }}
                    tickFormatter={valueFormatter}
                    width={resolvedYAxisWidth}
                  />
                )}

                {showTooltip && (
                  <Tooltip
                    cursor={{
                      fill: "hsl(var(--muted-foreground))",
                      opacity: 0.08,
                    }}
                    content={({ active, payload, label }) => {
                      if (!active || !payload?.length) return null
                      return (
                        <div className="bg-background rounded-lg border px-3 py-2 shadow-lg">
                          <p className="text-foreground mb-1 text-sm font-medium">
                            {labelFormatter(label)}
                          </p>
                          {payload.map((entry, index) => (
                            <div
                              key={index}
                              className={cn(
                                "flex items-center gap-2 text-sm transition-opacity",
                                highlight.isDimmed(entry.name as string) &&
                                  "opacity-40"
                              )}
                            >
                              <div
                                className="size-2 rounded-full"
                                style={{ backgroundColor: entry.color }}
                              />
                              <span className="text-muted-foreground">
                                {entry.name}:
                              </span>
                              <span style={{ color: entry.color }}>
                                {valueFormatter(entry.value as number)}
                              </span>
                            </div>
                          ))}
                        </div>
                      )
                    }}
                  />
                )}

                {/* All series always render — the focused one stays vivid while
                    the rest fade (never removed, so grouped bars never re-flow). */}
                {series.map((s) => (
                  <Bar
                    key={s.dataKey}
                    dataKey={s.dataKey}
                    name={s.name}
                    fill={s.color}
                    radius={barRadius}
                    stackId={s.stackId}
                    maxBarSize={40}
                    className={cn(
                      "transition-opacity duration-200",
                      highlight.isDimmed(s.name) && "opacity-30"
                    )}
                  />
                ))}
              </RechartsBarChart>
            </ResponsiveContainer>
          </ChartPlotArea>

          <ChartWindowSelectionOverlay
            selection={zoom.selection}
            orientation={isVertical ? "y" : "x"}
            insetStart={resolvedYAxisWidth + 10}
            insetEnd={10}
          />

          {showZoomControls && !layoutBox.scrolls && zoomable && (
            <ChartZoomControls
              onZoomIn={zoom.zoomIn}
              onZoomOut={zoom.zoomOut}
              onReset={zoom.reset}
              isZoomed={zoom.isZoomed}
            />
          )}
        </div>
      </ChartLegendLayout>
    </div>
  )
}

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

import type { ChartPatternKind } from "../chart-theme"
import { useChartTheme } from "../chart-theme"

/**
 * A share-of-total bar: rounded segments laid along one track, with an
 * optional legend carrying each share.
 *
 * This is the "Income Breakdown" / budget-usage mark that dashboards lean
 * on constantly and that a pie chart reads worse than. It is CSS rather
 * than SVG on purpose — the whole mark is rectangles, so there is nothing
 * an `<svg>` would buy.
 */

export interface ProportionSegment {
  label: string
  value: number
  color?: string
  /** Per-segment override of the chart's texture. */
  pattern?: ChartPatternKind
}

export interface ProportionBarProps {
  data: ProportionSegment[]
  /**
   * Denominator for each share. Defaults to the sum of `value`, so the
   * segments fill the track; pass a larger number to leave a remainder
   * (a budget with headroom left).
   */
  total?: number
  height?: number
  /** Gap between segments, px. */
  gap?: number
  /** Corner radius, px. Defaults to a full pill. */
  radius?: number
  showTrack?: boolean
  trackColor?: string
  /** Texture painted over every segment. Defaults to the theme. */
  pattern?: ChartPatternKind
  showLegend?: boolean
  /** What the legend prints on the right of each row. */
  legendValue?: "percent" | "value" | "none"
  valueFormatter?: (value: number) => string
  className?: string
}

/** CSS stand-in for the SVG `<pattern>` textures — a bar is a rectangle,
 *  so a repeating gradient is both cheaper and resolution-independent. */
function textureFor(kind: ChartPatternKind): string | undefined {
  switch (kind) {
    case "hatch":
      return "repeating-linear-gradient(45deg, rgba(255,255,255,0.30) 0 2px, transparent 2px 7px)"
    case "hatch-dense":
      return "repeating-linear-gradient(45deg, rgba(255,255,255,0.30) 0 1.5px, transparent 1.5px 4px)"
    case "dots":
      return "radial-gradient(rgba(255,255,255,0.45) 1px, transparent 1.2px)"
    case "grid":
      return "repeating-linear-gradient(0deg, rgba(255,255,255,0.25) 0 1px, transparent 1px 8px), repeating-linear-gradient(90deg, rgba(255,255,255,0.25) 0 1px, transparent 1px 8px)"
    default:
      return undefined
  }
}

export function ProportionBar({
  data,
  total,
  height = 28,
  gap = 6,
  radius,
  showTrack = true,
  trackColor = "var(--muted)",
  pattern,
  showLegend = true,
  legendValue = "percent",
  valueFormatter = (v) => v.toLocaleString(),
  className,
}: ProportionBarProps) {
  const theme = useChartTheme()
  const texture = pattern ?? theme.activePattern
  const corner = radius ?? height / 2

  const sum = data.reduce((acc, d) => acc + (Number(d.value) || 0), 0)
  const denominator = total && total > 0 ? total : sum
  // An all-zero dataset would divide by zero; render an empty track instead.
  const share = (value: number) =>
    denominator > 0 ? Math.max(0, value) / denominator : 0

  return (
    <div className={cn("w-full space-y-3", className)}>
      <div
        className="flex w-full overflow-hidden"
        style={{
          height,
          gap,
          borderRadius: corner,
          backgroundColor: showTrack ? trackColor : undefined,
        }}
        role="img"
        aria-label={data
          .map((d) => `${d.label} ${Math.round(share(d.value) * 100)}%`)
          .join(", ")}
      >
        {data.map((segment, index) => {
          const color =
            segment.color ?? theme.palette[index % theme.palette.length]
          const backgroundImage = textureFor(segment.pattern ?? texture)
          return (
            <div
              key={`${segment.label}-${index}`}
              title={`${segment.label}: ${valueFormatter(segment.value)}`}
              style={{
                flex: `0 0 ${share(segment.value) * 100}%`,
                backgroundColor: color,
                backgroundImage,
                backgroundSize:
                  (segment.pattern ?? texture) === "dots"
                    ? "6px 6px"
                    : undefined,
                borderRadius: corner,
                transition: theme.animate
                  ? `flex-basis ${theme.animationDuration}ms ease-out`
                  : undefined,
              }}
            />
          )
        })}
      </div>

      {showLegend && (
        <ul className="divide-border/60 divide-y">
          {data.map((segment, index) => {
            const color =
              segment.color ?? theme.palette[index % theme.palette.length]
            return (
              <li
                key={`${segment.label}-legend-${index}`}
                className="flex items-center justify-between gap-3 py-2 text-sm"
              >
                <span className="flex min-w-0 items-center gap-2">
                  <span
                    className="size-3 shrink-0 rounded-[4px]"
                    style={{ backgroundColor: color }}
                  />
                  <span className="text-foreground truncate">
                    {segment.label}
                  </span>
                </span>
                {legendValue !== "none" && (
                  <span className="text-muted-foreground shrink-0 tabular-nums">
                    {legendValue === "percent"
                      ? `${Math.round(share(segment.value) * 100)} %`
                      : valueFormatter(segment.value)}
                  </span>
                )}
              </li>
            )
          })}
        </ul>
      )}
    </div>
  )
}

"use client"

import * as React from "react"
import {
  Area,
  CartesianGrid,
  ComposedChart,
  Line,
  ReferenceLine,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts"

import { cn } from "@/lib/utils"

import {
  chartActiveTick,
  chartTagLabel,
  resolveReferenceValue,
  type ChartLabelRenderer,
} from "../chart-annotations"
import { ChartLegendLayout, useSeriesHighlight } from "../chart-legend"
import {
  autoTickInterval,
  ChartPlotArea,
  resolveResponsive,
  useCategoryLayout,
  useChartSize,
  type CategoryChartLayoutProps,
  type Responsive,
} from "../chart-responsive"
import {
  useChartTheme,
  type ChartTagVariant,
  type ChartTickVariant,
} from "../chart-theme"
import {
  ChartWindowSelectionOverlay,
  ChartZoomControls,
  useChartWindow,
} from "../chart-zoom"

export interface AreaChartDataPoint {
  label: string
  value: number
  [key: string]: unknown
}

export interface AreaChartProps extends CategoryChartLayoutProps {
  data: AreaChartDataPoint[]
  className?: string
  color?: string
  gradientFrom?: string
  gradientTo?: string
  gradientOpacity?: [number, number]
  showDots?: boolean
  showGrid?: boolean
  showTooltip?: boolean
  showCursor?: boolean
  valueFormatter?: (value: number) => string
  labelFormatter?: (label: string) => string
  yAxisDomain?: [number, number]
  yAxisTicks?: number[]
  animate?: boolean
  strokeWidth?: number
  dotRadius?: number
  xAxisAngle?: number
  curveType?: "linear" | "monotone" | "step"
  yAxisWidth?: Responsive<number>

  xAxisLabel?: string
  yAxisLabel?: string
  /**
   * Recharts tick interval for the category axis. The default draws every
   * label, which is unreadable past ~15 points — pass a number to draw
   * every Nth, or "preserveStartEnd" for just the ends.
   */
  xAxisInterval?: number | "preserveStart" | "preserveEnd" | "preserveStartEnd"
  showXAxis?: boolean
  showYAxis?: boolean
  /** Category to mark out on the axis. */
  activeLabel?: string | null
  /** How that tick is marked. Defaults to the chart theme. */
  activeTickVariant?: ChartTickVariant
  /** Horizontal marker: a literal value, or a statistic over the data. */
  referenceLine?: AreaChartReferenceLine | number | "avg" | "min" | "max" | null
}

/** Horizontal marker across the plot — a target, a budget, an average. */
export interface AreaChartReferenceLine {
  value: number | "avg" | "min" | "max"
  /** Text for the label, or your own renderer. Omit for a bare line. */
  label?: string | ChartLabelRenderer
  /** Shape of that label. Defaults to the chart theme. */
  labelVariant?: ChartTagVariant
  color?: string
  strokeDasharray?: string
  labelSide?: "left" | "right"
}

export function AreaChart({
  data,
  className,
  color = "var(--chart-3)",
  gradientFrom = "var(--chart-3)",
  gradientTo = "var(--chart-1)",
  gradientOpacity = [0.8, 0.1],
  showDots = false,
  showGrid = true,
  showTooltip = true,
  showCursor = true,
  valueFormatter = (value) => `${value}%`,
  labelFormatter = (label) => label,
  yAxisDomain,
  yAxisTicks,
  animate = true,
  strokeWidth = 2,
  dotRadius = 4,
  xAxisAngle = 0,
  aspectRatio = 2,
  minHeight = 180,
  overflow = "compress",
  minCategorySize = 24,
  zoomable = true,
  wheelZoom = false,
  showZoomControls = true,
  yAxisWidth,
  curveType = "linear",
  xAxisLabel,
  yAxisLabel,
  showXAxis = true,
  showYAxis = true,
  xAxisInterval = 0,
  activeLabel = null,
  activeTickVariant,
  referenceLine = null,
}: AreaChartProps) {
  const theme = useChartTheme({ activeTickVariant })
  const gradientId = React.useId().replace(/:/g, "")
  const patternId = React.useId().replace(/:/g, "")

  const { ref: sizeRef, width: containerWidth } = useChartSize<HTMLDivElement>()
  const layoutBox = useCategoryLayout({
    count: data.length,
    containerWidth,
    aspectRatio,
    minHeight,
    overflow,
    minCategorySize,
  })
  const resolvedYAxisWidth = resolveResponsive(
    yAxisWidth,
    containerWidth,
    containerWidth && containerWidth < 420 ? 38 : 50
  )
  const zoom = useChartWindow({
    length: data.length,
    // Scrolling already owns the pointer; two ways to move the same axis
    // just fight each other.
    disabled: !zoomable || layoutBox.scrolls,
    wheelZoom,
    insetStart: resolvedYAxisWidth + 10,
    insetEnd: 30,
  })
  const displayData = zoom.slice(data)

  // Calculate domain from the currently-visible (possibly zoomed) data if
  // not provided, so zooming auto-fits the Y-axis to the selected range.
  const calculatedDomain = React.useMemo(() => {
    if (yAxisDomain) return yAxisDomain
    const values = displayData.map((d) => d.value)
    const min = Math.min(...values)
    const max = Math.max(...values)
    const padding = (max - min) * 0.1
    return [
      Math.max(0, Math.floor((min - padding) / 10) * 10),
      Math.ceil((max + padding) / 10) * 10,
    ] as [number, number]
  }, [displayData, yAxisDomain])

  // Calculate ticks if not provided
  const calculatedTicks = React.useMemo(() => {
    if (yAxisTicks) return yAxisTicks
    const [min, max] = calculatedDomain
    const step = (max - min) / 4
    return Array.from({ length: 5 }, (_, i) => Math.round(min + step * i))
  }, [calculatedDomain, yAxisTicks])

  const reference = React.useMemo(() => {
    if (referenceLine == null) return null
    const spec: AreaChartReferenceLine =
      typeof referenceLine === "object"
        ? referenceLine
        : { value: referenceLine }
    const resolved = resolveReferenceValue(
      spec.value,
      displayData.map((d) => Number(d.value))
    )
    return resolved == null ? null : { ...spec, resolved }
  }, [referenceLine, displayData])

  const marksActiveTick = activeLabel != null
  const resolvedInterval =
    xAxisInterval ||
    autoTickInterval(
      displayData.length,
      layoutBox.plotWidth - resolvedYAxisWidth
    )

  return (
    <div ref={sizeRef} className={cn("group/chart relative w-full", className)}>
      <div className="relative" {...zoom.bind}>
        <ChartPlotArea layout={layoutBox}>
          <ResponsiveContainer width="100%" height={layoutBox.plotHeight}>
            <ComposedChart
              data={displayData}
              margin={{
                top: 20,
                right: 30,
                left: yAxisLabel ? 20 : 10,
                bottom: (xAxisAngle === 0 ? 20 : 60) + (xAxisLabel ? 24 : 0),
              }}
            >
              <defs>
                {/* Gradient fill - stronger fade */}
                <linearGradient
                  id={`gradient-${gradientId}`}
                  x1="0"
                  y1="0"
                  x2="0"
                  y2="1"
                >
                  <stop
                    offset="0%"
                    stopColor={gradientFrom}
                    stopOpacity={gradientOpacity[0]}
                  />
                  <stop
                    offset="100%"
                    stopColor={gradientTo}
                    stopOpacity={gradientOpacity[1]}
                  />
                </linearGradient>

                {/* Dotted pattern overlay */}
                <pattern
                  id={`pattern-${patternId}`}
                  x="0"
                  y="0"
                  width="6"
                  height="6"
                  patternUnits="userSpaceOnUse"
                >
                  <circle
                    cx="1.5"
                    cy="1.5"
                    r="0.75"
                    fill="rgba(255,255,255,0.3)"
                  />
                </pattern>
              </defs>

              {/* Grid */}
              {showGrid && (
                <CartesianGrid
                  strokeDasharray="3 3"
                  vertical={true}
                  horizontal={true}
                  stroke="hsl(var(--border))"
                  strokeOpacity={0.5}
                />
              )}

              {/* Y-Axis */}
              <YAxis
                domain={calculatedDomain}
                ticks={calculatedTicks}
                tickFormatter={valueFormatter}
                hide={!showYAxis}
                label={
                  yAxisLabel
                    ? {
                        value: yAxisLabel,
                        angle: -90,
                        position: "insideLeft",
                        fill: "var(--muted-foreground)",
                        fontSize: 12,
                      }
                    : undefined
                }
                axisLine={false}
                tickLine={false}
                tick={({ x, y, payload }) => (
                  <text
                    x={x}
                    y={y}
                    dy={4}
                    textAnchor="end"
                    className="fill-muted-foreground text-xs"
                  >
                    {valueFormatter(payload.value)}
                  </text>
                )}
                width={resolvedYAxisWidth}
              />

              {/* X-Axis */}
              <XAxis
                dataKey="label"
                hide={!showXAxis}
                axisLine={false}
                tickLine={false}
                label={
                  xAxisLabel
                    ? {
                        value: xAxisLabel,
                        position: "insideBottom",
                        offset: -12,
                        fill: "var(--muted-foreground)",
                        fontSize: 12,
                      }
                    : undefined
                }
                tick={
                  marksActiveTick
                    ? chartActiveTick(activeLabel, {
                        variant: theme.activeTickVariant,
                        background: theme.activeTickBackground,
                        foreground: theme.activeTickForeground,
                        formatter: labelFormatter,
                      })
                    : ({ x, y, payload }) => (
                        <text
                          x={x}
                          y={y}
                          dy={16}
                          textAnchor="middle"
                          className="fill-muted-foreground text-xs"
                        >
                          {labelFormatter(payload.value)}
                        </text>
                      )
                }
                height={xAxisAngle === 0 ? 30 : 60}
                interval={resolvedInterval}
              />

              {reference && (
                <ReferenceLine
                  y={reference.resolved}
                  stroke={reference.color ?? "var(--muted-foreground)"}
                  strokeDasharray={reference.strokeDasharray ?? "2 6"}
                  ifOverflow="extendDomain"
                  label={
                    typeof reference.label === "function"
                      ? reference.label
                      : reference.label
                        ? chartTagLabel(reference.label, {
                            variant: reference.labelVariant ?? theme.tagVariant,
                            side: reference.labelSide ?? "left",
                            background: theme.tagBackground,
                            foreground: theme.tagForeground,
                          })
                        : undefined
                  }
                />
              )}

              {/* Tooltip with cursor line */}
              {showTooltip && (
                <Tooltip
                  cursor={
                    showCursor
                      ? {
                          stroke: "hsl(var(--muted-foreground))",
                          strokeWidth: 1,
                          strokeDasharray: "4 4",
                        }
                      : false
                  }
                  content={({ active, payload, label }) => {
                    if (!active || !payload?.length) return null
                    return (
                      <div className="bg-background rounded-lg border px-3 py-2 shadow-lg">
                        <p className="text-foreground text-sm font-medium">
                          {labelFormatter(label)}
                        </p>
                        {payload.map((entry, index) => (
                          <p
                            key={index}
                            className="text-sm"
                            style={{ color: entry.color }}
                          >
                            {entry.name}:{" "}
                            {valueFormatter(entry.value as number)}
                          </p>
                        ))}
                      </div>
                    )
                  }}
                />
              )}

              {/* Area fill with gradient */}
              <Area
                type={curveType}
                dataKey="value"
                stroke="none"
                fill={`url(#gradient-${gradientId})`}
                fillOpacity={1}
                isAnimationActive={animate}
                animationBegin={0}
                animationDuration={1500}
                animationEasing="ease-out"
              />

              {/* Dotted pattern overlay */}
              <Area
                type={curveType}
                dataKey="value"
                stroke="none"
                fill={`url(#pattern-${patternId})`}
                fillOpacity={1}
                isAnimationActive={animate}
                animationBegin={0}
                animationDuration={1500}
                animationEasing="ease-out"
              />

              {/* Line on top with dots */}
              <Line
                type={curveType}
                dataKey="value"
                stroke={color}
                strokeWidth={strokeWidth}
                dot={
                  showDots
                    ? {
                        r: dotRadius,
                        fill: "hsl(var(--background))",
                        stroke: color,
                        strokeWidth: 2,
                      }
                    : false
                }
                activeDot={{
                  r: 4,
                  fill: color,
                  stroke: "hsl(var(--background))",
                  strokeWidth: 2,
                }}
                isAnimationActive={animate}
                animationBegin={200}
                animationDuration={1800}
                animationEasing="ease-out"
              />
            </ComposedChart>
          </ResponsiveContainer>
        </ChartPlotArea>

        <ChartWindowSelectionOverlay
          selection={zoom.selection}
          insetStart={resolvedYAxisWidth + 10}
          insetEnd={30}
        />
      </div>

      {showZoomControls && !layoutBox.scrolls && zoomable && (
        <ChartZoomControls
          onZoomIn={zoom.zoomIn}
          onZoomOut={zoom.zoomOut}
          onReset={zoom.reset}
          isZoomed={zoom.isZoomed}
        />
      )}
    </div>
  )
}

// Helper function to generate chart data
export function generateAreaChartData(
  labels: string[],
  values: number[]
): AreaChartDataPoint[] {
  return labels.map((label, index) => ({
    label,
    value: values[index] ?? 0,
  }))
}

// ============================================
// Multi-Series Area Chart
// ============================================

export interface MultiAreaChartSeries {
  name: string
  dataKey: string
  color: string
  gradientFrom?: string
  gradientTo?: string
}

export interface MultiAreaChartDataPoint {
  label: string
  [key: string]: string | number
}

export interface MultiAreaChartProps extends CategoryChartLayoutProps {
  data: MultiAreaChartDataPoint[]
  series: MultiAreaChartSeries[]
  className?: string
  showGrid?: boolean
  showTooltip?: boolean
  showCursor?: boolean
  showLegend?: boolean
  /** Side the legend sits on. A side legend eats width a narrow container
   *  doesn't have, so it falls to the bottom below `md` by default. */
  legendPosition?: Responsive<"top" | "bottom" | "left" | "right">
  valueFormatter?: (value: number) => string
  labelFormatter?: (label: string) => string
  yAxisDomain?: [number, number]
  yAxisTicks?: number[]
  animate?: boolean
  strokeWidth?: number
  xAxisAngle?: number
  yAxisWidth?: Responsive<number>
  curveType?: "linear" | "monotone" | "step"
  stacked?: boolean
  gradientOpacity?: [number, number]
}

export function MultiAreaChart({
  data,
  series,
  className,
  showGrid = true,
  showTooltip = true,
  showCursor = true,
  showLegend = true,
  legendPosition = { base: "bottom", md: "right" },
  valueFormatter = (value) => `${value}`,
  labelFormatter = (label) => label,
  yAxisDomain,
  yAxisTicks,
  animate = true,
  strokeWidth = 2,
  xAxisAngle = 0,
  aspectRatio = 2,
  minHeight = 180,
  overflow = "compress",
  minCategorySize = 24,
  zoomable = true,
  wheelZoom = false,
  showZoomControls = true,
  yAxisWidth,
  curveType = "monotone",
  stacked = false,
  gradientOpacity = [0.6, 0.1],
}: MultiAreaChartProps) {
  const baseId = React.useId().replace(/:/g, "")

  const { ref: sizeRef, width: containerWidth } = useChartSize<HTMLDivElement>()
  const layoutBox = useCategoryLayout({
    count: data.length,
    containerWidth,
    aspectRatio,
    minHeight,
    overflow,
    minCategorySize,
  })
  const resolvedLegendPosition = resolveResponsive(
    legendPosition,
    containerWidth,
    "right"
  )
  const resolvedYAxisWidth = resolveResponsive(
    yAxisWidth,
    containerWidth,
    containerWidth && containerWidth < 420 ? 38 : 50
  )
  const zoom = useChartWindow({
    length: data.length,
    disabled: !zoomable || layoutBox.scrolls,
    wheelZoom,
    insetStart: resolvedYAxisWidth + 10,
    insetEnd: 30,
  })
  const displayData = zoom.slice(data)
  // Legend highlight: click a series to emphasize it (others fade but stay
  // drawn so the stack layout never shifts), hover to preview — Plotly-style.
  const highlight = useSeriesHighlight()

  // Calculate domain from the currently-visible (possibly zoomed) data
  // across ALL series — highlighting only fades series, it never removes
  // them, so the Y-axis stays put as you emphasize different series.
  const calculatedDomain = React.useMemo(() => {
    if (yAxisDomain) return yAxisDomain
    const allValues = displayData.flatMap((d) =>
      series.map((s) => (d[s.dataKey] as number) || 0)
    )
    const min = Math.min(...allValues)
    const max = Math.max(...allValues)
    const padding = (max - min) * 0.1
    return [
      Math.max(0, Math.floor((min - padding) / 10) * 10),
      Math.ceil((max + padding) / 10) * 10,
    ] as [number, number]
  }, [displayData, series, yAxisDomain])

  const calculatedTicks = React.useMemo(() => {
    if (yAxisTicks) return yAxisTicks
    const [min, max] = calculatedDomain
    const step = (max - min) / 4
    return Array.from({ length: 5 }, (_, i) => Math.round(min + step * i))
  }, [calculatedDomain, yAxisTicks])

  return (
    <div ref={sizeRef} className={cn("group/chart relative w-full", className)}>
      <ChartLegendLayout
        position={resolvedLegendPosition}
        show={showLegend && series.length > 1}
        legend={
          <div
            className={cn(
              "flex gap-3",
              legendPosition === "left" || legendPosition === "right"
                ? "flex-col items-start"
                : "flex-wrap items-center justify-center",
              legendPosition === "top" && "pb-4",
              legendPosition === "bottom" && "pt-4",
              legendPosition === "left" && "pr-4",
              legendPosition === "right" && "pl-4"
            )}
          >
            {series.map((s) => (
              <button
                key={s.dataKey}
                type="button"
                onClick={() => highlight.toggle(s.name)}
                onMouseEnter={() => highlight.setHovered(s.name)}
                onMouseLeave={() => highlight.setHovered(null)}
                className={cn(
                  "flex items-center gap-2 text-sm transition-opacity hover:opacity-80",
                  !highlight.isActive(s.name) && "opacity-40"
                )}
              >
                <div
                  className="size-3 rounded-sm"
                  style={{ backgroundColor: s.color }}
                />
                <span className="text-muted-foreground">{s.name}</span>
              </button>
            ))}
          </div>
        }
      >
        <div className="relative w-full flex-1" {...zoom.bind}>
          <ChartPlotArea layout={layoutBox}>
            <ResponsiveContainer width="100%" height={layoutBox.plotHeight}>
              <ComposedChart
                data={displayData}
                margin={{
                  top: 20,
                  right: 30,
                  left: 10,
                  bottom: xAxisAngle === 0 ? 20 : 60,
                }}
              >
                <defs>
                  {series.map((s, i) => (
                    <linearGradient
                      key={s.dataKey}
                      id={`gradient-${baseId}-${i}`}
                      x1="0"
                      y1="0"
                      x2="0"
                      y2="1"
                    >
                      <stop
                        offset="0%"
                        stopColor={s.gradientFrom || s.color}
                        stopOpacity={gradientOpacity[0]}
                      />
                      <stop
                        offset="100%"
                        stopColor={s.gradientTo || s.color}
                        stopOpacity={gradientOpacity[1]}
                      />
                    </linearGradient>
                  ))}
                  {/* Dot pattern overlay */}
                  <pattern
                    id={`pattern-${baseId}`}
                    x="0"
                    y="0"
                    width="6"
                    height="6"
                    patternUnits="userSpaceOnUse"
                  >
                    <circle
                      cx="1.5"
                      cy="1.5"
                      r="0.75"
                      fill="rgba(255,255,255,0.25)"
                    />
                  </pattern>
                </defs>

                {showGrid && (
                  <CartesianGrid
                    strokeDasharray="3 3"
                    vertical={true}
                    horizontal={true}
                    stroke="hsl(var(--border))"
                    strokeOpacity={0.5}
                  />
                )}

                <YAxis
                  domain={calculatedDomain}
                  ticks={calculatedTicks}
                  tickFormatter={valueFormatter}
                  axisLine={false}
                  tickLine={false}
                  tick={({ x, y, payload }) => (
                    <text
                      x={x}
                      y={y}
                      dy={4}
                      textAnchor="end"
                      className="fill-muted-foreground text-xs"
                    >
                      {valueFormatter(payload.value)}
                    </text>
                  )}
                  width={50}
                />

                <XAxis
                  dataKey="label"
                  axisLine={false}
                  tickLine={false}
                  tick={({ x, y, payload }) => (
                    <text
                      x={x}
                      y={y}
                      dy={16}
                      textAnchor="middle"
                      className="fill-muted-foreground text-xs"
                    >
                      {labelFormatter(payload.value)}
                    </text>
                  )}
                  height={xAxisAngle === 0 ? 30 : 60}
                  interval={0}
                />

                {showTooltip && (
                  <Tooltip
                    cursor={
                      showCursor
                        ? {
                            stroke: "hsl(var(--muted-foreground))",
                            strokeWidth: 1,
                            strokeDasharray: "4 4",
                          }
                        : false
                    }
                    content={({ active, payload, label }) => {
                      if (!active || !payload?.length) return null
                      return (
                        <div className="bg-background rounded-lg border px-3 py-2 shadow-lg">
                          <p className="text-foreground mb-1 text-sm font-medium">
                            {labelFormatter(label)}
                          </p>
                          {payload.map((entry, index) => (
                            <div
                              key={index}
                              className={cn(
                                "flex items-center gap-2 text-sm transition-opacity",
                                highlight.isDimmed(entry.name as string) &&
                                  "opacity-40"
                              )}
                            >
                              <div
                                className="size-2 rounded-full"
                                style={{ backgroundColor: entry.color }}
                              />
                              <span className="text-muted-foreground">
                                {entry.name}:
                              </span>
                              <span style={{ color: entry.color }}>
                                {valueFormatter(entry.value as number)}
                              </span>
                            </div>
                          ))}
                        </div>
                      )
                    }}
                  />
                )}

                {/* Render areas in reverse order so first series is on top.
              All series always render — the focused one stays vivid while
              the rest fade (never removed, so the layout never shifts). */}
                {[...series].reverse().map((s, i) => (
                  <Area
                    key={`${s.dataKey}-fill`}
                    type={curveType}
                    dataKey={s.dataKey}
                    name={s.name}
                    stroke={s.color}
                    strokeWidth={strokeWidth}
                    fill={`url(#gradient-${baseId}-${series.indexOf(s)})`}
                    fillOpacity={1}
                    stackId={stacked ? "stack" : undefined}
                    isAnimationActive={animate}
                    animationBegin={i * 100}
                    animationDuration={1500}
                    animationEasing="ease-out"
                    className={cn(
                      "transition-opacity duration-200",
                      highlight.isDimmed(s.name) && "opacity-30"
                    )}
                    activeDot={{
                      r: 4,
                      fill: s.color,
                      stroke: "hsl(var(--background))",
                      strokeWidth: 2,
                    }}
                  />
                ))}

                {/* Dot pattern overlay for each series */}
                {[...series].reverse().map((s, i) => (
                  <Area
                    key={`${s.dataKey}-pattern`}
                    type={curveType}
                    dataKey={s.dataKey}
                    stroke="none"
                    fill={`url(#pattern-${baseId})`}
                    fillOpacity={1}
                    stackId={stacked ? "stack-pattern" : undefined}
                    isAnimationActive={animate}
                    animationBegin={i * 100}
                    animationDuration={1500}
                    animationEasing="ease-out"
                    legendType="none"
                    tooltipType="none"
                    className={cn(
                      "transition-opacity duration-200",
                      highlight.isDimmed(s.name) && "opacity-30"
                    )}
                  />
                ))}
              </ComposedChart>
            </ResponsiveContainer>
          </ChartPlotArea>

          <ChartWindowSelectionOverlay
            selection={zoom.selection}
            insetStart={resolvedYAxisWidth + 10}
            insetEnd={30}
          />

          {showZoomControls && !layoutBox.scrolls && zoomable && (
            <ChartZoomControls
              onZoomIn={zoom.zoomIn}
              onZoomOut={zoom.zoomOut}
              onReset={zoom.reset}
              isZoomed={zoom.isZoomed}
            />
          )}
        </div>
      </ChartLegendLayout>
    </div>
  )
}

"use client"

import * as React from "react"
import { scaleLinear } from "d3-scale"

import { cn } from "@/lib/utils"

import { ChartAxis } from "../chart-axis"
import type { BaseChartProps, ChartConfig } from "../chart-config"
import { ChartContainer } from "../chart-container"
import { ChartGrid } from "../chart-grid"
import {
  ChartLegend,
  ChartLegendLayout,
  useSeriesHighlight,
  type LegendItem,
} from "../chart-legend"
import { ChartTooltipContent } from "../chart-tooltip"
import {
  ChartZoomResetButton,
  ChartZoomSelectionRect,
  useChartZoom,
} from "../chart-zoom"

export interface ScatterChartDataPoint {
  x: number
  y: number
  size?: number
  label?: string
  [key: string]: unknown
}

export interface ScatterChartSeries {
  name: string
  data: ScatterChartDataPoint[]
  color?: string
  symbol?: "circle" | "square" | "triangle" | "diamond" | "cross"
  size?: number
}

export interface ScatterChartProps extends Omit<BaseChartProps, "config"> {
  data: ScatterChartSeries[]
  xAxisLabel?: string
  yAxisLabel?: string
  sizeRange?: [number, number]
  symbol?: "circle" | "square" | "triangle" | "diamond" | "cross"
  size?: number
  showTrendLine?: boolean
  config?: ChartConfig
}

// SVG path generators for different symbols
// Default colors using CSS variables
const DEFAULT_COLORS = [
  "var(--chart-1)",
  "var(--chart-2)",
  "var(--chart-3)",
  "var(--chart-4)",
  "var(--chart-5)",
]

const symbolPaths: Record<string, (size: number) => string> = {
  circle: (s) => {
    const r = s / 2
    return `M 0,${-r} A ${r},${r} 0 1,1 0,${r} A ${r},${r} 0 1,1 0,${-r}`
  },
  square: (s) => {
    const h = s / 2
    return `M ${-h},${-h} L ${h},${-h} L ${h},${h} L ${-h},${h} Z`
  },
  triangle: (s) => {
    const h = s / 2
    return `M 0,${-h} L ${h},${h} L ${-h},${h} Z`
  },
  diamond: (s) => {
    const h = s / 2
    return `M 0,${-h} L ${h},0 L 0,${h} L ${-h},0 Z`
  },
  cross: (s) => {
    const h = s / 2
    const w = s / 6
    return `M ${-w},${-h} L ${w},${-h} L ${w},${-w} L ${h},${-w} L ${h},${w} L ${w},${w} L ${w},${h} L ${-w},${h} L ${-w},${w} L ${-h},${w} L ${-h},${-w} L ${-w},${-w} Z`
  },
}

export function ScatterChart({
  data,
  config,
  className,
  width = 600,
  height = 400,
  margin = { top: 20, right: 20, bottom: 50, left: 60 },
  showGrid = true,
  showTooltip = true,
  showLegend = true,
  legendPosition = "right",
  xAxisLabel,
  yAxisLabel,
  sizeRange = [6, 20],
  symbol = "circle",
  size = 8,
  showTrendLine = false,
}: ScatterChartProps) {
  const svgRef = React.useRef<SVGSVGElement>(null)
  const [hoveredPoint, setHoveredPoint] = React.useState<{
    seriesIndex: number
    pointIndex: number
    point: ScatterChartDataPoint
    x: number
    y: number
  } | null>(null)
  // Legend highlight: click a series to emphasize it (others fade but stay
  // drawn), hover to preview — Plotly-style. `focused` = hover ?? selection.
  const highlight = useSeriesHighlight()
  const [zoomDomain, setZoomDomain] = React.useState<[number, number] | null>(
    null
  )
  const isZoomed = zoomDomain !== null

  const innerWidth = width - margin.left - margin.right
  const innerHeight = height - margin.top - margin.bottom

  // Apply the active zoom window (if any) by filtering each series down to
  // the selected x-range before it reaches the scales.
  const plotData = React.useMemo((): ScatterChartSeries[] => {
    if (!zoomDomain) return data
    const [lo, hi] = zoomDomain
    return data.map((series) => ({
      ...series,
      data: series.data.filter((d) => d.x >= lo && d.x <= hi),
    }))
  }, [data, zoomDomain])

  // Flatten currently-visible data points for scales
  const allPoints = plotData.flatMap((series) => series.data)

  // Scales
  const xScale = React.useMemo(() => {
    const xValues = allPoints.map((d) => d.x)
    const xMin = Math.min(...xValues)
    const xMax = Math.max(...xValues)
    const padding = (xMax - xMin) * 0.1
    return scaleLinear()
      .domain([xMin - padding, xMax + padding])
      .range([0, innerWidth])
      .nice()
  }, [allPoints, innerWidth])

  const yScale = React.useMemo(() => {
    const yValues = allPoints.map((d) => d.y)
    const yMin = Math.min(...yValues)
    const yMax = Math.max(...yValues)
    const padding = (yMax - yMin) * 0.1
    return scaleLinear()
      .domain([yMin - padding, yMax + padding])
      .range([innerHeight, 0])
      .nice()
  }, [allPoints, innerHeight])

  // Size scale for bubble chart
  const sizeScale = React.useMemo(() => {
    const sizeValues = allPoints.map((d) => d.size ?? 1)
    const sizeMin = Math.min(...sizeValues)
    const sizeMax = Math.max(...sizeValues)
    return scaleLinear().domain([sizeMin, sizeMax]).range(sizeRange)
  }, [allPoints, sizeRange])

  // Calculate trend line (simple linear regression)
  const trendLine = React.useMemo(() => {
    if (!showTrendLine) return null

    const n = allPoints.length
    if (n < 2) return null

    const sumX = allPoints.reduce((acc, d) => acc + d.x, 0)
    const sumY = allPoints.reduce((acc, d) => acc + d.y, 0)
    const sumXY = allPoints.reduce((acc, d) => acc + d.x * d.y, 0)
    const sumX2 = allPoints.reduce((acc, d) => acc + d.x * d.x, 0)

    const slope = (n * sumXY - sumX * sumY) / (n * sumX2 - sumX * sumX)
    const intercept = (sumY - slope * sumX) / n

    const xDomain = xScale.domain()
    return {
      x1: xDomain[0],
      y1: slope * xDomain[0] + intercept,
      x2: xDomain[1],
      y2: slope * xDomain[1] + intercept,
    }
  }, [allPoints, showTrendLine, xScale])

  // Drag-to-zoom: converts the pixel drag range into a data-domain range
  // and narrows the view to it. Re-zooming while already zoomed narrows
  // further (inverted against the current, already-zoomed scale).
  const zoom = useChartZoom({
    svgRef,
    marginLeft: margin.left,
    innerWidth,
    onZoom: ({ x0, x1 }) => {
      const lo = xScale.invert(x0)
      const hi = xScale.invert(x1)
      const hasPointsInRange = allPoints.some((d) => d.x >= lo && d.x <= hi)
      if (hasPointsInRange) setZoomDomain([lo, hi])
    },
    onReset: () => setZoomDomain(null),
  })

  // Legend items
  const legendItems: LegendItem[] = data.map((series, index) => ({
    name: series.name,
    color: series.color ?? DEFAULT_COLORS[index % DEFAULT_COLORS.length],
  }))

  return (
    <ChartContainer
      config={config}
      className={cn("relative !aspect-auto", className)}
    >
      {/* Plot + legend layout — legend sits on `legendPosition` side, click
          a series to highlight it (others fade), click again to restore */}
      <ChartLegendLayout
        position={legendPosition}
        show={showLegend && data.length > 1}
        legend={
          <ChartLegend
            items={legendItems}
            position={legendPosition}
            onItemHover={highlight.setHovered}
            onItemClick={highlight.toggle}
            isItemActive={highlight.isActive}
          />
        }
      >
        <svg
          ref={svgRef}
          viewBox={`0 0 ${width} ${height}`}
          className="w-full overflow-visible select-none"
          onMouseDown={zoom.handlers.onMouseDown}
          onMouseMove={zoom.handlers.onMouseMove}
          onMouseUp={zoom.handlers.onMouseUp}
          onMouseLeave={zoom.handlers.onMouseLeave}
          onDoubleClick={zoom.handlers.onDoubleClick}
        >
          <g transform={`translate(${margin.left}, ${margin.top})`}>
            {/* Invisible background for mouse events */}
            <rect
              width={innerWidth}
              height={innerHeight}
              fill="transparent"
              className="cursor-crosshair"
            />

            {/* Drag-to-zoom selection rectangle */}
            <ChartZoomSelectionRect
              range={zoom.dragRange}
              height={innerHeight}
            />

            {/* Grid */}
            {showGrid && (
              <ChartGrid
                xScale={xScale}
                yScale={yScale}
                width={innerWidth}
                height={innerHeight}
              />
            )}

            {/* Trend line */}
            {trendLine && (
              <line
                x1={xScale(trendLine.x1)}
                y1={yScale(trendLine.y1)}
                x2={xScale(trendLine.x2)}
                y2={yScale(trendLine.y2)}
                stroke="currentColor"
                strokeWidth={2}
                strokeDasharray="6,4"
                className="text-muted-foreground/50"
              />
            )}

            {/* Points */}
            {data.map((series, seriesIndex) => {
              const seriesColor =
                series.color ??
                DEFAULT_COLORS[seriesIndex % DEFAULT_COLORS.length]
              const seriesSymbol = series.symbol ?? symbol
              const isActive = highlight.isActive(series.name)
              const plotSeries = plotData[seriesIndex]

              return plotSeries.data.map((point, pointIndex) => {
                const pointSize =
                  point.size !== undefined
                    ? sizeScale(point.size)
                    : (series.size ?? size)
                const isHovered =
                  hoveredPoint?.seriesIndex === seriesIndex &&
                  hoveredPoint?.pointIndex === pointIndex

                return (
                  <g
                    key={`${seriesIndex}-${pointIndex}`}
                    transform={`translate(${xScale(point.x)}, ${yScale(point.y)})`}
                    className={cn(
                      "cursor-pointer transition-all duration-200",
                      !isActive && "opacity-30"
                    )}
                    onMouseEnter={() =>
                      setHoveredPoint({
                        seriesIndex,
                        pointIndex,
                        point,
                        x: xScale(point.x),
                        y: yScale(point.y),
                      })
                    }
                    onMouseLeave={() => setHoveredPoint(null)}
                  >
                    <path
                      d={symbolPaths[seriesSymbol](
                        isHovered ? pointSize * 1.3 : pointSize
                      )}
                      fill={seriesColor}
                      stroke="white"
                      strokeWidth={1}
                    />
                  </g>
                )
              })
            })}

            {/* X Axis */}
            <ChartAxis
              scale={xScale}
              orientation="bottom"
              transform={`translate(0, ${innerHeight})`}
              label={xAxisLabel}
            />

            {/* Y Axis */}
            <ChartAxis scale={yScale} orientation="left" label={yAxisLabel} />
          </g>
        </svg>

        {/* Tooltip */}
        {showTooltip && hoveredPoint && (
          <div
            className="pointer-events-none absolute z-50"
            style={{
              left: margin.left + hoveredPoint.x + 15,
              top: margin.top + hoveredPoint.y - 10,
            }}
          >
            <div className="border-border/50 bg-background rounded-lg border px-2.5 py-1.5 text-xs shadow-xl">
              <div className="mb-1 font-medium">
                {hoveredPoint.point.label ??
                  data[hoveredPoint.seriesIndex].name}
              </div>
              <div className="text-muted-foreground">
                x: {hoveredPoint.point.x.toLocaleString()}
              </div>
              <div className="text-muted-foreground">
                y: {hoveredPoint.point.y.toLocaleString()}
              </div>
            </div>
          </div>
        )}

        <ChartZoomResetButton
          visible={isZoomed}
          onReset={() => setZoomDomain(null)}
        />
      </ChartLegendLayout>
    </ChartContainer>
  )
}

"use client"

import * as React from "react"
import { arc, pie, type PieArcDatum } from "d3-shape"

import { cn } from "@/lib/utils"

import type { BaseChartProps, ChartConfig } from "../chart-config"
import { ChartContainer } from "../chart-container"
import {
  ChartLegend,
  ChartLegendLayout,
  useSeriesHighlight,
  type LegendItem,
} from "../chart-legend"

// ============================================================================
// Types & Interfaces
// ============================================================================

export interface PieChartDataPoint {
  label: string
  value: number
  color?: string
  [key: string]: unknown
}

export interface PieChartProps extends BaseChartProps {
  /** Data points for the pie chart */
  data: PieChartDataPoint[]
  /** Inner radius (0 for pie, > 0 for donut) */
  innerRadius?: number
  /** Outer radius */
  outerRadius?: number
  /** Padding angle between segments */
  padAngle?: number
  /** Corner radius for rounded segments */
  cornerRadius?: number
  /** Starting angle in radians */
  startAngle?: number
  /** Ending angle in radians */
  endAngle?: number
  /** Sort values by size */
  sortValues?: boolean
  /** Show labels on segments */
  showLabels?: boolean
  /** Label display type */
  labelType?: "percent" | "value" | "label"
  /** Chart variant */
  variant?:
    | "default"
    | "donut"
    | "donut-active"
    | "donut-text"
    | "label"
    | "interactive"
  /** Active segment index (for donut-active variant) */
  activeIndex?: number
  /** Center label text (for donut-text variant) */
  centerLabel?: React.ReactNode
  /** Center value text (for donut-text variant) */
  centerValue?: React.ReactNode
  /** Show total in center (for donut-text variant) */
  showTotal?: boolean
  /** Value formatter */
  valueFormatter?: (value: number, total: number) => string
  /** Callback when segment is clicked */
  onSegmentClick?: (data: PieChartDataPoint, index: number) => void
  /** Interactive selection options (for interactive variant) */
  selectionOptions?: { key: string; label: string }[]
  /** Selected key (for interactive variant) */
  selectedKey?: string
  /** On selection change (for interactive variant) */
  onSelectionChange?: (key: string) => void
}

// ============================================================================
// Constants
// ============================================================================

const DEFAULT_COLORS = [
  "var(--chart-1)",
  "var(--chart-2)",
  "var(--chart-3)",
  "var(--chart-4)",
  "var(--chart-5)",
]

// ============================================================================
// Component
// ============================================================================

export function PieChart({
  data,
  config,
  className,
  width = 400,
  height = 400,
  margin: marginProp,
  showTooltip = true,
  showLegend: showLegendProp,
  legendPosition = "right",
  innerRadius: innerRadiusProp,
  outerRadius: outerRadiusProp,
  padAngle: padAngleProp,
  cornerRadius: cornerRadiusProp,
  startAngle = 0,
  endAngle = 2 * Math.PI,
  sortValues = false,
  showLabels: showLabelsProp,
  labelType = "percent",
  variant = "default",
  activeIndex: activeIndexProp,
  centerLabel,
  centerValue,
  showTotal = true,
  valueFormatter = (value, total) => `${((value / total) * 100).toFixed(1)}%`,
  onSegmentClick,
  selectionOptions,
  selectedKey,
  onSelectionChange,
}: PieChartProps) {
  const [hoveredIndex, setHoveredIndex] = React.useState<number | null>(null)
  const [internalActiveIndex, setInternalActiveIndex] = React.useState(0)
  const [internalSelectedKey, setInternalSelectedKey] = React.useState(
    selectedKey ?? selectionOptions?.[0]?.key ?? ""
  )
  // Legend/slice click-to-highlight: nothing selected shows all segments, a
  // pinned label emphasizes only that one (others fade but stay drawn).
  // Independent of the "interactive" variant's selectedKey mechanism, which is
  // always-one-active with no "show all" state. Hover-driven slice expansion /
  // center-text still runs off `hoveredIndex` below, so this hook is used for
  // the selection (isolate) state only — `highlight.hovered` stays unused.
  const highlight = useSeriesHighlight()

  // Variant-specific defaults
  const getVariantDefaults = () => {
    switch (variant) {
      case "donut":
        return {
          innerRadius: 60,
          padAngle: 0.02,
          cornerRadius: 0,
          showLabels: false,
          showLegend: true,
          margin: { top: 20, right: 20, bottom: 20, left: 20 },
        }
      case "donut-active":
        return {
          innerRadius: 60,
          padAngle: 0.02,
          cornerRadius: 0,
          showLabels: false,
          showLegend: true,
          margin: { top: 20, right: 20, bottom: 20, left: 20 },
        }
      case "donut-text":
        return {
          innerRadius: 60,
          padAngle: 0.02,
          cornerRadius: 0,
          showLabels: false,
          showLegend: true,
          margin: { top: 20, right: 20, bottom: 20, left: 20 },
        }
      case "label":
        return {
          innerRadius: 0,
          padAngle: 0.02,
          cornerRadius: 0,
          showLabels: true,
          showLegend: true,
          margin: { top: 40, right: 40, bottom: 40, left: 40 },
        }
      case "interactive":
        return {
          innerRadius: 60,
          padAngle: 0.02,
          cornerRadius: 0,
          showLabels: false,
          showLegend: false,
          margin: { top: 20, right: 20, bottom: 20, left: 20 },
        }
      default:
        return {
          innerRadius: 0,
          padAngle: 0.02,
          cornerRadius: 4,
          showLabels: false,
          showLegend: true,
          margin: { top: 20, right: 20, bottom: 20, left: 20 },
        }
    }
  }

  const defaults = getVariantDefaults()
  const margin = marginProp ?? defaults.margin
  const innerRadius = innerRadiusProp ?? defaults.innerRadius
  const padAngle = padAngleProp ?? defaults.padAngle
  const cornerRadius = cornerRadiusProp ?? defaults.cornerRadius
  const showLabels = showLabelsProp ?? defaults.showLabels
  const showLegend = showLegendProp ?? defaults.showLegend

  const innerWidth = width - margin.left - margin.right
  const innerHeight = height - margin.top - margin.bottom
  const radius = Math.min(innerWidth, innerHeight) / 2
  const outerRadius = outerRadiusProp ?? radius

  // Handle interactive variant selection
  const effectiveSelectedKey = selectedKey ?? internalSelectedKey
  const handleSelectionChange = (key: string) => {
    setInternalSelectedKey(key)
    onSelectionChange?.(key)
    // Update active index when selection changes in interactive mode
    const newIndex = data.findIndex(
      (d) => d.label.toLowerCase() === key.toLowerCase()
    )
    if (newIndex >= 0) {
      setInternalActiveIndex(newIndex)
    }
  }

  // Calculate total
  const total = data.reduce((sum, d) => sum + d.value, 0)

  // Active index handling
  const activeIndex =
    variant === "donut-active" || variant === "interactive"
      ? (activeIndexProp ?? internalActiveIndex)
      : hoveredIndex

  // Index of the isolated segment, used as a fallback for center-text
  // display when nothing is actively hovered. Doesn't apply to
  // "donut-active"/"interactive" variants, which manage their own
  // always-one-active index.
  const isolatedIndex = React.useMemo(() => {
    if (variant === "donut-active" || variant === "interactive") return null
    if (highlight.selected === null) return null
    const idx = data.findIndex((d) => d.label === highlight.selected)
    return idx >= 0 ? idx : null
  }, [variant, highlight.selected, data])

  // Create pie generator
  const pieGenerator = React.useMemo(() => {
    const gen = pie<PieChartDataPoint>()
      .value((d) => d.value)
      .padAngle(padAngle)
      .startAngle(startAngle)
      .endAngle(endAngle)

    if (sortValues) {
      return gen.sort((a, b) => b.value - a.value)
    }
    return gen.sort(null)
  }, [padAngle, startAngle, endAngle, sortValues])

  // Arc datum type
  type ArcDatum = PieArcDatum<PieChartDataPoint>

  // Create arc generators
  const arcGenerator = arc<ArcDatum>()
    .innerRadius(innerRadius)
    .outerRadius(outerRadius)
    .cornerRadius(cornerRadius)

  // Active arc (slightly larger)
  const activeArcGenerator = arc<ArcDatum>()
    .innerRadius(innerRadius)
    .outerRadius(outerRadius + 10)
    .cornerRadius(cornerRadius)

  // Interactive double-ring arc for active segment
  const interactiveOuterArcGenerator = arc<ArcDatum>()
    .innerRadius(outerRadius + 12)
    .outerRadius(outerRadius + 25)
    .cornerRadius(cornerRadius)

  // Label arc (for positioning external labels)
  const labelArcGenerator = arc<ArcDatum>()
    .innerRadius(outerRadius * 0.7)
    .outerRadius(outerRadius * 0.7)

  // External label arc (for label variant)
  const externalLabelArcGenerator = arc<ArcDatum>()
    .innerRadius(outerRadius + 15)
    .outerRadius(outerRadius + 15)

  const arcs = pieGenerator(data)

  // Get color for segment
  const getColor = (d: PieChartDataPoint, index: number): string => {
    if (d.color) return d.color
    const configItem = config?.[d.label]
    if (configItem && "color" in configItem && configItem.color) {
      return configItem.color
    }
    return DEFAULT_COLORS[index % DEFAULT_COLORS.length]
  }

  // Format label
  const formatLabel = (d: PieChartDataPoint): string => {
    switch (labelType) {
      case "percent":
        return valueFormatter(d.value, total)
      case "value":
        return d.value.toLocaleString()
      case "label":
        return d.label
      default:
        return ""
    }
  }

  // Legend items
  const legendItems: LegendItem[] = data.map((d, i) => ({
    name: d.label,
    color: getColor(d, i),
    value: d.value,
  }))

  // Center content for donut-text variant
  const displayedCenterValue = React.useMemo(() => {
    if (variant === "donut-text" || variant === "interactive") {
      const idx = activeIndex ?? isolatedIndex
      if (idx !== null) {
        return data[idx]?.value.toLocaleString() ?? ""
      }
      return centerValue ?? (showTotal ? total.toLocaleString() : null)
    }
    return null
  }, [variant, activeIndex, isolatedIndex, data, centerValue, showTotal, total])

  const displayedCenterLabel = React.useMemo(() => {
    if (variant === "donut-text" || variant === "interactive") {
      const idx = activeIndex ?? isolatedIndex
      if (idx !== null) {
        return data[idx]?.label ?? ""
      }
      return centerLabel ?? (showTotal ? "Total" : null)
    }
    return null
  }, [variant, activeIndex, isolatedIndex, data, centerLabel, showTotal])

  // Handle segment interaction
  const handleSegmentEnter = (index: number) => {
    if (variant === "donut-active" || variant === "interactive") {
      setInternalActiveIndex(index)
    }
    setHoveredIndex(index)
  }

  const handleSegmentLeave = () => {
    setHoveredIndex(null)
  }

  // Isolate a segment by label. The "interactive" variant already has its
  // own always-one-active selection mechanism (selectionOptions/selectedKey)
  // driven by a dropdown — reuse that state instead of introducing a second,
  // parallel isolate mechanism. Every other variant uses the shared
  // useSeriesHighlight() toggle (pin/unpin) via highlight.toggle.
  const applyIsolate = (label: string) => {
    if (variant === "interactive" && selectionOptions) {
      const option = selectionOptions.find(
        (o) => o.label.toLowerCase() === label.toLowerCase()
      )
      if (option) {
        handleSelectionChange(option.key)
      }
      return
    }
    highlight.toggle(label)
  }

  const handleSegmentClick = (d: PieChartDataPoint, index: number) => {
    onSegmentClick?.(d, index)
    applyIsolate(d.label)
  }

  // Drives the legend's onItemClick — shares the same isolate state as
  // clicking a slice directly (via applyIsolate above).
  const handleLegendClick = (name: string) => {
    applyIsolate(name)
  }

  const isLegendItemActive = (name: string) => {
    if (variant === "interactive" && selectionOptions) {
      const option = selectionOptions.find(
        (o) => o.label.toLowerCase() === name.toLowerCase()
      )
      return option ? option.key === effectiveSelectedKey : true
    }
    return highlight.isActive(name)
  }

  return (
    <ChartContainer
      config={config}
      className={cn("relative !aspect-auto", className)}
    >
      {/* Interactive selector dropdown */}
      {variant === "interactive" && selectionOptions && (
        <div className="absolute top-4 right-4 z-10">
          <select
            value={effectiveSelectedKey}
            onChange={(e) => handleSelectionChange(e.target.value)}
            className="bg-background border-input text-foreground focus:ring-ring rounded-lg border px-3 py-1.5 text-sm shadow-sm focus:ring-2 focus:outline-none"
          >
            {selectionOptions.map((option) => (
              <option key={option.key} value={option.key}>
                {option.label}
              </option>
            ))}
          </select>
        </div>
      )}

      {/* Plot + legend layout — legend sits on `legendPosition` side, click a
          slice to highlight it (others fade), click again to restore */}
      <ChartLegendLayout
        position={legendPosition}
        show={showLegend}
        legend={
          <ChartLegend
            items={legendItems}
            position={legendPosition}
            onItemHover={(name) => {
              const index = data.findIndex((d) => d.label === name)
              if (index >= 0) {
                handleSegmentEnter(index)
              } else {
                handleSegmentLeave()
              }
            }}
            onItemClick={handleLegendClick}
            isItemActive={isLegendItemActive}
          />
        }
      >
        <div className="relative mx-auto aspect-square w-full max-w-[280px]">
          <svg
            viewBox={`0 0 ${width} ${height}`}
            className="h-full w-full overflow-visible"
          >
            <g
              transform={`translate(${margin.left + innerWidth / 2}, ${margin.top + innerHeight / 2})`}
            >
              {arcs.map((arcData, index) => {
                const isActive = activeIndex === index
                const isHovered = hoveredIndex === index
                const color = getColor(data[index], index)
                // The "interactive" variant renders every segment regardless
                // of isolate state (it has its own always-one-active spotlight
                // look); other variants heavily dim segments isolated out via
                // the legend/slice click-to-isolate feature.
                const isVisible =
                  variant === "interactive" ||
                  highlight.isActive(data[index].label)
                const shouldExpand =
                  isVisible &&
                  ((variant === "donut-active" && isActive) ||
                    (variant === "interactive" && isActive) ||
                    (variant !== "donut-active" &&
                      variant !== "interactive" &&
                      isHovered))

                return (
                  <g key={index}>
                    {/* Pie segment */}
                    <path
                      d={
                        (shouldExpand ? activeArcGenerator : arcGenerator)(
                          arcData
                        ) ?? ""
                      }
                      fill={color}
                      stroke="hsl(var(--background))"
                      strokeWidth={variant === "label" ? 0 : 2}
                      className={cn(
                        "cursor-pointer transition-all duration-200",
                        (activeIndex !== null || hoveredIndex !== null) &&
                          !isActive &&
                          !isHovered &&
                          "opacity-50",
                        !isVisible && "opacity-30"
                      )}
                      onMouseEnter={() => handleSegmentEnter(index)}
                      onMouseLeave={handleSegmentLeave}
                      onClick={() => handleSegmentClick(data[index], index)}
                    />

                    {/* Interactive outer ring for active segment */}
                    {variant === "interactive" && isActive && (
                      <path
                        d={interactiveOuterArcGenerator(arcData) ?? ""}
                        fill={color}
                        className="pointer-events-none"
                      />
                    )}

                    {/* Internal labels (for label variant) */}
                    {showLabels && variant === "label" && isVisible && (
                      <text
                        transform={`translate(${labelArcGenerator.centroid(arcData)})`}
                        textAnchor="middle"
                        dominantBaseline="middle"
                        className="fill-foreground pointer-events-none text-[11px] font-medium"
                      >
                        {data[index].value}
                      </text>
                    )}

                    {/* External labels with lines (for label variant) */}
                    {variant === "label" && isVisible && (
                      <g className="pointer-events-none">
                        {/* Label line */}
                        <polyline
                          points={(() => {
                            const posA = arcGenerator.centroid(arcData)
                            const posB =
                              externalLabelArcGenerator.centroid(arcData)
                            const midAngle =
                              (arcData.startAngle + arcData.endAngle) / 2
                            const posC = [
                              posB[0] + (midAngle < Math.PI ? 8 : -8),
                              posB[1],
                            ]
                            return `${posA[0]},${posA[1]} ${posB[0]},${posB[1]} ${posC[0]},${posC[1]}`
                          })()}
                          fill="none"
                          stroke="hsl(var(--muted-foreground))"
                          strokeWidth={1}
                          strokeOpacity={0.5}
                        />
                        {/* External label text */}
                        <text
                          transform={`translate(${externalLabelArcGenerator.centroid(arcData)})`}
                          textAnchor={
                            (arcData.startAngle + arcData.endAngle) / 2 <
                            Math.PI
                              ? "start"
                              : "end"
                          }
                          dx={
                            (arcData.startAngle + arcData.endAngle) / 2 <
                            Math.PI
                              ? 12
                              : -12
                          }
                          dominantBaseline="middle"
                          className="fill-muted-foreground text-[10px]"
                        >
                          {data[index].label}
                        </text>
                      </g>
                    )}
                  </g>
                )
              })}

              {/* Center text for donut-text and interactive variants */}
              {(variant === "donut-text" || variant === "interactive") && (
                <g className="pointer-events-none">
                  {displayedCenterValue && (
                    <text
                      textAnchor="middle"
                      dominantBaseline="middle"
                      y={displayedCenterLabel ? -8 : 0}
                      className="fill-foreground text-3xl font-bold"
                    >
                      {displayedCenterValue}
                    </text>
                  )}
                  {displayedCenterLabel && (
                    <text
                      textAnchor="middle"
                      dominantBaseline="middle"
                      y={displayedCenterValue ? 20 : 0}
                      className="fill-muted-foreground text-sm"
                    >
                      {displayedCenterLabel}
                    </text>
                  )}
                </g>
              )}
            </g>
          </svg>

          {/* Tooltip */}
          {showTooltip &&
            hoveredIndex !== null &&
            variant !== "interactive" && (
              <div className="pointer-events-none absolute top-1/2 left-1/2 z-50 -translate-x-1/2 -translate-y-1/2">
                <div className="border-border/50 bg-background rounded-lg border px-3 py-2 text-sm shadow-xl">
                  <div className="flex items-center gap-2">
                    <div
                      className="h-3 w-3 rounded-sm"
                      style={{
                        backgroundColor: getColor(
                          data[hoveredIndex],
                          hoveredIndex
                        ),
                      }}
                    />
                    <span className="font-medium">
                      {data[hoveredIndex].label}
                    </span>
                  </div>
                  <div className="text-muted-foreground mt-1">
                    {data[hoveredIndex].value.toLocaleString()} (
                    {valueFormatter(data[hoveredIndex].value, total)})
                  </div>
                </div>
              </div>
            )}
        </div>
      </ChartLegendLayout>
    </ChartContainer>
  )
}

"use client"

import * as React from "react"
import { interpolate } from "d3-interpolate"
import { arc, pie, type PieArcDatum } from "d3-shape"

import { cn } from "@/lib/utils"

import type { BaseChartProps, ChartConfig } from "../chart-config"
import { ChartContainer } from "../chart-container"
import { ChartLegendLayout, useSeriesHighlight } from "../chart-legend"

export interface DonutChartDataPoint {
  label: string
  value: number
  color?: string
  [key: string]: unknown
}

export interface DonutChartProps extends BaseChartProps {
  data: DonutChartDataPoint[]
  /** Inner radius as ratio (0-1) of outer radius. 0.6 = 60% hollow */
  innerRadius?: number
  /** Padding angle between segments in radians */
  padAngle?: number
  /** Corner radius for rounded segments */
  cornerRadius?: number
  /** Starting angle in radians (0 = top) */
  startAngle?: number
  /** Ending angle in radians */
  endAngle?: number
  /** Sort segments by value */
  sortValues?: boolean
  /** Show percentage labels on segments */
  showLabels?: boolean
  /** Show label lines for small segments */
  showLabelLines?: boolean
  /** Minimum angle (radians) to show inline label */
  minLabelAngle?: number
  /** Center text (top line) */
  centerLabel?: React.ReactNode
  /** Center value (large text) */
  centerValue?: React.ReactNode
  /** Animate on mount */
  animate?: boolean
  /** Animation duration in ms */
  animationDuration?: number
  /** Active/selected segment index */
  activeIndex?: number
  /** Callback when segment is clicked */
  onSegmentClick?: (data: DonutChartDataPoint, index: number) => void
  /** Value formatter for tooltip and labels */
  valueFormatter?: (value: number, total: number) => string
  /** Show total in center when nothing hovered */
  showTotal?: boolean
  /** Variant style */
  variant?: "default" | "gradient" | "separated"
}

// Default colors
const DEFAULT_COLORS = [
  "var(--chart-1)",
  "var(--chart-2)",
  "var(--chart-3)",
  "var(--chart-4)",
  "var(--chart-5)",
]

export function DonutChart({
  data,
  config,
  className,
  width = 400,
  height = 400,
  margin = { top: 40, right: 40, bottom: 40, left: 40 },
  showTooltip = true,
  showLegend = true,
  legendPosition = "right",
  innerRadius: innerRadiusRatio = 0.6,
  padAngle = 0.02,
  cornerRadius = 4,
  startAngle = -Math.PI / 2,
  endAngle = Math.PI * 1.5,
  sortValues = false,
  showLabels = false,
  showLabelLines = true,
  minLabelAngle = 0.4,
  centerLabel,
  centerValue,
  animate = true,
  animationDuration = 750,
  activeIndex: controlledActiveIndex,
  onSegmentClick,
  valueFormatter = (value, total) => `${((value / total) * 100).toFixed(1)}%`,
  showTotal = true,
  variant = "default",
}: DonutChartProps) {
  const [hoveredIndex, setHoveredIndex] = React.useState<number | null>(null)
  const [animationProgress, setAnimationProgress] = React.useState(
    animate ? 0 : 1
  )
  const [tooltipData, setTooltipData] = React.useState<{
    x: number
    y: number
    data: DonutChartDataPoint
    index: number
  } | null>(null)
  // Legend/slice click-to-highlight: nothing selected shows all segments, a
  // pinned label emphasizes only that one (others fade but stay drawn). Click
  // the highlighted item again to restore all. Hover-driven segment expansion
  // and center-text still run off `hoveredIndex`, so this hook tracks the
  // selection (isolate) state only — `highlight.hovered` stays unused.
  const highlight = useSeriesHighlight()

  const containerRef = React.useRef<HTMLDivElement>(null)
  const gradientId = React.useId().replace(/:/g, "")

  // Animation
  React.useEffect(() => {
    if (!animate) return

    const startTime = Date.now()
    const animateFrame = () => {
      const elapsed = Date.now() - startTime
      const progress = Math.min(elapsed / animationDuration, 1)
      // Ease out cubic
      const eased = 1 - Math.pow(1 - progress, 3)
      setAnimationProgress(eased)

      if (progress < 1) {
        requestAnimationFrame(animateFrame)
      }
    }
    requestAnimationFrame(animateFrame)
  }, [animate, animationDuration])

  const innerWidth = width - margin.left - margin.right
  const innerHeight = height - margin.top - margin.bottom
  const outerRadius = Math.min(innerWidth, innerHeight) / 2
  const innerRadius = outerRadius * Math.max(0, Math.min(1, innerRadiusRatio))

  // Calculate total
  const total = data.reduce((sum, d) => sum + d.value, 0)

  // Active index (controlled or hovered)
  const activeIndex = controlledActiveIndex ?? hoveredIndex

  // Create pie generator
  const pieGenerator = React.useMemo(() => {
    const gen = pie<DonutChartDataPoint>()
      .value((d) => d.value)
      .padAngle(variant === "separated" ? 0.06 : padAngle)
      .startAngle(startAngle)
      .endAngle(interpolate(startAngle, endAngle)(animationProgress))

    if (sortValues) {
      return gen.sort((a, b) => b.value - a.value)
    }
    return gen.sort(null)
  }, [variant, padAngle, startAngle, endAngle, animationProgress, sortValues])

  // Arc datum type
  type ArcDatum = PieArcDatum<DonutChartDataPoint>

  // Create arc generators
  const arcGenerator = arc<ArcDatum>()
    .innerRadius(innerRadius)
    .outerRadius(outerRadius)
    .cornerRadius(cornerRadius)

  // Hover arc (slightly larger)
  const hoverArcGenerator = arc<ArcDatum>()
    .innerRadius(innerRadius - 4)
    .outerRadius(outerRadius + 8)
    .cornerRadius(cornerRadius)

  // Label arc (for positioning)
  const labelArcGenerator = arc<ArcDatum>()
    .innerRadius(outerRadius + 15)
    .outerRadius(outerRadius + 15)

  const arcs = pieGenerator(data)

  // Get color for segment
  const getColor = (d: DonutChartDataPoint, index: number): string => {
    if (d.color) return d.color
    const configColor = config?.[d.label]?.color
    if (configColor) return configColor
    return DEFAULT_COLORS[index % DEFAULT_COLORS.length]
  }

  // Handle mouse events
  const handleMouseMove = (
    e: React.MouseEvent,
    data: DonutChartDataPoint,
    index: number
  ) => {
    if (!showTooltip) return
    const rect = containerRef.current?.getBoundingClientRect()
    if (rect) {
      setTooltipData({
        x: e.clientX - rect.left,
        y: e.clientY - rect.top,
        data,
        index,
      })
    }
  }

  // Determine if label should be outside
  const shouldShowOutsideLabel = (
    arcData: ReturnType<typeof pieGenerator>[number]
  ) => {
    const angle = arcData.endAngle - arcData.startAngle
    return showLabels && showLabelLines && angle < minLabelAngle && angle > 0.1
  }

  // Center content
  const displayedCenterValue =
    activeIndex !== null
      ? valueFormatter(data[activeIndex].value, total)
      : (centerValue ?? (showTotal ? total.toLocaleString() : null))

  const displayedCenterLabel =
    activeIndex !== null
      ? data[activeIndex].label
      : (centerLabel ?? (showTotal ? "Total" : null))

  return (
    <ChartContainer
      config={config}
      className={cn("relative !aspect-auto", className)}
    >
      {/* Plot + legend layout — legend sits on `legendPosition` side, click a
          segment or legend item to highlight it (others fade), click again to
          restore */}
      <ChartLegendLayout
        position={legendPosition}
        show={showLegend}
        legend={
          <div
            className={cn(
              "flex gap-4",
              legendPosition === "left" || legendPosition === "right"
                ? "flex-col items-start self-center"
                : "mt-4 flex-wrap justify-center"
            )}
          >
            {data.map((d, i) => (
              <button
                key={i}
                type="button"
                aria-pressed={!highlight.isActive(d.label)}
                className={cn(
                  "flex items-center gap-2 rounded-md px-2 py-1 text-sm transition-all",
                  "hover:bg-muted/50",
                  activeIndex === i && "bg-muted",
                  !highlight.isActive(d.label) && "opacity-40"
                )}
                onMouseEnter={() => setHoveredIndex(i)}
                onMouseLeave={() => setHoveredIndex(null)}
                onClick={() => {
                  onSegmentClick?.(d, i)
                  highlight.toggle(d.label)
                }}
              >
                <div
                  className="h-3 w-3 rounded-full"
                  style={{ backgroundColor: getColor(d, i) }}
                />
                <span className="text-muted-foreground">{d.label}</span>
                <span className="font-medium">
                  {valueFormatter(d.value, total)}
                </span>
              </button>
            ))}
          </div>
        }
      >
        <div
          ref={containerRef}
          className="relative mx-auto aspect-square w-full max-w-[280px]"
        >
          <svg
            viewBox={`0 0 ${width} ${height}`}
            className="h-full w-full overflow-visible"
          >
            {/* Gradient definitions */}
            {variant === "gradient" && (
              <defs>
                {data.map((d, i) => {
                  const color = getColor(d, i)
                  return (
                    <linearGradient
                      key={i}
                      id={`gradient-${gradientId}-${i}`}
                      x1="0%"
                      y1="0%"
                      x2="100%"
                      y2="100%"
                    >
                      <stop offset="0%" stopColor={color} stopOpacity={1} />
                      <stop offset="100%" stopColor={color} stopOpacity={0.6} />
                    </linearGradient>
                  )
                })}
              </defs>
            )}

            <g
              transform={`translate(${margin.left + innerWidth / 2}, ${margin.top + innerHeight / 2})`}
            >
              {/* Background ring */}
              <circle
                r={(outerRadius + innerRadius) / 2}
                fill="none"
                stroke="hsl(var(--muted))"
                strokeWidth={outerRadius - innerRadius}
                strokeOpacity={0.15}
              />

              {/* Donut segments */}
              {arcs.map((arcData, index) => {
                const isActive = activeIndex === index
                const d = data[index]
                const color = getColor(d, index)
                const fill =
                  variant === "gradient"
                    ? `url(#gradient-${gradientId}-${index})`
                    : color
                const isVisible = highlight.isActive(d.label)

                return (
                  <g key={index}>
                    {/* Shadow for active segment */}
                    {isActive && (
                      <path
                        d={hoverArcGenerator(arcData) ?? ""}
                        fill="black"
                        fillOpacity={0.1}
                        filter="blur(8px)"
                        className="pointer-events-none"
                      />
                    )}

                    {/* Main segment */}
                    <path
                      d={
                        (isActive ? hoverArcGenerator : arcGenerator)(
                          arcData
                        ) ?? ""
                      }
                      fill={fill}
                      stroke={
                        variant === "separated"
                          ? "hsl(var(--background))"
                          : "none"
                      }
                      strokeWidth={variant === "separated" ? 3 : 0}
                      className={cn(
                        "cursor-pointer transition-all duration-200",
                        activeIndex !== null && !isActive && "opacity-50",
                        !isVisible && "opacity-30"
                      )}
                      style={{
                        filter: isActive ? "brightness(1.1)" : undefined,
                      }}
                      onMouseEnter={() => setHoveredIndex(index)}
                      onMouseMove={(e) => handleMouseMove(e, d, index)}
                      onMouseLeave={() => {
                        setHoveredIndex(null)
                        setTooltipData(null)
                      }}
                      onClick={() => {
                        onSegmentClick?.(d, index)
                        highlight.toggle(d.label)
                      }}
                    />

                    {/* Inline labels for large segments */}
                    {isVisible &&
                      showLabels &&
                      arcData.endAngle - arcData.startAngle >=
                        minLabelAngle && (
                        <text
                          transform={`translate(${arcGenerator.centroid(arcData)})`}
                          textAnchor="middle"
                          dominantBaseline="middle"
                          className="pointer-events-none text-[11px] font-semibold"
                          fill="white"
                          style={{ textShadow: "0 1px 2px rgba(0,0,0,0.5)" }}
                        >
                          {valueFormatter(d.value, total)}
                        </text>
                      )}

                    {/* Outside labels with lines for small segments */}
                    {isVisible && shouldShowOutsideLabel(arcData) && (
                      <g className="pointer-events-none">
                        <polyline
                          points={(() => {
                            const posA = arcGenerator.centroid(arcData)
                            const posB = labelArcGenerator.centroid(arcData)
                            const midAngle =
                              (arcData.startAngle + arcData.endAngle) / 2
                            const posC = [
                              posB[0] + (midAngle < Math.PI ? 10 : -10),
                              posB[1],
                            ]
                            return `${posA[0]},${posA[1]} ${posB[0]},${posB[1]} ${posC[0]},${posC[1]}`
                          })()}
                          fill="none"
                          stroke="hsl(var(--muted-foreground))"
                          strokeWidth={1}
                          strokeOpacity={0.5}
                        />
                        <text
                          transform={`translate(${labelArcGenerator.centroid(arcData)})`}
                          textAnchor={
                            (arcData.startAngle + arcData.endAngle) / 2 <
                            Math.PI
                              ? "start"
                              : "end"
                          }
                          dx={
                            (arcData.startAngle + arcData.endAngle) / 2 <
                            Math.PI
                              ? 15
                              : -15
                          }
                          dominantBaseline="middle"
                          className="fill-muted-foreground text-[10px]"
                        >
                          {d.label}
                        </text>
                      </g>
                    )}
                  </g>
                )
              })}

              {/* Center content */}
              <g className="pointer-events-none">
                {displayedCenterValue && (
                  <text
                    textAnchor="middle"
                    dominantBaseline="middle"
                    y={displayedCenterLabel ? -6 : 0}
                    className="fill-foreground text-2xl font-bold"
                    style={{ fontSize: innerRadius * 0.35 }}
                  >
                    {displayedCenterValue}
                  </text>
                )}
                {displayedCenterLabel && (
                  <text
                    textAnchor="middle"
                    dominantBaseline="middle"
                    y={displayedCenterValue ? innerRadius * 0.2 : 0}
                    className="fill-muted-foreground text-sm"
                    style={{ fontSize: innerRadius * 0.15 }}
                  >
                    {displayedCenterLabel}
                  </text>
                )}
              </g>
            </g>
          </svg>

          {/* Tooltip */}
          {showTooltip && tooltipData && (
            <div
              className="pointer-events-none absolute z-50 -translate-x-1/2 -translate-y-full"
              style={{
                left: tooltipData.x,
                top: tooltipData.y - 10,
              }}
            >
              <div className="bg-popover text-popover-foreground rounded-lg border px-3 py-2 shadow-lg">
                <div className="flex items-center gap-2">
                  <div
                    className="h-3 w-3 rounded-full"
                    style={{
                      backgroundColor: getColor(
                        tooltipData.data,
                        tooltipData.index
                      ),
                    }}
                  />
                  <span className="font-medium">{tooltipData.data.label}</span>
                </div>
                <div className="mt-1 text-sm">
                  <span className="text-muted-foreground">Value: </span>
                  <span className="font-semibold">
                    {tooltipData.data.value.toLocaleString()}
                  </span>
                  <span className="text-muted-foreground ml-2">
                    ({valueFormatter(tooltipData.data.value, total)})
                  </span>
                </div>
              </div>
            </div>
          )}
        </div>
      </ChartLegendLayout>
    </ChartContainer>
  )
}

"use client"

import * as React from "react"
import { bin } from "d3-array"
import { scaleLinear } from "d3-scale"

import { cn } from "@/lib/utils"

import { ChartAxis } from "../chart-axis"
import type { BaseChartProps } from "../chart-config"
import { ChartContainer } from "../chart-container"
import { ChartHorizontalGrid } from "../chart-grid"
import {
  ChartZoomResetButton,
  ChartZoomSelectionRect,
  useChartZoom,
} from "../chart-zoom"

// ============================================================================
// Types & Interfaces
// ============================================================================

export interface HistogramDataset {
  data: number[]
  label?: string
  color?: string
}

export interface HistogramChartProps extends BaseChartProps {
  /** Single dataset or multiple datasets for overlay */
  data: number[] | HistogramDataset[]
  /** Number of bins */
  bins?: number
  /** X-axis label */
  xAxisLabel?: string
  /** Y-axis label */
  yAxisLabel?: string
  /** Bar color (for single dataset) */
  color?: string
  /** Bar padding between bins */
  barPadding?: number
  /** Show density instead of count */
  showDensity?: boolean
  /** Normalize to percentages */
  normalized?: boolean
  /** Variant style */
  variant?: "default" | "overlay" | "gradient" | "stepped"
  /** Show bar border/stroke */
  showBorder?: boolean
  /** Border color */
  borderColor?: string
  /** Bar corner radius */
  cornerRadius?: number
  /** Opacity for overlay/stepped variants */
  fillOpacity?: number
  /** Color scale for gradient variant */
  colorScale?: "viridis" | "plasma" | "warm" | "cool" | "rainbow"
  /** Show legend for multiple datasets */
  showLegend?: boolean
}

// ============================================================================
// Color Scales
// ============================================================================

const COLOR_SCALES = {
  // Blue-purple gradient (default) - professional blue tones
  viridis: (t: number) => {
    const colors = [
      "#1e3a5f",
      "#2563eb",
      "#3b82f6",
      "#60a5fa",
      "#93c5fd",
      "#bfdbfe",
    ]
    const idx = Math.min(Math.floor(t * (colors.length - 1)), colors.length - 2)
    const localT = t * (colors.length - 1) - idx
    return interpolateColor(colors[idx], colors[idx + 1], localT)
  },
  // Plasma: deep purple -> magenta -> orange
  plasma: (t: number) => {
    const colors = [
      "#0d0887",
      "#6a00a8",
      "#b12a90",
      "#e16462",
      "#fca636",
      "#f0f921",
    ]
    const idx = Math.min(Math.floor(t * (colors.length - 1)), colors.length - 2)
    const localT = t * (colors.length - 1) - idx
    return interpolateColor(colors[idx], colors[idx + 1], localT)
  },
  // Warm: purple -> pink -> orange -> gold
  warm: (t: number) => {
    const colors = ["#6e40aa", "#be3caf", "#fe4b83", "#ff7847", "#e2b72f"]
    const idx = Math.min(Math.floor(t * (colors.length - 1)), colors.length - 2)
    const localT = t * (colors.length - 1) - idx
    return interpolateColor(colors[idx], colors[idx + 1], localT)
  },
  // Cool: indigo -> blue -> cyan
  cool: (t: number) => {
    const colors = [
      "#312e81",
      "#4338ca",
      "#6366f1",
      "#818cf8",
      "#a5b4fc",
      "#c7d2fe",
    ]
    const idx = Math.min(Math.floor(t * (colors.length - 1)), colors.length - 2)
    const localT = t * (colors.length - 1) - idx
    return interpolateColor(colors[idx], colors[idx + 1], localT)
  },
  // Rainbow with blue emphasis
  rainbow: (t: number) => {
    const h = 220 + t * 140 // Start from blue, cycle through purple to cyan
    return `hsl(${h % 360}, 70%, 55%)`
  },
}

function interpolateColor(c1: string, c2: string, t: number): string {
  const hex2rgb = (hex: string) => {
    const h = hex.replace("#", "")
    return [
      parseInt(h.substring(0, 2), 16),
      parseInt(h.substring(2, 4), 16),
      parseInt(h.substring(4, 6), 16),
    ]
  }
  const rgb2hex = (r: number, g: number, b: number) =>
    "#" +
    [r, g, b].map((x) => Math.round(x).toString(16).padStart(2, "0")).join("")

  const [r1, g1, b1] = hex2rgb(c1)
  const [r2, g2, b2] = hex2rgb(c2)
  return rgb2hex(r1 + (r2 - r1) * t, g1 + (g2 - g1) * t, b1 + (b2 - b1) * t)
}

// Default colors for multiple datasets (overlay variant)
const DEFAULT_COLORS = [
  "var(--chart-3)",
  "var(--chart-1)",
  "var(--chart-5)",
  "var(--chart-2)",
  "var(--chart-4)",
  "var(--chart-3)",
]

// ============================================================================
// Component
// ============================================================================

export function HistogramChart({
  data,
  config,
  className,
  width = 600,
  height = 400,
  margin = { top: 20, right: 20, bottom: 40, left: 50 },
  showGrid = true,
  showTooltip = true,
  bins = 30,
  xAxisLabel,
  yAxisLabel,
  color,
  barPadding = 1,
  showDensity = false,
  normalized = false,
  variant = "default",
  showBorder = true,
  borderColor,
  cornerRadius = 0,
  fillOpacity,
  colorScale = "viridis",
  showLegend = true,
}: HistogramChartProps) {
  const svgRef = React.useRef<SVGSVGElement>(null)
  const [hoveredBin, setHoveredBin] = React.useState<{
    datasetIdx: number
    binIdx: number
  } | null>(null)
  const [activeDatasetIndex, setActiveDatasetIndex] = React.useState<
    number | null
  >(null)
  const [zoomRange, setZoomRange] = React.useState<[number, number] | null>(
    null
  )
  const isZoomed = zoomRange !== null

  const isDatasetVisible = React.useCallback(
    (idx: number) => activeDatasetIndex === null || activeDatasetIndex === idx,
    [activeDatasetIndex]
  )

  const innerWidth = width - margin.left - margin.right
  const innerHeight = height - margin.top - margin.bottom

  // Normalize data to array of datasets
  const datasets: HistogramDataset[] = React.useMemo(() => {
    if (Array.isArray(data) && data.length > 0) {
      if (typeof data[0] === "number") {
        return [
          {
            data: data as number[],
            label: "Data",
            color: color || DEFAULT_COLORS[0],
          },
        ]
      }
      return (data as HistogramDataset[]).map((d, i) => ({
        ...d,
        color: d.color || DEFAULT_COLORS[i % DEFAULT_COLORS.length],
      }))
    }
    return []
  }, [data, color])

  // Calculate global domain — narrowed to the active drag-to-zoom range
  // when set, so bins are recomputed (via d3's `bin().domain(...)`) across
  // only the visible x-range.
  const globalDomain = React.useMemo(() => {
    if (zoomRange) return zoomRange
    const allData = datasets.flatMap((d) => d.data)
    if (allData.length === 0) return [0, 1]
    return [Math.min(...allData), Math.max(...allData)]
  }, [datasets, zoomRange])

  // Create histogram bins for each dataset
  const histograms = React.useMemo(() => {
    const binGenerator = bin()
      .domain(globalDomain as [number, number])
      .thresholds(bins)

    return datasets.map((dataset) => {
      const hist = binGenerator(dataset.data)
      const total = dataset.data.length
      return hist.map((b) => ({
        x0: b.x0!,
        x1: b.x1!,
        count: b.length,
        density: b.length / total / (b.x1! - b.x0!),
        percent: (b.length / total) * 100,
      }))
    })
  }, [datasets, globalDomain, bins])

  // Scales
  const xScale = React.useMemo(() => {
    return scaleLinear().domain(globalDomain).range([0, innerWidth])
  }, [globalDomain, innerWidth])

  const yScale = React.useMemo(() => {
    let maxY = 0
    histograms.forEach((binData) => {
      binData.forEach((b) => {
        const val = showDensity ? b.density : normalized ? b.percent : b.count
        if (val > maxY) maxY = val
      })
    })
    return scaleLinear()
      .domain([0, maxY * 1.1])
      .range([innerHeight, 0])
      .nice()
  }, [histograms, innerHeight, showDensity, normalized])

  // Drag-to-zoom: converts the pixel drag range into a data-domain range
  // (via `xScale.invert`) and narrows `globalDomain` — and therefore the
  // bins — to it.
  const zoom = useChartZoom({
    svgRef,
    marginLeft: margin.left,
    innerWidth,
    onZoom: ({ x0, x1 }) => {
      const lo = xScale.invert(x0)
      const hi = xScale.invert(x1)
      const hasDataInRange = datasets.some((dataset) =>
        dataset.data.some((v) => v >= lo && v <= hi)
      )
      if (hasDataInRange) setZoomRange([lo, hi])
    },
    onReset: () => setZoomRange(null),
  })

  // Get color function for gradient variant
  const getGradientColor = React.useCallback(
    (binIdx: number, totalBins: number) => {
      const t = binIdx / (totalBins - 1)
      return COLOR_SCALES[colorScale](t)
    },
    [colorScale]
  )

  // Determine fill opacity based on variant
  const getFillOpacity = () => {
    if (fillOpacity !== undefined) return fillOpacity
    switch (variant) {
      case "overlay":
        return 0.6
      case "stepped":
        return 0.4
      default:
        return 1
    }
  }

  // Generate stepped path for a dataset
  const generateSteppedPath = (binData: (typeof histograms)[0]) => {
    if (binData.length === 0) return ""

    const points: string[] = []
    points.push(`M ${xScale(binData[0].x0)} ${innerHeight}`)

    binData.forEach((b) => {
      const yValue = showDensity ? b.density : normalized ? b.percent : b.count
      const y = yScale(yValue)
      points.push(`L ${xScale(b.x0)} ${y}`)
      points.push(`L ${xScale(b.x1)} ${y}`)
    })

    points.push(`L ${xScale(binData[binData.length - 1].x1)} ${innerHeight}`)
    points.push("Z")

    return points.join(" ")
  }

  // Render bars for a single dataset
  const renderBars = (
    binData: (typeof histograms)[0],
    datasetIdx: number,
    datasetColor: string
  ) => {
    return binData.map((b, binIdx) => {
      const barX = xScale(b.x0)
      const barWidth = Math.max(0, xScale(b.x1) - xScale(b.x0) - barPadding)
      const yValue = showDensity ? b.density : normalized ? b.percent : b.count
      const barY = yScale(yValue)
      const barHeight = Math.max(0, innerHeight - barY)

      let fillColor = datasetColor
      if (variant === "gradient") {
        fillColor = getGradientColor(binIdx, binData.length)
      }

      const isHovered =
        hoveredBin?.datasetIdx === datasetIdx && hoveredBin?.binIdx === binIdx

      return (
        <rect
          key={`${datasetIdx}-${binIdx}`}
          x={barX}
          y={barY}
          width={barWidth}
          height={barHeight}
          fill={fillColor}
          fillOpacity={getFillOpacity()}
          stroke={showBorder ? borderColor || fillColor : "none"}
          strokeWidth={showBorder ? 1 : 0}
          rx={cornerRadius}
          ry={cornerRadius}
          className={cn(
            "cursor-pointer transition-opacity duration-150",
            hoveredBin !== null && !isHovered && "opacity-60"
          )}
          onMouseEnter={() => setHoveredBin({ datasetIdx, binIdx })}
          onMouseLeave={() => setHoveredBin(null)}
        />
      )
    })
  }

  // Render stepped/area histogram
  const renderStepped = (
    binData: (typeof histograms)[0],
    datasetIdx: number,
    datasetColor: string
  ) => {
    const path = generateSteppedPath(binData)
    return (
      <g key={datasetIdx}>
        {/* The filled area path */}
        <path
          d={path}
          fill={datasetColor}
          fillOpacity={getFillOpacity()}
          stroke={datasetColor}
          strokeWidth={1.5}
          className={cn(
            "transition-opacity duration-150",
            hoveredBin !== null &&
              hoveredBin.datasetIdx !== datasetIdx &&
              "opacity-50"
          )}
        />
        {/* Invisible hit areas for each bin segment */}
        {binData.map((b, binIdx) => {
          const barX = xScale(b.x0)
          const barWidth = Math.max(0, xScale(b.x1) - xScale(b.x0))
          const yValue = showDensity
            ? b.density
            : normalized
              ? b.percent
              : b.count
          const barY = yScale(yValue)
          const barHeight = Math.max(0, innerHeight - barY)

          const isHovered =
            hoveredBin?.datasetIdx === datasetIdx &&
            hoveredBin?.binIdx === binIdx

          return (
            <rect
              key={`hit-${datasetIdx}-${binIdx}`}
              x={barX}
              y={barY}
              width={barWidth}
              height={barHeight}
              fill="transparent"
              className={cn("cursor-pointer", isHovered && "fill-foreground/5")}
              onMouseEnter={() => setHoveredBin({ datasetIdx, binIdx })}
              onMouseLeave={() => setHoveredBin(null)}
            />
          )
        })}
      </g>
    )
  }

  return (
    <ChartContainer config={config} className={cn("relative", className)}>
      <svg
        ref={svgRef}
        viewBox={`0 0 ${width} ${height}`}
        className="h-full w-full select-none"
        onMouseDown={zoom.handlers.onMouseDown}
        onMouseMove={zoom.handlers.onMouseMove}
        onMouseUp={zoom.handlers.onMouseUp}
        onMouseLeave={zoom.handlers.onMouseLeave}
        onDoubleClick={zoom.handlers.onDoubleClick}
      >
        <g transform={`translate(${margin.left}, ${margin.top})`}>
          {/* Grid */}
          {showGrid && (
            <ChartHorizontalGrid scale={yScale} width={innerWidth} />
          )}

          {/* Drag-to-zoom selection rectangle */}
          <ChartZoomSelectionRect range={zoom.dragRange} height={innerHeight} />

          {/* Render based on variant — datasets isolated via legend click
              are skipped entirely (hidden, not just dimmed). */}
          {variant === "stepped"
            ? datasets.map(
                (dataset, idx) =>
                  isDatasetVisible(idx) &&
                  renderStepped(histograms[idx], idx, dataset.color!)
              )
            : datasets.map(
                (dataset, idx) =>
                  isDatasetVisible(idx) &&
                  renderBars(histograms[idx], idx, dataset.color!)
              )}

          {/* X Axis */}
          <ChartAxis
            scale={xScale}
            orientation="bottom"
            transform={`translate(0, ${innerHeight})`}
            label={xAxisLabel}
          />

          {/* Y Axis */}
          <ChartAxis
            scale={yScale}
            orientation="left"
            label={
              yAxisLabel ??
              (showDensity ? "Density" : normalized ? "Percentage" : "Count")
            }
          />
        </g>

        {/* Legend for multiple datasets */}
        {showLegend && datasets.length > 1 && (
          <g
            transform={`translate(${width - margin.right - 100}, ${margin.top})`}
          >
            <rect
              x={-10}
              y={-10}
              width={110}
              height={datasets.length * 22 + 10}
              fill="var(--background)"
              stroke="var(--border)"
              strokeWidth={1}
              rx={4}
            />
            {datasets.map((dataset, idx) => (
              <g
                key={idx}
                transform={`translate(0, ${idx * 22})`}
                className={cn(
                  "cursor-pointer transition-opacity duration-150",
                  !isDatasetVisible(idx) && "opacity-40"
                )}
                onClick={() =>
                  setActiveDatasetIndex((prev) => (prev === idx ? null : idx))
                }
              >
                <rect
                  x={0}
                  y={0}
                  width={16}
                  height={14}
                  fill={dataset.color}
                  fillOpacity={getFillOpacity()}
                  stroke={dataset.color}
                  strokeWidth={1}
                  rx={2}
                />
                <text x={22} y={11} className="fill-foreground text-[11px]">
                  {dataset.label || `Dataset ${idx + 1}`}
                </text>
              </g>
            ))}
          </g>
        )}
      </svg>

      {/* Tooltip */}
      {showTooltip && hoveredBin !== null && (
        <div
          className="pointer-events-none absolute z-50"
          style={{
            left:
              margin.left +
              xScale(
                (histograms[hoveredBin.datasetIdx][hoveredBin.binIdx].x0 +
                  histograms[hoveredBin.datasetIdx][hoveredBin.binIdx].x1) /
                  2
              ),
            top:
              margin.top +
              yScale(
                showDensity
                  ? histograms[hoveredBin.datasetIdx][hoveredBin.binIdx].density
                  : normalized
                    ? histograms[hoveredBin.datasetIdx][hoveredBin.binIdx]
                        .percent
                    : histograms[hoveredBin.datasetIdx][hoveredBin.binIdx].count
              ) -
              10,
            transform: "translateX(-50%)",
          }}
        >
          <div className="border-border/50 bg-background rounded-lg border px-2.5 py-1.5 text-xs shadow-xl">
            {datasets.length > 1 && (
              <div
                className="mb-1 font-medium"
                style={{ color: datasets[hoveredBin.datasetIdx].color }}
              >
                {datasets[hoveredBin.datasetIdx].label ||
                  `Dataset ${hoveredBin.datasetIdx + 1}`}
              </div>
            )}
            <div className="font-medium">
              {histograms[hoveredBin.datasetIdx][hoveredBin.binIdx].x0.toFixed(
                1
              )}{" "}
              -{" "}
              {histograms[hoveredBin.datasetIdx][hoveredBin.binIdx].x1.toFixed(
                1
              )}
            </div>
            <div className="text-muted-foreground">
              Count:{" "}
              {histograms[hoveredBin.datasetIdx][hoveredBin.binIdx].count}
            </div>
            <div className="text-muted-foreground">
              {histograms[hoveredBin.datasetIdx][
                hoveredBin.binIdx
              ].percent.toFixed(1)}
              %
            </div>
          </div>
        </div>
      )}

      <ChartZoomResetButton
        visible={isZoomed}
        onReset={() => setZoomRange(null)}
      />
    </ChartContainer>
  )
}

"use client"

import * as React from "react"
import { max, median, min, quantile } from "d3-array"
import { scaleBand, scaleLinear } from "d3-scale"

import { cn } from "@/lib/utils"

import {
  ChartZoomResetButton,
  ChartZoomSelectionRect,
  getBandScaleIndexRange,
  useChartZoom,
} from "../chart-zoom"

export interface BoxPlotDataPoint {
  label: string
  values: number[]
  color?: string
}

export interface BoxPlotStats {
  label: string
  min: number
  q1: number
  median: number
  q3: number
  max: number
  outliers: number[]
  color?: string
}

export interface BoxPlotChartProps {
  data: BoxPlotDataPoint[] | BoxPlotStats[]
  className?: string
  color?: string
  showGrid?: boolean
  showTooltip?: boolean
  orientation?: "vertical" | "horizontal"
  boxWidth?: number
  showOutliers?: boolean
  whiskerType?: "minmax" | "iqr"
  aspectRatio?: number
  valueFormatter?: (value: number) => string
}

function isStats(
  data: BoxPlotDataPoint[] | BoxPlotStats[]
): data is BoxPlotStats[] {
  return data.length > 0 && "median" in data[0]
}

function calculateStats(
  values: number[],
  whiskerType: "minmax" | "iqr"
): Omit<BoxPlotStats, "label" | "color"> {
  const sorted = [...values].sort((a, b) => a - b)
  const q1 = quantile(sorted, 0.25) ?? 0
  const med = median(sorted) ?? 0
  const q3 = quantile(sorted, 0.75) ?? 0
  const iqr = q3 - q1

  let minVal: number, maxVal: number
  let outliers: number[] = []

  if (whiskerType === "iqr") {
    const lowerFence = q1 - 1.5 * iqr
    const upperFence = q3 + 1.5 * iqr
    minVal = min(sorted.filter((v) => v >= lowerFence)) ?? sorted[0]
    maxVal =
      max(sorted.filter((v) => v <= upperFence)) ?? sorted[sorted.length - 1]
    outliers = sorted.filter((v) => v < lowerFence || v > upperFence)
  } else {
    minVal = min(sorted) ?? 0
    maxVal = max(sorted) ?? 0
  }

  return { min: minVal, q1, median: med, q3, max: maxVal, outliers }
}

export function BoxPlotChart({
  data,
  className,
  color = "var(--chart-1)",
  showGrid = true,
  showTooltip = true,
  orientation = "vertical",
  boxWidth = 0.6,
  showOutliers = true,
  whiskerType = "iqr",
  aspectRatio = 2,
  valueFormatter = (value) => value.toFixed(0),
}: BoxPlotChartProps) {
  const containerRef = React.useRef<HTMLDivElement>(null)
  const svgRef = React.useRef<SVGSVGElement>(null)
  const [dimensions, setDimensions] = React.useState({ width: 0, height: 0 })
  const [hoveredIndex, setHoveredIndex] = React.useState<number | null>(null)
  const [tooltipPos, setTooltipPos] = React.useState({ x: 0, y: 0 })
  const [zoomDomain, setZoomDomain] = React.useState<[number, number] | null>(
    null
  )
  const isZoomed = zoomDomain !== null

  // Responsive sizing
  React.useEffect(() => {
    const updateDimensions = () => {
      if (containerRef.current) {
        const width = containerRef.current.offsetWidth
        setDimensions({ width, height: width / aspectRatio })
      }
    }
    updateDimensions()
    window.addEventListener("resize", updateDimensions)
    return () => window.removeEventListener("resize", updateDimensions)
  }, [aspectRatio])

  // Reset any active zoom if the underlying data set changes.
  React.useEffect(() => {
    setZoomDomain(null)
  }, [data])

  const { width, height } = dimensions
  const margin = { top: 20, right: 20, bottom: 40, left: 50 }
  const innerWidth = Math.max(0, width - margin.left - margin.right)
  const innerHeight = Math.max(0, height - margin.top - margin.bottom)
  const isVertical = orientation === "vertical"

  // Calculate stats if raw values provided
  const statsData: BoxPlotStats[] = React.useMemo(() => {
    if (isStats(data)) return data
    return data.map((d) => ({
      label: d.label,
      color: d.color,
      ...calculateStats(d.values, whiskerType),
    }))
  }, [data, whiskerType])

  // Narrow the view to the zoomed index window — box plots per category
  // are independent of one another, so slicing the computed stats is safe.
  const plotStatsData = zoomDomain
    ? statsData.slice(zoomDomain[0], zoomDomain[1] + 1)
    : statsData

  // Category scale
  const categoryScale = React.useMemo(() => {
    return scaleBand()
      .domain(plotStatsData.map((d) => d.label))
      .range(isVertical ? [0, innerWidth] : [0, innerHeight])
      .padding(0.3)
  }, [plotStatsData, innerWidth, innerHeight, isVertical])

  // Value scale
  const valueScale = React.useMemo(() => {
    const allValues = plotStatsData.flatMap((d) => [
      d.min,
      d.max,
      ...d.outliers,
    ])
    const minV = Math.min(...allValues)
    const maxV = Math.max(...allValues)
    const padding = (maxV - minV) * 0.1
    return scaleLinear()
      .domain([Math.floor(minV - padding), Math.ceil(maxV + padding)])
      .range(isVertical ? [innerHeight, 0] : [0, innerWidth])
      .nice()
  }, [plotStatsData, innerWidth, innerHeight, isVertical])

  // Drag-to-zoom: converts the pixel drag range into a data-index range
  // (band scale) and narrows the view to it. Only meaningful when the
  // categorical axis runs horizontally (vertical orientation) since the
  // drag gesture is x-axis based.
  const zoom = useChartZoom({
    svgRef,
    marginLeft: margin.left,
    innerWidth,
    disabled: !isVertical,
    onZoom: ({ x0, x1 }) => {
      const [start, end] = getBandScaleIndexRange(categoryScale, x0, x1)
      const currentOffset = zoomDomain ? zoomDomain[0] : 0
      setZoomDomain([currentOffset + start, currentOffset + end])
    },
    onReset: () => setZoomDomain(null),
  })

  const actualBoxWidth = categoryScale.bandwidth() * boxWidth
  const ticks = valueScale.ticks(5)

  if (width === 0) {
    return <div ref={containerRef} className={cn("w-full", className)} />
  }

  return (
    <div ref={containerRef} className={cn("relative w-full", className)}>
      <svg
        ref={svgRef}
        width={width}
        height={height}
        viewBox={`0 0 ${width} ${height}`}
        className="overflow-visible select-none"
        onMouseDown={zoom.handlers.onMouseDown}
        onMouseMove={zoom.handlers.onMouseMove}
        onMouseUp={zoom.handlers.onMouseUp}
        onMouseLeave={zoom.handlers.onMouseLeave}
        onDoubleClick={zoom.handlers.onDoubleClick}
      >
        <g transform={`translate(${margin.left}, ${margin.top})`}>
          {/* Drag-to-zoom selection rectangle */}
          <ChartZoomSelectionRect range={zoom.dragRange} height={innerHeight} />

          {/* Grid */}
          {showGrid && (
            <>
              {/* Horizontal grid lines */}
              {ticks.map((tick) => (
                <line
                  key={`h-${tick}`}
                  x1={0}
                  x2={innerWidth}
                  y1={isVertical ? valueScale(tick) : 0}
                  y2={isVertical ? valueScale(tick) : innerHeight}
                  stroke="hsl(var(--border))"
                  strokeOpacity={0.5}
                  strokeDasharray="3 3"
                />
              ))}
              {/* Vertical grid lines */}
              {plotStatsData.map((d) => {
                const x =
                  (categoryScale(d.label) ?? 0) + categoryScale.bandwidth() / 2
                return (
                  <line
                    key={`v-${d.label}`}
                    x1={x}
                    x2={x}
                    y1={0}
                    y2={innerHeight}
                    stroke="hsl(var(--border))"
                    strokeOpacity={0.5}
                    strokeDasharray="3 3"
                  />
                )
              })}
            </>
          )}

          {/* Box plots */}
          {plotStatsData.map((d, index) => {
            const boxColor = d.color ?? color
            const center =
              (categoryScale(d.label) ?? 0) + categoryScale.bandwidth() / 2
            const boxOffset = actualBoxWidth / 2
            const isHovered = hoveredIndex === index

            if (isVertical) {
              return (
                <g
                  key={d.label}
                  className={cn(
                    "cursor-pointer transition-opacity duration-200",
                    hoveredIndex !== null && !isHovered && "opacity-40"
                  )}
                  onMouseEnter={(e) => {
                    setHoveredIndex(index)
                    const rect = containerRef.current?.getBoundingClientRect()
                    if (rect) {
                      setTooltipPos({
                        x: e.clientX - rect.left,
                        y: e.clientY - rect.top,
                      })
                    }
                  }}
                  onMouseMove={(e) => {
                    const rect = containerRef.current?.getBoundingClientRect()
                    if (rect) {
                      setTooltipPos({
                        x: e.clientX - rect.left,
                        y: e.clientY - rect.top,
                      })
                    }
                  }}
                  onMouseLeave={() => setHoveredIndex(null)}
                >
                  {/* Whisker line */}
                  <line
                    x1={center}
                    x2={center}
                    y1={valueScale(d.min)}
                    y2={valueScale(d.max)}
                    stroke={boxColor}
                    strokeWidth={1.5}
                  />

                  {/* Min whisker */}
                  <line
                    x1={center - boxOffset * 0.5}
                    x2={center + boxOffset * 0.5}
                    y1={valueScale(d.min)}
                    y2={valueScale(d.min)}
                    stroke={boxColor}
                    strokeWidth={2}
                  />

                  {/* Max whisker */}
                  <line
                    x1={center - boxOffset * 0.5}
                    x2={center + boxOffset * 0.5}
                    y1={valueScale(d.max)}
                    y2={valueScale(d.max)}
                    stroke={boxColor}
                    strokeWidth={2}
                  />

                  {/* Box */}
                  <rect
                    x={center - boxOffset}
                    y={valueScale(d.q3)}
                    width={actualBoxWidth}
                    height={Math.max(0, valueScale(d.q1) - valueScale(d.q3))}
                    fill={boxColor}
                    fillOpacity={0.2}
                    stroke={boxColor}
                    strokeWidth={2}
                    rx={4}
                  />

                  {/* Median line */}
                  <line
                    x1={center - boxOffset}
                    x2={center + boxOffset}
                    y1={valueScale(d.median)}
                    y2={valueScale(d.median)}
                    stroke={boxColor}
                    strokeWidth={3}
                  />

                  {/* Outliers */}
                  {showOutliers &&
                    d.outliers.map((outlier, i) => (
                      <circle
                        key={i}
                        cx={center}
                        cy={valueScale(outlier)}
                        r={4}
                        fill={boxColor}
                        fillOpacity={0.5}
                        stroke={boxColor}
                        strokeWidth={1.5}
                      />
                    ))}
                </g>
              )
            } else {
              // Horizontal orientation
              return (
                <g
                  key={d.label}
                  className={cn(
                    "cursor-pointer transition-opacity duration-200",
                    hoveredIndex !== null && !isHovered && "opacity-40"
                  )}
                  onMouseEnter={(e) => {
                    setHoveredIndex(index)
                    const rect = containerRef.current?.getBoundingClientRect()
                    if (rect) {
                      setTooltipPos({
                        x: e.clientX - rect.left,
                        y: e.clientY - rect.top,
                      })
                    }
                  }}
                  onMouseMove={(e) => {
                    const rect = containerRef.current?.getBoundingClientRect()
                    if (rect) {
                      setTooltipPos({
                        x: e.clientX - rect.left,
                        y: e.clientY - rect.top,
                      })
                    }
                  }}
                  onMouseLeave={() => setHoveredIndex(null)}
                >
                  {/* Whisker line */}
                  <line
                    y1={center}
                    y2={center}
                    x1={valueScale(d.min)}
                    x2={valueScale(d.max)}
                    stroke={boxColor}
                    strokeWidth={1.5}
                  />

                  {/* Min whisker */}
                  <line
                    y1={center - boxOffset * 0.5}
                    y2={center + boxOffset * 0.5}
                    x1={valueScale(d.min)}
                    x2={valueScale(d.min)}
                    stroke={boxColor}
                    strokeWidth={2}
                  />

                  {/* Max whisker */}
                  <line
                    y1={center - boxOffset * 0.5}
                    y2={center + boxOffset * 0.5}
                    x1={valueScale(d.max)}
                    x2={valueScale(d.max)}
                    stroke={boxColor}
                    strokeWidth={2}
                  />

                  {/* Box */}
                  <rect
                    y={center - boxOffset}
                    x={valueScale(d.q1)}
                    height={actualBoxWidth}
                    width={Math.max(0, valueScale(d.q3) - valueScale(d.q1))}
                    fill={boxColor}
                    fillOpacity={0.2}
                    stroke={boxColor}
                    strokeWidth={2}
                    rx={4}
                  />

                  {/* Median line */}
                  <line
                    y1={center - boxOffset}
                    y2={center + boxOffset}
                    x1={valueScale(d.median)}
                    x2={valueScale(d.median)}
                    stroke={boxColor}
                    strokeWidth={3}
                  />

                  {/* Outliers */}
                  {showOutliers &&
                    d.outliers.map((outlier, i) => (
                      <circle
                        key={i}
                        cy={center}
                        cx={valueScale(outlier)}
                        r={4}
                        fill={boxColor}
                        fillOpacity={0.5}
                        stroke={boxColor}
                        strokeWidth={1.5}
                      />
                    ))}
                </g>
              )
            }
          })}

          {/* X Axis */}
          <g transform={`translate(0, ${innerHeight})`}>
            {plotStatsData.map((d) => {
              const x =
                (categoryScale(d.label) ?? 0) + categoryScale.bandwidth() / 2
              return (
                <text
                  key={d.label}
                  x={x}
                  y={24}
                  textAnchor="middle"
                  className="fill-muted-foreground text-xs"
                >
                  {d.label}
                </text>
              )
            })}
          </g>

          {/* Y Axis */}
          <g>
            {ticks.map((tick) => (
              <text
                key={tick}
                x={-12}
                y={valueScale(tick)}
                dy="0.32em"
                textAnchor="end"
                className="fill-muted-foreground text-xs"
              >
                {valueFormatter(tick)}
              </text>
            ))}
          </g>
        </g>
      </svg>

      {/* Tooltip */}
      {showTooltip && hoveredIndex !== null && (
        <div
          className="pointer-events-none absolute z-50"
          style={{
            left: tooltipPos.x + 10,
            top: tooltipPos.y - 10,
            transform: "translateY(-100%)",
          }}
        >
          <div className="bg-background rounded-lg border px-3 py-2 shadow-lg">
            <p className="text-foreground mb-1 text-sm font-medium">
              {plotStatsData[hoveredIndex].label}
            </p>
            <div className="space-y-0.5 text-sm">
              <div className="flex items-center justify-between gap-4">
                <span className="text-muted-foreground">Max</span>
                <span
                  style={{ color: plotStatsData[hoveredIndex].color ?? color }}
                >
                  {valueFormatter(plotStatsData[hoveredIndex].max)}
                </span>
              </div>
              <div className="flex items-center justify-between gap-4">
                <span className="text-muted-foreground">Q3</span>
                <span
                  style={{ color: plotStatsData[hoveredIndex].color ?? color }}
                >
                  {valueFormatter(plotStatsData[hoveredIndex].q3)}
                </span>
              </div>
              <div className="flex items-center justify-between gap-4">
                <span className="text-muted-foreground">Median</span>
                <span
                  style={{ color: plotStatsData[hoveredIndex].color ?? color }}
                >
                  {valueFormatter(plotStatsData[hoveredIndex].median)}
                </span>
              </div>
              <div className="flex items-center justify-between gap-4">
                <span className="text-muted-foreground">Q1</span>
                <span
                  style={{ color: plotStatsData[hoveredIndex].color ?? color }}
                >
                  {valueFormatter(plotStatsData[hoveredIndex].q1)}
                </span>
              </div>
              <div className="flex items-center justify-between gap-4">
                <span className="text-muted-foreground">Min</span>
                <span
                  style={{ color: plotStatsData[hoveredIndex].color ?? color }}
                >
                  {valueFormatter(plotStatsData[hoveredIndex].min)}
                </span>
              </div>
            </div>
          </div>
        </div>
      )}

      <ChartZoomResetButton
        visible={isZoomed}
        onReset={() => setZoomDomain(null)}
      />
    </div>
  )
}

"use client"

import * as React from "react"
import { max, median, min, quantile } from "d3-array"
import { scaleBand, scaleLinear } from "d3-scale"
import { area, curveCardinal } from "d3-shape"

import { cn } from "@/lib/utils"

import {
  ChartZoomResetButton,
  ChartZoomSelectionRect,
  getBandScaleIndexRange,
  useChartZoom,
} from "../chart-zoom"

export interface ViolinDataPoint {
  category: string
  values: number[]
}

export interface ViolinChartProps {
  /** Violin data */
  data: ViolinDataPoint[]
  className?: string
  /** Visual style variant: standard (full violin), boxplot (box only), split (A/B comparison) */
  variant?: "standard" | "boxplot" | "split"
  /** Show box plot overlay (for standard/split) */
  showBoxPlot?: boolean
  /** Show median marker */
  showMedian?: boolean
  /** Show grid lines */
  showGrid?: boolean
  /** KDE bandwidth (auto-calculated if not provided) */
  bandwidth?: number
  /** KDE resolution (number of points) */
  resolution?: number
  /** Single color for all violins */
  color?: string
  /** Per-category colors */
  colors?: string[]
  /** Groups for split variant (e.g., ["Group A", "Group B"]) */
  splitGroups?: [string, string]
  /** Custom value formatter */
  valueFormatter?: (value: number) => string
}

// Kernel density estimation using Gaussian kernel
function kde(
  values: number[],
  domain: [number, number],
  bandwidth: number,
  resolution: number
): Array<{ x: number; density: number }> {
  const [minVal, maxVal] = domain
  const step = (maxVal - minVal) / resolution
  const points: Array<{ x: number; density: number }> = []

  for (let x = minVal; x <= maxVal; x += step) {
    let density = 0
    for (const v of values) {
      const u = (x - v) / bandwidth
      // Gaussian kernel
      density += Math.exp(-0.5 * u * u) / Math.sqrt(2 * Math.PI)
    }
    density /= values.length * bandwidth
    points.push({ x, density })
  }

  return points
}

// Calculate statistics for a set of values
function calculateStats(values: number[]) {
  const sorted = [...values].sort((a, b) => a - b)
  const q1 = quantile(sorted, 0.25) ?? 0
  const med = median(sorted) ?? 0
  const q3 = quantile(sorted, 0.75) ?? 0
  const minVal = min(sorted) ?? 0
  const maxVal = max(sorted) ?? 0
  const iqr = q3 - q1

  // Silverman's rule of thumb for bandwidth
  const std = Math.sqrt(
    values.reduce((acc, v) => acc + Math.pow(v - med, 2), 0) / values.length
  )
  const autoBandwidth =
    0.9 * Math.min(std, iqr / 1.34) * Math.pow(values.length, -0.2)

  return { q1, median: med, q3, min: minVal, max: maxVal, autoBandwidth }
}

const DEFAULT_COLORS = [
  "var(--chart-1)",
  "var(--chart-2)",
  "var(--chart-3)",
  "var(--chart-4)",
  "var(--chart-5)",
  "var(--chart-1)",
]

export function ViolinChart({
