  )
  const isZoomed = zoomDomain !== null

  // Reset any active zoom if the underlying data set changes.
  React.useEffect(() => {
    setZoomDomain(null)
  }, [data])

  // Narrow the view to the zoomed index window — categories are
  // independent of one another, so filtering the raw data is safe.
  const plotData = zoomDomain
    ? data.slice(zoomDomain[0], zoomDomain[1] + 1)
    : data

  // Dynamic sizing based on the full (unzoomed) data set — keeps the
  // chart's overall footprint stable while zoomed in, letting the
  // remaining violins widen to fill the same plot area.
  const width = Math.max(400, data.length * 80 + 100)
  const height = 320
  const margin = { top: 20, right: 30, bottom: 50, left: 55 }
  const innerWidth = width - margin.left - margin.right
  const innerHeight = height - margin.top - margin.bottom

  // Get color for a category
  const getColor = (index: number): string => {
    if (color) return color
    return colors[index % colors.length]
  }

  // Split variant colors
  const splitColors = splitGroups
    ? [colors[0], colors[1]]
    : ["var(--chart-1)", "var(--chart-4)"]

  // Process data
  const processedData = React.useMemo(() => {
    if (!plotData || plotData.length === 0) return []

    const allValues = plotData.flatMap((d) => d.values)
    const globalMin = min(allValues) ?? 0
    const globalMax = max(allValues) ?? 100
    const padding = (globalMax - globalMin) * 0.1
    const domain: [number, number] = [globalMin - padding, globalMax + padding]

    return plotData.map((d) => {
      const stats = calculateStats(d.values)
      const bw = bandwidthProp ?? stats.autoBandwidth

      return {
        category: d.category,
        values: d.values,
        density: kde(d.values, domain, bw, resolution),
        stats,
      }
    })
  }, [plotData, bandwidthProp, resolution])

  // Category scale
  const categoryScale = React.useMemo(() => {
    return scaleBand<string>()
      .domain(plotData.map((d) => d.category))
      .range([0, innerWidth])
      .padding(0.3)
  }, [plotData, innerWidth])

  // Value scale (Y-axis)
  const valueScale = React.useMemo(() => {
    const allValues = plotData.flatMap((d) => d.values)
    const minV = min(allValues) ?? 0
    const maxV = max(allValues) ?? 100
    const padding = (maxV - minV) * 0.15

    return scaleLinear()
      .domain([minV - padding, maxV + padding])
      .range([innerHeight, 0])
      .nice()
  }, [plotData, innerHeight])

  // Drag-to-zoom: converts the pixel drag range into a data-index range
  // (band scale) and narrows the view to it.
  const zoom = useChartZoom({
    svgRef,
    marginLeft: margin.left,
    innerWidth,
    onZoom: ({ x0, x1 }) => {
      const [start, end] = getBandScaleIndexRange(categoryScale, x0, x1)
      const currentOffset = zoomDomain ? zoomDomain[0] : 0
      setZoomDomain([currentOffset + start, currentOffset + end])
    },
    onReset: () => setZoomDomain(null),
  })

  // Max density across all violins (for width scaling)
  const maxDensity = React.useMemo(() => {
    return (
      max(
        processedData.flatMap((d) =>
          d.density ? [max(d.density, (p) => p.density) ?? 0] : []
        )
      ) ?? 1
    )
  }, [processedData])

  // Density scale (for violin width)
  const densityScale = scaleLinear()
    .domain([0, maxDensity])
    .range([0, categoryScale.bandwidth() / 2])

  const yTicks = valueScale.ticks(6)

  // Render single violin (full or half for split variant)
  const renderViolin = (
    density: Array<{ x: number; density: number }>,
    center: number,
    isHovered: boolean,
    violinColor: string,
    side?: "left" | "right" // For split variant
  ) => {
    let violinArea

    if (side === "left") {
      // Left half only
      violinArea = area<{ x: number; density: number }>()
        .curve(curveCardinal)
        .x0(() => center)
        .x1((p) => center - densityScale(p.density))
        .y((p) => valueScale(p.x))
    } else if (side === "right") {
      // Right half only
      violinArea = area<{ x: number; density: number }>()
        .curve(curveCardinal)
        .x0(() => center)
        .x1((p) => center + densityScale(p.density))
        .y((p) => valueScale(p.x))
    } else {
      // Full violin
      violinArea = area<{ x: number; density: number }>()
        .curve(curveCardinal)
        .x0((p) => center - densityScale(p.density))
        .x1((p) => center + densityScale(p.density))
        .y((p) => valueScale(p.x))
    }

    return (
      <path
        d={violinArea(density) ?? ""}
        fill={violinColor}
        fillOpacity={isHovered ? 0.4 : 0.25}
        stroke={violinColor}
        strokeWidth={isHovered ? 2 : 1.5}
        className="transition-all duration-150"
      />
    )
  }

  // Render box plot
  const renderBoxPlot = (
    stats: { q1: number; median: number; q3: number; min: number; max: number },
    center: number,
    boxColor: string
  ) => {
    const boxWidth = 6

    return (
      <g>
        {/* Whisker line */}
        <line
          x1={center}
          x2={center}
          y1={valueScale(stats.min)}
          y2={valueScale(stats.max)}
          stroke={boxColor}
          strokeWidth={1}
        />
        {/* Box */}
        <rect
          x={center - boxWidth / 2}
          y={valueScale(stats.q3)}
          width={boxWidth}
          height={Math.max(0, valueScale(stats.q1) - valueScale(stats.q3))}
          fill={boxColor}
          fillOpacity={0.7}
          rx={1}
        />
        {/* Whisker caps */}
        <line
          x1={center - 3}
          x2={center + 3}
          y1={valueScale(stats.min)}
          y2={valueScale(stats.min)}
          stroke={boxColor}
          strokeWidth={1}
        />
        <line
          x1={center - 3}
          x2={center + 3}
          y1={valueScale(stats.max)}
          y2={valueScale(stats.max)}
          stroke={boxColor}
          strokeWidth={1}
        />
      </g>
    )
  }

  // Render median marker
  const renderMedian = (
    medianVal: number,
    center: number,
    medianColor: string
  ) => (
    <circle
      cx={center}
      cy={valueScale(medianVal)}
      r={3}
      fill="white"
      stroke={medianColor}
      strokeWidth={2}
    />
  )

  const handleMouseMove = (e: React.MouseEvent<SVGSVGElement>) => {
    if (!svgRef.current) return
    const rect = svgRef.current.getBoundingClientRect()
    const x = e.clientX - rect.left - margin.left

    // Find which category is being hovered
    let hoveredIdx: number | null = null
    plotData.forEach((d, i) => {
      const catX = categoryScale(d.category) ?? 0
      if (x >= catX && x <= catX + categoryScale.bandwidth()) {
        hoveredIdx = i
      }
    })

    if (hoveredIdx !== null) {
      setTooltipPos({
        x:
          (categoryScale(plotData[hoveredIdx].category) ?? 0) +
          categoryScale.bandwidth() / 2 +
          margin.left,
        y: margin.top + 20,
      })
    }
    setHoveredIndex(hoveredIdx)
  }

  const handleSvgMouseMove = (e: React.MouseEvent<SVGSVGElement>) => {
    handleMouseMove(e)
    zoom.handlers.onMouseMove(e)
  }

  const handleSvgMouseLeave = (e: React.MouseEvent<SVGSVGElement>) => {
    setHoveredIndex(null)
    zoom.handlers.onMouseLeave(e)
  }

  if (!data || data.length === 0 || processedData.length === 0) {
    return (
      <div
        className={cn(
          "text-muted-foreground flex h-[320px] items-center justify-center",
          className
        )}
      >
        No data available
      </div>
    )
  }

  return (
    <div className={cn("relative w-full", className)}>
      <svg
        ref={svgRef}
        viewBox={`0 0 ${width} ${height}`}
        className="h-auto w-full overflow-visible select-none"
        onMouseMove={handleSvgMouseMove}
        onMouseLeave={handleSvgMouseLeave}
        onMouseDown={zoom.handlers.onMouseDown}
        onMouseUp={zoom.handlers.onMouseUp}
        onDoubleClick={zoom.handlers.onDoubleClick}
      >
        <g transform={`translate(${margin.left}, ${margin.top})`}>
          {/* Drag-to-zoom selection rectangle */}
          <ChartZoomSelectionRect range={zoom.dragRange} height={innerHeight} />

          {/* Grid lines */}
          {showGrid &&
            yTicks.map((tick) => (
              <line
                key={tick}
                x1={0}
                x2={innerWidth}
                y1={valueScale(tick)}
                y2={valueScale(tick)}
                strokeWidth={1}
                className="stroke-zinc-200 dark:stroke-zinc-700"
              />
            ))}

          {/* X axis line */}
          <line
            x1={0}
            x2={innerWidth}
            y1={innerHeight}
            y2={innerHeight}
            strokeWidth={1}
            className="stroke-zinc-300 dark:stroke-zinc-600"
          />

          {/* Render violins */}
          {processedData.map((d, i) => {
            const center =
              (categoryScale(d.category) ?? 0) + categoryScale.bandwidth() / 2
            const isHovered = hoveredIndex === i
            const violinColor = getColor(i)

            if (variant === "split") {
              // Split variant: render two half-violins side by side
              return (
                <g key={d.category}>
                  {/* Left half (Group A) */}
                  {renderViolin(
                    d.density,
                    center,
                    isHovered,
                    splitColors[0],
                    "left"
                  )}
                  {/* Right half (Group B) */}
                  {renderViolin(
                    d.density,
                    center,
                    isHovered,
                    splitColors[1],
                    "right"
                  )}
                  {/* Median markers */}
                  {showMedian && (
                    <>
                      <circle
                        cx={center - 4}
                        cy={valueScale(d.stats.median)}
                        r={2.5}
                        fill="white"
                        stroke={splitColors[0]}
                        strokeWidth={1.5}
                      />
                      <circle
                        cx={center + 4}
                        cy={valueScale(d.stats.median)}
                        r={2.5}
                        fill="white"
                        stroke={splitColors[1]}
                        strokeWidth={1.5}
                      />
                    </>
                  )}
                </g>
              )
            }

            return (
              <g key={d.category}>
                {/* Violin shape */}
                {variant !== "boxplot" &&
                  renderViolin(d.density, center, isHovered, violinColor)}

                {/* Box plot */}
                {(showBoxPlot || variant === "boxplot") &&
                  renderBoxPlot(d.stats, center, violinColor)}

                {/* Median marker */}
                {showMedian &&
                  renderMedian(d.stats.median, center, violinColor)}
              </g>
            )
          })}

          {/* Category labels */}
          {plotData.map((d) => (
            <text
              key={d.category}
              x={
                (categoryScale(d.category) ?? 0) + categoryScale.bandwidth() / 2
              }
              y={innerHeight + 25}
              textAnchor="middle"
              fontSize={12}
              className="fill-foreground"
            >
              {d.category}
            </text>
          ))}

          {/* Y axis labels */}
          {yTicks.map((tick) => (
            <text
              key={tick}
              x={-12}
              y={valueScale(tick)}
              textAnchor="end"
              dominantBaseline="middle"
              fontSize={11}
              className="fill-muted-foreground"
            >
              {valueFormatter(tick)}
            </text>
          ))}
        </g>
      </svg>

      {/* Tooltip */}
      {hoveredIndex !== null && processedData[hoveredIndex] && (
        <div
          className="bg-foreground text-background pointer-events-none absolute z-50 -translate-x-1/2 rounded-lg px-3 py-2 text-xs shadow-lg"
          style={{ left: tooltipPos.x, top: tooltipPos.y }}
        >
          <div className="mb-1 font-semibold">
            {processedData[hoveredIndex].category}
          </div>
          <div className="space-y-0.5 opacity-90">
            <div>n: {processedData[hoveredIndex].values.length}</div>
            <div>
              Median: {valueFormatter(processedData[hoveredIndex].stats.median)}
            </div>
            <div>
              Q1-Q3: {valueFormatter(processedData[hoveredIndex].stats.q1)} -{" "}
              {valueFormatter(processedData[hoveredIndex].stats.q3)}
            </div>
            <div>
              Range: {valueFormatter(processedData[hoveredIndex].stats.min)} -{" "}
              {valueFormatter(processedData[hoveredIndex].stats.max)}
            </div>
          </div>
        </div>
      )}

      <ChartZoomResetButton
        visible={isZoomed}
        onReset={() => setZoomDomain(null)}
      />
    </div>
  )
}

"use client"

import * as React from "react"
import { scaleBand, scaleLinear } from "d3-scale"

import { cn } from "@/lib/utils"

import { ChartAxis } from "../chart-axis"
import {
  ChartZoomResetButton,
  ChartZoomSelectionRect,
  getBandScaleIndexRange,
  useChartZoom,
} from "../chart-zoom"

export interface CandlestickDataPoint {
  date: string | Date
  open: number
  high: number
  low: number
  close: number
}

export interface CandlestickChartProps {
  data: CandlestickDataPoint[]
  className?: string
  upColor?: string
  downColor?: string
  showGrid?: boolean
  showTooltip?: boolean
  hollowCandles?: boolean
  aspectRatio?: number
  valueFormatter?: (value: number) => string
  dateFormatter?: (date: Date) => string
  /**
   * Axis title text. Renders centered along the axis edge, same
   * convention as line-chart / area-chart.
   */
  xAxisLabel?: string
  yAxisLabel?: string
}

export function CandlestickChart({
  data,
  className,
  upColor = "var(--chart-2)",
  downColor = "var(--chart-4)",
  showGrid = true,
  showTooltip = true,
  hollowCandles = false,
  aspectRatio = 2.5,
  valueFormatter = (value) => `$${value.toFixed(0)}`,
  dateFormatter = (date) =>
    date.toLocaleDateString("en-US", { month: "short" }),
  xAxisLabel,
  yAxisLabel,
}: CandlestickChartProps) {
  const containerRef = React.useRef<HTMLDivElement>(null)
  const svgRef = React.useRef<SVGSVGElement>(null)
  const [dimensions, setDimensions] = React.useState({ width: 0, height: 0 })
  const [hoveredIndex, setHoveredIndex] = React.useState<number | null>(null)
  const [tooltipPos, setTooltipPos] = React.useState({ x: 0, y: 0 })
  const [zoomDomain, setZoomDomain] = React.useState<[number, number] | null>(
    null
  )
  const isZoomed = zoomDomain !== null
  const plotData = zoomDomain
    ? data.slice(zoomDomain[0], zoomDomain[1] + 1)
    : data

  // Responsive sizing
  React.useEffect(() => {
    const updateDimensions = () => {
      if (containerRef.current) {
        const width = containerRef.current.offsetWidth
        setDimensions({ width, height: width / aspectRatio })
      }
    }
    updateDimensions()
    window.addEventListener("resize", updateDimensions)
    return () => window.removeEventListener("resize", updateDimensions)
  }, [aspectRatio])

  // Reset any active zoom if the underlying data set changes.
  React.useEffect(() => {
    setZoomDomain(null)
  }, [data])

  const { width, height } = dimensions
  const margin = { top: 20, right: 20, bottom: 40, left: 50 }
  const innerWidth = Math.max(0, width - margin.left - margin.right)
  const innerHeight = Math.max(0, height - margin.top - margin.bottom)

  // X Scale
  const xScale = React.useMemo(() => {
    return scaleBand()
      .domain(plotData.map((d) => String(d.date)))
      .range([0, innerWidth])
      .padding(0.2)
  }, [plotData, innerWidth])

  // Y Scale (price)
  const yScale = React.useMemo(() => {
    const allPrices = plotData.flatMap((d) => [d.high, d.low])
    const minPrice = Math.min(...allPrices)
    const maxPrice = Math.max(...allPrices)
    const padding = (maxPrice - minPrice) * 0.1
    return scaleLinear()
      .domain([Math.max(0, minPrice - padding), maxPrice + padding])
      .range([innerHeight, 0])
      .nice()
  }, [plotData, innerHeight])

  // Drag-to-zoom: converts the pixel drag range into a data-index range
  // (band scale) and narrows the view to it.
  const zoom = useChartZoom({
    svgRef,
    marginLeft: margin.left,
    innerWidth,
    onZoom: ({ x0, x1 }) => {
      const [start, end] = getBandScaleIndexRange(xScale, x0, x1)
      const currentOffset = zoomDomain ? zoomDomain[0] : 0
      setZoomDomain([currentOffset + start, currentOffset + end])
    },
    onReset: () => setZoomDomain(null),
  })

  const candleWidth = xScale.bandwidth() * 0.8
  const ticks = yScale.ticks(5)

  // Get unique months for x-axis labels
  const monthLabels = React.useMemo(() => {
    const labels: { date: string; x: number }[] = []
    let lastMonth = -1
    plotData.forEach((d) => {
      const date = new Date(d.date)
      const month = date.getMonth()
      if (month !== lastMonth) {
        labels.push({
          date: String(d.date),
          x: (xScale(String(d.date)) ?? 0) + xScale.bandwidth() / 2,
        })
        lastMonth = month
      }
    })
    return labels
  }, [plotData, xScale])

  if (width === 0) {
    return <div ref={containerRef} className={cn("w-full", className)} />
  }

  return (
    <div ref={containerRef} className={cn("relative w-full", className)}>
      <svg
        ref={svgRef}
        width={width}
        height={height}
        viewBox={`0 0 ${width} ${height}`}
        className="overflow-visible select-none"
        onMouseDown={zoom.handlers.onMouseDown}
        onMouseMove={zoom.handlers.onMouseMove}
        onMouseUp={zoom.handlers.onMouseUp}
        onMouseLeave={zoom.handlers.onMouseLeave}
        onDoubleClick={zoom.handlers.onDoubleClick}
      >
        <g transform={`translate(${margin.left}, ${margin.top})`}>
          {/* Drag-to-zoom selection rectangle */}
          <ChartZoomSelectionRect range={zoom.dragRange} height={innerHeight} />

          {/* Grid - dashed lines like area chart */}
          {showGrid && (
            <>
              {/* Horizontal grid lines */}
              {ticks.map((tick) => (
                <line
                  key={`h-${tick}`}
                  x1={0}
                  x2={innerWidth}
                  y1={yScale(tick)}
                  y2={yScale(tick)}
                  stroke="hsl(var(--border))"
                  strokeDasharray="3 3"
                  strokeOpacity={0.5}
                />
              ))}
              {/* Vertical grid lines at month boundaries */}
              {monthLabels.map((label, i) => (
                <line
                  key={`v-${i}`}
                  x1={label.x}
                  x2={label.x}
                  y1={0}
                  y2={innerHeight}
                  stroke="hsl(var(--border))"
                  strokeDasharray="3 3"
                  strokeOpacity={0.5}
                />
              ))}
            </>
          )}

          {/* Candlesticks */}
          {plotData.map((d, index) => {
            const isUp = d.close >= d.open
            const color = isUp ? upColor : downColor
            const bodyTop = isUp ? d.close : d.open
            const bodyBottom = isUp ? d.open : d.close
            const x = (xScale(String(d.date)) ?? 0) + xScale.bandwidth() / 2
            const isHovered = hoveredIndex === index

            // For hollow candles: up candles are hollow, down are filled
            const fill = hollowCandles ? (isUp ? "transparent" : color) : color

            return (
              <g
                key={index}
                className={cn(
                  "cursor-pointer transition-opacity duration-200",
                  hoveredIndex !== null && !isHovered && "opacity-40"
                )}
                onMouseEnter={(e) => {
                  setHoveredIndex(index)
                  const rect = containerRef.current?.getBoundingClientRect()
                  if (rect) {
                    setTooltipPos({
                      x: e.clientX - rect.left,
                      y: e.clientY - rect.top,
                    })
                  }
                }}
                onMouseMove={(e) => {
                  const rect = containerRef.current?.getBoundingClientRect()
                  if (rect) {
                    setTooltipPos({
                      x: e.clientX - rect.left,
                      y: e.clientY - rect.top,
                    })
                  }
                }}
                onMouseLeave={() => setHoveredIndex(null)}
              >
                {/* Wick (high to low) */}
                <line
                  x1={x}
                  x2={x}
                  y1={yScale(d.high)}
                  y2={yScale(d.low)}
                  stroke={color}
                  strokeWidth={1}
                />

                {/* Body */}
                <rect
                  x={x - candleWidth / 2}
                  y={yScale(bodyTop)}
                  width={candleWidth}
                  height={Math.max(1, yScale(bodyBottom) - yScale(bodyTop))}
                  fill={fill}
                  stroke={color}
                  strokeWidth={1}
                  rx={1}
                />
              </g>
            )
          })}

          {/* X Axis — delegated to the shared ChartAxis primitive so
              we get the axis line + axis title + band-scale tick
              sampling for free (same code path as line-chart). */}
          <ChartAxis
            scale={xScale}
            orientation="bottom"
            transform={`translate(0, ${innerHeight})`}
            label={xAxisLabel}
            tickFormat={(d) => dateFormatter(new Date(d as string))}
          />

          {/* Y Axis — same primitive, with the existing $ formatter
              for tick values. Pre-refactor this was bare <text>
              labels with no axis line and no title support. */}
          <ChartAxis
            scale={yScale}
            orientation="left"
            label={yAxisLabel}
            tickFormat={(d) => valueFormatter(d as number)}
          />
        </g>
      </svg>

      {/* Tooltip - auto-adjusts position based on available space */}
      {showTooltip &&
        hoveredIndex !== null &&
        (() => {
          const tooltipWidth = 140
          const tooltipHeight = 120
          const padding = 10

          // Determine horizontal position
          const spaceOnRight = width - tooltipPos.x
          const showOnLeft = spaceOnRight < tooltipWidth + padding * 2

          // Determine vertical position
          const spaceOnTop = tooltipPos.y
          const showBelow = spaceOnTop < tooltipHeight + padding

          return (
            <div
              className="pointer-events-none absolute z-50"
              style={{
                left: showOnLeft
                  ? tooltipPos.x - padding
                  : tooltipPos.x + padding,
                top: showBelow
                  ? tooltipPos.y + padding
                  : tooltipPos.y - padding,
                transform: `translate(${showOnLeft ? "-100%" : "0"}, ${showBelow ? "0" : "-100%"})`,
              }}
            >
              <div className="bg-background rounded-lg border px-3 py-2 shadow-lg">
                <p className="text-foreground mb-1 text-sm font-medium">
                  {new Date(plotData[hoveredIndex].date).toLocaleDateString(
                    "en-US",
                    {
                      month: "short",
                      day: "numeric",
                      year: "numeric",
                    }
                  )}
                </p>
                <div className="grid grid-cols-2 gap-x-4 gap-y-0.5 text-sm">
                  <span className="text-muted-foreground">Open</span>
                  <span
                    className="font-mono"
                    style={{
                      color:
                        plotData[hoveredIndex].close >=
                        plotData[hoveredIndex].open
                          ? upColor
                          : downColor,
                    }}
                  >
                    {valueFormatter(plotData[hoveredIndex].open)}
                  </span>
                  <span className="text-muted-foreground">High</span>
                  <span
                    className="font-mono"
                    style={{
                      color:
                        plotData[hoveredIndex].close >=
                        plotData[hoveredIndex].open
                          ? upColor
                          : downColor,
                    }}
                  >
                    {valueFormatter(plotData[hoveredIndex].high)}
                  </span>
                  <span className="text-muted-foreground">Low</span>
                  <span
                    className="font-mono"
                    style={{
                      color:
                        plotData[hoveredIndex].close >=
                        plotData[hoveredIndex].open
                          ? upColor
                          : downColor,
                    }}
                  >
                    {valueFormatter(plotData[hoveredIndex].low)}
                  </span>
                  <span className="text-muted-foreground">Close</span>
                  <span
                    className="font-mono"
                    style={{
                      color:
                        plotData[hoveredIndex].close >=
                        plotData[hoveredIndex].open
                          ? upColor
                          : downColor,
                    }}
                  >
                    {valueFormatter(plotData[hoveredIndex].close)}
                  </span>
                </div>
              </div>
            </div>
          )
        })()}

      <ChartZoomResetButton
        visible={isZoomed}
        onReset={() => setZoomDomain(null)}
      />
    </div>
  )
}

"use client"

import * as React from "react"
import { scaleBand, scaleLinear } from "d3-scale"

import { cn } from "@/lib/utils"

import { ChartAxis } from "../chart-axis"
import type { BaseChartProps, ChartConfig } from "../chart-config"
import { ChartContainer } from "../chart-container"
import { ChartHorizontalGrid } from "../chart-grid"
import { ChartTooltipContent } from "../chart-tooltip"
import {
  ChartZoomResetButton,
  ChartZoomSelectionRect,
  getBandScaleIndexRange,
  useChartZoom,
} from "../chart-zoom"

export interface WaterfallDataPoint {
  label: string
  value: number
  isTotal?: boolean
  isSubtotal?: boolean
}

export interface WaterfallChartProps extends BaseChartProps {
  data: WaterfallDataPoint[]
  positiveColor?: string
  negativeColor?: string
  totalColor?: string
  connectorColor?: string
  showConnector?: boolean
  barRadius?: number
  xAxisLabel?: string
  yAxisLabel?: string
}

export function WaterfallChart({
  data,
  config,
  className,
  width = 700,
  height = 400,
  margin = { top: 20, right: 20, bottom: 60, left: 60 },
  showGrid = true,
  showTooltip = true,
  positiveColor = "var(--chart-1)",
  negativeColor = "var(--chart-3)",
  totalColor = "var(--chart-5)",
  connectorColor = "currentColor",
  showConnector = true,
  barRadius = 2,
  xAxisLabel,
  yAxisLabel,
}: WaterfallChartProps) {
  const [hoveredIndex, setHoveredIndex] = React.useState<number | null>(null)
  const svgRef = React.useRef<SVGSVGElement>(null)
  const [zoomDomain, setZoomDomain] = React.useState<[number, number] | null>(
    null
  )
  const isZoomed = zoomDomain !== null

  const innerWidth = width - margin.left - margin.right
  const innerHeight = height - margin.top - margin.bottom

  // Calculate cumulative values against the full (unzoomed) data set so
  // running totals stay correct regardless of the current zoom window.
  const processedData = React.useMemo(() => {
    let runningTotal = 0
    return data.map((d, i) => {
      const start = d.isTotal || d.isSubtotal ? 0 : runningTotal
      const end = d.isTotal || d.isSubtotal ? d.value : runningTotal + d.value
      runningTotal = end
      return {
        ...d,
        start,
        end,
        isPositive: d.value >= 0,
      }
    })
  }, [data])

  // Reset any active zoom if the underlying data set changes.
  React.useEffect(() => {
    setZoomDomain(null)
  }, [data])

  // Narrow the view to the zoomed index window (slicing the already
  // cumulative-processed data keeps each bar's true start/end position).
  const plotData = zoomDomain
    ? processedData.slice(zoomDomain[0], zoomDomain[1] + 1)
    : processedData

  // Scales
  const xScale = React.useMemo(() => {
    return scaleBand()
      .domain(plotData.map((d) => d.label))
      .range([0, innerWidth])
      .padding(0.3)
  }, [plotData, innerWidth])

  const yScale = React.useMemo(() => {
    const allValues = plotData.flatMap((d) => [d.start, d.end])
    const minVal = Math.min(0, ...allValues)
    const maxVal = Math.max(0, ...allValues)
    const padding = (maxVal - minVal) * 0.1
    return scaleLinear()
      .domain([minVal - padding, maxVal + padding])
      .range([innerHeight, 0])
      .nice()
  }, [plotData, innerHeight])

  // Drag-to-zoom: converts the pixel drag range into a data-index range
  // (band scale) and narrows the view to it.
  const zoom = useChartZoom({
    svgRef,
    marginLeft: margin.left,
    innerWidth,
    onZoom: ({ x0, x1 }) => {
      const [start, end] = getBandScaleIndexRange(xScale, x0, x1)
      const currentOffset = zoomDomain ? zoomDomain[0] : 0
      setZoomDomain([currentOffset + start, currentOffset + end])
    },
    onReset: () => setZoomDomain(null),
  })

  return (
    <ChartContainer
      config={config}
      className={cn("relative !aspect-auto", className)}
    >
      <svg
        ref={svgRef}
        viewBox={`0 0 ${width} ${height}`}
        className="h-full w-full select-none"
        onMouseDown={zoom.handlers.onMouseDown}
        onMouseMove={zoom.handlers.onMouseMove}
        onMouseUp={zoom.handlers.onMouseUp}
        onMouseLeave={zoom.handlers.onMouseLeave}
        onDoubleClick={zoom.handlers.onDoubleClick}
      >
        <g transform={`translate(${margin.left}, ${margin.top})`}>
          {/* Drag-to-zoom selection rectangle */}
          <ChartZoomSelectionRect range={zoom.dragRange} height={innerHeight} />

          {/* Grid */}
          {showGrid && (
            <ChartHorizontalGrid scale={yScale} width={innerWidth} />
          )}

          {/* Zero line */}
          <line
            x1={0}
            x2={innerWidth}
            y1={yScale(0)}
            y2={yScale(0)}
            stroke="currentColor"
            strokeWidth={1}
            className="text-border"
          />

          {/* Bars and connectors */}
          {plotData.map((d, index) => {
            const x = xScale(d.label) ?? 0
            const barWidth = xScale.bandwidth()
            const y1 = yScale(Math.max(d.start, d.end))
            const y2 = yScale(Math.min(d.start, d.end))
            const barHeight = Math.abs(y2 - y1)

            const color =
              d.isTotal || d.isSubtotal
                ? totalColor
                : d.isPositive
                  ? positiveColor
                  : negativeColor

            const isHovered = hoveredIndex === index

            return (
              <g key={index}>
                {/* Connector line */}
                {showConnector && index > 0 && !d.isTotal && (
                  <line
                    x1={xScale(plotData[index - 1].label)! + barWidth}
                    x2={x}
                    y1={yScale(plotData[index - 1].end)}
                    y2={yScale(plotData[index - 1].end)}
                    stroke={connectorColor}
                    strokeWidth={1}
                    strokeDasharray="3,3"
                    className="text-muted-foreground/50"
                  />
                )}

                {/* Bar */}
                <rect
                  x={x}
                  y={y1}
                  width={barWidth}
                  height={Math.max(1, barHeight)}
                  fill={color}
                  rx={barRadius}
                  ry={barRadius}
                  className={cn(
                    "cursor-pointer transition-opacity duration-200",
                    hoveredIndex !== null && !isHovered && "opacity-50"
                  )}
                  onMouseEnter={() => setHoveredIndex(index)}
                  onMouseLeave={() => setHoveredIndex(null)}
                />

                {/* Value label */}
                <text
                  x={x + barWidth / 2}
                  y={d.value >= 0 ? y1 - 5 : y2 + 14}
                  textAnchor="middle"
                  className="fill-foreground pointer-events-none text-[10px] font-medium"
                >
                  {d.value >= 0 ? "+" : ""}
                  {d.value.toLocaleString()}
                </text>
              </g>
            )
          })}

          {/* X Axis */}
          <ChartAxis
            scale={xScale}
            orientation="bottom"
            transform={`translate(0, ${innerHeight})`}
            label={xAxisLabel}
          />

          {/* Y Axis */}
          <ChartAxis scale={yScale} orientation="left" label={yAxisLabel} />
        </g>
      </svg>

      {/* Tooltip */}
      {showTooltip && hoveredIndex !== null && (
        <div
          className="pointer-events-none absolute z-50"
          style={{
            left:
              margin.left +
              (xScale(plotData[hoveredIndex].label) ?? 0) +
              xScale.bandwidth() / 2,
            top:
              margin.top +
              yScale(
                Math.max(
                  plotData[hoveredIndex].start,
                  plotData[hoveredIndex].end
                )
              ) -
              50,
          }}
        >
          <div className="border-border/50 bg-background -translate-x-1/2 rounded-lg border px-2.5 py-1.5 text-xs shadow-xl">
            <div className="font-medium">{plotData[hoveredIndex].label}</div>
            <div className="text-muted-foreground">
              Change: {plotData[hoveredIndex].value >= 0 ? "+" : ""}
              {plotData[hoveredIndex].value.toLocaleString()}
            </div>
            <div className="text-muted-foreground">
              Running Total: {plotData[hoveredIndex].end.toLocaleString()}
            </div>
          </div>
        </div>
      )}

      <ChartZoomResetButton
        visible={isZoomed}
        onReset={() => setZoomDomain(null)}
      />
    </ChartContainer>
  )
}

"use client"

import * as React from "react"
import { scaleLinear } from "d3-scale"
import { area, curveBasis } from "d3-shape"

import { cn } from "@/lib/utils"

import type { BaseChartProps, ChartConfig } from "../chart-config"
import { ChartContainer } from "../chart-container"
import {
  ChartLegend,
  ChartLegendLayout,
  useSeriesHighlight,
  type LegendItem,
} from "../chart-legend"

export interface FunnelSeries {
  name: string
  values: number[] // Value at each stage
  color?: string
}

export interface FunnelChartProps extends BaseChartProps {
  /** Stage labels */
  stages: string[]
  /** Data series - each series flows through all stages */
  series: FunnelSeries[]
  /** Color scheme */
  colorScheme?:
    | "orange"
    | "blue"
    | "purple"
    | "green"
    | "pink"
    | "theme"
    | "custom"
  /** Show stage markers (vertical lines) */
  showStageMarkers?: boolean
  /** Show value pills at each stage */
  showValuePills?: boolean
  /** Position of value pills */
  pillPosition?: "top" | "bottom" | "both" | "center"
  /** Animate on mount */
  animate?: boolean
  /** Animation duration */
  animationDuration?: number
  /** Value formatter */
  valueFormatter?: (value: number) => string
  /** Minimum height for the flow (prevents collapse to zero) */
  minFlowHeight?: number
  /** How much of vertical space to use (0-1, default 0.85) */
  flowExpansion?: number
  /** Click handler */
  onSeriesClick?: (series: FunnelSeries, stageIndex: number) => void
}

// Legacy interface for backwards compatibility
export interface FunnelDataPoint {
  label: string
  value: number
  color?: string
}

// Color schemes matching the images - gradient from light to dark
const COLOR_SCHEMES = {
  orange: [
    "#FEF3C7", // lightest
    "#FDE68A",
    "#FCD34D",
    "#FBBF24",
    "#F59E0B",
    "#D97706",
    "#B45309",
    "#92400E", // darkest
  ],
  blue: [
    "#DBEAFE",
    "#BFDBFE",
    "#93C5FD",
    "#60A5FA",
    "#3B82F6",
    "#2563EB",
    "#1D4ED8",
    "#1E40AF",
  ],
  purple: [
    "#EDE9FE",
    "#DDD6FE",
    "#C4B5FD",
    "#A78BFA",
    "#8B5CF6",
    "#7C3AED",
    "#6D28D9",
    "#5B21B6",
  ],
  green: [
    "#D1FAE5",
    "#A7F3D0",
    "#6EE7B7",
    "#34D399",
    "#10B981",
    "#059669",
    "#047857",
    "#065F46",
  ],
  pink: [
    "#FCE7F3",
    "#FBCFE8",
    "#F9A8D4",
    "#F472B6",
    "#EC4899",
    "#DB2777",
    "#BE185D",
    "#9D174D",
  ],
  custom: [],
}

export function FunnelChart({
  stages,
  series,
  config,
  className,
  width = 900,
  height = 320,
  margin = { top: 45, right: 40, bottom: 45, left: 40 },
  showTooltip = true,
  showLegend = true,
  legendPosition = "right",
  colorScheme = "orange",
  showStageMarkers = true,
  showValuePills = true,
  pillPosition = "both",
  animate = true,
  animationDuration = 1000,
  valueFormatter = (v) => v.toLocaleString(),
  minFlowHeight = 12,
  flowExpansion = 0.98,
  onSeriesClick,
}: FunnelChartProps) {
  const [animationProgress, setAnimationProgress] = React.useState(
    animate ? 0 : 1
  )
  const [tooltipData, setTooltipData] = React.useState<{
    x: number
    y: number
    seriesIndex: number
    stageIndex: number
  } | null>(null)
  // Legend/flow click-to-highlight: nothing focused shows every flow, a
  // focused series emphasizes only that one (others fade but stay drawn).
  // Hovering a flow band or legend item previews it; clicking pins the
  // selection (click again to restore all).
  const highlight = useSeriesHighlight()
  const containerRef = React.useRef<HTMLDivElement>(null)
  const gradientId = React.useId().replace(/:/g, "")

  // Animation
  React.useEffect(() => {
    if (!animate) return
    const startTime = Date.now()
    const animateFrame = () => {
      const elapsed = Date.now() - startTime
      const progress = Math.min(elapsed / animationDuration, 1)
      // Ease out cubic
      const eased = 1 - Math.pow(1 - progress, 3)
      setAnimationProgress(eased)
      if (progress < 1) requestAnimationFrame(animateFrame)
    }
    requestAnimationFrame(animateFrame)
  }, [animate, animationDuration])

  const innerWidth = width - margin.left - margin.right
  const innerHeight = height - margin.top - margin.bottom
  const centerY = innerHeight / 2

  const stageCount = stages.length
  const seriesCount = series.length

  // CSS variable colors for theme-aware rendering
  const THEME_COLORS = [
    "var(--chart-5)",
    "var(--chart-4)",
    "var(--chart-3)",
    "var(--chart-2)",
    "var(--chart-1)",
  ]

  // Get color for series - innermost is lightest, outermost is darkest
  const getColor = (index: number): string => {
    if (colorScheme === "custom" && series[index]?.color) {
      return series[index].color!
    }
    if (colorScheme === "theme") {
      const colorIndex = Math.floor(
        (index / Math.max(seriesCount - 1, 1)) * (THEME_COLORS.length - 1)
      )
      return THEME_COLORS[Math.min(colorIndex, THEME_COLORS.length - 1)]
    }
    const scheme = COLOR_SCHEMES[colorScheme] || COLOR_SCHEMES.orange
    // Map series index to color - distribute evenly across scheme
    const colorIndex = Math.floor(
      (index / Math.max(seriesCount - 1, 1)) * (scheme.length - 1)
    )
    return scheme[Math.min(colorIndex, scheme.length - 1)]
  }

  // Legend items — one entry per named funnel series, colored to match its
  // flow band. Clicking / hovering drives the shared highlight state.
  const legendItems: LegendItem[] = series.map((s, i) => ({
    name: s.name,
    color: getColor(i),
  }))

  // Calculate max total at any stage for scaling
  const maxStageTotal = React.useMemo(() => {
    let max = 0
    for (let stageIndex = 0; stageIndex < stageCount; stageIndex++) {
      let total = 0
      for (const s of series) {
        total += s.values[stageIndex] || 0
      }
      max = Math.max(max, total)
    }
    return max || 1
  }, [series, stageCount])

  // Y scale - maps values to heights (half the inner height for symmetric expansion)
  // flowExpansion controls how much of the available vertical space is used
  const yScale = scaleLinear()
    .domain([0, maxStageTotal])
    .range([0, (innerHeight / 2) * flowExpansion])

  // Generate intermediate points for smoother curves
  const generateIntermediatePoints = (
    x1: number,
    y1: number,
    x2: number,
    y2: number,
    segments: number = 3
  ): [number, number][] => {
    const points: [number, number][] = []
    for (let i = 0; i <= segments; i++) {
      const t = i / segments
      // Use ease-in-out for natural flow
      const easeT = t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2
      points.push([x1 + (x2 - x1) * t, y1 + (y2 - y1) * easeT])
    }
    return points
  }

  // Generate flowing area paths for each series
  const areaPaths = React.useMemo(() => {
    const paths: {
      topPath: string
      bottomPath: string
      color: string
      seriesIndex: number
    }[] = []

    // Calculate heights at each stage for each series
    const seriesHeights: number[][] = []
    for (let stageIndex = 0; stageIndex < stageCount; stageIndex++) {
      const heights: number[] = []
      for (let seriesIndex = 0; seriesIndex < seriesCount; seriesIndex++) {
        const value = series[seriesIndex].values[stageIndex] || 0
        const height = Math.max(
          yScale(value) * animationProgress,
          minFlowHeight * animationProgress
        )
        heights.push(height)
      }
      seriesHeights.push(heights)
    }

    // Calculate cumulative offsets at each stage
    const cumulativeOffsets: number[][] = []
    for (let stageIndex = 0; stageIndex < stageCount; stageIndex++) {
      const offsets: number[] = [0]
      let cumulative = 0
      for (let seriesIndex = 0; seriesIndex < seriesCount; seriesIndex++) {
        cumulative += seriesHeights[stageIndex][seriesIndex]
        offsets.push(cumulative)
      }
      cumulativeOffsets.push(offsets)
    }

    // Create area path for each series (from innermost to outermost)
    for (let seriesIndex = 0; seriesIndex < seriesCount; seriesIndex++) {
      // Build points with intermediate values for smooth curves
      const topPoints: [number, number][] = []
      const bottomPoints: [number, number][] = []

      for (let stageIndex = 0; stageIndex < stageCount; stageIndex++) {
        const stageX = (stageIndex / (stageCount - 1)) * innerWidth
        const offset = cumulativeOffsets[stageIndex][seriesIndex]
        const height = seriesHeights[stageIndex][seriesIndex]

        // Top edge (above center line)
        const topY = centerY - offset - height
        // Bottom edge (below center line)
        const bottomY = centerY + offset + height

        if (stageIndex > 0) {
          // Add intermediate points for smooth transitions
          const prevStageX = ((stageIndex - 1) / (stageCount - 1)) * innerWidth
          const prevOffset = cumulativeOffsets[stageIndex - 1][seriesIndex]
          const prevHeight = seriesHeights[stageIndex - 1][seriesIndex]
          const prevTopY = centerY - prevOffset - prevHeight
          const prevBottomY = centerY + prevOffset + prevHeight

          const intermediateTop = generateIntermediatePoints(
            prevStageX,
            prevTopY,
            stageX,
            topY,
            4
          )
          const intermediateBottom = generateIntermediatePoints(
            prevStageX,
            prevBottomY,
            stageX,
            bottomY,
            4
          )

          // Skip first point to avoid duplication
          topPoints.push(...intermediateTop.slice(1))
          bottomPoints.push(...intermediateBottom.slice(1))
        } else {
          topPoints.push([stageX, topY])
          bottomPoints.push([stageX, bottomY])
        }
      }

      // Create SVG path using D3 area
      const areaGenerator = area<[number, number]>()
        .x((d) => d[0])
        .y0((_, i) => bottomPoints[i]?.[1] ?? centerY)
        .y1((d) => d[1])
        .curve(curveBasis)

      const pathData = areaGenerator(topPoints)

      if (pathData) {
        paths.push({
          topPath: pathData,
          bottomPath: pathData, // Same path works due to y0/y1
          color: getColor(seriesIndex),
          seriesIndex,
        })
      }
    }

    // Reverse so innermost (first series) is rendered last (on top visually matches images)
    return paths.reverse()
  }, [
    series,
    seriesCount,
    stageCount,
    innerWidth,
    centerY,
    yScale,
    animationProgress,
    minFlowHeight,
    flowExpansion,
    colorScheme,
  ])

  // Calculate stage X positions
  const stagePositions = React.useMemo(() => {
    return stages.map((_, i) => (i / (stageCount - 1)) * innerWidth)
  }, [stages, stageCount, innerWidth])

  // Calculate values to display in pills (top and bottom at each stage)
  const pillData = React.useMemo(() => {
    return stages.map((_, stageIndex) => {
      // Get values sorted by their position (outer to inner for display)
      const stageValues = series.map((s, i) => ({
        value: s.values[stageIndex] || 0,
        seriesIndex: i,
      }))

      // Top half shows first half of series, bottom shows second half
      const midPoint = Math.ceil(seriesCount / 2)
      const topSeries = stageValues.slice(0, midPoint)
      const bottomSeries = stageValues.slice(midPoint)

      return {
        x: stagePositions[stageIndex],
        topValue: topSeries.reduce((sum, s) => sum + s.value, 0),
        bottomValue: bottomSeries.reduce((sum, s) => sum + s.value, 0),
        totalValue: stageValues.reduce((sum, s) => sum + s.value, 0),
      }
    })
  }, [series, seriesCount, stages, stagePositions])

  // Handle mouse move for tooltip
  const handleMouseMove = (e: React.MouseEvent, seriesIndex: number) => {
    if (!showTooltip) return
    const rect = containerRef.current?.getBoundingClientRect()
    if (rect) {
      // Determine which stage we're over
      const relativeX = e.clientX - rect.left - margin.left
      const stageIndex = Math.round((relativeX / innerWidth) * (stageCount - 1))
      setTooltipData({
        x: e.clientX - rect.left,
        y: e.clientY - rect.top,
        seriesIndex,
        stageIndex: Math.max(0, Math.min(stageCount - 1, stageIndex)),
      })
    }
  }

  return (
    <ChartContainer
      config={config}
      className={cn("relative !aspect-auto", className)}
    >
      {/* Plot + legend layout — legend sits on `legendPosition` side, click a
          flow band or legend item to highlight that series (others fade) */}
      <ChartLegendLayout
        position={legendPosition}
        show={showLegend && legendItems.length > 0}
        legend={
          <ChartLegend
            items={legendItems}
            position={legendPosition}
            onItemHover={highlight.setHovered}
            onItemClick={highlight.toggle}
            isItemActive={highlight.isActive}
          />
        }
      >
        <div className="relative w-full">
          <div
            ref={containerRef}
            className="relative w-full"
            style={{ aspectRatio: `${width}/${height}` }}
          >
            <svg
              viewBox={`0 0 ${width} ${height}`}
              className="h-full w-full overflow-visible"
            >
              {/* Gradient definitions for each series */}
              <defs>
                {series.map((_, i) => {
                  const color = getColor(i)
                  return (
                    <linearGradient
                      key={i}
                      id={`flow-gradient-${gradientId}-${i}`}
                      x1="0%"
                      y1="0%"
                      x2="100%"
                      y2="0%"
                    >
                      <stop offset="0%" stopColor={color} stopOpacity={1} />
                      <stop offset="50%" stopColor={color} stopOpacity={1} />
                      <stop offset="100%" stopColor={color} stopOpacity={1} />
                    </linearGradient>
                  )
                })}
                {/* Drop shadow filter */}
                <filter
                  id={`pill-shadow-${gradientId}`}
                  x="-20%"
                  y="-20%"
                  width="140%"
                  height="140%"
                >
                  <feDropShadow
                    dx="0"
                    dy="1"
                    stdDeviation="2"
                    floodOpacity="0.15"
                  />
                </filter>
              </defs>

              <g transform={`translate(${margin.left}, ${margin.top})`}>
                {/* Background fade for depth effect */}
                <rect
                  x={0}
                  y={0}
                  width={innerWidth}
                  height={innerHeight}
                  fill="transparent"
                />

                {/* Flowing area paths - rendered from outermost to innermost */}
                {areaPaths.map(({ topPath, color, seriesIndex }, i) => (
                  <path
                    key={i}
                    d={topPath}
                    fill={`url(#flow-gradient-${gradientId}-${seriesIndex})`}
                    className={cn(
                      "cursor-pointer transition-opacity duration-200",
                      highlight.isDimmed(series[seriesIndex].name) &&
                        "opacity-30"
                    )}
                    onMouseEnter={() =>
                      highlight.setHovered(series[seriesIndex].name)
                    }
                    onMouseMove={(e) => handleMouseMove(e, seriesIndex)}
                    onMouseLeave={() => {
                      highlight.setHovered(null)
                      setTooltipData(null)
                    }}
                    onClick={() => {
                      if (tooltipData) {
                        onSeriesClick?.(
                          series[seriesIndex],
                          tooltipData.stageIndex
                        )
                      }
                      highlight.toggle(series[seriesIndex].name)
                    }}
                  />
                ))}

                {/* Stage markers (vertical lines) - only between stages, not at edges */}
                {showStageMarkers &&
                  stagePositions
                    .slice(1, -1)
                    .map((x, i) => (
                      <line
                        key={i}
                        x1={x}
                        y1={0}
                        x2={x}
                        y2={innerHeight}
                        stroke="white"
                        strokeWidth={3}
                        strokeOpacity={0.9}
                        className="pointer-events-none"
                      />
                    ))}

                {/* Value pills */}
                {showValuePills &&
                  animationProgress > 0.6 &&
                  pillData.map(
                    ({ x, topValue, bottomValue, totalValue }, i) => (
                      <g
                        key={i}
                        style={{
                          opacity: Math.min(1, (animationProgress - 0.6) * 2.5),
                        }}
                      >
                        {/* Top pill */}
                        {(pillPosition === "top" || pillPosition === "both") &&
                          topValue > 0 && (
                            <g transform={`translate(${x}, -25)`}>
                              <rect
                                x={-40}
                                y={-14}
                                width={80}
                                height={28}
                                rx={14}
                                fill="white"
                                filter={`url(#pill-shadow-${gradientId})`}
                              />
                              <text
                                textAnchor="middle"
                                dominantBaseline="middle"
                                className="fill-foreground text-sm font-semibold"
                              >
                                {valueFormatter(topValue)}
                              </text>
                            </g>
                          )}

                        {/* Bottom pill */}
                        {(pillPosition === "bottom" ||
                          pillPosition === "both") &&
                          bottomValue > 0 && (
                            <g
                              transform={`translate(${x}, ${innerHeight + 25})`}
                            >
                              <rect
                                x={-40}
                                y={-14}
                                width={80}
                                height={28}
                                rx={14}
                                fill="white"
                                filter={`url(#pill-shadow-${gradientId})`}
                              />
                              <text
                                textAnchor="middle"
                                dominantBaseline="middle"
                                className="fill-foreground text-sm font-semibold"
                              >
                                {valueFormatter(bottomValue)}
                              </text>
                            </g>
                          )}

                        {/* Center pill - shows total */}
                        {pillPosition === "center" && (
                          <g transform={`translate(${x}, ${centerY})`}>
                            <rect
                              x={-40}
                              y={-14}
                              width={80}
                              height={28}
                              rx={14}
                              fill="white"
                              filter={`url(#pill-shadow-${gradientId})`}
                            />
                            <text
                              textAnchor="middle"
                              dominantBaseline="middle"
                              className="fill-foreground text-sm font-semibold"
                            >
                              {valueFormatter(totalValue)}
                            </text>
                          </g>
                        )}
                      </g>
                    )
                  )}
              </g>
            </svg>

            {/* Tooltip */}
            {showTooltip && tooltipData && (
              <div
                className="pointer-events-none absolute z-50 -translate-x-1/2 -translate-y-full"
                style={{
                  left: tooltipData.x,
                  top: tooltipData.y - 10,
                }}
              >
                <div className="bg-popover text-popover-foreground rounded-lg border px-3 py-2 shadow-lg">
                  <div className="flex items-center gap-2">
                    <div
                      className="h-3 w-3 rounded-sm"
                      style={{
                        backgroundColor: getColor(tooltipData.seriesIndex),
                      }}
                    />
                    <span className="font-medium">
                      {series[tooltipData.seriesIndex]?.name}
                    </span>
                  </div>
                  <div className="mt-1 text-sm">
                    <span className="text-muted-foreground">Stage: </span>
                    <span className="font-medium">
                      {stages[tooltipData.stageIndex]}
                    </span>
                  </div>
                  <div className="text-sm">
                    <span className="text-muted-foreground">Value: </span>
                    <span className="font-semibold">
                      {valueFormatter(
                        series[tooltipData.seriesIndex]?.values[
                          tooltipData.stageIndex
                        ] || 0
                      )}
                    </span>
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>
      </ChartLegendLayout>
    </ChartContainer>
  )
}

