// ============================================================================
// Utility Functions
// ============================================================================

const WEEKDAYS_SHORT = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"]
const MONTHS_SHORT = [
  "Jan",
  "Feb",
  "Mar",
  "Apr",
  "May",
  "Jun",
  "Jul",
  "Aug",
  "Sep",
  "Oct",
  "Nov",
  "Dec",
]

function parseDate(date: Date | string): Date {
  if (date instanceof Date) return date
  return new Date(date)
}

function formatDateKey(date: Date): string {
  return date.toISOString().split("T")[0]
}

function getWeekNumber(date: Date, weekStartsOn: 0 | 1 = 0): number {
  const d = new Date(date)
  d.setHours(0, 0, 0, 0)
  const startOfYear = new Date(d.getFullYear(), 0, 1)
  const diff = d.getTime() - startOfYear.getTime()
  const oneWeek = 7 * 24 * 60 * 60 * 1000
  return Math.floor(diff / oneWeek)
}

function getStartOfYear(date: Date): Date {
  return new Date(date.getFullYear(), 0, 1)
}

function getEndOfYear(date: Date): Date {
  return new Date(date.getFullYear(), 11, 31)
}

function generateDateRange(start: Date, end: Date): Date[] {
  const dates: Date[] = []
  const current = new Date(start)
  while (current <= end) {
    dates.push(new Date(current))
    current.setDate(current.getDate() + 1)
  }
  return dates
}

function defaultGetLevel(value: number, max: number): number {
  if (value <= 0) return 0
  if (max === 0) return 0
  const normalized = value / max
  if (normalized <= 0.25) return 1
  if (normalized <= 0.5) return 2
  if (normalized <= 0.75) return 3
  return 4
}

// ============================================================================
// Component
// ============================================================================

export function HeatmapChart({
  data,
  config,
  className,
  width = 900,
  height = 200,
  margin = { top: 30, right: 30, bottom: 20, left: 50 },
  showTooltip = true,
  variant = "matrix",
  colorScale,
  colorTheme = "green",
  showValues = false,
  cellRadius = 2,
  cellGap = 3,
  cellSize = 12,
  xAxisLabel,
  yAxisLabel,
  valueFormat = (v) => v.toString(),
  weekStartsOn = 0,
  showMonthLabels = true,
  showWeekdayLabels = true,
  legend = {
    show: true,
    position: "top-right",
    lessLabel: "Less",
    moreLabel: "More",
  },
  levels = 5,
  getLevelFromValue = defaultGetLevel,
  onCellClick,
  emptyColor,
}: HeatmapChartProps) {
  const [hoveredCell, setHoveredCell] = React.useState<{
    x: number
    y: number
    data: HeatmapDataPoint | CalendarDataPoint | RadialHeatmapDataPoint
  } | null>(null)
  // Detect dark mode
  const [isDark, setIsDark] = React.useState(false)
  React.useEffect(() => {
    const checkDark = () => {
      setIsDark(document.documentElement.classList.contains("dark"))
    }
    checkDark()
    const observer = new MutationObserver(checkDark)
    observer.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    })
    return () => observer.disconnect()
  }, [])

  // Get colors based on theme
  const colors = React.useMemo(() => {
    if (colorScale) return colorScale
    const theme = COLOR_THEMES[colorTheme]
    return isDark ? theme.dark : theme.light
  }, [colorScale, colorTheme, isDark])

  const emptyColorFinal = emptyColor || colors[0]

  // ============================================================================
  // Calendar Variant
  // ============================================================================
  if (variant === "calendar") {
    return (
      <CalendarHeatmap
        data={data as CalendarDataPoint[]}
        config={config}
        className={className}
        width={width}
        height={height}
        margin={margin}
        showTooltip={showTooltip}
        colors={colors}
        cellRadius={cellRadius}
        cellGap={cellGap}
        cellSize={cellSize}
        valueFormat={valueFormat}
        weekStartsOn={weekStartsOn}
        showMonthLabels={showMonthLabels}
        showWeekdayLabels={showWeekdayLabels}
        legend={legend}
        getLevelFromValue={getLevelFromValue}
        onCellClick={onCellClick}
        emptyColor={emptyColorFinal}
        hoveredCell={hoveredCell}
        setHoveredCell={setHoveredCell}
      />
    )
  }

  // ============================================================================
  // Radial Variant
  // ============================================================================
  if (variant === "radial") {
    return (
      <RadialHeatmap
        data={data as RadialHeatmapDataPoint[]}
        config={config}
        className={className}
        width={width}
        height={height}
        margin={margin}
        showTooltip={showTooltip}
        colors={colors}
        cellGap={cellGap}
        valueFormat={valueFormat}
        weekStartsOn={weekStartsOn}
        legend={legend}
        onCellClick={
          onCellClick as ((data: RadialHeatmapDataPoint) => void) | undefined
        }
        emptyColor={emptyColorFinal}
        hoveredCell={hoveredCell}
        setHoveredCell={setHoveredCell}
      />
    )
  }

  // ============================================================================
  // Matrix Variant (Original Implementation)
  // ============================================================================
  const matrixData = data as HeatmapDataPoint[]
  const innerWidth = width - margin.left - margin.right
  const innerHeight = height - margin.top - margin.bottom

  const svgRef = React.useRef<SVGSVGElement>(null)
  const [zoomColumnRange, setZoomColumnRange] = React.useState<
    [number, number] | null
  >(null)
  const isZoomed = zoomColumnRange !== null

  // Reset any active zoom if the underlying data set changes.
  React.useEffect(() => {
    setZoomColumnRange(null)
  }, [data])

  // Extract unique labels
  const fullXLabelsUnique = React.useMemo(() => {
    const labels = [...new Set(matrixData.map((d) => String(d.x)))]
    return labels.sort()
  }, [matrixData])

  const yLabelsUnique = React.useMemo(() => {
    const labels = [...new Set(matrixData.map((d) => String(d.y)))]
    return labels.sort()
  }, [matrixData])

  // Drag-to-zoom narrows the visible x-axis columns down to an index
  // window over `fullXLabelsUnique` — rows (y-axis) are never filtered.
  const xLabelsUnique = zoomColumnRange
    ? fullXLabelsUnique.slice(zoomColumnRange[0], zoomColumnRange[1] + 1)
    : fullXLabelsUnique

  // Cells actually in view — used for the value/color domain so the
  // legend rescales to the visible columns while zoomed.
  const plotData = React.useMemo(() => {
    if (!zoomColumnRange) return matrixData
    const visible = new Set(xLabelsUnique)
    return matrixData.filter((d) => visible.has(String(d.x)))
  }, [matrixData, zoomColumnRange, xLabelsUnique])

  // Scales
  const xScale = scaleBand()
    .domain(xLabelsUnique)
    .range([0, innerWidth])
    .padding(cellGap / 100)

  const yScale = scaleBand()
    .domain(yLabelsUnique)
    .range([0, innerHeight])
    .padding(cellGap / 100)

  // Drag-to-zoom: converts the pixel drag range into a data-index range
  // (band scale) over the x-axis columns and narrows the view to it.
  const zoom = useChartZoom({
    svgRef,
    marginLeft: margin.left,
    innerWidth,
    onZoom: ({ x0, x1 }) => {
      const [start, end] = getBandScaleIndexRange(xScale, x0, x1)
      const currentOffset = zoomColumnRange ? zoomColumnRange[0] : 0
      setZoomColumnRange([currentOffset + start, currentOffset + end])
    },
    onReset: () => setZoomColumnRange(null),
  })

  // Value scale for colors
  const values = plotData.map((d) => d.value)
  const minValue = Math.min(...values)
  const maxValue = Math.max(...values)

  const valueScale = scaleLinear().domain([minValue, maxValue]).range([0, 1])

  // Color interpolator
  const getColor = React.useCallback(
    (value: number) => {
      if (colors.length === 2) {
        const t = valueScale(value)
        return interpolateRgb(colors[0], colors[1])(t)
      }
      // Multi-color scale
      const t = valueScale(value)
      const segmentSize = 1 / (colors.length - 1)
      const segmentIndex = Math.min(
        Math.floor(t / segmentSize),
        colors.length - 2
      )
      const segmentT = (t - segmentIndex * segmentSize) / segmentSize
      return interpolateRgb(
        colors[segmentIndex],
        colors[segmentIndex + 1]
      )(segmentT)
    },
    [colors, valueScale]
  )

  // Create data matrix for quick lookup
  const dataMatrix = React.useMemo(() => {
    const matrix: Record<string, Record<string, number>> = {}
    matrixData.forEach((d) => {
      const xKey = String(d.x)
      const yKey = String(d.y)
      if (!matrix[yKey]) matrix[yKey] = {}
      matrix[yKey][xKey] = d.value
    })
    return matrix
  }, [matrixData])

  const compactMode = variant === "compact"
  const effectiveCellRadius = compactMode ? 1 : cellRadius
  const fontSize = compactMode ? 8 : 10

  return (
    <ChartContainer config={config} className={cn("relative", className)}>
      <svg
        ref={svgRef}
        viewBox={`0 0 ${width} ${height}`}
        className="h-full w-full select-none"
        onMouseDown={zoom.handlers.onMouseDown}
        onMouseMove={zoom.handlers.onMouseMove}
        onMouseUp={zoom.handlers.onMouseUp}
        onMouseLeave={zoom.handlers.onMouseLeave}
        onDoubleClick={zoom.handlers.onDoubleClick}
      >
        <g transform={`translate(${margin.left}, ${margin.top})`}>
          {/* Drag-to-zoom selection rectangle */}
          <ChartZoomSelectionRect range={zoom.dragRange} height={innerHeight} />

          {/* Cells */}
          {yLabelsUnique.map((yLabel) =>
            xLabelsUnique.map((xLabel) => {
              const value = dataMatrix[yLabel]?.[xLabel]
              if (value === undefined) return null

              const x = xScale(xLabel) ?? 0
              const y = yScale(yLabel) ?? 0
              const cellWidth = xScale.bandwidth()
              const cellHeight = yScale.bandwidth()
              const isHovered =
                hoveredCell?.data &&
                "x" in hoveredCell.data &&
                hoveredCell.data.x === xLabel &&
                hoveredCell.data.y === yLabel

              return (
                <g key={`${xLabel}-${yLabel}`}>
                  <rect
                    x={x}
                    y={y}
                    width={cellWidth}
                    height={cellHeight}
                    fill={getColor(value)}
                    rx={effectiveCellRadius}
                    ry={effectiveCellRadius}
                    className={cn(
                      "cursor-pointer transition-all duration-200",
                      isHovered && "stroke-foreground stroke-2"
                    )}
                    onMouseEnter={(e) =>
                      setHoveredCell({
                        x: e.clientX,
                        y: e.clientY,
                        data: { x: xLabel, y: yLabel, value },
                      })
                    }
                    onMouseLeave={() => setHoveredCell(null)}
                    onClick={() =>
                      onCellClick?.({ x: xLabel, y: yLabel, value })
                    }
                  />

                  {/* Value label */}
                  {showValues && cellWidth > 25 && cellHeight > 15 && (
                    <text
                      x={x + cellWidth / 2}
                      y={y + cellHeight / 2}
                      textAnchor="middle"
                      dominantBaseline="middle"
                      className={cn(
                        "pointer-events-none font-medium",
                        valueScale(value) > 0.5
                          ? "fill-white"
                          : "fill-foreground"
                      )}
                      style={{ fontSize }}
                    >
                      {valueFormat(value)}
                    </text>
                  )}
                </g>
              )
            })
          )}

          {/* X Axis */}
          <ChartAxis
            scale={xScale}
            orientation="bottom"
            transform={`translate(0, ${innerHeight})`}
            label={xAxisLabel}
          />

          {/* Y Axis */}
          <ChartAxis scale={yScale} orientation="left" label={yAxisLabel} />
        </g>

        {/* Color legend */}
        {legend.show && (
          <g
            transform={`translate(${width - margin.right + 15}, ${margin.top})`}
          >
            <defs>
              <linearGradient
                id="heatmap-matrix-gradient"
                x1="0"
                y1="1"
                x2="0"
                y2="0"
              >
                {colors.map((color, i) => (
                  <stop
                    key={i}
                    offset={`${(i / (colors.length - 1)) * 100}%`}
                    stopColor={color}
                  />
                ))}
              </linearGradient>
            </defs>
            <rect
              width={15}
              height={innerHeight}
              fill="url(#heatmap-matrix-gradient)"
              rx={2}
            />
            <text
              x={20}
              y={0}
              dominantBaseline="hanging"
              className="fill-muted-foreground text-[10px]"
            >
              {maxValue.toFixed(1)}
            </text>
            <text
              x={20}
              y={innerHeight}
              dominantBaseline="auto"
              className="fill-muted-foreground text-[10px]"
            >
              {minValue.toFixed(1)}
            </text>
          </g>
        )}
      </svg>

      {/* Tooltip */}
      {showTooltip &&
        hoveredCell &&
        hoveredCell.data &&
        "x" in hoveredCell.data && (
          <div
            className="pointer-events-none fixed z-50"
            style={{
              left: hoveredCell.x + 10,
              top: hoveredCell.y - 10,
            }}
          >
            <div className="border-border/50 bg-background rounded-lg border px-2.5 py-1.5 text-xs shadow-xl">
              <div className="font-medium">
                {String(hoveredCell.data.x)} × {String(hoveredCell.data.y)}
              </div>
              <div className="text-muted-foreground">
                Value: {valueFormat(hoveredCell.data.value)}
              </div>
            </div>
          </div>
        )}

      <ChartZoomResetButton
        visible={isZoomed}
        onReset={() => setZoomColumnRange(null)}
      />
    </ChartContainer>
  )
}

// ============================================================================
// Calendar Heatmap Sub-component
// ============================================================================

interface CalendarHeatmapProps {
  data: CalendarDataPoint[]
  config?: BaseChartProps["config"]
  className?: string
  width: number
  height: number
  margin: { top: number; right: number; bottom: number; left: number }
  showTooltip: boolean
  colors: readonly string[] | string[]
  cellRadius: number
  cellGap: number
  cellSize: number
  valueFormat: (value: number) => string
  weekStartsOn: 0 | 1
  showMonthLabels: boolean
  showWeekdayLabels: boolean
  legend: HeatmapLegendConfig
  getLevelFromValue: (value: number, max: number) => number
  onCellClick?: (data: CalendarDataPoint) => void
  emptyColor: string
  hoveredCell: {
    x: number
    y: number
    data: HeatmapDataPoint | CalendarDataPoint | RadialHeatmapDataPoint
  } | null
  setHoveredCell: React.Dispatch<
    React.SetStateAction<{
      x: number
      y: number
      data: HeatmapDataPoint | CalendarDataPoint | RadialHeatmapDataPoint
    } | null>
  >
}

function CalendarHeatmap({
  data,
  config,
  className,
  width,
  height,
  margin,
  showTooltip,
  colors,
  cellRadius,
  cellGap,
  cellSize,
  valueFormat,
  weekStartsOn,
  showMonthLabels,
  showWeekdayLabels,
  legend,
  getLevelFromValue,
  onCellClick,
  emptyColor,
  hoveredCell,
  setHoveredCell,
}: CalendarHeatmapProps) {
  // Build date -> value map
  const dataMap = React.useMemo(() => {
    const map = new Map<string, CalendarDataPoint>()
    data.forEach((d) => {
      const date = parseDate(d.date)
      const key = formatDateKey(date)
      const existing = map.get(key)
      if (existing) {
        // Aggregate values for same date
        map.set(key, { ...d, value: existing.value + d.value })
      } else {
        map.set(key, d)
      }
    })
    return map
  }, [data])

  // Get date range from data
  const dateRange = React.useMemo(() => {
    if (data.length === 0) {
      const now = new Date()
      return {
        start: getStartOfYear(now),
        end: getEndOfYear(now),
      }
    }
    const dates = data.map((d) => parseDate(d.date))
    const minDate = new Date(Math.min(...dates.map((d) => d.getTime())))
    const maxDate = new Date(Math.max(...dates.map((d) => d.getTime())))
    // Extend to full year view
    return {
      start: getStartOfYear(minDate),
      end: getEndOfYear(maxDate),
    }
  }, [data])

  // Max value for level calculation
  const maxValue = React.useMemo(() => {
    return Math.max(...data.map((d) => d.value), 1)
  }, [data])

  // Generate all dates in range
  const allDates = React.useMemo(() => {
    return generateDateRange(dateRange.start, dateRange.end)
  }, [dateRange])

  // Group dates by week
  const weeks = React.useMemo(() => {
    const weeksMap: Date[][] = []
    let currentWeek: Date[] = []

    // Pad start to align with week start
    const firstDate = allDates[0]
    const firstDay = firstDate.getDay()
    const padStart = (firstDay - weekStartsOn + 7) % 7
    for (let i = 0; i < padStart; i++) {
      currentWeek.push(new Date(NaN)) // Invalid date placeholder
    }

    allDates.forEach((date) => {
      const day = date.getDay()
      const adjustedDay = (day - weekStartsOn + 7) % 7

      if (adjustedDay === 0 && currentWeek.length > 0) {
        weeksMap.push(currentWeek)
        currentWeek = []
      }
      currentWeek.push(date)
    })

    if (currentWeek.length > 0) {
      weeksMap.push(currentWeek)
    }

    return weeksMap
  }, [allDates, weekStartsOn])

  // Calculate month labels positions
  const monthLabels = React.useMemo(() => {
    const labels: { month: string; x: number }[] = []
    let lastMonth = -1

    weeks.forEach((week, weekIndex) => {
      const validDate = week.find((d) => !isNaN(d.getTime()))
      if (validDate) {
        const month = validDate.getMonth()
        if (month !== lastMonth) {
          labels.push({
            month: MONTHS_SHORT[month],
            x: weekIndex * (cellSize + cellGap),
          })
          lastMonth = month
        }
      }
    })

    return labels
  }, [weeks, cellSize, cellGap])

  // Weekday labels (showing only Sun, Tue, Thu, Sat for space)
  const weekdayLabels = React.useMemo(() => {
    const labels: { day: string; y: number }[] = []
    const daysToShow = weekStartsOn === 0 ? [0, 2, 4, 6] : [1, 3, 5]

    daysToShow.forEach((dayIndex) => {
      const adjustedIndex = (dayIndex - weekStartsOn + 7) % 7
      labels.push({
        day: WEEKDAYS_SHORT[dayIndex].toUpperCase(),
        y: adjustedIndex * (cellSize + cellGap) + cellSize / 2,
      })
    })
    return labels
  }, [cellSize, cellGap, weekStartsOn])

  // Calculate dimensions
  const chartWidth = weeks.length * (cellSize + cellGap)
  const chartHeight = 7 * (cellSize + cellGap)
  const labelWidth = showWeekdayLabels ? 35 : 0
  const labelHeight = showMonthLabels ? 20 : 0

  const svgWidth = Math.max(
    width,
    chartWidth + labelWidth + margin.left + margin.right
  )
  const svgHeight = chartHeight + labelHeight + margin.top + margin.bottom

  return (
    <ChartContainer config={config} className={cn("relative", className)}>
      <div className="overflow-x-auto">
        <svg
          viewBox={`0 0 ${svgWidth} ${svgHeight}`}
          className="h-auto"
          style={{ minWidth: svgWidth }}
        >
          <g
            transform={`translate(${margin.left + labelWidth}, ${margin.top + labelHeight})`}
          >
            {/* Month labels */}
            {showMonthLabels &&
              monthLabels.map((label, i) => (
                <text
                  key={i}
                  x={label.x}
                  y={-8}
                  className="fill-muted-foreground text-[11px]"
                >
                  {label.month}
                </text>
              ))}

            {/* Weekday labels */}
            {showWeekdayLabels &&
              weekdayLabels.map((label, i) => (
                <text
                  key={i}
                  x={-8}
                  y={label.y}
                  textAnchor="end"
                  dominantBaseline="middle"
                  className="fill-muted-foreground text-[10px]"
                >
                  {label.day}
                </text>
              ))}

            {/* Calendar cells */}
            {weeks.map((week, weekIndex) =>
              week.map((date, dayIndex) => {
                if (isNaN(date.getTime())) {
                  return null // Skip placeholder dates
                }

                const key = formatDateKey(date)
                const dataPoint = dataMap.get(key)
                const value = dataPoint?.value ?? 0
                const level = getLevelFromValue(value, maxValue)
                const color = value > 0 ? colors[level] : emptyColor

                const x = weekIndex * (cellSize + cellGap)
                const y = dayIndex * (cellSize + cellGap)

                const isHovered =
                  hoveredCell?.data &&
                  "date" in hoveredCell.data &&
                  hoveredCell.data.date !== undefined &&
                  formatDateKey(parseDate(hoveredCell.data.date)) === key

                return (
                  <rect
                    key={key}
                    x={x}
                    y={y}
                    width={cellSize}
                    height={cellSize}
                    fill={color}
                    rx={cellRadius}
                    ry={cellRadius}
                    className={cn(
                      "cursor-pointer transition-all duration-150",
                      isHovered && "stroke-foreground stroke-[1.5]"
                    )}
                    onMouseEnter={(e) =>
                      setHoveredCell({
                        x: e.clientX,
                        y: e.clientY,
                        data: dataPoint || { date, value: 0 },
                      })
                    }
                    onMouseLeave={() => setHoveredCell(null)}
                    onClick={() =>
                      onCellClick?.(dataPoint || { date, value: 0 })
                    }
                  />
                )
              })
            )}
          </g>

          {/* Legend */}
          {legend.show && (
            <g
              transform={`translate(${svgWidth - margin.right - colors.length * (cellSize + 2) - 60}, ${margin.top})`}
            >
              <text
                x={0}
                y={cellSize / 2}
                dominantBaseline="middle"
                className="fill-muted-foreground text-[11px]"
              >
                {legend.lessLabel || "Less"}
              </text>
              {colors.map((color, i) => (
                <rect
                  key={i}
                  x={35 + i * (cellSize + 2)}
                  y={0}
                  width={cellSize}
                  height={cellSize}
                  fill={color}
                  rx={cellRadius}
                  ry={cellRadius}
                />
              ))}
              <text
                x={35 + colors.length * (cellSize + 2) + 5}
                y={cellSize / 2}
                dominantBaseline="middle"
                className="fill-muted-foreground text-[11px]"
              >
                {legend.moreLabel || "More"}
              </text>
            </g>
          )}
        </svg>
      </div>

      {/* Tooltip */}
      {showTooltip &&
        hoveredCell &&
        hoveredCell.data &&
        "date" in hoveredCell.data &&
        hoveredCell.data.date && (
          <div
            className="pointer-events-none fixed z-50"
            style={{
              left: hoveredCell.x + 10,
              top: hoveredCell.y - 10,
            }}
          >
            <div className="border-border/50 bg-background rounded-lg border px-2.5 py-1.5 text-xs shadow-xl">
              <div className="font-medium">
                {parseDate(hoveredCell.data.date!).toLocaleDateString("en-US", {
                  weekday: "short",
                  year: "numeric",
                  month: "short",
                  day: "numeric",
                })}
              </div>
              <div className="text-muted-foreground">
                {hoveredCell.data.value > 0
                  ? `${valueFormat(hoveredCell.data.value)} contributions`
                  : "No contributions"}
              </div>
            </div>
          </div>
        )}
    </ChartContainer>
  )
}

// ============================================================================
// Radial Heatmap Sub-component
// ============================================================================

const WEEKDAYS_FULL = [
  "Sunday",
  "Monday",
  "Tuesday",
  "Wednesday",
  "Thursday",
  "Friday",
  "Saturday",
]

const HOURS_12 = [
  "12am",
  "1am",
  "2am",
  "3am",
  "4am",
  "5am",
  "6am",
  "7am",
  "8am",
  "9am",
  "10am",
  "11am",
  "12pm",
  "1pm",
  "2pm",
  "3pm",
  "4pm",
  "5pm",
  "6pm",
  "7pm",
  "8pm",
  "9pm",
  "10pm",
  "11pm",
]

interface RadialHeatmapProps {
  data: RadialHeatmapDataPoint[]
  config?: BaseChartProps["config"]
  className?: string
  width: number
  height: number
  margin: { top: number; right: number; bottom: number; left: number }
  showTooltip: boolean
  colors: readonly string[] | string[]
  cellGap: number
  valueFormat: (value: number) => string
  weekStartsOn: 0 | 1
  legend: HeatmapLegendConfig
  onCellClick?: (data: RadialHeatmapDataPoint) => void
  emptyColor: string
  hoveredCell: {
    x: number
    y: number
    data: HeatmapDataPoint | CalendarDataPoint | RadialHeatmapDataPoint
  } | null
  setHoveredCell: React.Dispatch<
    React.SetStateAction<{
      x: number
      y: number
      data: HeatmapDataPoint | CalendarDataPoint | RadialHeatmapDataPoint
    } | null>
  >
}

function RadialHeatmap({
  data,
  config,
  className,
  width,
  height,
  margin,
  showTooltip,
  colors,
  cellGap,
  valueFormat,
  weekStartsOn,
  legend,
  onCellClick,
  emptyColor,
  hoveredCell,
  setHoveredCell,
}: RadialHeatmapProps) {
  // Parse day to index (0-6)
  const parseDayIndex = (day: number | string): number => {
    if (typeof day === "number") return day
    const lower = day.toLowerCase()
    const index = WEEKDAYS_FULL.findIndex((d) =>
      d.toLowerCase().startsWith(lower)
    )
    return index >= 0 ? index : 0
  }

  // Parse hour to index (0-23)
  const parseHourIndex = (hour: number | string): number => {
    if (typeof hour === "number") return hour
    const lower = hour.toLowerCase().replace(/\s/g, "")
    const index = HOURS_12.findIndex((h) => h.toLowerCase() === lower)
    return index >= 0 ? index : 0
  }

  // Build data matrix [day][hour] = value
  const dataMatrix = React.useMemo(() => {
    const matrix: number[][] = Array.from({ length: 7 }, () =>
      Array(24).fill(0)
    )
    data.forEach((d) => {
      const dayIndex = parseDayIndex(d.day)
      const hourIndex = parseHourIndex(d.hour)
      matrix[dayIndex][hourIndex] = (matrix[dayIndex][hourIndex] || 0) + d.value
    })
    return matrix
  }, [data])

  // Get max value for color scaling
  const maxValue = React.useMemo(() => {
    return Math.max(...data.map((d) => d.value), 1)
  }, [data])

  // Calculate dimensions
  const size = Math.min(
    width - margin.left - margin.right,
    height - margin.top - margin.bottom
  )
  const centerX = size / 2
  const centerY = size / 2
  const outerRadius = size / 2 - 30 // Leave space for hour labels
  const innerRadius = outerRadius * 0.35 // Center hole for day labels
  const ringWidth = (outerRadius - innerRadius) / 7 - cellGap / 2

  // Color interpolator
  const getColor = React.useCallback(
    (value: number) => {
      if (value <= 0) return emptyColor
      const t = Math.min(value / maxValue, 1)
      if (colors.length === 2) {
        return interpolateRgb(colors[0], colors[1])(t)
      }
      const segmentSize = 1 / (colors.length - 1)
      const segmentIndex = Math.min(
        Math.floor(t / segmentSize),
        colors.length - 2
      )
      const segmentT = (t - segmentIndex * segmentSize) / segmentSize
      return interpolateRgb(
        colors[segmentIndex],
        colors[segmentIndex + 1]
      )(segmentT)
    },
    [colors, maxValue, emptyColor]
  )

  // Generate arc path
  const generateArc = (dayIndex: number, hourIndex: number): string => {
    // Day rings: Sunday (0) is innermost, Saturday (6) is outermost
    const dayRadius = innerRadius + dayIndex * (ringWidth + cellGap / 2)
    const nextDayRadius = dayRadius + ringWidth

    // Hour segments: 12am starts at bottom (270 degrees), going clockwise
    const hourAngle = 360 / 24
    const startAngle = (270 + hourIndex * hourAngle) % 360
    const endAngle = (startAngle + hourAngle - cellGap) % 360

    const startRad = (startAngle * Math.PI) / 180
    const endRad = (endAngle * Math.PI) / 180

    // Calculate points
    const innerStartX = centerX + dayRadius * Math.cos(startRad)
    const innerStartY = centerY + dayRadius * Math.sin(startRad)
    const innerEndX = centerX + dayRadius * Math.cos(endRad)
    const innerEndY = centerY + dayRadius * Math.sin(endRad)
    const outerStartX = centerX + nextDayRadius * Math.cos(startRad)
    const outerStartY = centerY + nextDayRadius * Math.sin(startRad)
    const outerEndX = centerX + nextDayRadius * Math.cos(endRad)
    const outerEndY = centerY + nextDayRadius * Math.sin(endRad)

    const largeArc = hourAngle - cellGap > 180 ? 1 : 0

    return `
      M ${innerStartX} ${innerStartY}
      A ${dayRadius} ${dayRadius} 0 ${largeArc} 1 ${innerEndX} ${innerEndY}
      L ${outerEndX} ${outerEndY}
      A ${nextDayRadius} ${nextDayRadius} 0 ${largeArc} 0 ${outerStartX} ${outerStartY}
      Z
    `
  }

  // Generate hour label positions
  const hourLabels = React.useMemo(() => {
    const labels: { hour: string; x: number; y: number; angle: number }[] = []
    const labelRadius = outerRadius + 18

    for (let i = 0; i < 24; i++) {
      const angle = (270 + i * 15 + 7.5) % 360 // Center of each hour segment
      const rad = (angle * Math.PI) / 180
      labels.push({
        hour: HOURS_12[i],
        x: centerX + labelRadius * Math.cos(rad),
        y: centerY + labelRadius * Math.sin(rad),
        angle: angle > 90 && angle < 270 ? angle + 180 : angle,
      })
    }
    return labels
  }, [centerX, centerY, outerRadius])

  // Order days based on weekStartsOn
  const orderedDays = React.useMemo(() => {
    const days = [...WEEKDAYS_FULL]
    if (weekStartsOn === 1) {
      // Monday first
      days.push(days.shift()!) // Move Sunday to end
    }
    return days
  }, [weekStartsOn])

  return (
    <ChartContainer config={config} className={cn("relative", className)}>
      <svg
        viewBox={`0 0 ${size + margin.left + margin.right} ${size + margin.top + margin.bottom + 60}`}
        className="h-full w-full"
      >
        <g transform={`translate(${margin.left}, ${margin.top})`}>
          {/* Hour labels around the outside */}
          {hourLabels.map((label, i) => (
            <text
              key={i}
              x={label.x}
              y={label.y}
              textAnchor="middle"
              dominantBaseline="middle"
              className="fill-muted-foreground text-[10px]"
              transform={`rotate(${label.angle - 90}, ${label.x}, ${label.y})`}
            >
              {label.hour}
            </text>
          ))}

          {/* Radial cells */}
          {Array.from({ length: 7 }).map((_, dayIdx) => {
            const actualDayIndex =
              weekStartsOn === 1 ? (dayIdx + 1) % 7 : dayIdx
            return Array.from({ length: 24 }).map((_, hourIdx) => {
              const value = dataMatrix[actualDayIndex][hourIdx]
              const color = getColor(value)
              const path = generateArc(dayIdx, hourIdx)

              const isHovered =
                hoveredCell?.data &&
                "day" in hoveredCell.data &&
                "hour" in hoveredCell.data &&
                parseDayIndex(hoveredCell.data.day) === actualDayIndex &&
                parseHourIndex(hoveredCell.data.hour) === hourIdx

              return (
                <path
                  key={`${dayIdx}-${hourIdx}`}
                  d={path}
                  fill={color}
                  stroke={isHovered ? "var(--foreground)" : "var(--background)"}
                  strokeWidth={isHovered ? 2 : 0.5}
                  className="cursor-pointer transition-all duration-150"
                  onMouseEnter={(e) =>
                    setHoveredCell({
                      x: e.clientX,
                      y: e.clientY,
                      data: {
                        day: actualDayIndex,
                        hour: hourIdx,
                        value,
                      },
                    })
                  }
                  onMouseLeave={() => setHoveredCell(null)}
                  onClick={() =>
                    onCellClick?.({
                      day: actualDayIndex,
                      hour: hourIdx,
                      value,
                    })
                  }
                />
              )
            })
          })}

          {/* Day labels in center */}
          {orderedDays.map((day, i) => (
            <text
              key={day}
              x={centerX}
              y={centerY - innerRadius + 20 + i * 14}
              textAnchor="middle"
              dominantBaseline="middle"
              className="fill-muted-foreground text-[11px] font-medium"
            >
              {day}
            </text>
          ))}
        </g>

        {/* Legend */}
        {legend.show && (
          <g transform={`translate(${margin.left}, ${size + margin.top + 20})`}>
            <defs>
              <linearGradient
                id="radial-heatmap-gradient"
                x1="0"
                y1="0"
                x2="1"
                y2="0"
              >
                {colors.map((color, i) => (
                  <stop
                    key={i}
                    offset={`${(i / (colors.length - 1)) * 100}%`}
                    stopColor={color}
                  />
                ))}
              </linearGradient>
            </defs>
            <text x={0} y={10} className="fill-muted-foreground text-[11px]">
              {legend.lessLabel || "Less"}
            </text>
            <rect
              x={35}
              y={0}
              width={size - 100}
              height={16}
              fill="url(#radial-heatmap-gradient)"
              rx={3}
            />
            <text
              x={size - 60}
              y={10}
              className="fill-muted-foreground text-[11px]"
            >
              {legend.moreLabel || "More"}
            </text>
          </g>
        )}
      </svg>

      {/* Tooltip */}
      {showTooltip &&
        hoveredCell &&
        hoveredCell.data &&
        "day" in hoveredCell.data &&
        "hour" in hoveredCell.data && (
          <div
            className="pointer-events-none fixed z-50"
            style={{
              left: hoveredCell.x + 10,
              top: hoveredCell.y - 10,
            }}
          >
            <div className="border-border/50 bg-background rounded-lg border px-2.5 py-1.5 text-xs shadow-xl">
              <div className="font-medium">
                {WEEKDAYS_FULL[parseDayIndex(hoveredCell.data.day)]},{" "}
                {HOURS_12[parseHourIndex(hoveredCell.data.hour)]}
              </div>
              <div className="text-muted-foreground">
                Value: {valueFormat(hoveredCell.data.value)}
              </div>
            </div>
          </div>
        )}
    </ChartContainer>
  )
}

"use client"

import * as React from "react"
import { contours } from "d3-contour"
import { geoPath } from "d3-geo"
import { interpolateRgb } from "d3-interpolate"
import { scaleLinear } from "d3-scale"

import { cn } from "@/lib/utils"

import { ChartAxis } from "../chart-axis"
import type { BaseChartProps } from "../chart-config"
import { ChartContainer } from "../chart-container"
import { ChartGrid } from "../chart-grid"
import {
  ChartZoomResetButton,
  ChartZoomSelectionRect,
  useChartZoom,
} from "../chart-zoom"

export interface ContourPoint {
  x: number
  y: number
  value?: number
}

export interface ContourChartProps extends BaseChartProps {
  /** 2D array of z values (grid data) */
  data: number[][]
  /** Optional scatter points to display on top */
  points?: ContourPoint[]
  xDomain?: [number, number]
  yDomain?: [number, number]
  /** Number of contour levels */
  levels?: number
  /** Color scale - supports 2-7 colors for gradient */
  colorScale?: string[]
  /** Show filled contour regions */
  showFill?: boolean
  /** Show contour lines */
  showLines?: boolean
  /** Contour line width */
  lineWidth?: number
  /** Line color (defaults to darker shade of fill) */
  lineColor?: string
  /** Show data point markers */
  showMarkers?: boolean
  /** Marker symbol: "x", "cross", "circle", "diamond" */
  markerSymbol?: "x" | "cross" | "circle" | "diamond"
  /** Marker size */
  markerSize?: number
  /** Marker color */
  markerColor?: string
  xAxisLabel?: string
  yAxisLabel?: string
  /** Smoothing factor for contours (higher = smoother) */
  bandwidth?: number
}

// Predefined color scales
export const CONTOUR_COLOR_SCALES = {
  // Rainbow (like the image)
  rainbow: ["#0000ff", "#00ffff", "#00ff00", "#ffff00", "#ff8000", "#ff0000"],
  // Viridis-like
  viridis: ["#440154", "#414487", "#2a788e", "#22a884", "#7ad151", "#fde725"],
  // Cool to warm
  coolwarm: [
    "#3b4cc0",
    "#7092c0",
    "#aac7fd",
    "#f7f7f7",
    "#f4a582",
    "#d6604d",
    "#b40426",
  ],
  // Ocean
  ocean: [
    "#023858",
    "#045a8d",
    "#0570b0",
    "#3690c0",
    "#74a9cf",
    "#a6bddb",
    "#d0d1e6",
  ],
  // Thermal
  thermal: ["#0d0887", "#6a00a8", "#b12a90", "#e16462", "#fca636", "#f0f921"],
  // Default blue
  blue: ["#eff6ff", "#3b82f6", "#1e3a8a"],
}

export function ContourChart({
  data,
  points,
  config,
  className,
  width = 600,
  height = 400,
  margin = { top: 20, right: 80, bottom: 50, left: 60 },
  showGrid = true,
  showTooltip = true,
  xDomain,
  yDomain,
  levels = 10,
  colorScale = CONTOUR_COLOR_SCALES.rainbow,
  showFill = true,
  showLines = true,
  lineWidth = 0.5,
  lineColor,
  showMarkers = true,
  markerSymbol = "x",
  markerSize = 8,
  markerColor = "#333333",
  xAxisLabel,
  yAxisLabel,
  bandwidth = 1,
}: ContourChartProps) {
  const svgRef = React.useRef<SVGSVGElement>(null)
  const [mousePos, setMousePos] = React.useState<{
    x: number
    y: number
    value: number
  } | null>(null)
  const [zoomDomain, setZoomDomain] = React.useState<[number, number] | null>(
    null
  )
  const isZoomed = zoomDomain !== null

  const gradientId = React.useId().replace(/:/g, "")
  const innerWidth = width - margin.left - margin.right
  const innerHeight = height - margin.top - margin.bottom

  // Reset any active zoom if the underlying grid changes.
  React.useEffect(() => {
    setZoomDomain(null)
  }, [data])

  // Full (unzoomed) grid dimensions and x-domain — the drag-to-zoom column
  // window is computed against these, since they define the fixed
  // index<->domain mapping regardless of the current zoom state.
  const fullRows = data.length
  const fullCols = data[0]?.length ?? 0
  const fullXDomain = xDomain ?? [0, fullCols - 1]
  const fullYDomain = yDomain ?? [0, fullRows - 1]

  // Translate the active x-zoom domain into a [startCol, endCol] window
  // over the full grid's columns.
  const colRange = React.useMemo((): [number, number] => {
    if (!zoomDomain || fullCols < 2) return [0, fullCols - 1]
    const [xMin, xMax] = fullXDomain
    const span = xMax - xMin || 1
    const toIndex = (v: number) =>
      Math.round(((v - xMin) / span) * (fullCols - 1))
    let start = toIndex(zoomDomain[0])
    let end = toIndex(zoomDomain[1])
    start = Math.max(0, Math.min(start, fullCols - 1))
    end = Math.max(0, Math.min(end, fullCols - 1))
    if (end <= start) end = Math.min(start + 1, fullCols - 1)
    return [start, end]
  }, [zoomDomain, fullXDomain, fullCols])

  // Apply the active zoom window (if any) by slicing every row down to the
  // selected column range before it reaches the scales/contour generator —
  // same "filter data before the scales" pattern used elsewhere, just
  // expressed as a column-index window instead of a data-point filter.
  const plotData = React.useMemo(() => {
    if (!zoomDomain) return data
    const [start, end] = colRange
    return data.map((row) => row.slice(start, end + 1))
  }, [data, zoomDomain, colRange])

  const rows = plotData.length
  const cols = plotData[0]?.length ?? 0

  // Calculate value range (from the currently visible window)
  const allValues = plotData.flat()
  const minValue = Math.min(...allValues)
  const maxValue = Math.max(...allValues)

  // Scales — x narrows to the zoomed column window's domain range; y is
  // unaffected since drag-to-zoom is a horizontal gesture.
  const actualXDomain = React.useMemo((): [number, number] => {
    if (!zoomDomain) return fullXDomain
    const [xMin, xMax] = fullXDomain
    const span = xMax - xMin || 1
    const toValue = (i: number) => xMin + (span * i) / Math.max(1, fullCols - 1)
    return [toValue(colRange[0]), toValue(colRange[1])]
  }, [zoomDomain, fullXDomain, fullCols, colRange])
  const actualYDomain = fullYDomain

  const xScale = scaleLinear().domain(actualXDomain).range([0, innerWidth])
  const yScale = scaleLinear().domain(actualYDomain).range([innerHeight, 0])
  const valueScale = scaleLinear().domain([minValue, maxValue]).range([0, 1])

  // Color interpolator for multiple colors
  const getColor = React.useCallback(
    (value: number) => {
      const t = valueScale(value)
      const n = colorScale.length - 1
      const segment = Math.min(Math.floor(t * n), n - 1)
      const localT = t * n - segment
      return interpolateRgb(
        colorScale[segment],
        colorScale[segment + 1]
      )(localT)
    },
    [colorScale, valueScale]
  )

  // Generate contours using d3-contour
  const contourGenerator = React.useMemo(() => {
    const thresholds = Array.from(
      { length: levels + 1 },
      (_, i) => minValue + ((maxValue - minValue) * i) / levels
    )
    return contours().size([cols, rows]).thresholds(thresholds)
  }, [cols, rows, levels, minValue, maxValue])

  // Flatten data for d3-contour (expects 1D array)
  const flatData = React.useMemo(() => {
    // d3-contour expects row-major order, bottom to top
    const result: number[] = []
    for (let j = rows - 1; j >= 0; j--) {
      for (let i = 0; i < cols; i++) {
        result.push(plotData[j][i])
      }
    }
    return result
  }, [plotData, rows, cols])

  // Generate contour paths
  const contourPaths = React.useMemo(() => {
    return contourGenerator(flatData)
  }, [contourGenerator, flatData])

  // Path generator that transforms from grid coords to screen coords
  const pathGenerator = React.useMemo(() => {
    return geoPath().projection({
      stream: (s) => ({
        point: (x: number, y: number) => {
          // Transform from grid coordinates to screen coordinates
          const screenX = (x / (cols - 1)) * innerWidth
          const screenY = innerHeight - (y / (rows - 1)) * innerHeight
          s.point(screenX, screenY)
        },
        lineStart: () => s.lineStart(),
        lineEnd: () => s.lineEnd(),
        polygonStart: () => s.polygonStart(),
        polygonEnd: () => s.polygonEnd(),
        sphere: () => {},
      }),
    })
  }, [cols, rows, innerWidth, innerHeight])

  // Generate marker path based on symbol
  const getMarkerPath = React.useCallback(
    (cx: number, cy: number) => {
      const s = markerSize / 2
      switch (markerSymbol) {
        case "x":
          return `M${cx - s},${cy - s}L${cx + s},${cy + s}M${cx + s},${cy - s}L${cx - s},${cy + s}`
        case "cross":
          return `M${cx},${cy - s}L${cx},${cy + s}M${cx - s},${cy}L${cx + s},${cy}`
        case "diamond":
          return `M${cx},${cy - s}L${cx + s},${cy}L${cx},${cy + s}L${cx - s},${cy}Z`
        case "circle":
        default:
          return ""
      }
    },
    [markerSize, markerSymbol]
  )

  // Handle mouse move
  const handleMouseMove = (e: React.MouseEvent<SVGSVGElement>) => {
    const rect = e.currentTarget.getBoundingClientRect()
    const x = e.clientX - rect.left - margin.left
    const y = e.clientY - rect.top - margin.top

    if (x < 0 || x > innerWidth || y < 0 || y > innerHeight) {
      setMousePos(null)
      return
    }

    const dataX = Math.round((x / innerWidth) * (cols - 1))
    const dataY = Math.round(((innerHeight - y) / innerHeight) * (rows - 1))

    if (dataX >= 0 && dataX < cols && dataY >= 0 && dataY < rows) {
      setMousePos({
        x: xScale.invert(x),
        y: yScale.invert(y),
        value: plotData[dataY]?.[dataX] ?? 0,
      })
    }
  }

  // Generate grid points for markers
  const gridPoints = React.useMemo(() => {
    if (!showMarkers && !points) return []

    if (points) {
      // Filter explicit scatter-overlay points down to the current x-zoom
      // window, same "filter before it reaches the scales" pattern as the
      // grid itself.
      const visiblePoints = zoomDomain
        ? points.filter((p) => p.x >= zoomDomain[0] && p.x <= zoomDomain[1])
        : points
      return visiblePoints.map((p) => ({
        x: xScale(p.x),
        y: yScale(p.y),
        value: p.value,
      }))
    }

    // Generate markers at grid intersections
    const result: { x: number; y: number; value: number }[] = []
    for (let j = 0; j < rows; j++) {
      for (let i = 0; i < cols; i++) {
        const gridX =
          actualXDomain[0] +
          ((actualXDomain[1] - actualXDomain[0]) * i) / (cols - 1)
        const gridY =
          actualYDomain[0] +
          ((actualYDomain[1] - actualYDomain[0]) * j) / (rows - 1)
        result.push({
          x: xScale(gridX),
          y: yScale(gridY),
          value: plotData[j][i],
        })
      }
    }
    return result
  }, [
    showMarkers,
    points,
    plotData,
    rows,
    cols,
    xScale,
    yScale,
    actualXDomain,
    actualYDomain,
    zoomDomain,
  ])

  // Drag-to-zoom: converts the pixel drag range into an x-domain range and
  // narrows the visible column window to it. Re-zooming while already
  // zoomed narrows further (inverted against the current, already-zoomed
  // scale).
  const zoom = useChartZoom({
    svgRef,
    marginLeft: margin.left,
    innerWidth,
    onZoom: ({ x0, x1 }) => {
      const lo = xScale.invert(x0)
      const hi = xScale.invert(x1)
      setZoomDomain([Math.min(lo, hi), Math.max(lo, hi)])
    },
    onReset: () => setZoomDomain(null),
  })

  const handleSvgMouseMove = (e: React.MouseEvent<SVGSVGElement>) => {
    handleMouseMove(e)
    zoom.handlers.onMouseMove(e)
  }

  const handleSvgMouseLeave = (e: React.MouseEvent<SVGSVGElement>) => {
    setMousePos(null)
    zoom.handlers.onMouseLeave(e)
  }

  return (
    <ChartContainer
      config={config}
      className={cn("relative !aspect-auto flex-col", className)}
    >
      <div className="w-full">
        <svg
          ref={svgRef}
          viewBox={`0 0 ${width} ${height}`}
          className="h-full w-full select-none"
          onMouseMove={handleSvgMouseMove}
          onMouseLeave={handleSvgMouseLeave}
          onMouseDown={zoom.handlers.onMouseDown}
          onMouseUp={zoom.handlers.onMouseUp}
          onDoubleClick={zoom.handlers.onDoubleClick}
        >
          <g transform={`translate(${margin.left}, ${margin.top})`}>
            {/* Clip path for contours */}
            <defs>
              <clipPath id={`clip-${gradientId}`}>
                <rect width={innerWidth} height={innerHeight} />
              </clipPath>
            </defs>

            {/* Filled contours */}
            {showFill && (
              <g clipPath={`url(#clip-${gradientId})`}>
                {contourPaths.map((contour, i) => (
                  <path
                    key={`fill-${i}`}
                    d={pathGenerator(contour) || ""}
                    fill={getColor(contour.value)}
                    fillOpacity={0.9}
                    className="pointer-events-none"
                  />
                ))}
              </g>
            )}

            {/* Contour lines */}
            {showLines && (
              <g clipPath={`url(#clip-${gradientId})`}>
                {contourPaths.map((contour, i) => (
                  <path
                    key={`line-${i}`}
                    d={pathGenerator(contour) || ""}
                    fill="none"
                    stroke={lineColor || "rgba(0,0,0,0.3)"}
                    strokeWidth={lineWidth}
                    className="pointer-events-none"
                  />
                ))}
              </g>
            )}

            {/* Grid */}
            {showGrid && (
              <ChartGrid
                xScale={xScale}
                yScale={yScale}
                width={innerWidth}
                height={innerHeight}
              />
            )}

            {/* Data point markers */}
            {showMarkers &&
              gridPoints.map((point, i) =>
                markerSymbol === "circle" ? (
                  <circle
                    key={`marker-${i}`}
                    cx={point.x}
                    cy={point.y}
                    r={markerSize / 2}
                    fill="none"
                    stroke={markerColor}
                    strokeWidth={1.5}
                    className="pointer-events-none"
                  />
                ) : (
                  <path
                    key={`marker-${i}`}
                    d={getMarkerPath(point.x, point.y)}
                    fill="none"
                    stroke={markerColor}
                    strokeWidth={1.5}
                    className="pointer-events-none"
                  />
                )
              )}

            {/* Drag-to-zoom selection rectangle — drawn above the (mostly
                opaque) contour fill so the selection stays visible while
                dragging. */}
            <ChartZoomSelectionRect
              range={zoom.dragRange}
              height={innerHeight}
            />

            {/* X Axis */}
            <ChartAxis
              scale={xScale}
              orientation="bottom"
              transform={`translate(0, ${innerHeight})`}
              label={xAxisLabel}
            />

            {/* Y Axis */}
            <ChartAxis scale={yScale} orientation="left" label={yAxisLabel} />
          </g>

          {/* Color legend */}
          <g
            transform={`translate(${width - margin.right + 15}, ${margin.top})`}
          >
            <defs>
              <linearGradient
                id={`contour-gradient-${gradientId}`}
                x1="0"
                y1="1"
                x2="0"
                y2="0"
              >
                {colorScale.map((color, i) => (
                  <stop
                    key={i}
                    offset={`${(i / (colorScale.length - 1)) * 100}%`}
                    stopColor={color}
                  />
                ))}
              </linearGradient>
            </defs>
            <rect
              width={15}
              height={innerHeight}
              fill={`url(#contour-gradient-${gradientId})`}
              rx={2}
            />
            <text
              x={20}
              y={0}
              dominantBaseline="hanging"
              className="fill-muted-foreground text-[10px]"
            >
              {maxValue.toFixed(1)}
            </text>
            <text
              x={20}
              y={innerHeight}
              dominantBaseline="auto"
              className="fill-muted-foreground text-[10px]"
            >
              {minValue.toFixed(1)}
            </text>
          </g>
        </svg>
      </div>

      {/* Tooltip */}
      {showTooltip && mousePos && (
        <div
          className="pointer-events-none absolute z-50"
          style={{
            left: margin.left + xScale(mousePos.x),
            top: margin.top + yScale(mousePos.y),
          }}
        >
          <div className="border-border/50 bg-background -mt-2 -translate-x-1/2 -translate-y-full rounded-lg border px-2.5 py-1.5 text-xs shadow-xl">
            <div className="text-muted-foreground">
              x: {mousePos.x.toFixed(2)}, y: {mousePos.y.toFixed(2)}
            </div>
            <div className="font-medium">
              Value: {mousePos.value.toFixed(2)}
            </div>
          </div>
        </div>
      )}

      <ChartZoomResetButton
        visible={isZoomed}
        onReset={() => setZoomDomain(null)}
      />
    </ChartContainer>
  )
}

"use client"

import * as React from "react"
import { scaleLinear } from "d3-scale"
import { curveLinearClosed, lineRadial } from "d3-shape"

import { cn } from "@/lib/utils"

import type { BaseChartProps, ChartConfig } from "../chart-config"
import { ChartContainer } from "../chart-container"
import {
  ChartLegend,
  ChartLegendLayout,
  useSeriesHighlight,
  type LegendItem,
} from "../chart-legend"

// ============================================================================
// Types & Interfaces
// ============================================================================

export interface RadarChartDataPoint {
  axis: string
  value: number
}

export interface RadarChartSeries {
  name: string
  data: RadarChartDataPoint[]
  color?: string
  fillOpacity?: number
}

export type RadarChartVariant =
  | "default"
  | "comparison"
  | "legend"
  | "filled"
  | "circle"
  | "minimal"
  | "labels"

export interface RadarChartProps extends BaseChartProps {
  data: RadarChartSeries[]
  variant?: RadarChartVariant
  maxValue?: number
  levels?: number
  showDots?: boolean
  dotSize?: number
  fillOpacity?: number
  strokeWidth?: number
  showLabels?: boolean
  labelOffset?: number
  showLevelLabels?: boolean
  gridType?: "polygon" | "circle"
  showRadialLines?: boolean
}

// ============================================================================
// Variant Configuration
// ============================================================================

interface VariantDefaults {
  levels: number
  showDots: boolean
  dotSize: number
  fillOpacity: number
  strokeWidth: number
  showLabels: boolean
  labelOffset: number
  showLevelLabels: boolean
  gridType: "polygon" | "circle"
  showRadialLines: boolean
  showLegend: boolean
  showGrid: boolean
}

function getVariantDefaults(variant: RadarChartVariant): VariantDefaults {
  switch (variant) {
    case "comparison":
      return {
        levels: 5,
        showDots: false,
        dotSize: 4,
        fillOpacity: 0.4,
        strokeWidth: 2.5,
        showLabels: true,
        labelOffset: 25,
        showLevelLabels: false,
        gridType: "polygon",
        showRadialLines: true,
        showLegend: false,
        showGrid: true,
      }
    case "legend":
      return {
        levels: 5,
        showDots: false,
        dotSize: 4,
        fillOpacity: 0.35,
        strokeWidth: 2,
        showLabels: true,
        labelOffset: 20,
        showLevelLabels: false,
        gridType: "polygon",
        showRadialLines: true,
        showLegend: true,
        showGrid: true,
      }
    case "filled":
      return {
        levels: 5,
        showDots: false,
        dotSize: 4,
        fillOpacity: 0.5,
        strokeWidth: 2,
        showLabels: true,
        labelOffset: 20,
        showLevelLabels: false,
        gridType: "polygon",
        showRadialLines: true,
        showLegend: false,
        showGrid: true,
      }
    case "circle":
      return {
        levels: 4,
        showDots: false,
        dotSize: 4,
        fillOpacity: 0.4,
        strokeWidth: 2,
        showLabels: true,
        labelOffset: 20,
        showLevelLabels: false,
        gridType: "circle",
        showRadialLines: false,
        showLegend: false,
        showGrid: true,
      }
    case "minimal":
      return {
        levels: 0,
        showDots: true,
        dotSize: 5,
        fillOpacity: 0.4,
        strokeWidth: 2,
        showLabels: true,
        labelOffset: 20,
        showLevelLabels: false,
        gridType: "polygon",
        showRadialLines: false,
        showLegend: false,
        showGrid: false,
      }
    case "labels":
      return {
        levels: 5,
        showDots: false,
        dotSize: 4,
        fillOpacity: 0.4,
        strokeWidth: 2,
        showLabels: true,
        labelOffset: 35,
        showLevelLabels: false,
        gridType: "polygon",
        showRadialLines: true,
        showLegend: false,
        showGrid: true,
      }
    default:
      return {
        levels: 5,
        showDots: true,
        dotSize: 4,
        fillOpacity: 0.25,
        strokeWidth: 2,
        showLabels: true,
        labelOffset: 20,
        showLevelLabels: true,
        gridType: "polygon",
        showRadialLines: true,
        showLegend: true,
        showGrid: true,
      }
  }
}

// ============================================================================
// Component
// ============================================================================

export function RadarChart({
  data,
  config,
  className,
  variant = "default",
  width = 500,
  height = 500,
  margin: marginProp,
  showTooltip = true,
  showLegend: showLegendProp,
  legendPosition = "right",
  showGrid: showGridProp,
  maxValue: maxValueProp,
  levels: levelsProp,
  showDots: showDotsProp,
  dotSize: dotSizeProp,
  fillOpacity: fillOpacityProp,
  strokeWidth: strokeWidthProp,
  showLabels: showLabelsProp,
  labelOffset: labelOffsetProp,
  showLevelLabels: showLevelLabelsProp,
  gridType: gridTypeProp,
  showRadialLines: showRadialLinesProp,
}: RadarChartProps) {
  const defaults = getVariantDefaults(variant)

  // Apply variant defaults with prop overrides
  const levels = levelsProp ?? defaults.levels
  const showDots = showDotsProp ?? defaults.showDots
  const dotSize = dotSizeProp ?? defaults.dotSize
  const fillOpacity = fillOpacityProp ?? defaults.fillOpacity
  const strokeWidth = strokeWidthProp ?? defaults.strokeWidth
  const showLabels = showLabelsProp ?? defaults.showLabels
  const labelOffset = labelOffsetProp ?? defaults.labelOffset
  const showLevelLabels = showLevelLabelsProp ?? defaults.showLevelLabels
  const gridType = gridTypeProp ?? defaults.gridType
  const showRadialLines = showRadialLinesProp ?? defaults.showRadialLines
  const showLegend = showLegendProp ?? defaults.showLegend
  const showGrid = showGridProp ?? defaults.showGrid

  const margin = marginProp ?? { top: 50, right: 50, bottom: 50, left: 50 }

  // Legend highlight: click a series to emphasize it (others fade but stay
  // drawn), hover to preview — Plotly-style. `focused` = hover ?? selection.
  // Area/dot hover also drives it so hovering the shape previews too.
  const highlight = useSeriesHighlight()
  const [hoveredPoint, setHoveredPoint] = React.useState<{
    series: string
    axis: string
    value: number
    x: number
    y: number
  } | null>(null)
  const [tooltipPosition, setTooltipPosition] = React.useState<{
    x: number
    y: number
  } | null>(null)

  const innerWidth = width - margin.left - margin.right
  const innerHeight = height - margin.top - margin.bottom
  const radius = Math.min(innerWidth, innerHeight) / 2
  const centerX = innerWidth / 2
  const centerY = innerHeight / 2

  // Get all axes from data
  const axes = React.useMemo(() => {
    const axisSet = new Set<string>()
    data.forEach((series) => {
      series.data.forEach((d) => axisSet.add(d.axis))
    })
    return Array.from(axisSet)
  }, [data])

  const angleSlice = (2 * Math.PI) / axes.length

  // Calculate max value
  const maxValue =
    maxValueProp ??
    Math.max(...data.flatMap((s) => s.data.map((d) => d.value))) * 1.1

  // Radial scale
  const rScale = scaleLinear().domain([0, maxValue]).range([0, radius])

  // Get coordinates for a data point
  const getPoint = (axis: string, value: number) => {
    const index = axes.indexOf(axis)
    const angle = angleSlice * index - Math.PI / 2
    const r = rScale(value)
    return {
      x: centerX + r * Math.cos(angle),
      y: centerY + r * Math.sin(angle),
    }
  }

  // Generate radar area path
  const radarLine = lineRadial<RadarChartDataPoint>()
    .angle((d) => axes.indexOf(d.axis) * angleSlice)
    .radius((d) => rScale(d.value))
    .curve(curveLinearClosed)

  // Generate polygon path for grid
  const generatePolygonPath = (levelRadius: number): string => {
    const points: string[] = []
    for (let i = 0; i < axes.length; i++) {
      const angle = angleSlice * i - Math.PI / 2
      const x = centerX + levelRadius * Math.cos(angle)
      const y = centerY + levelRadius * Math.sin(angle)
      points.push(`${x},${y}`)
    }
    return `M ${points.join(" L ")} Z`
  }

  // Get color for series
  const getSeriesColor = (series: RadarChartSeries, index: number): string => {
    return (
      series.color ??
      config?.[series.name]?.color ??
      `var(--chart-${(index % 5) + 1})`
    )
  }

  // Legend items
  const legendItems: LegendItem[] = data.map((series, i) => ({
    name: series.name,
    color: getSeriesColor(series, i),
  }))

  // Get sorted data for a series
  const getSortedData = (series: RadarChartSeries) => {
    return axes.map((axis) => {
      const point = series.data.find((d) => d.axis === axis)
      return { axis, value: point?.value ?? 0 }
    })
  }

  // Handle area hover
  const handleAreaEnter = (series: RadarChartSeries) => {
    highlight.setHovered(series.name)
  }

  const handleAreaLeave = () => {
    highlight.setHovered(null)
    setTooltipPosition(null)
  }

  // Handle area mouse move for tooltip positioning
  const handleAreaMove = (
    e: React.MouseEvent<SVGPathElement>,
    series: RadarChartSeries,
    seriesIndex: number
  ) => {
    const svgRect = e.currentTarget.ownerSVGElement?.getBoundingClientRect()
    if (svgRect) {
      const x = e.clientX - svgRect.left
      const y = e.clientY - svgRect.top
      setTooltipPosition({ x, y })
      highlight.setHovered(series.name)
    }
  }

  return (
    <ChartContainer
      config={config}
      className={cn("relative !aspect-auto", className)}
    >
      {/* Plot + legend layout — legend sits on `legendPosition` side, click
          a series to highlight it (others fade), click again to restore */}
      <ChartLegendLayout
        position={legendPosition}
        show={showLegend && data.length > 1}
        legend={
          <ChartLegend
            items={legendItems}
            position={legendPosition}
            onItemHover={highlight.setHovered}
            onItemClick={highlight.toggle}
            isItemActive={highlight.isActive}
          />
        }
      >
        <div className="relative mx-auto aspect-square w-full max-w-[320px]">
          <svg
            viewBox={`0 0 ${width} ${height}`}
            className="h-full w-full overflow-visible"
          >
            <g transform={`translate(${margin.left}, ${margin.top})`}>
              {/* Filled grid background for 'filled' variant */}
              {variant === "filled" && showGrid && (
                <path
                  d={generatePolygonPath(radius)}
                  fill="currentColor"
                  className="text-primary/10"
                />
              )}

              {/* Grid levels */}
              {showGrid &&
                levels > 0 &&
                Array.from({ length: levels }, (_, i) => {
                  const levelRadius = (radius / levels) * (i + 1)

                  if (gridType === "circle") {
                    return (
                      <circle
                        key={i}
                        cx={centerX}
                        cy={centerY}
                        r={levelRadius}
                        fill="none"
                        stroke="currentColor"
                        strokeWidth={i === levels - 1 ? 1 : 0.5}
                        strokeOpacity={i === levels - 1 ? 0.5 : 0.3}
                        className="text-border"
                      />
                    )
                  }

                  return (
                    <path
                      key={i}
                      d={generatePolygonPath(levelRadius)}
                      fill="none"
                      stroke="currentColor"
                      strokeWidth={0.5}
                      strokeOpacity={0.3}
                      className="text-border"
                    />
                  )
                })}

              {/* Radial lines (axis lines from center) */}
              {showRadialLines &&
                axes.map((axis, i) => {
                  const angle = angleSlice * i - Math.PI / 2
                  const x2 = centerX + radius * Math.cos(angle)
                  const y2 = centerY + radius * Math.sin(angle)
                  return (
                    <line
                      key={axis}
                      x1={centerX}
                      y1={centerY}
                      x2={x2}
                      y2={y2}
                      stroke="currentColor"
                      strokeWidth={0.5}
                      strokeOpacity={0.3}
                      className="text-border"
                    />
                  )
                })}

              {/* Axis labels */}
              {showLabels &&
                axes.map((axis, i) => {
                  const angle = angleSlice * i - Math.PI / 2
                  const x = centerX + (radius + labelOffset) * Math.cos(angle)
                  const y = centerY + (radius + labelOffset) * Math.sin(angle)

                  // For 'labels' variant, show values alongside axis names
                  if (variant === "labels") {
                    const values = data.map((series) => {
                      const point = series.data.find((d) => d.axis === axis)
                      return point?.value ?? 0
                    })

                    return (
                      <g key={axis}>
                        <text
                          x={x}
                          y={y - (i === 0 ? 8 : 0)}
                          textAnchor="middle"
                          dominantBaseline="middle"
                          className="fill-foreground text-[13px] font-medium"
                        >
                          {values.length > 1 ? (
                            <>
                              <tspan>{values[0]}</tspan>
                              <tspan className="fill-muted-foreground">/</tspan>
                              <tspan>{values[1]}</tspan>
                            </>
                          ) : (
                            values[0]
                          )}
                        </text>
                        <text
                          x={x}
                          y={y + (i === 0 ? 8 : 14)}
                          textAnchor="middle"
                          dominantBaseline="middle"
                          className="fill-muted-foreground text-[11px]"
                        >
                          {axis}
                        </text>
                      </g>
                    )
                  }

                  return (
                    <text
                      key={axis}
                      x={x}
                      y={y}
                      textAnchor="middle"
                      dominantBaseline="middle"
                      className="fill-muted-foreground text-[11px]"
                    >
                      {axis}
                    </text>
                  )
                })}

              {/* Level labels */}
              {showLevelLabels &&
                levels > 0 &&
                Array.from({ length: levels }, (_, i) => {
                  const levelValue = (maxValue / levels) * (i + 1)
                  const levelRadius = (radius / levels) * (i + 1)
                  return (
                    <text
                      key={i}
                      x={centerX + 4}
                      y={centerY - levelRadius}
                      className="fill-muted-foreground text-[9px]"
                      dominantBaseline="middle"
                    >
                      {levelValue.toFixed(0)}
                    </text>
                  )
                })}

              {/* Radar areas — every series stays drawn; the focused one
                (legend/area hover or click-to-pin) keeps full opacity while
                the others fade, Plotly-style */}
              {data.map((series, seriesIndex) => {
                const color = getSeriesColor(series, seriesIndex)
                const isActive = highlight.isActive(series.name)
                const sortedData = getSortedData(series)
                const seriesFillOpacity = series.fillOpacity ?? fillOpacity

                return (
                  <g key={series.name}>
                    {/* Invisible hit area for better mouse interaction */}
                    <path
                      d={radarLine(sortedData) ?? ""}
                      transform={`translate(${centerX}, ${centerY})`}
                      fill="transparent"
                      stroke="transparent"
                      strokeWidth={20}
                      className="cursor-pointer"
                      style={{ pointerEvents: "stroke" }}
                      onMouseEnter={() => handleAreaEnter(series)}
                      onMouseMove={(e) =>
                        handleAreaMove(e, series, seriesIndex)
                      }
                      onMouseLeave={handleAreaLeave}
                    />

                    {/* Visible Area */}
                    <path
                      d={radarLine(sortedData) ?? ""}
                      transform={`translate(${centerX}, ${centerY})`}
                      fill={color}
                      fillOpacity={seriesFillOpacity}
                      stroke={color}
                      strokeWidth={strokeWidth}
                      className={cn(
                        "cursor-pointer transition-opacity duration-200",
                        !isActive && "opacity-30"
                      )}
                      style={{ pointerEvents: "visiblePainted" }}
                      onMouseEnter={() => handleAreaEnter(series)}
                      onMouseMove={(e) =>
                        handleAreaMove(e, series, seriesIndex)
                      }
                      onMouseLeave={handleAreaLeave}
                    />

                    {/* Dots */}
                    {showDots &&
                      sortedData.map((d) => {
                        const point = getPoint(d.axis, d.value)
                        const isPointHovered =
                          hoveredPoint?.series === series.name &&
                          hoveredPoint?.axis === d.axis

                        return (
                          <circle
                            key={d.axis}
                            cx={point.x}
                            cy={point.y}
                            r={isPointHovered ? dotSize * 1.5 : dotSize}
                            fill={color}
                            stroke="hsl(var(--background))"
                            strokeWidth={2}
                            className={cn(
                              "cursor-pointer transition-all duration-200",
                              !isActive && "opacity-30"
                            )}
                            onMouseEnter={() =>
                              setHoveredPoint({
                                series: series.name,
                                axis: d.axis,
                                value: d.value,
                                x: point.x,
                                y: point.y,
                              })
                            }
                            onMouseLeave={() => setHoveredPoint(null)}
                          />
                        )
                      })}
                  </g>
                )
              })}
            </g>
          </svg>

          {/* Tooltip for dot hover */}
          {showTooltip && hoveredPoint && (
            <div
              className="pointer-events-none absolute z-50"
              style={{
                left: margin.left + hoveredPoint.x,
                top: margin.top + hoveredPoint.y - 10,
              }}
            >
              <div className="border-border/50 bg-background -translate-x-1/2 -translate-y-full rounded-lg border px-3 py-2 text-xs shadow-xl">
                <div className="flex items-center gap-2">
                  <div
                    className="h-2.5 w-2.5 rounded-full"
                    style={{
                      backgroundColor: getSeriesColor(
                        data.find((s) => s.name === hoveredPoint.series)!,
                        data.findIndex((s) => s.name === hoveredPoint.series)
                      ),
                    }}
                  />
                  <span className="font-medium">{hoveredPoint.series}</span>
                </div>
                <div className="text-muted-foreground mt-1">
                  {hoveredPoint.axis}: {hoveredPoint.value.toLocaleString()}
                </div>
              </div>
            </div>
          )}

          {/* Tooltip for area hover (when no dot is hovered) */}
          {showTooltip &&
            !hoveredPoint &&
            highlight.hovered &&
            tooltipPosition &&
            data.length > 0 && (
              <div
                className="pointer-events-none absolute z-50"
                style={{
                  left: tooltipPosition.x + 15,
                  top: tooltipPosition.y - 10,
                }}
              >
                <div className="border-border/50 bg-background rounded-lg border px-3 py-2 text-xs shadow-xl">
                  <div className="flex items-center gap-2 font-medium">
                    <div
                      className="h-2.5 w-2.5 rounded-full"
                      style={{
                        backgroundColor: getSeriesColor(
                          data.find((s) => s.name === highlight.hovered)!,
                          data.findIndex((s) => s.name === highlight.hovered)
                        ),
                      }}
                    />
                    {highlight.hovered}
                  </div>
                  <div className="text-muted-foreground mt-1.5 space-y-0.5">
                    {data
                      .find((s) => s.name === highlight.hovered)
                      ?.data.map((d) => (
                        <div
                          key={d.axis}
                          className="flex justify-between gap-3"
                        >
                          <span>{d.axis}:</span>
                          <span className="text-foreground font-medium">
                            {d.value.toLocaleString()}
                          </span>
                        </div>
                      ))}
                  </div>
                </div>
              </div>
            )}
        </div>
      </ChartLegendLayout>
    </ChartContainer>
  )
}

"use client"

import * as React from "react"
import {
  hierarchy,
  treemap,
  treemapBinary,
  treemapDice,
  treemapSlice,
  treemapSquarify,
} from "d3-hierarchy"

import { cn } from "@/lib/utils"

import type { BaseChartProps, ChartConfig } from "../chart-config"
import { ChartContainer } from "../chart-container"

export interface TreemapNode {
  name: string
  value?: number
  children?: TreemapNode[]
  color?: string
}

export interface TreemapChartProps extends BaseChartProps {
  data: TreemapNode
  tile?: "squarify" | "binary" | "slice" | "dice"
  padding?: number
  paddingInner?: number
  paddingOuter?: number
  round?: boolean
  showLabels?: boolean
  labelMinSize?: number
}

const tileMap = {
  squarify: treemapSquarify,
  binary: treemapBinary,
  slice: treemapSlice,
  dice: treemapDice,
}

export function TreemapChart({
  data,
  config,
  className,
  width = 600,
  height = 400,
  margin = { top: 10, right: 10, bottom: 10, left: 10 },
  showTooltip = true,
  tile = "squarify",
  padding = 1,
  paddingInner = 2,
  paddingOuter = 2,
  round = true,
  showLabels = true,
  labelMinSize = 30,
}: TreemapChartProps) {
  const [hoveredNode, setHoveredNode] = React.useState<TreemapNode | null>(null)

  const innerWidth = width - margin.left - margin.right
  const innerHeight = height - margin.top - margin.bottom

  // Create hierarchy and compute treemap layout
  const root = React.useMemo(() => {
    const h = hierarchy(data)
      .sum((d) => d.value ?? 0)
      .sort((a, b) => (b.value ?? 0) - (a.value ?? 0))

    const treemapLayout = treemap<TreemapNode>()
      .size([innerWidth, innerHeight])
      .tile(tileMap[tile])
      .padding(padding)
      .paddingInner(paddingInner)
      .paddingOuter(paddingOuter)
      .round(round)

    return treemapLayout(h)
  }, [
    data,
    innerWidth,
    innerHeight,
    tile,
    padding,
    paddingInner,
    paddingOuter,
    round,
  ])

  // Get all leaves (nodes with values)
  const leaves = root.leaves()

  // Calculate total value for percentages
  const totalValue = root.value ?? 1

  // Generate colors based on depth and index
  const getColor = (node: (typeof leaves)[number], index: number): string => {
    const nodeData = node.data
    if (nodeData.color) return nodeData.color
    if (config?.[nodeData.name]?.color) return config[nodeData.name].color!

    // Use different shades based on parent
    const parentIndex = node.parent
      ? leaves.filter((l) => l.parent === node.parent).indexOf(node)
      : index
    return `var(--chart-${(parentIndex % 5) + 1})`
  }

  return (
    <ChartContainer
      config={config}
      className={cn("!aspect-auto flex-col", className)}
    >
      <div className="relative mx-auto w-full max-w-[500px]">
        <svg
          viewBox={`0 0 ${width} ${height}`}
          className="h-full w-full overflow-visible"
        >
          <g transform={`translate(${margin.left}, ${margin.top})`}>
            {leaves.map((node, index) => {
              const nodeData = node.data
              const x = node.x0
              const y = node.y0
              const w = node.x1 - node.x0
              const h = node.y1 - node.y0
              const color = getColor(node, index)
              const isHovered = hoveredNode === nodeData

              return (
                <g key={`${nodeData.name}-${index}`}>
                  <rect
                    x={x}
                    y={y}
                    width={w}
                    height={h}
                    fill={color}
                    rx={2}
                    ry={2}
                    className={cn(
                      "cursor-pointer transition-all duration-200",
                      hoveredNode !== null && !isHovered && "opacity-60",
                      isHovered && "brightness-110"
                    )}
                    onMouseEnter={() => setHoveredNode(nodeData)}
                    onMouseLeave={() => setHoveredNode(null)}
                  />

                  {/* Label */}
                  {showLabels && w >= labelMinSize && h >= labelMinSize && (
                    <text
                      x={x + w / 2}
                      y={y + h / 2}
                      textAnchor="middle"
                      dominantBaseline="middle"
                      className="pointer-events-none fill-white text-[11px] font-medium"
                      style={{ textShadow: "0 1px 2px rgba(0,0,0,0.3)" }}
                    >
                      {nodeData.name.length > w / 8
                        ? `${nodeData.name.slice(0, Math.floor(w / 8))}...`
                        : nodeData.name}
                    </text>
                  )}
                </g>
              )
            })}
          </g>
        </svg>

        {/* Tooltip */}
        {showTooltip && hoveredNode && (
          <div
            className="pointer-events-none fixed z-50"
            style={{
              left: "50%",
              top: "50%",
              transform: "translate(-50%, -50%)",
            }}
          >
            <div className="border-border/50 bg-background rounded-lg border px-3 py-2 text-sm shadow-xl">
              <div className="font-medium">{hoveredNode.name}</div>
              <div className="text-muted-foreground">
                Value: {(hoveredNode.value ?? 0).toLocaleString()}
              </div>
              <div className="text-muted-foreground">
                {(((hoveredNode.value ?? 0) / totalValue) * 100).toFixed(1)}% of
                total
              </div>
            </div>
          </div>
        )}
      </div>
    </ChartContainer>
  )
}

"use client"

import * as React from "react"
import { hierarchy, partition } from "d3-hierarchy"
import { scaleOrdinal } from "d3-scale"
import { arc } from "d3-shape"

import { cn } from "@/lib/utils"

import type { BaseChartProps, ChartConfig } from "../chart-config"
import { ChartContainer } from "../chart-container"

export interface SunburstNode {
  name: string
  value?: number
  children?: SunburstNode[]
  color?: string
}

export interface SunburstChartProps extends BaseChartProps {
  data: SunburstNode
  innerRadius?: number
  padAngle?: number
  cornerRadius?: number
  showLabels?: boolean
  labelMinAngle?: number
}

export function SunburstChart({
  data,
  config,
  className,
  width = 500,
  height = 500,
  margin = { top: 10, right: 10, bottom: 10, left: 10 },
  showTooltip = true,
  innerRadius = 50,
  padAngle = 0.01,
  cornerRadius = 3,
  showLabels = true,
  labelMinAngle = 0.1,
}: SunburstChartProps) {
  const [hoveredNode, setHoveredNode] = React.useState<SunburstNode | null>(
    null
  )
  const [breadcrumbs, setBreadcrumbs] = React.useState<SunburstNode[]>([])

  const innerWidth = width - margin.left - margin.right
  const innerHeight = height - margin.top - margin.bottom
  const radius = Math.min(innerWidth, innerHeight) / 2
  const centerX = innerWidth / 2
  const centerY = innerHeight / 2

  // Create hierarchy and partition layout
  const root = React.useMemo(() => {
    const h = hierarchy(data)
      .sum((d) => d.value ?? 0)
      .sort((a, b) => (b.value ?? 0) - (a.value ?? 0))

    const partitionLayout = partition<SunburstNode>().size([
      2 * Math.PI,
      radius,
    ])

    return partitionLayout(h)
  }, [data, radius])

  // Calculate depth for color scaling
  const maxDepth = root.height

  // Color scale based on depth
  const depthColors = [
    "var(--chart-1)",
    "var(--chart-2)",
    "var(--chart-3)",
    "var(--chart-4)",
    "var(--chart-5)",
  ]

  const getColor = (node: typeof root, index: number): string => {
    const nodeData = node.data
    if (nodeData.color) return nodeData.color
    if (config?.[nodeData.name]?.color) return config[nodeData.name].color!
    return depthColors[node.depth % depthColors.length]
  }

  // Arc generator
  const arcGenerator = arc<typeof root>()
    .startAngle((d) => d.x0)
    .endAngle((d) => d.x1)
    .padAngle(padAngle)
    .innerRadius((d) =>
      d.depth === 0 ? 0 : innerRadius + (d.y0 / radius) * (radius - innerRadius)
    )
    .outerRadius((d) =>
      d.depth === 0
        ? innerRadius
        : innerRadius + (d.y1 / radius) * (radius - innerRadius)
    )
    .cornerRadius(cornerRadius)

  // Label arc for positioning
  const labelArc = arc<typeof root>()
    .startAngle((d) => d.x0)
    .endAngle((d) => d.x1)
    .innerRadius(
      (d) => innerRadius + ((d.y0 + d.y1) / 2 / radius) * (radius - innerRadius)
    )
    .outerRadius(
      (d) => innerRadius + ((d.y0 + d.y1) / 2 / radius) * (radius - innerRadius)
    )

  // Get all descendants for rendering
  const descendants = root.descendants()

  // Handle hover
  const handleHover = (node: typeof root | null) => {
    if (!node) {
      setHoveredNode(null)
      setBreadcrumbs([])
      return
    }
    setHoveredNode(node.data)
    setBreadcrumbs(
      node
        .ancestors()
        .reverse()
        .map((n) => n.data)
    )
  }

  // Total value for percentage calculation
  const totalValue = root.value ?? 1

  return (
    <ChartContainer
      config={config}
      className={cn("!aspect-auto flex-col", className)}
    >
      <div className="relative mx-auto aspect-square w-full max-w-[320px]">
        <svg
          viewBox={`0 0 ${width} ${height}`}
          className="h-full w-full overflow-visible"
        >
          <g
            transform={`translate(${margin.left + centerX}, ${margin.top + centerY})`}
          >
            {descendants.map((node, index) => {
              const nodeData = node.data
              const color = getColor(node, index)
              const isHovered = hoveredNode === nodeData
              const isAncestor = breadcrumbs.includes(nodeData)
              const angle = node.x1 - node.x0

              return (
                <g key={`${nodeData.name}-${node.depth}-${index}`}>
                  <path
                    d={arcGenerator(node) ?? ""}
                    fill={color}
                    className={cn(
                      "cursor-pointer transition-all duration-200",
                      hoveredNode !== null &&
                        !isHovered &&
                        !isAncestor &&
                        "opacity-40",
                      isHovered && "brightness-110"
                    )}
                    onMouseEnter={() => handleHover(node)}
                    onMouseLeave={() => handleHover(null)}
                  />

                  {/* Label */}
                  {showLabels && angle >= labelMinAngle && node.depth > 0 && (
                    <text
                      transform={`translate(${labelArc.centroid(node)}) rotate(${
                        ((node.x0 + node.x1) / 2 - Math.PI / 2) *
                        (180 / Math.PI)
                      })`}
                      textAnchor="middle"
                      dominantBaseline="middle"
                      className="pointer-events-none fill-white text-[9px] font-medium"
                      style={{ textShadow: "0 1px 2px rgba(0,0,0,0.5)" }}
                    >
                      {nodeData.name.length > 10
                        ? `${nodeData.name.slice(0, 8)}...`
                        : nodeData.name}
                    </text>
                  )}
                </g>
              )
            })}

            {/* Center label */}
            <text
              textAnchor="middle"
              dominantBaseline="middle"
              className="fill-foreground text-sm font-medium"
            >
              {hoveredNode?.name ?? data.name}
            </text>
            {hoveredNode && (
              <text
                y={16}
                textAnchor="middle"
                dominantBaseline="middle"
                className="fill-muted-foreground text-xs"
              >
                {(hoveredNode.value ?? 0).toLocaleString()}
              </text>
            )}
          </g>
        </svg>

        {/* Breadcrumb trail */}
        {breadcrumbs.length > 1 && (
          <div className="absolute top-2 left-2 flex items-center gap-1 text-xs">
            {breadcrumbs.map((node, i) => (
              <React.Fragment key={i}>
                {i > 0 && <span className="text-muted-foreground">/</span>}
                <span
                  className={
                    i === breadcrumbs.length - 1
                      ? "font-medium"
                      : "text-muted-foreground"
                  }
                >
                  {node.name}
                </span>
              </React.Fragment>
            ))}
          </div>
        )}

        {/* Tooltip */}
        {showTooltip && hoveredNode && breadcrumbs.length > 1 && (
          <div className="border-border/50 bg-background absolute bottom-2 left-2 rounded-lg border px-2.5 py-1.5 text-xs shadow-xl">
            <div className="font-medium">{hoveredNode.name}</div>
            <div className="text-muted-foreground">
              Value: {(hoveredNode.value ?? 0).toLocaleString()}
            </div>
            <div className="text-muted-foreground">
              {(((hoveredNode.value ?? 0) / totalValue) * 100).toFixed(1)}% of
              total
            </div>
          </div>
        )}
      </div>
    </ChartContainer>
  )
}

"use client"

import * as React from "react"
import {
  sankey,
  sankeyCenter,
  sankeyJustify,
  sankeyLeft,
  sankeyLinkHorizontal,
  sankeyRight,
} from "d3-sankey"

import { cn } from "@/lib/utils"

import type { BaseChartProps, ChartConfig } from "../chart-config"
import { ChartContainer } from "../chart-container"

export interface SankeyNode {
  id: string
  name?: string
  color?: string
}

export interface SankeyLink {
  source: string
  target: string
  value: number
  color?: string
}

export interface SankeyChartProps extends BaseChartProps {
  nodes: SankeyNode[]
  links: SankeyLink[]
  nodeWidth?: number
  nodePadding?: number
  nodeAlign?: "left" | "right" | "center" | "justify"
  linkOpacity?: number
  showLabels?: boolean
  showValues?: boolean
}

const alignMap = {
  left: sankeyLeft,
  right: sankeyRight,
  center: sankeyCenter,
  justify: sankeyJustify,
}

interface SankeyComputedNode {
  id: string
  name?: string
  color?: string
  x0: number
  x1: number
  y0: number
  y1: number
  value: number
  sourceLinks: SankeyComputedLink[]
  targetLinks: SankeyComputedLink[]
}

interface SankeyComputedLink {
  source: SankeyComputedNode
  target: SankeyComputedNode
  value: number
  width: number
  y0: number
  y1: number
  color?: string
}

export function SankeyChart({
  nodes,
  links,
  config,
  className,
  width = 800,
  height = 500,
  margin = { top: 20, right: 150, bottom: 20, left: 150 },
  showTooltip = true,
  nodeWidth = 15,
  nodePadding = 20,
  nodeAlign = "justify",
  linkOpacity = 0.5,
  showLabels = true,
  showValues = true,
}: SankeyChartProps) {
  const [hoveredElement, setHoveredElement] = React.useState<{
    type: "node" | "link"
    data: SankeyComputedNode | SankeyComputedLink
  } | null>(null)
  const hoverTimeoutRef = React.useRef<NodeJS.Timeout | null>(null)

  // Clear hover with a small delay to prevent flickering
  const clearHover = React.useCallback(() => {
    if (hoverTimeoutRef.current) {
      clearTimeout(hoverTimeoutRef.current)
    }
    hoverTimeoutRef.current = setTimeout(() => {
      setHoveredElement(null)
    }, 50)
  }, [])

  const setHover = React.useCallback(
    (type: "node" | "link", data: SankeyComputedNode | SankeyComputedLink) => {
      if (hoverTimeoutRef.current) {
        clearTimeout(hoverTimeoutRef.current)
        hoverTimeoutRef.current = null
      }
      setHoveredElement({ type, data })
    },
    []
  )

  React.useEffect(() => {
    return () => {
      if (hoverTimeoutRef.current) {
        clearTimeout(hoverTimeoutRef.current)
      }
    }
  }, [])

  const innerWidth = width - margin.left - margin.right
  const innerHeight = height - margin.top - margin.bottom

  // Create sankey layout
  const { computedNodes, computedLinks } = React.useMemo(() => {
    // Validate inputs
    if (!nodes.length || !links.length) {
      return { computedNodes: [], computedLinks: [] }
    }

    // Create graph - use string IDs for links when using nodeId()
    const sankeyData = {
      nodes: nodes.map((n) => ({ ...n })),
      links: links.map((l) => ({
        source: l.source,
        target: l.target,
        value: l.value,
        color: l.color,
      })),
    }

    // Create sankey generator
    const sankeyGenerator = sankey<
      (typeof sankeyData.nodes)[0],
      (typeof sankeyData.links)[0]
    >()
      .nodeId((d) => d.id)
      .nodeWidth(nodeWidth)
      .nodePadding(nodePadding)
      .nodeAlign(alignMap[nodeAlign])
      .extent([
        [0, 0],
        [innerWidth, innerHeight],
      ])

    try {
      const result = sankeyGenerator(sankeyData as any)
      return {
        computedNodes: result.nodes as unknown as SankeyComputedNode[],
        computedLinks: result.links as unknown as SankeyComputedLink[],
      }
    } catch (error) {
      console.error("Sankey layout error:", error)
      return { computedNodes: [], computedLinks: [] }
    }
  }, [nodes, links, innerWidth, innerHeight, nodeWidth, nodePadding, nodeAlign])

  // Get color for node
  const getNodeColor = (node: SankeyComputedNode, index: number): string => {
    if (node.color) return node.color
    const configColor =
      config?.[node.id]?.color ?? config?.[node.name ?? ""]?.color
    if (configColor) return configColor
    return `var(--chart-${(index % 5) + 1})`
  }

  // Link path generator
  const linkPath = sankeyLinkHorizontal()

  // Check if node or its links are highlighted
  const isNodeHighlighted = (node: SankeyComputedNode): boolean => {
    if (!hoveredElement) return true
    if (hoveredElement.type === "node") {
      const hoveredNode = hoveredElement.data as SankeyComputedNode
      if (hoveredNode === node) return true
      return (
        hoveredNode.sourceLinks.some((l) => l.target === node) ||
        hoveredNode.targetLinks.some((l) => l.source === node)
      )
    }
    if (hoveredElement.type === "link") {
      const hoveredLink = hoveredElement.data as SankeyComputedLink
      return hoveredLink.source === node || hoveredLink.target === node
    }
    return false
  }

  const isLinkHighlighted = (link: SankeyComputedLink): boolean => {
    if (!hoveredElement) return true
    if (hoveredElement.type === "link") {
      return hoveredElement.data === link
    }
    if (hoveredElement.type === "node") {
      const hoveredNode = hoveredElement.data as SankeyComputedNode
      return link.source === hoveredNode || link.target === hoveredNode
    }
    return false
  }

  return (
    <ChartContainer
      config={config}
      className={cn("!aspect-auto flex-col", className)}
    >
      <div
        className="relative mx-auto w-full"
        style={{ aspectRatio: `${width} / ${height}` }}
      >
        <svg
          viewBox={`0 0 ${width} ${height}`}
          className="h-full w-full overflow-visible"
        >
          <g transform={`translate(${margin.left}, ${margin.top})`}>
            {/* Links */}
            {computedLinks.map((link, index) => {
              const color =
                link.color ??
                getNodeColor(link.source, computedNodes.indexOf(link.source))
              const highlighted = isLinkHighlighted(link)
              const isHovered =
                hoveredElement?.type === "link" && hoveredElement.data === link

              return (
                <path
                  key={index}
                  d={linkPath(link as any) ?? ""}
                  fill="none"
                  stroke={color}
                  strokeWidth={Math.max(1, link.width)}
                  opacity={highlighted ? 1 : 0.15}
                  strokeOpacity={isHovered ? linkOpacity + 0.2 : linkOpacity}
                  className="cursor-pointer"
                  style={{ transition: "opacity 150ms ease-out" }}
                  onMouseEnter={() => setHover("link", link)}
                  onMouseLeave={clearHover}
                />
              )
            })}

            {/* Nodes */}
            {computedNodes.map((node, index) => {
              const color = getNodeColor(node, index)
              const highlighted = isNodeHighlighted(node)

              // Determine node type and label position:
              // - Source nodes (no incoming): label on LEFT
              // - Sink nodes (no outgoing): label on RIGHT
              // - Middle nodes: label on LEFT (same as source to prevent horizontal overlap)
              const isSink = node.sourceLinks.length === 0

              // Calculate label position - all non-sink nodes get labels on LEFT
              let labelX: number
              let labelY: number
              let textAnchor: "start" | "middle" | "end"

              if (isSink) {
                // Right side label for sink nodes
                labelX = node.x1 + 8
                labelY = (node.y0 + node.y1) / 2
                textAnchor = "start"
              } else {
                // Left side label for source and middle nodes
                labelX = node.x0 - 8
                labelY = (node.y0 + node.y1) / 2
                textAnchor = "end"
              }

              const labelText = showValues
                ? `${node.name ?? node.id} (${node.value.toLocaleString()})`
                : (node.name ?? node.id)

              return (
                <g key={node.id}>
                  <rect
                    x={node.x0}
                    y={node.y0}
                    width={node.x1 - node.x0}
                    height={Math.max(1, node.y1 - node.y0)}
                    fill={color}
                    rx={2}
                    opacity={highlighted ? 1 : 0.3}
                    className="cursor-pointer"
                    style={{ transition: "opacity 150ms ease-out" }}
                    onMouseEnter={() => setHover("node", node)}
                    onMouseLeave={clearHover}
                  />

                  {/* Node label */}
                  {showLabels && (
                    <text
                      x={labelX}
                      y={labelY}
                      textAnchor={textAnchor}
                      dominantBaseline="middle"
                      opacity={highlighted ? 1 : 0.4}
                      className="fill-foreground pointer-events-none text-[10px] font-medium"
                      style={{ transition: "opacity 150ms ease-out" }}
                    >
                      {labelText}
                    </text>
                  )}
                </g>
              )
            })}
          </g>
        </svg>

        {/* Tooltip */}
        {showTooltip && hoveredElement && (
          <div className="border-border/50 bg-background absolute bottom-4 left-4 rounded-lg border px-3 py-2 text-sm shadow-xl">
            {hoveredElement.type === "node" && (
              <>
                <div className="font-medium">
                  {(hoveredElement.data as SankeyComputedNode).name ??
                    (hoveredElement.data as SankeyComputedNode).id}
                </div>
                <div className="text-muted-foreground">
                  Value:{" "}
                  {(
                    hoveredElement.data as SankeyComputedNode
                  ).value.toLocaleString()}
                </div>
                <div className="text-muted-foreground mt-1 text-xs">
                  Incoming:{" "}
                  {
                    (hoveredElement.data as SankeyComputedNode).targetLinks
                      .length
                  }{" "}
                  | Outgoing:{" "}
                  {
                    (hoveredElement.data as SankeyComputedNode).sourceLinks
                      .length
                  }
                </div>
              </>
            )}
            {hoveredElement.type === "link" && (
              <>
                <div className="font-medium">
                  {(hoveredElement.data as SankeyComputedLink).source.name ??
                    (hoveredElement.data as SankeyComputedLink).source.id}{" "}
                  →{" "}
                  {(hoveredElement.data as SankeyComputedLink).target.name ??
                    (hoveredElement.data as SankeyComputedLink).target.id}
                </div>
                <div className="text-muted-foreground">
                  Value:{" "}
                  {(
                    hoveredElement.data as SankeyComputedLink
                  ).value.toLocaleString()}
                </div>
              </>
            )}
          </div>
        )}
      </div>
    </ChartContainer>
  )
}

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

import type { BaseChartProps } from "../chart-config"
import { ChartContainer } from "../chart-container"

export interface GaugeChartProps extends BaseChartProps {
  /** Current value to display */
  value: number
  /** Minimum value */
  min?: number
  /** Maximum value */
  max?: number
  /** Label text below value */
  label?: string
  /** Units to display after value */
  units?: string
  /** Show the numeric value */
  showValue?: boolean
  /** Gauge variant style */
  variant?:
    | "modern"
    | "speedometer"
    | "segmented"
    | "radial"
    | "minimal"
    | "gradient"
    | "meter"
    | "dashboard"
    | "ticks"
  /** Arc thickness (as percentage of radius, 0-1) */
  thickness?: number
  /** Primary color or color for filled arc */
  color?: string
  /** Secondary color for gradient */
  colorSecondary?: string
  /** Background arc color */
  bgColor?: string
  /** Segments for segmented variant */
  segments?: Array<{ value: number; color: string; label?: string }>
  /** Show tick marks */
  showTicks?: boolean
  /** Number of tick marks. Defaults to 14 for `variant="ticks"`, else 5. */
  tickCount?: number
  /** Degrees the `ticks` arc spans, centred on twelve o'clock. */
  tickArc?: number
  /** Centre overlay — a badge, a caption, anything non-SVG. */
  children?: React.ReactNode
  /** Animate on mount */
  animate?: boolean
  /** Animation duration in ms */
  animationDuration?: number
  /** Value formatter */
  valueFormatter?: (value: number) => string
  /** Show percentage instead of value */
  showPercentage?: boolean
}

// Default colors using CSS variables for theme support
const COLORS = {
  primary: "var(--chart-1)",
  success: "var(--chart-2)",
  warning: "var(--chart-3)",
  danger: "var(--chart-4)",
  muted: "var(--muted)",
  purple: "var(--chart-5)",
  pink: "var(--chart-3)",
}

export function GaugeChart({
  value,
  config,
  className,
  width = 280,
  height = 200,
  margin = { top: 20, right: 20, bottom: 20, left: 20 },
  min = 0,
  max = 100,
  label,
  units,
  showValue = true,
  variant = "modern",
  thickness = 0.15,
  color = COLORS.primary,
  colorSecondary = COLORS.purple,
  bgColor = COLORS.muted,
  segments,
  showTicks = false,
  tickCount,
  tickArc = 200,
  children,
  animate = true,
  animationDuration = 1000,
  valueFormatter,
  showPercentage = false,
}: GaugeChartProps) {
  const [animatedPercentage, setAnimatedPercentage] = React.useState(0)
  const gradientId = React.useId().replace(/:/g, "")

  const innerWidth = width - margin.left - margin.right
  const innerHeight = height - margin.top - margin.bottom

  // Calculate dimensions based on variant
  const isRadial = variant === "radial"
  const centerX = innerWidth / 2
  const centerY = isRadial ? innerHeight / 2 : innerHeight * 0.75
  const radius =
    Math.min(innerWidth / 2, isRadial ? innerHeight / 2 : innerHeight * 0.7) *
    0.85
  const strokeWidth = radius * thickness
  // The dotted-arc variant needs many more segments than a needle gauge's
  // scale marks, so its default differs.
  const resolvedTickCount = tickCount ?? (variant === "ticks" ? 14 : 5)

  // Clamp value and calculate percentage
  const clampedValue = Math.max(min, Math.min(max, value))
  const targetPercentage = (clampedValue - min) / (max - min)

  // Animate percentage
  React.useEffect(() => {
    if (!animate) {
      setAnimatedPercentage(targetPercentage)
      return
    }

    const startTime = Date.now()
    const startPercentage = animatedPercentage

    const animateFrame = () => {
      const elapsed = Date.now() - startTime
      const progress = Math.min(elapsed / animationDuration, 1)
      // Ease out cubic
      const eased = 1 - Math.pow(1 - progress, 3)
      const newPercentage =
        startPercentage + (targetPercentage - startPercentage) * eased
      setAnimatedPercentage(newPercentage)
      if (progress < 1) requestAnimationFrame(animateFrame)
    }
    requestAnimationFrame(animateFrame)
  }, [targetPercentage, animate, animationDuration])

  // Arc calculations for semi-circle (270 degrees for gauge, 360 for radial)
  const arcAngle = isRadial ? 360 : 270
  const circumference = 2 * Math.PI * radius
  const arcLength = (arcAngle / 360) * circumference
  const dashOffset = arcLength * (1 - animatedPercentage)

  // Format value
  const formatValue = (v: number): string => {
    if (valueFormatter) return valueFormatter(v)
    if (showPercentage) return `${Math.round((v / max) * 100)}%`
    if (v >= 1000000) return `${(v / 1000000).toFixed(1)}M`
    if (v >= 1000) return `${(v / 1000).toFixed(1)}K`
    return Math.round(v).toString()
  }

  // Get segment color at current value
  const getSegmentColor = (): string => {
    if (!segments || segments.length === 0) return color
    const currentValue = min + (max - min) * animatedPercentage
    for (let i = segments.length - 1; i >= 0; i--) {
      if (currentValue >= segments[i].value) {
        return segments[i].color
      }
    }
    return segments[0]?.color || color
  }

  // Generate tick positions for semi-circle
  const generateTicks = () => {
    if (!showTicks) return []
    const ticks = []
    const startAngle = -225 // Start from bottom-left
    const totalAngle = 270 // Semi-circle arc

    for (let i = 0; i < resolvedTickCount; i++) {
      const angle = startAngle + (totalAngle / (resolvedTickCount - 1)) * i
      const rad = (angle * Math.PI) / 180
      const tickValue = min + ((max - min) / (resolvedTickCount - 1)) * i

      // Outer tick position
      const outerX = centerX + (radius + 10) * Math.cos(rad)
      const outerY = centerY + (radius + 10) * Math.sin(rad)

      // Inner tick position
      const innerX = centerX + (radius - strokeWidth / 2 - 5) * Math.cos(rad)
      const innerY = centerY + (radius - strokeWidth / 2 - 5) * Math.sin(rad)

      // Label position
      const labelX = centerX + (radius + 25) * Math.cos(rad)
      const labelY = centerY + (radius + 25) * Math.sin(rad)

      ticks.push({
        angle,
        innerX,
        innerY,
        outerX,
        outerY,
        labelX,
        labelY,
        value: tickValue,
      })
    }
    return ticks
  }

  const ticks = generateTicks()

  // Semi-circle arc path (for background)
  const semiCirclePath = `
    M ${centerX - radius} ${centerY}
    A ${radius} ${radius} 0 1 1 ${centerX + radius} ${centerY}
  `

  // Radial uses circle
  const renderRadial = () => (
    <>
      {/* Background circle */}
      <circle
        cx={centerX}
        cy={centerY}
        r={radius}
        fill="none"
        stroke={bgColor}
        strokeWidth={strokeWidth}
      />
      {/* Value arc */}
      <circle
        cx={centerX}
        cy={centerY}
        r={radius}
        fill="none"
        stroke={segments ? getSegmentColor() : color}
        strokeWidth={strokeWidth}
        strokeLinecap="round"
        strokeDasharray={circumference}
        strokeDashoffset={circumference * (1 - animatedPercentage)}
        transform={`rotate(-90 ${centerX} ${centerY})`}
        style={{ transition: animate ? "none" : "stroke-dashoffset 0.3s ease" }}
      />
      {/* Center content */}
      {showValue && (
        <g transform={`translate(${centerX}, ${centerY})`}>
          <text
            textAnchor="middle"
            dominantBaseline="middle"
            className="fill-foreground font-bold"
            style={{ fontSize: radius * 0.4 }}
          >
            {formatValue(min + (max - min) * animatedPercentage)}
          </text>
          {(units || label) && (
            <text
              y={radius * 0.3}
              textAnchor="middle"
              className="fill-muted-foreground"
              style={{ fontSize: radius * 0.14 }}
            >
              {units || label}
            </text>
          )}
        </g>
      )}
    </>
  )

  // Modern clean arc
  const renderModern = () => (
    <>
      {/* Background arc */}
      <path
        d={semiCirclePath}
        fill="none"
        stroke={bgColor}
        strokeWidth={strokeWidth}
        strokeLinecap="round"
      />
      {/* Value arc */}
      <path
        d={semiCirclePath}
        fill="none"
        stroke={segments ? getSegmentColor() : color}
        strokeWidth={strokeWidth}
        strokeLinecap="round"
        strokeDasharray={arcLength}
        strokeDashoffset={dashOffset}
        style={{ transition: animate ? "none" : "stroke-dashoffset 0.3s ease" }}
      />
      {/* Center value */}
      {showValue && (
        <g transform={`translate(${centerX}, ${centerY - radius * 0.15})`}>
          <text
            textAnchor="middle"
            dominantBaseline="middle"
            className="fill-foreground font-bold"
            style={{ fontSize: radius * 0.45 }}
          >
            {formatValue(min + (max - min) * animatedPercentage)}
          </text>
          {units && (
            <text
              y={radius * 0.25}
              textAnchor="middle"
              className="fill-muted-foreground"
              style={{ fontSize: radius * 0.14 }}
            >
              {units}
            </text>
          )}
          {label && (
            <text
              y={radius * 0.45}
              textAnchor="middle"
              className="fill-muted-foreground"
              style={{ fontSize: radius * 0.12 }}
            >
              {label}
            </text>
          )}
        </g>
      )}
    </>
  )

  // Gradient arc
  const renderGradient = () => (
    <>
      <defs>
        <linearGradient
          id={`gauge-gradient-${gradientId}`}
          x1="0%"
          y1="0%"
          x2="100%"
          y2="0%"
        >
          <stop offset="0%" stopColor={color} />
          <stop offset="100%" stopColor={colorSecondary} />
        </linearGradient>
      </defs>
      {/* Background arc */}
      <path
        d={semiCirclePath}
        fill="none"
        stroke={bgColor}
        strokeWidth={strokeWidth}
        strokeLinecap="round"
      />
      {/* Gradient value arc */}
      <path
        d={semiCirclePath}
        fill="none"
        stroke={`url(#gauge-gradient-${gradientId})`}
        strokeWidth={strokeWidth}
        strokeLinecap="round"
        strokeDasharray={arcLength}
        strokeDashoffset={dashOffset}
      />
      {/* Center value */}
      {showValue && (
        <g transform={`translate(${centerX}, ${centerY - radius * 0.15})`}>
          <text
            textAnchor="middle"
            dominantBaseline="middle"
            className="fill-foreground font-bold"
            style={{ fontSize: radius * 0.45 }}
          >
            {formatValue(min + (max - min) * animatedPercentage)}
          </text>
          {label && (
            <text
              y={radius * 0.35}
              textAnchor="middle"
              className="fill-muted-foreground"
              style={{ fontSize: radius * 0.12 }}
            >
              {label}
            </text>
          )}
        </g>
      )}
    </>
  )

  // Speedometer with needle
  const renderSpeedometer = () => {
    const needleAngle = -225 + 270 * animatedPercentage
    const needleRad = (needleAngle * Math.PI) / 180
    const needleLength = radius * 0.7
    const needleX = centerX + needleLength * Math.cos(needleRad)
    const needleY = centerY + needleLength * Math.sin(needleRad)

    return (
      <>
        {/* Background arc */}
        <path
          d={semiCirclePath}
          fill="none"
          stroke={bgColor}
          strokeWidth={strokeWidth}
          strokeLinecap="round"
        />
        {/* Value arc */}
        <path
          d={semiCirclePath}
          fill="none"
          stroke={segments ? getSegmentColor() : color}
          strokeWidth={strokeWidth}
          strokeLinecap="round"
          strokeDasharray={arcLength}
          strokeDashoffset={dashOffset}
        />
        {/* Tick marks */}
        {ticks.map((tick, i) => (
          <g key={i}>
            <line
              x1={tick.innerX}
              y1={tick.innerY}
              x2={tick.innerX + (tick.outerX - tick.innerX) * 0.5}
              y2={tick.innerY + (tick.outerY - tick.innerY) * 0.5}
              stroke="currentColor"
              strokeWidth={2}
              className="text-muted-foreground"
            />
            <text
              x={tick.labelX}
              y={tick.labelY}
              textAnchor="middle"
              dominantBaseline="middle"
              className="fill-muted-foreground"
              style={{ fontSize: 9 }}
            >
              {formatValue(tick.value)}
            </text>
          </g>
        ))}
        {/* Needle */}
        <line
          x1={centerX}
          y1={centerY}
          x2={needleX}
          y2={needleY}
          stroke={segments ? getSegmentColor() : color}
          strokeWidth={3}
          strokeLinecap="round"
        />
        {/* Needle center */}
        <circle
          cx={centerX}
          cy={centerY}
          r={12}
          fill={segments ? getSegmentColor() : color}
        />
        <circle cx={centerX} cy={centerY} r={6} fill="white" />
        {/* Value below */}
        {showValue && (
          <text
            x={centerX}
            y={centerY + radius * 0.35}
            textAnchor="middle"
            className="fill-foreground font-bold"
            style={{ fontSize: radius * 0.28 }}
          >
            {formatValue(min + (max - min) * animatedPercentage)}
            {units && (
              <tspan
                className="fill-muted-foreground font-normal"
                style={{ fontSize: radius * 0.12 }}
              >
                {" "}
                {units}
              </tspan>
            )}
          </text>
        )}
      </>
    )
  }

  // Segmented colored zones
  const renderSegmented = () => {
    const segs = segments || [
      { value: 0, color: COLORS.success },
      { value: 33, color: COLORS.warning },
      { value: 66, color: COLORS.danger },
    ]

    // Gap angle in degrees between segments
    const gapAngle = 3

    // Generate individual arc paths for each segment
    const generateSegmentArc = (startPercent: number, endPercent: number) => {
      const startAngle = -225 + 270 * startPercent
      const endAngle = -225 + 270 * endPercent
      const startRad = (startAngle * Math.PI) / 180
      const endRad = (endAngle * Math.PI) / 180

      const x1 = centerX + radius * Math.cos(startRad)
      const y1 = centerY + radius * Math.sin(startRad)
      const x2 = centerX + radius * Math.cos(endRad)
      const y2 = centerY + radius * Math.sin(endRad)

      const largeArcFlag = endAngle - startAngle > 180 ? 1 : 0

      return `M ${x1} ${y1} A ${radius} ${radius} 0 ${largeArcFlag} 1 ${x2} ${y2}`
    }

    return (
      <>
        {/* Segmented arcs - using individual arc paths for clean edges */}
        {segs.map((seg, i) => {
          const nextValue = segs[i + 1]?.value ?? max
          const segStart = (seg.value - min) / (max - min)
          const segEnd = (nextValue - min) / (max - min)

          // Add small gaps between segments
          const gapOffset = gapAngle / 270 // Convert gap angle to percentage
          const adjustedStart = i === 0 ? segStart : segStart + gapOffset / 2
          const adjustedEnd =
            i === segs.length - 1 ? segEnd : segEnd - gapOffset / 2

          const isActive = animatedPercentage >= segStart

          return (
            <path
              key={i}
              d={generateSegmentArc(adjustedStart, adjustedEnd)}
              fill="none"
              stroke={seg.color}
              strokeWidth={strokeWidth}
              strokeLinecap="round"
              opacity={isActive ? 1 : 0.25}
              style={{ transition: "opacity 0.3s ease" }}
            />
          )
        })}
        {/* Indicator needle */}
        {(() => {
          const needleAngle = -225 + 270 * animatedPercentage
          const needleRad = (needleAngle * Math.PI) / 180
          const needleOuterX =
            centerX + (radius + strokeWidth / 2 + 6) * Math.cos(needleRad)
          const needleOuterY =
            centerY + (radius + strokeWidth / 2 + 6) * Math.sin(needleRad)
          const needleInnerX =
            centerX + (radius - strokeWidth / 2 - 6) * Math.cos(needleRad)
          const needleInnerY =
            centerY + (radius - strokeWidth / 2 - 6) * Math.sin(needleRad)

          return (
            <g>
              {/* Needle line */}
              <line
                x1={needleInnerX}
                y1={needleInnerY}
                x2={needleOuterX}
                y2={needleOuterY}
                stroke={getSegmentColor()}
                strokeWidth={3}
                strokeLinecap="round"
              />
              {/* Needle dot on arc */}
              <circle
                cx={centerX + radius * Math.cos(needleRad)}
                cy={centerY + radius * Math.sin(needleRad)}
                r={strokeWidth / 2 + 2}
                fill={getSegmentColor()}
              />
            </g>
          )
        })()}
        {/* Center value */}
        {showValue && (
          <g transform={`translate(${centerX}, ${centerY - radius * 0.15})`}>
            <text
              textAnchor="middle"
              dominantBaseline="middle"
              className="font-bold"
              style={{ fontSize: radius * 0.4, fill: getSegmentColor() }}
            >
              {formatValue(min + (max - min) * animatedPercentage)}
            </text>
            {label && (
              <text
                y={radius * 0.3}
                textAnchor="middle"
                className="fill-muted-foreground"
                style={{ fontSize: radius * 0.12 }}
              >
                {label}
              </text>
            )}
          </g>
        )}
      </>
    )
  }

  // Minimal thin arc
  const renderMinimal = () => (
    <>
      {/* Background arc */}
      <path
        d={semiCirclePath}
        fill="none"
        stroke={bgColor}
        strokeWidth={strokeWidth * 0.5}
        strokeLinecap="round"
      />
      {/* Value arc */}
      <path
        d={semiCirclePath}
        fill="none"
        stroke={segments ? getSegmentColor() : color}
        strokeWidth={strokeWidth}
        strokeLinecap="round"
        strokeDasharray={arcLength}
        strokeDashoffset={dashOffset}
      />
      {/* Min label */}
      <text
        x={centerX - radius - 10}
        y={centerY + 15}
        textAnchor="middle"
        className="fill-muted-foreground"
        style={{ fontSize: 10 }}
      >
        {formatValue(min)}
      </text>
      {/* Max label */}
      <text
        x={centerX + radius + 10}
        y={centerY + 15}
        textAnchor="middle"
        className="fill-muted-foreground"
        style={{ fontSize: 10 }}
      >
        {formatValue(max)}
      </text>
      {/* Center value */}
      {showValue && (
        <g transform={`translate(${centerX}, ${centerY - radius * 0.2})`}>
          <text
            textAnchor="middle"
            dominantBaseline="middle"
            className="fill-foreground font-bold"
            style={{ fontSize: radius * 0.5 }}
          >
            {formatValue(min + (max - min) * animatedPercentage)}
          </text>
          {label && (
            <text
              y={radius * 0.3}
              textAnchor="middle"
              className="fill-muted-foreground"
              style={{ fontSize: radius * 0.12 }}
            >
              {label}
            </text>
          )}
        </g>
      )}
    </>
  )

  // Meter style with ticks outside
  const renderMeter = () => (
    <>
      {/* Outer tick marks */}
      {ticks.map((tick, i) => (
        <g key={i}>
          <line
            x1={tick.outerX}
            y1={tick.outerY}
            x2={tick.outerX + (tick.labelX - tick.outerX) * 0.4}
            y2={tick.outerY + (tick.labelY - tick.outerY) * 0.4}
            stroke="currentColor"
            strokeWidth={i === 0 || i === resolvedTickCount - 1 ? 2.5 : 1.5}
            className="text-muted-foreground"
          />
          <text
            x={tick.labelX}
            y={tick.labelY}
            textAnchor="middle"
            dominantBaseline="middle"
            className="fill-muted-foreground font-medium"
            style={{ fontSize: 10 }}
          >
            {formatValue(tick.value)}
          </text>
        </g>
      ))}
      {/* Background arc */}
      <path
        d={semiCirclePath}
        fill="none"
        stroke={bgColor}
        strokeWidth={strokeWidth}
        strokeLinecap="round"
      />
      {/* Value arc */}
      <path
        d={semiCirclePath}
        fill="none"
        stroke={segments ? getSegmentColor() : color}
        strokeWidth={strokeWidth}
        strokeLinecap="round"
        strokeDasharray={arcLength}
        strokeDashoffset={dashOffset}
      />
      {/* Center value */}
      {showValue && (
        <g transform={`translate(${centerX}, ${centerY - radius * 0.1})`}>
          <text
            textAnchor="middle"
            dominantBaseline="middle"
            className="fill-foreground font-bold"
            style={{ fontSize: radius * 0.35 }}
          >
            {formatValue(min + (max - min) * animatedPercentage)}
          </text>
          {label && (
            <text
              y={radius * 0.25}
              textAnchor="middle"
              className="fill-muted-foreground"
              style={{ fontSize: radius * 0.11 }}
            >
              {label}
            </text>
          )}
        </g>
      )}
    </>
  )

  // Dashboard card style
  const renderDashboard = () => {
    const percentage = Math.round(animatedPercentage * 100)
    return (
      <>
        {/* Background arc */}
        <path
          d={semiCirclePath}
          fill="none"
          stroke={bgColor}
          strokeWidth={strokeWidth * 1.5}
          strokeLinecap="round"
        />
        {/* Value arc with rounded gradient look */}
        <path
          d={semiCirclePath}
          fill="none"
          stroke={segments ? getSegmentColor() : color}
          strokeWidth={strokeWidth * 1.5}
          strokeLinecap="round"
          strokeDasharray={arcLength}
          strokeDashoffset={dashOffset}
        />
        {/* Large percentage in center */}
        {showValue && (
          <g transform={`translate(${centerX}, ${centerY - radius * 0.2})`}>
            <text
              textAnchor="middle"
              dominantBaseline="middle"
              className="fill-foreground font-bold"
              style={{ fontSize: radius * 0.6 }}
            >
              {percentage}
              <tspan style={{ fontSize: radius * 0.25 }}>%</tspan>
            </text>
            {label && (
              <text
                y={radius * 0.35}
                textAnchor="middle"
                className="fill-muted-foreground font-medium"
                style={{ fontSize: radius * 0.13 }}
              >
                {label}
              </text>
            )}
          </g>
        )}
      </>
    )
  }

  /** Discrete rounded capsules radiating around an arc, filled up to the
   *  value — the "how far through the budget am I" meter. Reads at a glance
   *  from across a room in a way a thin arc does not. */
  const renderTicks = () => {
    const n = Math.max(2, resolvedTickCount)
    // -90deg is twelve o'clock in this file's angle convention.
    const start = -90 - tickArc / 2
    const step = tickArc / n
    const inner = radius - strokeWidth * 0.85
    const outer = radius + strokeWidth * 0.85
    const filled = Math.round(n * animatedPercentage)

    return (
      <>
        {Array.from({ length: n }, (_, i) => {
          const rad = ((start + step * (i + 0.5)) * Math.PI) / 180
          const on = i < filled
          return (
            <line
              key={i}
              x1={centerX + inner * Math.cos(rad)}
              y1={centerY + inner * Math.sin(rad)}
              x2={centerX + outer * Math.cos(rad)}
              y2={centerY + outer * Math.sin(rad)}
              stroke={on ? color : bgColor}
              strokeWidth={strokeWidth * 1.15}
              strokeLinecap="round"
              style={{ transition: "stroke 0.3s ease" }}
            />
          )
        })}
        {showValue && (
          <text
            x={centerX}
            y={centerY}
            textAnchor="middle"
            dominantBaseline="central"
            className="fill-foreground font-semibold"
            style={{ fontSize: radius * 0.34 }}
          >
            {formatValue(showPercentage ? animatedPercentage * max : value)}
            {units && (
              <tspan style={{ fontSize: radius * 0.18 }}> {units}</tspan>
            )}
          </text>
        )}
        {label && (
          <text
            x={centerX}
            y={centerY + radius * 0.3}
            textAnchor="middle"
            className="fill-muted-foreground"
            style={{ fontSize: radius * 0.14 }}
          >
            {label}
          </text>
        )}
      </>
    )
  }

  const renderContent = () => {
    switch (variant) {
      case "speedometer":
        return renderSpeedometer()
      case "segmented":
        return renderSegmented()
      case "radial":
        return renderRadial()
      case "minimal":
        return renderMinimal()
      case "gradient":
        return renderGradient()
      case "meter":
        return renderMeter()
      case "dashboard":
        return renderDashboard()
      case "ticks":
        return renderTicks()
      default:
        return renderModern()
    }
  }

  return (
    <ChartContainer
      config={config}
      className={cn("!aspect-auto flex-col", className)}
    >
      <div
        className={cn(
          "relative mx-auto w-full max-w-[280px]",
          // The ticks arc fills a landscape box; a square one strands half
          // the card in empty space below the meter.
          variant === "ticks" ? "aspect-[7/5]" : "aspect-square"
        )}
      >
        <svg
          viewBox={`0 0 ${width} ${height}`}
          className="h-full w-full overflow-visible"
        >
          <g transform={`translate(${margin.left}, ${margin.top})`}>
            {renderContent()}
          </g>
        </svg>
        {children && (
          <div className="pointer-events-none absolute inset-0 flex flex-col items-center justify-center">
            {children}
          </div>
        )}
      </div>
    </ChartContainer>
  )
}

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

import { useChartTheme } from "../chart-theme"
import { polarToCartesian } from "../chart-utils"

/**
 * Concentric progress rings — one arc per series, each against its own
 * track, with whatever you like in the middle.
 *
 * A donut divides a whole into parts; this compares several independent
 * ratios that do *not* sum to anything. Reaching for a donut there is the
 * usual reason dashboard "spend vs budget" cards read wrong.
 */

export interface RadialProgressSeries {
  name: string
  value: number
  /** Denominator for this ring only. Falls back to the chart's `max`. */
  max?: number
  color?: string
}

export interface RadialProgressChartProps {
  data: RadialProgressSeries[]
  /** Default denominator for rings that don't carry their own. */
  max?: number
  /** SVG viewBox edge, px. The chart scales to its container regardless. */
  size?: number
  /** Ring stroke width, px. */
  thickness?: number
  /** Space between rings, px. */
  gap?: number
  /** Degrees, 0 = twelve o'clock, growing clockwise. */
  startAngle?: number
  endAngle?: number
  rounded?: boolean
  track?: "dashed" | "solid" | "none"
  trackColor?: string
  /** Centre content — a headline number, a badge, anything. */
  children?: React.ReactNode
  showLegend?: boolean
  /** Side the legend sits on. `none` renders it under the rings. */
  legendPosition?: "right" | "bottom"
  valueFormatter?: (value: number) => string
  className?: string
  animate?: boolean
}

/** Clockwise arc from `a0` to `a1`. A full turn is degenerate as a single
 *  SVG arc, so it stops a hair short of closing. */
function arcPath(
  cx: number,
  cy: number,
  r: number,
  a0: number,
  a1: number
): string {
  const end = Math.abs(a1 - a0) >= 360 ? a0 + 359.99 : a1
  const s = polarToCartesian(cx, cy, r, a0)
  const e = polarToCartesian(cx, cy, r, end)
  const large = Math.abs(end - a0) > 180 ? 1 : 0
  const sweep = end >= a0 ? 1 : 0
  return `M ${s.x} ${s.y} A ${r} ${r} 0 ${large} ${sweep} ${e.x} ${e.y}`
}

export function RadialProgressChart({
  data,
  max = 100,
  size = 240,
  thickness = 12,
  gap = 8,
  startAngle = 0,
  endAngle = 360,
  rounded = true,
  track = "dashed",
  trackColor = "var(--border)",
  children,
  showLegend = false,
  legendPosition = "right",
  valueFormatter = (v) => `${v}`,
  className,
  animate,
}: RadialProgressChartProps) {
  const theme = useChartTheme()
  const isAnimated = animate ?? theme.animate

  // Grow the arcs on mount rather than snapping — `pathLength={1}` lets a
  // single dash offset drive it regardless of the ring's real length.
  const [drawn, setDrawn] = React.useState(!isAnimated)
  React.useEffect(() => {
    if (!isAnimated) return
    const id = requestAnimationFrame(() => setDrawn(true))
    return () => cancelAnimationFrame(id)
  }, [isAnimated])

  const cx = size / 2
  const cy = size / 2
  const outer = size / 2 - thickness / 2

  const rings = data.map((series, index) => {
    const radius = outer - index * (thickness + gap)
    const denominator = series.max ?? max
    const fraction =
      denominator > 0 ? Math.min(1, Math.max(0, series.value / denominator)) : 0
    return {
      ...series,
      radius,
      fraction,
      color: series.color ?? theme.palette[index % theme.palette.length],
    }
  })

  const legend = showLegend && (
    <ul
      className={cn(
        "space-y-3",
        legendPosition === "bottom" && "flex gap-6 space-y-0"
      )}
    >
      {rings.map((ring) => (
        <li key={ring.name} className="min-w-0">
          <span className="flex items-center gap-2">
            <span
              className="h-3.5 w-1 shrink-0 rounded-full"
              style={{ backgroundColor: ring.color }}
            />
            <span className="text-muted-foreground truncate text-sm">
              {ring.name}
            </span>
          </span>
          <span className="text-foreground block pl-3 text-lg font-semibold tabular-nums">
            {valueFormatter(ring.value)}
          </span>
        </li>
      ))}
    </ul>
  )

  return (
    <div
      className={cn(
        "flex w-full items-center gap-6",
        legendPosition === "bottom" && "flex-col",
        className
      )}
    >
      <div className="relative mx-auto w-full max-w-[280px] flex-1">
        <svg
          viewBox={`0 0 ${size} ${size}`}
          className="h-full w-full overflow-visible"
          role="img"
          aria-label={rings
            .map((r) => `${r.name} ${Math.round(r.fraction * 100)}%`)
            .join(", ")}
        >
          {rings.map((ring) => (
            <g key={ring.name}>
              {track !== "none" && (
                <path
                  d={arcPath(cx, cy, ring.radius, startAngle, endAngle)}
                  fill="none"
                  stroke={trackColor}
                  strokeWidth={track === "dashed" ? 1 : thickness}
                  strokeDasharray={track === "dashed" ? "2 6" : undefined}
                  strokeLinecap="round"
                  opacity={track === "dashed" ? 1 : 0.35}
                />
              )}
              <path
                d={arcPath(cx, cy, ring.radius, startAngle, endAngle)}
                fill="none"
                stroke={ring.color}
                strokeWidth={thickness}
                strokeLinecap={rounded ? "round" : "butt"}
                pathLength={1}
                strokeDasharray={1}
                strokeDashoffset={drawn ? 1 - ring.fraction : 1}
                style={
                  isAnimated
                    ? {
                        transition: `stroke-dashoffset ${theme.animationDuration}ms ease-out`,
                      }
                    : undefined
                }
              />
            </g>
          ))}
        </svg>

        {children && (
          <div className="pointer-events-none absolute inset-0 flex flex-col items-center justify-center text-center">
            {children}
          </div>
        )}
      </div>

      {legend}
    </div>
  )
}

"use client"

import * as React from "react"
import { scaleLinear } from "d3-scale"

import { cn } from "@/lib/utils"

export interface BulletChartData {
  label: string
  value: number
  target: number
  ranges: [number, number, number] // [poor, satisfactory, good]
  max?: number
}

export interface BulletChartProps {
  data: BulletChartData[]
  className?: string
  /** Visual style variant: standard (horizontal), compact (smaller), vertical */
  variant?: "standard" | "compact" | "vertical"
  /** Show labels */
  showLabels?: boolean
  /** Show values */
  showValues?: boolean
  /** Show legend for range meanings */
  showLegend?: boolean
  /** Labels for ranges [poor, satisfactory, good] */
  rangeLabels?: [string, string, string]
  /** Format value for display */
  valueFormatter?: (value: number) => string
  /** Primary color for value bar */
  color?: string
  /** Target marker color */
  targetColor?: string
}

const DEFAULT_COLOR = "var(--chart-1)"
const DEFAULT_TARGET_COLOR = "var(--foreground)"

// Parse hex color to RGB values
function hexToRgb(hex: string): { r: number; g: number; b: number } | null {
  const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex)
  return result
    ? {
        r: parseInt(result[1], 16),
        g: parseInt(result[2], 16),
        b: parseInt(result[3], 16),
      }
    : null
}

// Get rgba color with opacity
function getRgba(hex: string, opacity: number): string {
  const rgb = hexToRgb(hex)
  if (!rgb) return hex
  return `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, ${opacity})`
}

export function BulletChart({
  data,
  className,
  variant = "standard",
  showLabels = true,
  showValues = true,
  showLegend = false,
  rangeLabels = ["Poor", "Satisfactory", "Good"],
  valueFormatter = (value) => value.toLocaleString(),
  color = DEFAULT_COLOR,
  targetColor = DEFAULT_TARGET_COLOR,
}: BulletChartProps) {
  const containerRef = React.useRef<HTMLDivElement>(null)
  const [hoveredIndex, setHoveredIndex] = React.useState<number | null>(null)
  const [tooltipPos, setTooltipPos] = React.useState({ x: 0, y: 0 })

  const isVertical = variant === "vertical"
  const barSize = variant === "compact" ? 18 : 24
  const barSpacing = variant === "compact" ? 40 : isVertical ? 80 : 60
  const labelWidth = showLabels && !isVertical ? 100 : 0
  const valueWidth = showValues && !isVertical ? 60 : 0

  // Dimensions
  const width = isVertical ? Math.max(300, data.length * barSpacing + 80) : 500
  const height = isVertical ? 300 : data.length * barSpacing + 40

  const margin = isVertical
    ? {
        top: showValues ? 30 : 20,
        right: 20,
        bottom: showLabels ? 50 : 30,
        left: 40,
      }
    : { top: 20, right: valueWidth + 20, bottom: 20, left: labelWidth }

  const innerWidth = width - margin.left - margin.right
  const innerHeight = height - margin.top - margin.bottom

  // Range colors with proper rgba
  const rangeColors = React.useMemo(() => {
    return [getRgba(color, 0.15), getRgba(color, 0.3), getRgba(color, 0.5)]
  }, [color])

  const handleMouseMove = (e: React.MouseEvent, index: number) => {
    if (containerRef.current) {
      const rect = containerRef.current.getBoundingClientRect()
      setTooltipPos({
        x: e.clientX - rect.left,
        y: e.clientY - rect.top,
      })
    }
    setHoveredIndex(index)
  }

  if (!data || data.length === 0) {
    return (
      <div
        className={cn(
          "text-muted-foreground flex h-[200px] items-center justify-center",
          className
        )}
      >
        No data available
      </div>
    )
  }

  return (
    <div ref={containerRef} className={cn("relative w-full", className)}>
      {/* Legend */}
      {showLegend && (
        <div className="mb-4 flex flex-wrap items-center justify-center gap-x-6 gap-y-2">
          {rangeLabels.map((label, i) => (
            <div key={label} className="flex items-center gap-2">
              <div
                className="h-3 w-3 rounded"
                style={{ backgroundColor: rangeColors[2 - i] }}
              />
              <span className="text-muted-foreground text-sm">{label}</span>
            </div>
          ))}
          <div className="flex items-center gap-2">
            <div
              className="h-3 w-1 rounded"
              style={{ backgroundColor: targetColor }}
            />
            <span className="text-muted-foreground text-sm">Target</span>
          </div>
        </div>
      )}

      <svg
        viewBox={`0 0 ${width} ${height}`}
        className="h-auto w-full overflow-visible"
      >
        <g transform={`translate(${margin.left}, ${margin.top})`}>
          {data.map((d, index) => {
            const max = d.max ?? Math.max(d.ranges[2], d.target, d.value) * 1.1
            const scale = scaleLinear()
              .domain([0, max])
              .range(isVertical ? [innerHeight, 0] : [0, innerWidth])

            const isHovered = hoveredIndex === index

            if (isVertical) {
              // Vertical rendering
              const x = index * barSpacing
              return (
                <g
                  key={d.label}
                  transform={`translate(${x}, 0)`}
                  className={cn(
                    "cursor-pointer transition-opacity duration-200",
                    hoveredIndex !== null && !isHovered && "opacity-40"
                  )}
                  onMouseMove={(e) => handleMouseMove(e, index)}
                  onMouseLeave={() => setHoveredIndex(null)}
                >
                  {/* Range backgrounds - outer (good) */}
                  <rect
                    x={0}
                    y={scale(d.ranges[2])}
                    width={barSize}
                    height={innerHeight - scale(d.ranges[2])}
                    fill={rangeColors[0]}
                    rx={3}
                    className="dark:opacity-60"
                  />
                  {/* Range - middle (satisfactory) */}
                  <rect
                    x={barSize * 0.15}
                    y={scale(d.ranges[1])}
                    width={barSize * 0.7}
                    height={innerHeight - scale(d.ranges[1])}
                    fill={rangeColors[1]}
                    rx={2}
                    className="dark:opacity-70"
                  />
                  {/* Range - inner (poor) */}
                  <rect
                    x={barSize * 0.3}
                    y={scale(d.ranges[0])}
                    width={barSize * 0.4}
                    height={innerHeight - scale(d.ranges[0])}
                    fill={rangeColors[2]}
                    rx={2}
                    className="dark:opacity-80"
                  />

                  {/* Value bar */}
                  <rect
                    x={barSize * 0.35}
                    y={scale(d.value)}
                    width={barSize * 0.3}
                    height={innerHeight - scale(d.value)}
                    fill={color}
                    rx={2}
                    className={cn(
                      "transition-all duration-150",
                      isHovered && "brightness-110"
                    )}
                  />

                  {/* Target marker */}
                  <line
                    x1={barSize * 0.1}
                    x2={barSize * 0.9}
                    y1={scale(d.target)}
                    y2={scale(d.target)}
                    stroke={targetColor}
                    strokeWidth={3}
                    className="dark:stroke-zinc-300"
                  />

                  {/* Label */}
                  {showLabels && (
                    <text
                      x={barSize / 2}
                      y={innerHeight + 20}
                      textAnchor="middle"
                      className="fill-foreground text-xs font-medium"
                    >
                      {d.label}
                    </text>
                  )}

                  {/* Value */}
                  {showValues && (
                    <text
                      x={barSize / 2}
                      y={-10}
                      textAnchor="middle"
                      className="fill-muted-foreground text-xs"
                    >
                      {valueFormatter(d.value)}
                    </text>
                  )}
                </g>
              )
            }

            // Horizontal rendering
            const y = index * barSpacing
            return (
              <g
                key={d.label}
                transform={`translate(0, ${y})`}
                className={cn(
                  "cursor-pointer transition-opacity duration-200",
                  hoveredIndex !== null && !isHovered && "opacity-40"
                )}
                onMouseMove={(e) => handleMouseMove(e, index)}
                onMouseLeave={() => setHoveredIndex(null)}
              >
                {/* Range backgrounds - outer (good) */}
                <rect
                  x={0}
                  y={0}
                  width={scale(d.ranges[2])}
                  height={barSize}
                  fill={rangeColors[0]}
                  rx={3}
                  className="dark:opacity-60"
                />
                {/* Range - middle (satisfactory) */}
                <rect
                  x={0}
                  y={barSize * 0.15}
                  width={scale(d.ranges[1])}
                  height={barSize * 0.7}
                  fill={rangeColors[1]}
                  rx={2}
                  className="dark:opacity-70"
                />
                {/* Range - inner (poor) */}
                <rect
                  x={0}
                  y={barSize * 0.3}
                  width={scale(d.ranges[0])}
                  height={barSize * 0.4}
                  fill={rangeColors[2]}
                  rx={2}
                  className="dark:opacity-80"
                />

                {/* Value bar */}
                <rect
                  x={0}
                  y={barSize * 0.35}
                  width={scale(d.value)}
                  height={barSize * 0.3}
                  fill={color}
                  rx={2}
                  className={cn(
                    "transition-all duration-150",
                    isHovered && "brightness-110"
                  )}
                />

                {/* Target marker */}
                <line
                  x1={scale(d.target)}
                  x2={scale(d.target)}
                  y1={barSize * 0.1}
                  y2={barSize * 0.9}
                  stroke={targetColor}
                  strokeWidth={variant === "compact" ? 2 : 3}
                  className="dark:stroke-zinc-300"
                />

                {/* Label */}
                {showLabels && (
                  <text
                    x={-10}
                    y={barSize / 2}
                    textAnchor="end"
                    dominantBaseline="middle"
                    className="fill-foreground text-sm font-medium"
                  >
                    {d.label}
                  </text>
                )}

                {/* Value */}
                {showValues && (
                  <text
                    x={innerWidth + 10}
                    y={barSize / 2}
                    textAnchor="start"
                    dominantBaseline="middle"
                    className="fill-muted-foreground text-sm"
                  >
                    {valueFormatter(d.value)}
                  </text>
                )}
              </g>
            )
          })}
        </g>
      </svg>

      {/* Mouse-following Tooltip */}
      {hoveredIndex !== null && (
        <div
          className="bg-foreground text-background pointer-events-none absolute z-50 -translate-x-1/2 -translate-y-full rounded-lg px-3 py-2 text-xs shadow-lg"
          style={{ left: tooltipPos.x, top: tooltipPos.y - 10 }}
        >
          <div className="mb-1 font-semibold">{data[hoveredIndex].label}</div>
          <div className="space-y-0.5 opacity-90">
            <div>Value: {valueFormatter(data[hoveredIndex].value)}</div>
            <div>Target: {valueFormatter(data[hoveredIndex].target)}</div>
            <div>
              {data[hoveredIndex].value >= data[hoveredIndex].target
                ? "Above target"
                : "Below target"}
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

"use client"

import * as React from "react"
import { hierarchy, partition } from "d3-hierarchy"

import { cn } from "@/lib/utils"

export interface IcicleNode {
  name: string
  value?: number
  children?: IcicleNode[]
  color?: string
}

export interface IcicleChartProps {
  data: IcicleNode
  className?: string
  orientation?: "horizontal" | "vertical"
  showLabels?: boolean
  labelMinSize?: number
  padding?: number
  colorScheme?: string[]
}

export function IcicleChart({
  data,
  className,
  orientation = "vertical",
  showLabels = true,
  labelMinSize = 40,
  padding = 1,
  colorScheme = [
    "var(--chart-5)",
    "var(--chart-4)",
    "var(--chart-3)",
    "var(--chart-2)",
    "var(--chart-1)",
    "var(--chart-1)",
  ],
}: IcicleChartProps) {
  const [hoveredNode, setHoveredNode] = React.useState<IcicleNode | null>(null)

  const isVertical = orientation === "vertical"
  const width = 500
  const height = 400

  // Create hierarchy and partition layout
  const root = React.useMemo(() => {
    const h = hierarchy(data)
      .sum((d) => d.value ?? 0)
      .sort((a, b) => (b.value ?? 0) - (a.value ?? 0))

    const partitionLayout = partition<IcicleNode>()
      .size(isVertical ? [width, height] : [height, width])
      .padding(padding)

    return partitionLayout(h)
  }, [data, width, height, padding, isVertical])

  // Get all nodes except root
  const nodes = root.descendants().filter((d) => d.depth > 0)

  // Calculate total value for percentages
  const totalValue = root.value ?? 1

  // Get color based on depth and index
  const getColor = (node: (typeof nodes)[number]): string => {
    if (node.data.color) return node.data.color
    const depthIndex = node.depth - 1
    return colorScheme[depthIndex % colorScheme.length]
  }

  return (
    <div className={cn("w-full", className)}>
      <svg
        viewBox={`0 0 ${width} ${height}`}
        className="h-auto w-full overflow-visible"
      >
        {nodes.map((node, index) => {
          const isHovered = hoveredNode === node.data

          // For vertical: x0,x1 are horizontal, y0,y1 are depth
          // For horizontal: swap them
          const x = isVertical ? node.x0 : node.y0
          const y = isVertical ? node.y0 : node.x0
          const w = isVertical ? node.x1 - node.x0 : node.y1 - node.y0
          const h = isVertical ? node.y1 - node.y0 : node.x1 - node.x0

          const color = getColor(node)
          const showLabel = showLabels && w >= labelMinSize && h >= 20

          return (
            <g key={`${node.data.name}-${index}`}>
              <rect
                x={x}
                y={y}
                width={w}
                height={h}
                fill={color}
                stroke="#fff"
                strokeWidth={1}
                rx={2}
                className={cn(
                  "cursor-pointer transition-all duration-200",
                  hoveredNode !== null && !isHovered && "opacity-60",
                  isHovered && "brightness-110"
                )}
                onMouseEnter={() => setHoveredNode(node.data)}
                onMouseLeave={() => setHoveredNode(null)}
              />

              {showLabel && (
                <text
                  x={x + w / 2}
                  y={y + h / 2}
                  textAnchor="middle"
                  dominantBaseline="middle"
                  className="pointer-events-none fill-white text-[11px] font-medium"
                  style={{ textShadow: "0 1px 2px rgba(0,0,0,0.3)" }}
                >
                  {node.data.name.length > w / 8
                    ? `${node.data.name.slice(0, Math.floor(w / 8))}...`
                    : node.data.name}
                </text>
              )}
            </g>
          )
        })}
      </svg>

      {/* Tooltip */}
      {hoveredNode && (
        <div className="mt-3 text-center">
          <div className="border-border/50 bg-background mx-auto inline-block rounded-lg border px-3 py-2 text-sm shadow-lg">
            <div className="font-medium">{hoveredNode.name}</div>
            <div className="text-muted-foreground">
              Value: {(hoveredNode.value ?? 0).toLocaleString()}
            </div>
            <div className="text-muted-foreground">
              {(((hoveredNode.value ?? 0) / totalValue) * 100).toFixed(1)}% of
              total
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

"use client"

import * as React from "react"
import { bin, extent, max } from "d3-array"
import { scaleLinear } from "d3-scale"

import { cn } from "@/lib/utils"

import {
  ChartZoomResetButton,
  ChartZoomSelectionRect,
  useChartZoom,
} from "../chart-zoom"

export interface DotPlotDataPoint {
  value: number
  color?: string
}

export interface DotPlotChartProps {
  data: DotPlotDataPoint[] | number[]
  className?: string
  dotSize?: number
  dotSpacing?: number
  showGrid?: boolean
  showXAxis?: boolean
  xAxisLabel?: string
  binCount?: number
  color?: string
  valueFormatter?: (value: number) => string
}

export function DotPlotChart({
  data,
  className,
  dotSize = 8,
  dotSpacing = 2,
  showGrid = true,
  showXAxis = true,
  xAxisLabel,
  binCount = 20,
  color = "var(--chart-1)",
  valueFormatter = (value) => value.toLocaleString(),
}: DotPlotChartProps) {
  const [hoveredBin, setHoveredBin] = React.useState<number | null>(null)
  const svgRef = React.useRef<SVGSVGElement>(null)
  // Drag-to-zoom range over the (continuous) value domain — unlike the
  // band-scale charts, there's no fixed category count here, so the zoom
  // window is a pair of raw values rather than data indices.
  const [zoomDomain, setZoomDomain] = React.useState<[number, number] | null>(
    null
  )
  const isZoomed = zoomDomain !== null

  // Reset any active zoom if the underlying data set changes.
  React.useEffect(() => {
    setZoomDomain(null)
  }, [data])

  // Normalize data to array of values
  const values = React.useMemo(() => {
    return data.map((d) => (typeof d === "number" ? d : d.value))
  }, [data])

  // Get colors if provided
  const colors = React.useMemo(() => {
    return data.map((d) => (typeof d === "number" ? color : (d.color ?? color)))
  }, [data, color])

  // Values/colors narrowed to the active zoom window, if any — filtered
  // (not rescaled) so the bins below re-derive purely from what's visible.
  const plotValues = React.useMemo(() => {
    if (!zoomDomain) return values
    const [lo, hi] = zoomDomain
    return values.filter((v) => v >= lo && v <= hi)
  }, [values, zoomDomain])

  const plotColors = React.useMemo(() => {
    if (!zoomDomain) return colors
    const [lo, hi] = zoomDomain
    return values.reduce<string[]>((acc, v, i) => {
      if (v >= lo && v <= hi) acc.push(colors[i])
      return acc
    }, [])
  }, [values, colors, zoomDomain])

  const width = 500
  const margin = { top: 20, right: 20, bottom: xAxisLabel ? 60 : 40, left: 20 }

  const innerWidth = width - margin.left - margin.right

  // Create bins
  const binnedData = React.useMemo(() => {
    const [minVal, maxVal] = extent(plotValues) as [number, number]
    const binGenerator = bin().domain([minVal, maxVal]).thresholds(binCount)

    const bins = binGenerator(plotValues)

    // For each bin, track individual dots with their colors
    return bins.map((b) => {
      const dots: { value: number; color: string }[] = []
      b.forEach((val) => {
        // Find the actual index considering duplicates
        let foundCount = 0
        for (let i = 0; i < plotValues.length; i++) {
          if (plotValues[i] === val) {
            if (foundCount === dots.filter((d) => d.value === val).length) {
              dots.push({ value: val, color: plotColors[i] })
              break
            }
            foundCount++
          }
        }
      })
      return {
        x0: b.x0 ?? minVal,
        x1: b.x1 ?? maxVal,
        count: b.length,
        dots,
      }
    })
  }, [plotValues, plotColors, binCount])

  // Calculate max stack height
  const maxCount = max(binnedData, (d) => d.count) ?? 0

  // Dynamic height based on max stack
  const dotTotalSize = dotSize + dotSpacing
  const innerHeight = Math.max(maxCount * dotTotalSize + 20, 100)
  const height = innerHeight + margin.top + margin.bottom

  // Scales
  const xScale = React.useMemo(() => {
    const [minVal, maxVal] = extent(plotValues) as [number, number]
    const padding = (maxVal - minVal) * 0.05
    return scaleLinear()
      .domain([minVal - padding, maxVal + padding])
      .range([0, innerWidth])
      .nice()
  }, [plotValues, innerWidth])

  const xTicks = xScale.ticks(7)

  // Drag-to-zoom: converts the pixel drag range into a value-domain range
  // (continuous scale, so we invert directly rather than using
  // getBandScaleIndexRange) and narrows the view to it. Re-zooming while
  // already zoomed narrows further, since xScale is derived from the
  // current (possibly already-zoomed) plotValues.
  const zoom = useChartZoom({
    svgRef,
    marginLeft: margin.left,
    innerWidth,
    onZoom: ({ x0, x1 }) => {
      const lo = xScale.invert(x0)
      const hi = xScale.invert(x1)
      const hasPointsInRange = values.some((v) => v >= lo && v <= hi)
      if (hasPointsInRange) setZoomDomain([lo, hi])
    },
    onReset: () => setZoomDomain(null),
  })

  // Calculate tooltip position as percentage
  const getTooltipPosition = (binIndex: number) => {
    const bin = binnedData[binIndex]
    const binCenter = (bin.x0 + bin.x1) / 2
    const xPos = margin.left + xScale(binCenter)
    const yPos = margin.top + innerHeight - bin.count * dotTotalSize - 8
    return {
      left: `${(xPos / width) * 100}%`,
      top: `${(yPos / height) * 100}%`,
    }
  }

  return (
    <div className={cn("relative w-full", className)}>
      <svg
        ref={svgRef}
        viewBox={`0 0 ${width} ${height}`}
        className="h-auto w-full overflow-visible select-none"
        onMouseDown={zoom.handlers.onMouseDown}
        onMouseMove={zoom.handlers.onMouseMove}
        onMouseUp={zoom.handlers.onMouseUp}
        onMouseLeave={zoom.handlers.onMouseLeave}
        onDoubleClick={zoom.handlers.onDoubleClick}
      >
        <g transform={`translate(${margin.left}, ${margin.top})`}>
          {/* Drag-to-zoom selection rectangle */}
          <ChartZoomSelectionRect range={zoom.dragRange} height={innerHeight} />

          {/* Grid lines */}
          {showGrid &&
            xTicks.map((tick) => (
              <line
                key={tick}
                x1={xScale(tick)}
                x2={xScale(tick)}
                y1={0}
                y2={innerHeight}
                stroke="hsl(var(--border))"
                strokeDasharray="3 3"
                strokeOpacity={0.3}
              />
            ))}

          {/* Baseline */}
          <line
            x1={0}
            x2={innerWidth}
            y1={innerHeight}
            y2={innerHeight}
            stroke="hsl(var(--border))"
          />

          {/* Dots stacked from bottom */}
          {binnedData.map((binData, binIndex) => {
            const binCenter = (binData.x0 + binData.x1) / 2
            const cx = xScale(binCenter)
            const isHovered = hoveredBin === binIndex

            return (
              <g key={binIndex}>
                {binData.dots.map((dot, dotIndex) => {
                  const cy = innerHeight - (dotIndex + 0.5) * dotTotalSize

                  return (
                    <circle
                      key={dotIndex}
                      cx={cx}
                      cy={cy}
                      r={dotSize / 2}
                      fill={dot.color}
                      className={cn(
                        "cursor-pointer transition-opacity duration-200",
                        hoveredBin !== null && !isHovered && "opacity-40"
                      )}
                      onMouseEnter={() => setHoveredBin(binIndex)}
                      onMouseLeave={() => setHoveredBin(null)}
                    />
                  )
                })}
              </g>
            )
          })}

          {/* X-axis labels */}
          {showXAxis &&
            xTicks.map((tick) => (
              <text
                key={`tick-${tick}`}
                x={xScale(tick)}
                y={innerHeight + 20}
                textAnchor="middle"
                className="fill-muted-foreground text-xs"
              >
                {valueFormatter(tick)}
              </text>
            ))}

          {/* X-axis label */}
          {xAxisLabel && (
            <text
              x={innerWidth / 2}
              y={innerHeight + 45}
              textAnchor="middle"
              className="fill-foreground text-sm font-medium"
            >
              {xAxisLabel}
            </text>
          )}
        </g>
      </svg>

      {/* HTML Tooltip */}
      {hoveredBin !== null && binnedData[hoveredBin] && (
        <div
          className="pointer-events-none absolute z-50 -translate-x-1/2 -translate-y-full"
          style={getTooltipPosition(hoveredBin)}
        >
          <div className="bg-foreground text-background rounded-md px-2 py-1 text-xs font-medium shadow-lg">
            {Math.round(binnedData[hoveredBin].x0)}-
            {Math.round(binnedData[hoveredBin].x1)}:{" "}
            {binnedData[hoveredBin].count}
          </div>
        </div>
      )}

      <ChartZoomResetButton
        visible={isZoomed}
        onReset={() => setZoomDomain(null)}
      />
    </div>
  )
}

"use client"

import * as React from "react"
import { scaleBand, scaleLinear } from "d3-scale"

import { cn } from "@/lib/utils"

export interface LollipopDataPoint {
  category: string
  value: number
  color?: string
  group?: string
}

export interface LollipopChartProps {
  data: LollipopDataPoint[]
  className?: string
  orientation?: "horizontal" | "vertical"
  dotSize?: number
  showGrid?: boolean
  showLegend?: boolean
  valueFormatter?: (value: number) => string
  color?: string
  stemColor?: string
  yAxisLabel?: string
}

export function LollipopChart({
  data,
  className,
  orientation = "vertical",
  dotSize = 10,
  showGrid = true,
  showLegend = true,
  valueFormatter = (value) => value.toFixed(1),
  color = "var(--chart-1)",
  stemColor = "var(--muted)",
  yAxisLabel,
}: LollipopChartProps) {
  const [hoveredIndex, setHoveredIndex] = React.useState<number | null>(null)
  // Legend click-to-isolate: clicking a group in the legend shows only
  // that group's lollipops (fully hidden, not just dimmed, for the
  // others), clicking the same group again restores all. Points without
  // a `group` are unaffected by isolation. Drag-to-zoom is intentionally
  // skipped for this chart — see note near the categoryScale below.
  const [activeGroup, setActiveGroup] = React.useState<string | null>(null)
  const isGroupVisible = React.useCallback(
    (group?: string) => !group || activeGroup === null || activeGroup === group,
    [activeGroup]
  )

  const isHorizontal = orientation === "horizontal"

  // Calculate dimensions - ensure enough space for each item
  const minItemSpace = dotSize * 3 // Minimum space per item (3x dot diameter)
  const calculatedWidth = Math.max(600, data.length * minItemSpace + 100)

  const width = isHorizontal ? 500 : calculatedWidth
  const height = isHorizontal ? Math.max(400, data.length * 30) : 320

  const margin = isHorizontal
    ? { top: 20, right: 30, bottom: 30, left: 130 }
    : { top: 20, right: 30, bottom: 40, left: 45 }

  const innerWidth = width - margin.left - margin.right
  const innerHeight = height - margin.top - margin.bottom

  // Get unique groups for legend
  const groups = React.useMemo(() => {
    const groupMap = new Map<string, string>()
    data.forEach((d) => {
      if (d.group && d.color && !groupMap.has(d.group)) {
        groupMap.set(d.group, d.color)
      }
    })
    return Array.from(groupMap.entries())
  }, [data])

  // Note on drag-to-zoom: the band/categorical scale lives on the Y-axis
  // in "horizontal" orientation and on the X-axis in "vertical" (default)
  // orientation — but the shared `useChartZoom` primitive only tracks
  // horizontal (X) drags (it's hard-wired to `marginLeft`/`innerWidth`
  // pixel math, with no vertical counterpart), and this component can't
  // modify that primitive. Wiring zoom for one orientation only would
  // make the same chart draggable in one mode and inert in the other —
  // an inconsistent, surprising fit. On top of that, both the width
  // (vertical) and height (horizontal) here already auto-grow with
  // `data.length` and scroll via `overflow-x-auto` rather than cramming
  // items into a fixed plot area, so zoom wouldn't relieve any crowding
  // the way it does for fixed-size charts like the candlestick. Zoom is
  // intentionally skipped; legend click-to-isolate (below) is applied
  // instead since this chart already renders a real per-group legend.
  const categoryScale = React.useMemo(() => {
    return scaleBand()
      .domain(data.map((d) => d.category))
      .range(isHorizontal ? [0, innerHeight] : [0, innerWidth])
      .padding(0.4)
  }, [data, innerWidth, innerHeight, isHorizontal])

  const valueScale = React.useMemo(() => {
    const values = data.map((d) => d.value)
    const minVal = Math.min(...values, 0)
    const maxVal = Math.max(...values, 0)
    const range = maxVal - minVal || 1
    const padding = range * 0.2

    return scaleLinear()
      .domain([minVal - padding, maxVal + padding])
      .range(isHorizontal ? [0, innerWidth] : [innerHeight, 0])
      .nice()
  }, [data, innerWidth, innerHeight, isHorizontal])

  const ticks = valueScale.ticks(5)
  const zeroPos = valueScale(0)

  return (
    <div className={cn("relative w-full", className)}>
      {/* Legend — click a group to isolate it, click again to restore all */}
      {showLegend && groups.length > 0 && (
        <div className="mb-4 flex items-center justify-center gap-6">
          <span className="text-muted-foreground text-sm">cyl</span>
          {groups.map(([group, groupColor]) => (
            <button
              key={group}
              type="button"
              aria-pressed={!isGroupVisible(group)}
              onClick={() =>
                setActiveGroup((prev) => (prev === group ? null : group))
              }
              className={cn(
                "flex cursor-pointer items-center gap-2 transition-opacity hover:opacity-80",
                !isGroupVisible(group) && "opacity-40"
              )}
            >
              <div
                className="h-3.5 w-3.5 rounded-full"
                style={{ backgroundColor: groupColor }}
              />
              <span className="text-foreground text-sm">
                {group.replace(" cyl", "")}
              </span>
            </button>
          ))}
        </div>
      )}

      <div className="overflow-x-auto">
        <svg width={width} height={height} className="overflow-visible">
          <g transform={`translate(${margin.left}, ${margin.top})`}>
            {/* Grid lines */}
            {showGrid &&
              ticks.map((tick) => (
                <line
                  key={tick}
                  x1={isHorizontal ? valueScale(tick) : 0}
                  x2={isHorizontal ? valueScale(tick) : innerWidth}
                  y1={isHorizontal ? 0 : valueScale(tick)}
                  y2={isHorizontal ? innerHeight : valueScale(tick)}
                  stroke="#e5e7eb"
                  strokeWidth={1}
                />
              ))}

            {/* Lollipops — fully skipped (not just dimmed) when a legend
                group is isolated and this point belongs to another group */}
            {data.map((d, index) => {
              if (!isGroupVisible(d.group)) return null
              const isHovered = hoveredIndex === index
              const dotColor = d.color ?? color
              const categoryPos =
                (categoryScale(d.category) ?? 0) + categoryScale.bandwidth() / 2

              const x1 = isHorizontal ? zeroPos : categoryPos
              const y1 = isHorizontal ? categoryPos : zeroPos
              const x2 = isHorizontal ? valueScale(d.value) : categoryPos
              const y2 = isHorizontal ? categoryPos : valueScale(d.value)

              return (
                <g
                  key={`${d.category}-${index}`}
                  className="cursor-pointer"
                  onMouseEnter={() => setHoveredIndex(index)}
                  onMouseLeave={() => setHoveredIndex(null)}
                  style={{
                    opacity: hoveredIndex !== null && !isHovered ? 0.5 : 1,
                    transition: "opacity 150ms",
                  }}
                >
                  {/* Stem */}
                  <line
                    x1={x1}
                    y1={y1}
                    x2={x2}
                    y2={y2}
                    stroke={stemColor}
                    strokeWidth={2}
                  />

                  {/* Dot */}
                  <circle
                    cx={x2}
                    cy={y2}
                    r={isHovered ? dotSize + 2 : dotSize}
                    fill={dotColor}
                    style={{ transition: "r 150ms" }}
                  />
                </g>
              )
            })}

            {/* Category labels */}
            {data.map((d, index) => {
              if (!isGroupVisible(d.group)) return null
              const pos =
                (categoryScale(d.category) ?? 0) + categoryScale.bandwidth() / 2

              if (isHorizontal) {
                return (
                  <text
                    key={`label-${index}`}
                    x={-10}
                    y={pos}
                    textAnchor="end"
                    dominantBaseline="middle"
                    fontSize={11}
                    className="fill-foreground"
                  >
                    {d.category}
                  </text>
                )
              }

              return (
                <text
                  key={`label-${index}`}
                  x={pos}
                  y={innerHeight + 18}
                  textAnchor="middle"
                  fontSize={10}
                  className="fill-foreground"
                >
                  {d.category}
                </text>
              )
            })}

            {/* Value axis labels */}
            {ticks.map((tick) => (
              <text
                key={`tick-${tick}`}
                x={isHorizontal ? valueScale(tick) : -10}
                y={isHorizontal ? innerHeight + 16 : valueScale(tick)}
                textAnchor={isHorizontal ? "middle" : "end"}
                dominantBaseline={isHorizontal ? "auto" : "middle"}
                fontSize={12}
                className="fill-muted-foreground"
              >
                {tick}
              </text>
            ))}

            {/* Y-axis label */}
            {yAxisLabel && !isHorizontal && (
              <text
                x={0}
                y={0}
                textAnchor="middle"
                fontSize={12}
                className="fill-muted-foreground"
                transform={`translate(${-margin.left + 14}, ${innerHeight / 2}) rotate(-90)`}
              >
                {yAxisLabel}
              </text>
            )}
          </g>
        </svg>
      </div>

      {/* Tooltip */}
      {hoveredIndex !== null && (
        <div
          className="bg-foreground text-background pointer-events-none fixed z-[100] rounded-md px-2.5 py-1.5 text-xs font-medium shadow-lg"
          style={{
            left: "50%",
            top: "50%",
            transform: "translate(-50%, -50%)",
          }}
        >
          <span className="font-semibold">{data[hoveredIndex].category}</span>
          <span className="ml-1.5">
            {valueFormatter(data[hoveredIndex].value)}
          </span>
        </div>
      )}
    </div>
  )
}

"use client"

import * as React from "react"
import { scaleBand, scaleLinear } from "d3-scale"

import { cn } from "@/lib/utils"

import { ChartLegendLayout, useSeriesHighlight } from "../chart-legend"

export interface DumbbellDataPoint {
  category: string
  start: number
  end: number
}

export interface DumbbellChartProps {
  data: DumbbellDataPoint[]
  className?: string
  /** Show the legend */
  showLegend?: boolean
  /** Which side of the plot to place the legend on */
  legendPosition?: "top" | "bottom" | "left" | "right"
  dotSize?: number
  showGrid?: boolean
  valueFormatter?: (value: number) => string
  startColor?: string
  endColor?: string
  connectorColor?: string
  startLabel?: string
  endLabel?: string
}

export function DumbbellChart({
  data,
  className,
  showLegend = true,
  legendPosition = "right",
  dotSize = 8,
  showGrid = true,
  valueFormatter = (value) => value.toLocaleString(),
  startColor = "var(--chart-3)",
  endColor = "var(--chart-1)",
  connectorColor = "var(--muted)",
  startLabel = "Start",
  endLabel = "End",
}: DumbbellChartProps) {
  const [hoveredIndex, setHoveredIndex] = React.useState<number | null>(null)
  // Legend highlight: clicking "Start" or "End" emphasizes that side of
  // every dumbbell and fades the other (Plotly-style), clicking the same
  // one again restores both; hovering a legend item previews it. There's no
  // categorical/band axis here worth a drag-to-zoom window — the two-series
  // legend is this chart's interactive feature.
  const highlight = useSeriesHighlight()

  const width = 500
  const height = data.length * 45 + 70
  const margin = { top: 40, right: 40, bottom: 35, left: 90 }

  const innerWidth = width - margin.left - margin.right
  const innerHeight = height - margin.top - margin.bottom

  const categoryScale = React.useMemo(() => {
    return scaleBand()
      .domain(data.map((d) => d.category))
      .range([0, innerHeight])
      .padding(0.4)
  }, [data, innerHeight])

  const valueScale = React.useMemo(() => {
    const allValues = data.flatMap((d) => [d.start, d.end])
    const minVal = Math.min(...allValues)
    const maxVal = Math.max(...allValues)
    const range = maxVal - minVal || 1
    const padding = range * 0.15
    return scaleLinear()
      .domain([Math.max(0, minVal - padding), maxVal + padding])
      .range([0, innerWidth])
      .nice()
  }, [data, innerWidth])

  const ticks = valueScale.ticks(5)

  // Legend — click a side to highlight it (the other fades), click again to
  // restore both; hover previews. Positioned on `legendPosition` via layout.
  const isVerticalLegend =
    legendPosition === "left" || legendPosition === "right"
  const legend = (
    <div
      className={cn(
        "flex gap-6",
        isVerticalLegend
          ? "flex-col items-start"
          : "flex-wrap items-center justify-center",
        legendPosition === "top" && "pb-3",
        legendPosition === "bottom" && "pt-3",
        legendPosition === "left" && "pr-3",
        legendPosition === "right" && "pl-3"
      )}
    >
      <button
        type="button"
        aria-pressed={!highlight.isActive("start")}
        onClick={() => highlight.toggle("start")}
        onMouseEnter={() => highlight.setHovered("start")}
        onMouseLeave={() => highlight.setHovered(null)}
        className={cn(
          "flex cursor-pointer items-center gap-2 transition-opacity hover:opacity-80",
          !highlight.isActive("start") && "opacity-40"
        )}
      >
        <div
          className="h-3 w-3 rounded-full"
          style={{ backgroundColor: startColor }}
        />
        <span className="text-muted-foreground text-sm">{startLabel}</span>
      </button>
      <button
        type="button"
        aria-pressed={!highlight.isActive("end")}
        onClick={() => highlight.toggle("end")}
        onMouseEnter={() => highlight.setHovered("end")}
        onMouseLeave={() => highlight.setHovered(null)}
        className={cn(
          "flex cursor-pointer items-center gap-2 transition-opacity hover:opacity-80",
          !highlight.isActive("end") && "opacity-40"
        )}
      >
        <div
          className="h-3 w-3 rounded-full"
          style={{ backgroundColor: endColor }}
        />
        <span className="text-muted-foreground text-sm">{endLabel}</span>
      </button>
    </div>
  )

  return (
    <div className={cn("relative w-full", className)}>
      {/* Plot + legend layout — legend on `legendPosition` side; click a side
          to highlight it, click again to restore both */}
      <ChartLegendLayout
        position={legendPosition}
        show={showLegend}
        legend={legend}
      >
        <svg
          viewBox={`0 0 ${width} ${height}`}
          className="h-auto w-full overflow-visible"
        >
          <g transform={`translate(${margin.left}, ${margin.top})`}>
            {/* Grid lines */}
            {showGrid &&
              ticks.map((tick) => (
                <line
                  key={tick}
                  x1={valueScale(tick)}
                  x2={valueScale(tick)}
                  y1={0}
                  y2={innerHeight}
                  stroke="#e5e7eb"
                  strokeWidth={1}
                />
              ))}

            {/* Baseline */}
            <line
              x1={0}
              x2={innerWidth}
              y1={innerHeight}
              y2={innerHeight}
              stroke="#e5e7eb"
              strokeWidth={1}
            />

            {/* Dumbbells */}
            {data.map((d, index) => {
              const isHovered = hoveredIndex === index
              const categoryPos =
                (categoryScale(d.category) ?? 0) + categoryScale.bandwidth() / 2

              const x1 = valueScale(d.start)
              const x2 = valueScale(d.end)
              const y = categoryPos

              return (
                <g
                  key={d.category}
                  className="cursor-pointer"
                  onMouseEnter={() => setHoveredIndex(index)}
                  onMouseLeave={() => setHoveredIndex(null)}
                  style={{
                    opacity: hoveredIndex !== null && !isHovered ? 0.4 : 1,
                    transition: "opacity 150ms",
                  }}
                >
                  {/* Connector line — links the two endpoints; stays drawn but
                    dims while a single side is highlighted via the legend */}
                  <line
                    x1={x1}
                    y1={y}
                    x2={x2}
                    y2={y}
                    stroke={connectorColor}
                    strokeWidth={3}
                    strokeLinecap="round"
                    style={{
                      opacity: highlight.focused === null ? 1 : 0.3,
                      transition: "opacity 150ms",
                    }}
                  />

                  {/* Start dot — faded (never removed) when the other side is
                    highlighted */}
                  <circle
                    cx={x1}
                    cy={y}
                    r={isHovered ? dotSize + 2 : dotSize}
                    fill={startColor}
                    style={{
                      opacity: highlight.isDimmed("start") ? 0.3 : 1,
                      transition: "r 150ms, opacity 150ms",
                    }}
                  />

                  {/* End dot — faded (never removed) when the other side is
                    highlighted */}
                  <circle
                    cx={x2}
                    cy={y}
                    r={isHovered ? dotSize + 2 : dotSize}
                    fill={endColor}
                    style={{
                      opacity: highlight.isDimmed("end") ? 0.3 : 1,
                      transition: "r 150ms, opacity 150ms",
                    }}
                  />
                </g>
              )
            })}

            {/* Category labels */}
            {data.map((d) => {
              const pos =
                (categoryScale(d.category) ?? 0) + categoryScale.bandwidth() / 2
              return (
                <text
                  key={`label-${d.category}`}
                  x={-12}
                  y={pos}
                  textAnchor="end"
                  dominantBaseline="middle"
                  fontSize={12}
                  className="fill-foreground"
                >
                  {d.category}
                </text>
              )
            })}

            {/* Value axis labels */}
            {ticks.map((tick) => (
              <text
                key={`tick-${tick}`}
                x={valueScale(tick)}
                y={innerHeight + 20}
                textAnchor="middle"
                fontSize={11}
                className="fill-muted-foreground"
              >
                {valueFormatter(tick)}
              </text>
            ))}
          </g>
        </svg>

        {/* Tooltip — shows both sides; the highlighted side stays bright while
          the other dims (nothing is hidden) */}
        {hoveredIndex !== null && (
          <div className="bg-foreground text-background pointer-events-none absolute top-12 left-1/2 z-50 -translate-x-1/2 rounded-md px-3 py-1.5 text-xs font-medium shadow-lg">
            <span className="font-semibold">{data[hoveredIndex].category}</span>
            <span className="mx-2">·</span>
            <span style={{ opacity: highlight.isDimmed("start") ? 0.5 : 1 }}>
              {startLabel}: {valueFormatter(data[hoveredIndex].start)}
            </span>
            <span className="mx-1">→</span>
            <span style={{ opacity: highlight.isDimmed("end") ? 0.5 : 1 }}>
              {endLabel}: {valueFormatter(data[hoveredIndex].end)}
            </span>
            <span className="ml-2 opacity-70">
              ({data[hoveredIndex].end >= data[hoveredIndex].start ? "+" : ""}
              {valueFormatter(
                data[hoveredIndex].end - data[hoveredIndex].start
              )}
              )
            </span>
          </div>
        )}
      </ChartLegendLayout>
    </div>
  )
}

"use client"

import * as React from "react"
import { scaleLinear, scalePoint } from "d3-scale"
import { curveLinear, curveMonotoneX, line } from "d3-shape"

import { cn } from "@/lib/utils"

export interface SlopeDataPoint {
  category: string
  start: number
  end: number
  color?: string
}

export interface MultiPeriodSlopeDataPoint {
  category: string
  values: number[]
  color?: string
}

export interface SlopeChartProps {
  data: SlopeDataPoint[] | MultiPeriodSlopeDataPoint[]
  className?: string
  variant?: "lines" | "bumps" | "parallel"
  labels?: string[]
  showGrid?: boolean
  showValues?: boolean
  showRankChange?: boolean
  increaseColor?: string
  decreaseColor?: string
  neutralColor?: string
  valueFormatter?: (value: number) => string
}

// Type guard for multi-period data
function isMultiPeriod(
  data: SlopeDataPoint[] | MultiPeriodSlopeDataPoint[]
): data is MultiPeriodSlopeDataPoint[] {
  return data.length > 0 && "values" in data[0]
}

// Convert simple data to multi-period format
function normalizeData(
  data: SlopeDataPoint[] | MultiPeriodSlopeDataPoint[]
): MultiPeriodSlopeDataPoint[] {
  if (isMultiPeriod(data)) {
    return data
  }
  return data.map((d) => ({
    category: d.category,
    values: [d.start, d.end],
    color: d.color,
  }))
}

export function SlopeChart({
  data,
  className,
  variant = "lines",
  labels,
  showGrid = true,
  showValues = true,
  showRankChange = false,
  increaseColor = "var(--chart-2)",
  decreaseColor = "var(--chart-4)",
  neutralColor = "var(--chart-3)",
  valueFormatter = (value) => value.toLocaleString(),
}: SlopeChartProps) {
  const [hoveredIndex, setHoveredIndex] = React.useState<number | null>(null)

  // Normalize data to multi-period format
  const normalizedData = React.useMemo(() => normalizeData(data), [data])
  const periodCount = normalizedData[0]?.values.length ?? 2

  // Default labels
  const periodLabels =
    labels ??
    (periodCount === 2
      ? ["Start", "End"]
      : Array.from({ length: periodCount }, (_, i) => `Period ${i + 1}`))

  const width = 500
  const height = Math.max(300, normalizedData.length * 40 + 80)
  const margin = { top: 50, right: 90, bottom: 30, left: 90 }
  const innerWidth = width - margin.left - margin.right
  const innerHeight = height - margin.top - margin.bottom

  // X scale for periods
  const xScale = React.useMemo(() => {
    return scalePoint<number>()
      .domain(Array.from({ length: periodCount }, (_, i) => i))
      .range([0, innerWidth])
  }, [periodCount, innerWidth])

  // Y scale based on all values
  const yScale = React.useMemo(() => {
    const allValues = normalizedData.flatMap((d) => d.values)
    const minVal = Math.min(...allValues)
    const maxVal = Math.max(...allValues)
    const padding = (maxVal - minVal) * 0.15 || 10
    return scaleLinear()
      .domain([Math.min(0, minVal - padding), maxVal + padding])
      .range([innerHeight, 0])
      .nice()
  }, [normalizedData, innerHeight])

  const yTicks = yScale.ticks(5)

  // Get line color based on direction
  const getLineColor = (d: MultiPeriodSlopeDataPoint) => {
    if (d.color) return d.color
    const first = d.values[0]
    const last = d.values[d.values.length - 1]
    if (last > first) return increaseColor
    if (last < first) return decreaseColor
    return neutralColor
  }

  // Calculate overall change
  const getChange = (d: MultiPeriodSlopeDataPoint) => {
    const first = d.values[0]
    const last = d.values[d.values.length - 1]
    if (first === 0) return last > 0 ? 100 : 0
    return ((last - first) / Math.abs(first)) * 100
  }

  // Get rank at each period (for bumps chart)
  const getRanks = React.useMemo(() => {
    if (variant !== "bumps") return null

    const ranks: Map<string, number[]> = new Map()

    for (let period = 0; period < periodCount; period++) {
      const sorted = [...normalizedData]
        .map((d, i) => ({
          index: i,
          category: d.category,
          value: d.values[period],
        }))
        .sort((a, b) => b.value - a.value)

      sorted.forEach((item, rank) => {
        if (!ranks.has(item.category)) {
          ranks.set(item.category, [])
        }
        ranks.get(item.category)![period] = rank
      })
    }

    return ranks
  }, [normalizedData, periodCount, variant])

  // Y scale for ranks (bumps chart)
  const rankYScale = React.useMemo(() => {
    if (variant !== "bumps") return null
    return scaleLinear()
      .domain([0, normalizedData.length - 1])
      .range([20, innerHeight - 20])
  }, [variant, normalizedData.length, innerHeight])

  // Line generator
  const lineGenerator = React.useMemo(() => {
    return line<{ x: number; y: number }>()
      .x((d) => d.x)
      .y((d) => d.y)
      .curve(variant === "parallel" ? curveLinear : curveMonotoneX)
  }, [variant])

  // Generate path for each data series
  const getPath = (d: MultiPeriodSlopeDataPoint, index: number) => {
    if (variant === "bumps" && getRanks && rankYScale) {
      const ranks = getRanks.get(d.category)
      if (!ranks) return ""
      const points = ranks.map((rank, period) => ({
        x: xScale(period) ?? 0,
        y: rankYScale(rank),
      }))
      return lineGenerator(points) ?? ""
    }

    const points = d.values.map((value, period) => ({
      x: xScale(period) ?? 0,
      y: yScale(value),
    }))
    return lineGenerator(points) ?? ""
  }

  // Get Y position for endpoint
  const getEndY = (
    d: MultiPeriodSlopeDataPoint,
    index: number,
    periodIndex: number
  ) => {
    if (variant === "bumps" && getRanks && rankYScale) {
      const ranks = getRanks.get(d.category)
      return ranks ? rankYScale(ranks[periodIndex]) : 0
    }
    return yScale(d.values[periodIndex])
  }

  // Get rank change display
  const getRankChangeDisplay = (d: MultiPeriodSlopeDataPoint) => {
    if (!getRanks) return null
    const ranks = getRanks.get(d.category)
    if (!ranks) return null
    const change = ranks[0] - ranks[ranks.length - 1]
    if (change > 0) return `+${change}`
    if (change < 0) return `${change}`
    return "="
  }

  return (
    <div className={cn("relative w-full", className)}>
      {/* Legend */}
      <div className="mb-3 flex items-center justify-center gap-6">
        <div className="flex items-center gap-2">
          <div
            className="h-0.5 w-5"
            style={{ backgroundColor: increaseColor }}
          />
          <span className="text-muted-foreground text-sm">Increase</span>
        </div>
        <div className="flex items-center gap-2">
          <div
            className="h-0.5 w-5"
            style={{ backgroundColor: decreaseColor }}
          />
          <span className="text-muted-foreground text-sm">Decrease</span>
        </div>
        {variant !== "bumps" && (
          <div className="flex items-center gap-2">
            <div
              className="h-0.5 w-5"
              style={{ backgroundColor: neutralColor }}
            />
            <span className="text-muted-foreground text-sm">No change</span>
          </div>
        )}
      </div>

      <svg
        viewBox={`0 0 ${width} ${height}`}
        className="h-auto w-full overflow-visible"
      >
        <g transform={`translate(${margin.left}, ${margin.top})`}>
          {/* Grid lines */}
          {showGrid &&
            variant !== "bumps" &&
            yTicks.map((tick) => (
              <line
                key={tick}
                x1={0}
                x2={innerWidth}
                y1={yScale(tick)}
                y2={yScale(tick)}
                stroke="#e5e7eb"
                strokeDasharray="3 3"
              />
            ))}

          {/* Period headers */}
          {periodLabels.map((label, i) => (
            <text
              key={`header-${i}`}
              x={xScale(i) ?? 0}
              y={-25}
              textAnchor="middle"
              fontSize={12}
              fontWeight={500}
              className="fill-foreground"
            >
              {label}
            </text>
          ))}

          {/* Vertical axis lines */}
          {Array.from({ length: periodCount }).map((_, i) => (
            <line
              key={`axis-${i}`}
              x1={xScale(i) ?? 0}
              x2={xScale(i) ?? 0}
              y1={-10}
              y2={innerHeight + 10}
              stroke="#e5e7eb"
              strokeWidth={1}
            />
          ))}

          {/* Slope lines */}
          {normalizedData.map((d, index) => {
            const isHovered = hoveredIndex === index
            const color = getLineColor(d)
            const path = getPath(d, index)

            return (
              <g
                key={d.category}
                className="cursor-pointer"
                onMouseEnter={() => setHoveredIndex(index)}
                onMouseLeave={() => setHoveredIndex(null)}
                style={{
                  opacity: hoveredIndex !== null && !isHovered ? 0.2 : 1,
                  transition: "opacity 150ms",
                }}
              >
                {/* Line path */}
                <path
                  d={path}
                  fill="none"
                  stroke={color}
                  strokeWidth={isHovered ? 3 : 2}
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  style={{ transition: "stroke-width 150ms" }}
                />

                {/* Dots at each period */}
                {d.values.map((_, periodIndex) => (
                  <circle
                    key={periodIndex}
                    cx={xScale(periodIndex) ?? 0}
                    cy={getEndY(d, index, periodIndex)}
                    r={isHovered ? 5 : 4}
                    fill={color}
                    stroke="white"
                    strokeWidth={2}
                    style={{ transition: "r 150ms" }}
                  />
                ))}

                {/* Start label - category name */}
                <text
                  x={-12}
                  y={getEndY(d, index, 0)}
                  textAnchor="end"
                  dominantBaseline="middle"
                  fontSize={11}
                  className="fill-foreground"
                  style={{ fontWeight: isHovered ? 600 : 400 }}
                >
                  {d.category}
                </text>

                {/* End value */}
                {showValues && (
                  <text
                    x={innerWidth + 12}
                    y={getEndY(d, index, periodCount - 1)}
                    textAnchor="start"
                    dominantBaseline="middle"
                    fontSize={11}
                    className="fill-foreground"
                  >
                    {variant === "bumps" && showRankChange ? (
                      <>{getRankChangeDisplay(d)}</>
                    ) : (
                      <>
                        {valueFormatter(d.values[d.values.length - 1])}
                        <tspan fill={color} fontSize={10} fontWeight={500}>
                          {" "}
                          {getChange(d) >= 0 ? "+" : ""}
                          {getChange(d).toFixed(0)}%
                        </tspan>
                      </>
                    )}
                  </text>
                )}
              </g>
            )
          })}
        </g>
      </svg>

      {/* Tooltip */}
      {hoveredIndex !== null && (
        <div className="bg-foreground text-background pointer-events-none absolute top-16 left-1/2 z-50 -translate-x-1/2 rounded-md px-3 py-2 text-xs font-medium shadow-lg">
          <div className="mb-1 font-semibold">
            {normalizedData[hoveredIndex].category}
          </div>
          <div className="flex flex-wrap items-center gap-2 opacity-90">
            {normalizedData[hoveredIndex].values.map((value, i) => (
              <React.Fragment key={i}>
                <span>
                  {periodLabels[i]}: {valueFormatter(value)}
                </span>
                {i < normalizedData[hoveredIndex].values.length - 1 && (
                  <span className="opacity-50">→</span>
                )}
              </React.Fragment>
            ))}
          </div>
          {variant !== "bumps" && (
            <div
              className="mt-1.5 text-center font-semibold"
              style={{ color: getLineColor(normalizedData[hoveredIndex]) }}
            >
              {getChange(normalizedData[hoveredIndex]) >= 0 ? "+" : ""}
              {valueFormatter(
                normalizedData[hoveredIndex].values[
                  normalizedData[hoveredIndex].values.length - 1
                ] - normalizedData[hoveredIndex].values[0]
              )}{" "}
              ({getChange(normalizedData[hoveredIndex]) >= 0 ? "+" : ""}
              {getChange(normalizedData[hoveredIndex]).toFixed(1)}%)
            </div>
          )}
          {variant === "bumps" && getRanks && (
            <div
              className="mt-1.5 text-center font-semibold"
              style={{ color: getLineColor(normalizedData[hoveredIndex]) }}
            >
              Rank change: {getRankChangeDisplay(normalizedData[hoveredIndex])}
            </div>
          )}
        </div>
      )}
    </div>
  )
}

"use client"

import * as React from "react"
import { scaleBand, scaleLinear } from "d3-scale"

import { cn } from "@/lib/utils"

import {
  ChartZoomResetButton,
  ChartZoomSelectionRect,
  getBandScaleIndexRange,
  useChartZoom,
} from "../chart-zoom"

export interface OHLCDataPoint {
  date: string | Date
  open: number
  high: number
  low: number
  close: number
}

export interface OHLCChartProps {
  data: OHLCDataPoint[]
  className?: string
  upColor?: string
  downColor?: string
  showGrid?: boolean
  showTooltip?: boolean
  aspectRatio?: number
  valueFormatter?: (value: number) => string
  dateFormatter?: (date: Date) => string
}

export function OHLCChart({
  data,
  className,
  upColor = "var(--chart-2)",
  downColor = "var(--chart-4)",
  showGrid = true,
  showTooltip = true,
  aspectRatio = 2.5,
  valueFormatter = (value) => `$${value.toFixed(0)}`,
  dateFormatter = (date) =>
    date.toLocaleDateString("en-US", { month: "short" }),
}: OHLCChartProps) {
  const containerRef = React.useRef<HTMLDivElement>(null)
  const svgRef = React.useRef<SVGSVGElement>(null)
  const [dimensions, setDimensions] = React.useState({ width: 0, height: 0 })
  const [hoveredIndex, setHoveredIndex] = React.useState<number | null>(null)
  const [tooltipPos, setTooltipPos] = React.useState({ x: 0, y: 0 })
  const [zoomDomain, setZoomDomain] = React.useState<[number, number] | null>(
    null
  )
  const isZoomed = zoomDomain !== null
  const plotData = zoomDomain
    ? data.slice(zoomDomain[0], zoomDomain[1] + 1)
    : data

  React.useEffect(() => {
    const updateDimensions = () => {
      if (containerRef.current) {
        const width = containerRef.current.offsetWidth
        setDimensions({ width, height: width / aspectRatio })
      }
    }
    updateDimensions()
    window.addEventListener("resize", updateDimensions)
    return () => window.removeEventListener("resize", updateDimensions)
  }, [aspectRatio])

  // Reset any active zoom if the underlying data set changes.
  React.useEffect(() => {
    setZoomDomain(null)
  }, [data])

  const { width, height } = dimensions
  const margin = { top: 20, right: 20, bottom: 40, left: 50 }
  const innerWidth = Math.max(0, width - margin.left - margin.right)
  const innerHeight = Math.max(0, height - margin.top - margin.bottom)

  const xScale = React.useMemo(() => {
    return scaleBand()
      .domain(plotData.map((d) => String(d.date)))
      .range([0, innerWidth])
      .padding(0.3)
  }, [plotData, innerWidth])

  const yScale = React.useMemo(() => {
    const allPrices = plotData.flatMap((d) => [d.high, d.low])
    const minPrice = Math.min(...allPrices)
    const maxPrice = Math.max(...allPrices)
    const padding = (maxPrice - minPrice) * 0.1
    return scaleLinear()
      .domain([Math.max(0, minPrice - padding), maxPrice + padding])
      .range([innerHeight, 0])
      .nice()
  }, [plotData, innerHeight])

  // Drag-to-zoom: converts the pixel drag range into a data-index range
  // (band scale) and narrows the view to it.
  const zoom = useChartZoom({
    svgRef,
    marginLeft: margin.left,
    innerWidth,
    onZoom: ({ x0, x1 }) => {
      const [start, end] = getBandScaleIndexRange(xScale, x0, x1)
      const currentOffset = zoomDomain ? zoomDomain[0] : 0
      setZoomDomain([currentOffset + start, currentOffset + end])
    },
    onReset: () => setZoomDomain(null),
  })

  const tickWidth = xScale.bandwidth() * 0.4
  const ticks = yScale.ticks(5)

  const monthLabels = React.useMemo(() => {
    const labels: { date: string; x: number }[] = []
    let lastMonth = -1
    plotData.forEach((d) => {
      const date = new Date(d.date)
      const month = date.getMonth()
      if (month !== lastMonth) {
        labels.push({
          date: String(d.date),
          x: (xScale(String(d.date)) ?? 0) + xScale.bandwidth() / 2,
        })
        lastMonth = month
      }
    })
    return labels
  }, [plotData, xScale])

  if (width === 0) {
    return <div ref={containerRef} className={cn("w-full", className)} />
  }

  return (
    <div ref={containerRef} className={cn("relative w-full", className)}>
      <svg
        ref={svgRef}
        width={width}
        height={height}
        viewBox={`0 0 ${width} ${height}`}
        className="overflow-visible select-none"
        onMouseDown={zoom.handlers.onMouseDown}
        onMouseMove={zoom.handlers.onMouseMove}
        onMouseUp={zoom.handlers.onMouseUp}
        onMouseLeave={zoom.handlers.onMouseLeave}
        onDoubleClick={zoom.handlers.onDoubleClick}
      >
        <g transform={`translate(${margin.left}, ${margin.top})`}>
          {/* Drag-to-zoom selection rectangle */}
          <ChartZoomSelectionRect range={zoom.dragRange} height={innerHeight} />

          {showGrid && (
            <>
              {ticks.map((tick) => (
                <line
                  key={`h-${tick}`}
                  x1={0}
                  x2={innerWidth}
                  y1={yScale(tick)}
                  y2={yScale(tick)}
                  stroke="hsl(var(--border))"
                  strokeDasharray="3 3"
                  strokeOpacity={0.5}
                />
              ))}
              {monthLabels.map((label, i) => (
                <line
                  key={`v-${i}`}
                  x1={label.x}
                  x2={label.x}
                  y1={0}
                  y2={innerHeight}
                  stroke="hsl(var(--border))"
                  strokeDasharray="3 3"
                  strokeOpacity={0.5}
                />
              ))}
            </>
          )}

          {/* OHLC bars */}
          {plotData.map((d, index) => {
            const isUp = d.close >= d.open
            const color = isUp ? upColor : downColor
            const x = (xScale(String(d.date)) ?? 0) + xScale.bandwidth() / 2
            const isHovered = hoveredIndex === index

            return (
              <g
                key={index}
                className={cn(
                  "cursor-pointer transition-opacity duration-200",
                  hoveredIndex !== null && !isHovered && "opacity-40"
                )}
                onMouseEnter={(e) => {
                  setHoveredIndex(index)
                  const rect = containerRef.current?.getBoundingClientRect()
                  if (rect) {
                    setTooltipPos({
                      x: e.clientX - rect.left,
                      y: e.clientY - rect.top,
                    })
                  }
                }}
                onMouseMove={(e) => {
                  const rect = containerRef.current?.getBoundingClientRect()
                  if (rect) {
                    setTooltipPos({
                      x: e.clientX - rect.left,
                      y: e.clientY - rect.top,
                    })
                  }
                }}
                onMouseLeave={() => setHoveredIndex(null)}
              >
                {/* Vertical line (high to low) */}
                <line
                  x1={x}
                  x2={x}
                  y1={yScale(d.high)}
                  y2={yScale(d.low)}
                  stroke={color}
                  strokeWidth={2}
                />

                {/* Open tick (left) */}
                <line
                  x1={x - tickWidth}
                  x2={x}
                  y1={yScale(d.open)}
                  y2={yScale(d.open)}
                  stroke={color}
                  strokeWidth={2}
                />

                {/* Close tick (right) */}
                <line
                  x1={x}
                  x2={x + tickWidth}
                  y1={yScale(d.close)}
                  y2={yScale(d.close)}
                  stroke={color}
                  strokeWidth={2}
                />
              </g>
            )
          })}

          {/* X Axis */}
          <g transform={`translate(0, ${innerHeight})`}>
            {monthLabels.map((label, i) => {
              const date = new Date(label.date)
              return (
                <text
                  key={i}
                  x={label.x}
                  y={24}
                  textAnchor="middle"
                  className="fill-muted-foreground text-xs"
                >
                  {dateFormatter(date)}
                </text>
              )
            })}
          </g>

          {/* Y Axis */}
          <g>
            {ticks.map((tick) => (
              <text
                key={tick}
                x={-12}
                y={yScale(tick)}
                dy="0.32em"
                textAnchor="end"
                className="fill-muted-foreground text-xs"
              >
                {valueFormatter(tick)}
              </text>
            ))}
          </g>
        </g>
      </svg>

      {/* Tooltip */}
      {showTooltip && hoveredIndex !== null && (
        <div
          className="pointer-events-none absolute z-50"
          style={{
            left: tooltipPos.x + 10,
            top: tooltipPos.y - 10,
            transform: "translateY(-100%)",
          }}
        >
          <div className="bg-background rounded-lg border px-3 py-2 shadow-lg">
            <p className="text-foreground mb-1 text-sm font-medium">
              {new Date(plotData[hoveredIndex].date).toLocaleDateString(
                "en-US",
                {
                  month: "short",
                  day: "numeric",
                  year: "numeric",
                }
              )}
            </p>
            <div className="grid grid-cols-2 gap-x-4 gap-y-0.5 text-sm">
              <span className="text-muted-foreground">Open</span>
              <span
                className="font-mono"
                style={{
                  color:
                    plotData[hoveredIndex].close >= plotData[hoveredIndex].open
                      ? upColor
                      : downColor,
                }}
              >
                {valueFormatter(plotData[hoveredIndex].open)}
              </span>
              <span className="text-muted-foreground">High</span>
              <span
                className="font-mono"
                style={{
                  color:
                    plotData[hoveredIndex].close >= plotData[hoveredIndex].open
                      ? upColor
                      : downColor,
                }}
              >
                {valueFormatter(plotData[hoveredIndex].high)}
              </span>
              <span className="text-muted-foreground">Low</span>
              <span
                className="font-mono"
                style={{
                  color:
                    plotData[hoveredIndex].close >= plotData[hoveredIndex].open
                      ? upColor
                      : downColor,
                }}
              >
                {valueFormatter(plotData[hoveredIndex].low)}
              </span>
              <span className="text-muted-foreground">Close</span>
              <span
                className="font-mono"
                style={{
                  color:
                    plotData[hoveredIndex].close >= plotData[hoveredIndex].open
                      ? upColor
                      : downColor,
                }}
              >
                {valueFormatter(plotData[hoveredIndex].close)}
              </span>
            </div>
          </div>
        </div>
      )}

      <ChartZoomResetButton
        visible={isZoomed}
        onReset={() => setZoomDomain(null)}
      />
    </div>
  )
}

"use client"

import * as React from "react"
import type { GeoPermissibleObjects } from "d3-geo"
import {
  geoAlbersUsa,
  geoEqualEarth,
  geoMercator,
  geoNaturalEarth1,
  geoPath,
} from "d3-geo"
import { interpolateRgb } from "d3-interpolate"
import { feature } from "topojson-client"
import type { GeometryCollection, Topology } from "topojson-specification"

import { cn } from "@/lib/utils"

export interface GeoFeature {
  type: "Feature"
  properties: {
    name?: string
    iso_a2?: string
    iso_a3?: string
    [key: string]: unknown
  }
  geometry: GeoPermissibleObjects
  id?: string | number
}

export interface GeoJSON {
  type: "FeatureCollection"
  features: GeoFeature[]
}

export interface ChoroplethDataPoint {
  id: string // ISO country code (2 or 3 letter)
  value: number
  label?: string
}

export interface ChoroplethChartProps {
  data: ChoroplethDataPoint[]
  className?: string
  colorScale?: string[]
  showTooltip?: boolean
  showLegend?: boolean
  projection?: "naturalEarth" | "mercator" | "equalEarth" | "albersUsa"
  aspectRatio?: number
  legendTitle?: string
  valueFormatter?: (value: number) => string
  noDataColor?: string
  /** Custom GeoJSON/TopoJSON URL. Defaults to world countries. */
  geoUrl?: string
  /** Object name in TopoJSON (e.g., "states", "countries"). Auto-detected if not provided. */
  topojsonObject?: string
  /** Property name to use as feature ID (e.g., "name", "postal", "iso_a2") */
  idProperty?: string
}

// Default world countries GeoJSON URL
const WORLD_GEOJSON_URL =
  "https://cdn.jsdelivr.net/npm/world-atlas@2/countries-110m.json"

// Country-specific GeoJSON/TopoJSON URLs (all CORS-enabled)
export const GEO_URLS = {
  world: "https://cdn.jsdelivr.net/npm/world-atlas@2/countries-110m.json",
  usa: "https://cdn.jsdelivr.net/npm/us-atlas@3/states-10m.json",
  india:
    "https://raw.githubusercontent.com/datta07/INDIAN-SHAPEFILES/master/INDIA/INDIA_STATES.geojson",
  china:
    "https://raw.githubusercontent.com/markmarkoh/datamaps/master/src/js/data/chn.topo.json",
  uk: "https://raw.githubusercontent.com/markmarkoh/datamaps/master/src/js/data/gbr.topo.json",
  russia:
    "https://raw.githubusercontent.com/markmarkoh/datamaps/master/src/js/data/rus.topo.json",
  germany:
    "https://raw.githubusercontent.com/isellsoap/deutschlandGeoJSON/master/2_bundeslaender/4_niedrig.geo.json",
  france:
    "https://raw.githubusercontent.com/gregoiredavid/france-geojson/master/regions-version-simplifiee.geojson",
  brazil:
    "https://raw.githubusercontent.com/codeforamerica/click_that_hood/master/public/data/brazil-states.geojson",
} as const

export function ChoroplethChart({
  data,
  className,
  colorScale: colorScaleProp,
  showTooltip = true,
  showLegend = true,
  projection = "naturalEarth",
  aspectRatio = 2,
  legendTitle = "Value",
  valueFormatter = (v) => v.toLocaleString(),
  noDataColor = "hsl(var(--muted))",
  geoUrl,
  topojsonObject,
  idProperty,
}: ChoroplethChartProps) {
  const containerRef = React.useRef<HTMLDivElement>(null)
  const [dimensions, setDimensions] = React.useState({ width: 0, height: 0 })
  const [geoData, setGeoData] = React.useState<GeoJSON | null>(null)
  const [loading, setLoading] = React.useState(true)
  const [error, setError] = React.useState<string | null>(null)
  const [hoveredFeature, setHoveredFeature] = React.useState<GeoFeature | null>(
    null
  )
  const [tooltipPos, setTooltipPos] = React.useState({ x: 0, y: 0 })
  const gradientId = React.useId().replace(/:/g, "")

  // Convert any CSS color (including oklch) to rgb format that d3 understands
  const toRgb = React.useCallback((cssColor: string): string => {
    const tmp = document.createElement("div")
    tmp.style.color = cssColor
    tmp.style.display = "none"
    document.body.appendChild(tmp)
    const rgb = getComputedStyle(tmp).color
    document.body.removeChild(tmp)
    return rgb
  }, [])

  // Resolve CSS variable colors for d3 interpolation
  const [resolvedColorScale, setResolvedColorScale] = React.useState<string[]>(
    colorScaleProp || ["#bfdbfe", "#60a5fa", "#1e40af"]
  )
  React.useEffect(() => {
    if (colorScaleProp) {
      setResolvedColorScale(colorScaleProp)
      return
    }
    const resolve = () => {
      const el = containerRef.current
      if (!el) return
      const style = getComputedStyle(el)
      const c1 = style.getPropertyValue("--chart-1").trim()
      const c3 = style.getPropertyValue("--chart-3").trim()
      const c5 = style.getPropertyValue("--chart-5").trim()
      if (c1 && c3 && c5) {
        setResolvedColorScale([toRgb(c1), toRgb(c3), toRgb(c5)])
      }
    }
    // Resolve on mount and observe theme class changes on body
    resolve()
    const observer = new MutationObserver(resolve)
    observer.observe(document.body, {
      attributes: true,
      attributeFilter: ["class"],
    })
    observer.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    })
    return () => observer.disconnect()
  }, [colorScaleProp, toRgb])

  // Responsive sizing
  React.useEffect(() => {
    const updateDimensions = () => {
      if (containerRef.current) {
        const width = containerRef.current.offsetWidth
        setDimensions({ width, height: width / aspectRatio })
      }
    }
    updateDimensions()
    window.addEventListener("resize", updateDimensions)
    return () => window.removeEventListener("resize", updateDimensions)
  }, [aspectRatio])

  // Fetch GeoJSON/TopoJSON
  React.useEffect(() => {
    const fetchGeoData = async () => {
      try {
        setLoading(true)
        setError(null)
        const url = geoUrl || WORLD_GEOJSON_URL

        const response = await fetch(url)
        if (!response.ok) {
          throw new Error(`HTTP ${response.status}: ${response.statusText}`)
        }

        const jsonData = await response.json()

        // Check if it's TopoJSON (has "objects" property) or GeoJSON
        if (jsonData.type === "Topology" && jsonData.objects) {
          // Convert TopoJSON to GeoJSON
          const topoData = jsonData as Topology<{
            [key: string]: GeometryCollection
          }>

          // Use specified object or find first available (case-insensitive)
          const availableKeys = Object.keys(topoData.objects)
          let objectName = topojsonObject || availableKeys[0]

          // Try case-insensitive match if exact match fails
          if (!topoData.objects[objectName]) {
            const lowerName = objectName.toLowerCase()
            const match = availableKeys.find(
              (k) => k.toLowerCase() === lowerName
            )
            if (match) {
              objectName = match
            } else {
              throw new Error(
                `TopoJSON object "${objectName}" not found. Available: ${availableKeys.join(", ")}`
              )
            }
          }

          const geoJson = feature(
            topoData,
            topoData.objects[objectName]
          ) as unknown as GeoJSON

          setGeoData(geoJson)
        } else if (jsonData.type === "FeatureCollection") {
          // Already GeoJSON
          setGeoData(jsonData as GeoJSON)
        } else {
          throw new Error(
            `Invalid geo data format: ${jsonData.type || "unknown"}`
          )
        }
      } catch (err) {
        const message = err instanceof Error ? err.message : "Unknown error"
        setError(`Failed to load map: ${message}`)
        console.error("Failed to load GeoJSON:", err)
      } finally {
        setLoading(false)
      }
    }
    fetchGeoData()
  }, [geoUrl, topojsonObject])

  const { width, height } = dimensions
  const margin = { top: 10, right: showLegend ? 80 : 20, bottom: 10, left: 10 }
  const innerWidth = Math.max(0, width - margin.left - margin.right)
  const innerHeight = Math.max(0, height - margin.top - margin.bottom)

  // Create data map for quick lookup (support various ID formats)
  const dataMap = React.useMemo(() => {
    const map = new Map<string, ChoroplethDataPoint>()
    data.forEach((d) => {
      map.set(d.id, d) // exact match
      map.set(d.id.toUpperCase(), d)
      map.set(d.id.toLowerCase(), d)
    })
    return map
  }, [data])

  // Calculate value range
  const { minValue, maxValue } = React.useMemo(() => {
    if (data.length === 0) return { minValue: 0, maxValue: 100 }
    const values = data.map((d) => d.value)
    return {
      minValue: Math.min(...values),
      maxValue: Math.max(...values),
    }
  }, [data])

  // Color scale function
  const colorScale = resolvedColorScale
  const getColor = React.useCallback(
    (value: number | undefined) => {
      if (value === undefined) return noDataColor
      const range = maxValue - minValue || 1
      const t = (value - minValue) / range

      if (colorScale.length === 2) {
        return interpolateRgb(colorScale[0], colorScale[1])(t)
      }
      if (t < 0.5) {
        return interpolateRgb(colorScale[0], colorScale[1])(t * 2)
      }
      return interpolateRgb(colorScale[1], colorScale[2])((t - 0.5) * 2)
    },
    [colorScale, minValue, maxValue, noDataColor]
  )

  // Get feature value by matching ID
  const getFeatureValue = React.useCallback(
    (feature: GeoFeature) => {
      // If idProperty is specified, use it first
      if (idProperty && feature.properties[idProperty]) {
        const id = String(feature.properties[idProperty])
        const d =
          dataMap.get(id) ||
          dataMap.get(id.toUpperCase()) ||
          dataMap.get(id.toLowerCase())
        if (d) return d.value
      }

      // Try different ID formats (various GeoJSON schemas)
      const ids = [
        feature.id,
        feature.properties.name,
        feature.properties.NAME,
        feature.properties.nom, // French regions
        feature.properties.STNAME_SH, // India states (official)
        feature.properties.iso_a2,
        feature.properties.iso_a3,
        feature.properties.postal,
        feature.properties.code,
        feature.properties.st_nm, // India states (datamaps)
        feature.properties.sigla, // Brazil states
      ].filter(Boolean) as string[]

      for (const id of ids) {
        const d =
          dataMap.get(id) ||
          dataMap.get(id.toUpperCase()) ||
          dataMap.get(id.toLowerCase())
        if (d) return d.value
      }
      return undefined
    },
    [dataMap, idProperty]
  )

  // Create projection
  const projectionFn = React.useMemo(() => {
    if (innerWidth === 0 || innerHeight === 0 || !geoData) return null

    const projections = {
      naturalEarth: geoNaturalEarth1,
      mercator: geoMercator,
      equalEarth: geoEqualEarth,
      albersUsa: geoAlbersUsa,
    }

    const proj = projections[projection]()

    // AlbersUSA has its own built-in scale, others need fitSize
    if (projection === "albersUsa") {
      // Scale to fit container - AlbersUSA is designed for ~960x600
      const scale = Math.min(innerWidth / 960, innerHeight / 600) * 1100
      return proj.scale(scale).translate([innerWidth / 2, innerHeight / 2])
    }

    return proj.fitSize([innerWidth, innerHeight], geoData as any)
  }, [projection, innerWidth, innerHeight, geoData])

  const pathGenerator = React.useMemo(() => {
    if (!projectionFn) return null
    return geoPath().projection(projectionFn)
  }, [projectionFn])

  // Show loading state (use min-height when width not yet measured)
  if (loading) {
    return (
      <div ref={containerRef} className={cn("w-full", className)}>
        <div
          className="bg-muted/20 flex animate-pulse items-center justify-center rounded-lg"
          style={{ height: width > 0 ? width / aspectRatio : 200 }}
        >
          <span className="text-muted-foreground text-sm">Loading map...</span>
        </div>
      </div>
    )
  }

  // Show error state
  if (error || !geoData) {
    return (
      <div ref={containerRef} className={cn("w-full", className)}>
        <div
          className="bg-muted/20 flex items-center justify-center rounded-lg"
          style={{ height: width > 0 ? width / aspectRatio : 200 }}
        >
          <span className="text-muted-foreground text-sm">
            {error || "Failed to load map"}
          </span>
        </div>
      </div>
    )
  }

  // Wait for dimensions to be measured
  if (width === 0 || !pathGenerator) {
    return (
      <div
        ref={containerRef}
        className={cn("min-h-[200px] w-full", className)}
      />
    )
  }

  return (
    <div ref={containerRef} className={cn("relative w-full", className)}>
      <div className="flex w-full items-center justify-center">
        <svg
          width={width}
          height={height}
          viewBox={`0 0 ${width} ${height}`}
          className="overflow-visible"
        >
          <g transform={`translate(${margin.left}, ${margin.top})`}>
            {/* Map features */}
            {geoData.features.map((feature, index) => {
              const value = getFeatureValue(feature)
              const color = getColor(value)
              const isHovered = hoveredFeature === feature
              const pathD = pathGenerator(feature as any)

              if (!pathD) return null

              return (
                <path
                  key={feature.id || index}
                  d={pathD}
                  fill={color}
                  stroke="hsl(var(--background))"
                  strokeWidth={isHovered ? 1.5 : 0.5}
                  className={cn(
                    "cursor-pointer transition-all duration-150",
                    hoveredFeature !== null && !isHovered && "opacity-70"
                  )}
                  onMouseEnter={(e) => {
                    setHoveredFeature(feature)
                    const rect = containerRef.current?.getBoundingClientRect()
                    if (rect) {
                      setTooltipPos({
                        x: e.clientX - rect.left,
                        y: e.clientY - rect.top,
                      })
                    }
                  }}
                  onMouseMove={(e) => {
                    const rect = containerRef.current?.getBoundingClientRect()
                    if (rect) {
                      setTooltipPos({
                        x: e.clientX - rect.left,
                        y: e.clientY - rect.top,
                      })
                    }
                  }}
                  onMouseLeave={() => setHoveredFeature(null)}
                />
              )
            })}
          </g>

          {/* Color legend */}
          {showLegend && (
            <g
              transform={`translate(${width - margin.right + 15}, ${margin.top + 20})`}
            >
              <text
                className="fill-muted-foreground text-[10px] font-medium"
                y={-8}
              >
                {legendTitle}
              </text>
              <defs>
                <linearGradient
                  id={`gradient-${gradientId}`}
                  x1="0"
                  y1="1"
                  x2="0"
                  y2="0"
                >
                  <stop offset="0%" stopColor={colorScale[0]} />
                  {colorScale.length === 3 && (
                    <stop offset="50%" stopColor={colorScale[1]} />
                  )}
                  <stop
                    offset="100%"
                    stopColor={colorScale[colorScale.length - 1]}
                  />
                </linearGradient>
              </defs>
              <rect
                width={15}
                height={Math.max(0, innerHeight - 40)}
                fill={`url(#gradient-${gradientId})`}
                rx={2}
              />
              <text
                x={20}
                y={0}
                dominantBaseline="hanging"
                className="fill-muted-foreground text-[10px]"
              >
                {valueFormatter(maxValue)}
              </text>
              <text
                x={20}
                y={Math.max(0, innerHeight - 40)}
                dominantBaseline="auto"
                className="fill-muted-foreground text-[10px]"
              >
                {valueFormatter(minValue)}
              </text>
            </g>
          )}
        </svg>
      </div>

      {/* Tooltip */}
      {showTooltip &&
        hoveredFeature &&
        (() => {
          const value = getFeatureValue(hoveredFeature)
          const tooltipWidth = 160
          const tooltipHeight = 60
          const padding = 10

          const showOnLeft = tooltipPos.x + tooltipWidth + padding > width
          const showBelow = tooltipPos.y - tooltipHeight - padding < 0

          return (
            <div
              className="pointer-events-none absolute z-50"
              style={{
                left: showOnLeft
                  ? tooltipPos.x - padding
                  : tooltipPos.x + padding,
                top: showBelow
                  ? tooltipPos.y + padding
                  : tooltipPos.y - padding,
                transform: `translate(${showOnLeft ? "-100%" : "0"}, ${showBelow ? "0" : "-100%"})`,
              }}
            >
              <div className="bg-background rounded-lg border px-3 py-2 shadow-lg">
                <p className="text-foreground text-sm font-medium">
                  {String(
                    hoveredFeature.properties.name ||
                      hoveredFeature.properties.NAME ||
                      hoveredFeature.properties.nom ||
                      hoveredFeature.properties.STNAME_SH ||
                      hoveredFeature.id ||
                      "Unknown"
                  )}
                </p>
                <p className="text-muted-foreground text-sm">
                  {value !== undefined ? (
                    <>
                      {legendTitle}: {valueFormatter(value)}
                    </>
                  ) : (
                    "No data"
                  )}
                </p>
              </div>
            </div>
          )
        })()}
    </div>
  )
}

"use client"

import * as React from "react"
import { scaleBand, scaleLinear } from "d3-scale"
import { arc } from "d3-shape"

import { cn } from "@/lib/utils"

export interface PolarDataPoint {
  category: string
  value: number
  color?: string
}

export interface PolarChartProps {
  data: PolarDataPoint[]
  className?: string
  variant?: "rose" | "coxcomb" | "radar-area"
  innerRadius?: number
  showLabels?: boolean
  showValues?: boolean
  showGrid?: boolean
  valueFormatter?: (value: number) => string
  colorScheme?: string[]
}

export function PolarChart({
  data,
  className,
  variant = "rose",
  innerRadius = 0,
  showLabels = true,
  showValues = false,
  showGrid = true,
  valueFormatter = (value) => value.toLocaleString(),
  colorScheme = [
    "var(--chart-5)",
    "var(--chart-4)",
    "var(--chart-3)",
    "var(--chart-2)",
    "var(--chart-1)",
    "var(--chart-1)",
  ],
}: PolarChartProps) {
  const [hoveredIndex, setHoveredIndex] = React.useState<number | null>(null)

  const width = 400
  const height = 400
  const centerX = width / 2
  const centerY = height / 2
  const outerRadius = Math.min(width, height) / 2 - 40

  const maxValue = Math.max(...data.map((d) => d.value))

  // Angle scale (categories around the circle)
  const angleScale = scaleBand<string>()
    .domain(data.map((d) => d.category))
    .range([0, 2 * Math.PI])

  // Radius scale (values from center to edge)
  const radiusScale = scaleLinear()
    .domain([0, maxValue])
    .range([innerRadius, outerRadius])

  // Grid circles
  const gridCircles = radiusScale.ticks(4)

  // Arc generator
  const arcGenerator = arc<{
    startAngle: number
    endAngle: number
    innerRadius: number
    outerRadius: number
  }>()

  return (
    <div className={cn("w-full", className)}>
      <svg
        viewBox={`0 0 ${width} ${height}`}
        className="h-auto w-full overflow-visible"
      >
        <g transform={`translate(${centerX}, ${centerY})`}>
          {/* Grid circles */}
          {showGrid &&
            gridCircles.map((tick, i) => (
              <g key={`grid-${i}`}>
                <circle
                  r={radiusScale(tick)}
                  fill="none"
                  stroke="hsl(var(--border))"
                  strokeDasharray="3 3"
                  strokeOpacity={0.5}
                />
                <text
                  x={4}
                  y={-radiusScale(tick) - 2}
                  className="fill-muted-foreground text-[10px]"
                >
                  {valueFormatter(tick)}
                </text>
              </g>
            ))}

          {/* Grid lines (spokes) */}
          {showGrid &&
            data.map((d, i) => {
              const angle =
                (angleScale(d.category) ?? 0) +
                angleScale.bandwidth() / 2 -
                Math.PI / 2
              const x2 = Math.cos(angle) * outerRadius
              const y2 = Math.sin(angle) * outerRadius
              return (
                <line
                  key={`spoke-${i}`}
                  x1={0}
                  y1={0}
                  x2={x2}
                  y2={y2}
                  stroke="hsl(var(--border))"
                  strokeOpacity={0.3}
                />
              )
            })}

          {/* Rose/Coxcomb segments */}
          {data.map((d, index) => {
            const startAngle = angleScale(d.category) ?? 0
            const endAngle = startAngle + angleScale.bandwidth()
            const color = d.color ?? colorScheme[index % colorScheme.length]
            const isHovered = hoveredIndex === index

            let segmentRadius: number
            if (variant === "coxcomb") {
              // Coxcomb: equal angles, radius varies with sqrt(value) for equal area
              segmentRadius = radiusScale(
                Math.sqrt(d.value / maxValue) * maxValue
              )
            } else {
              // Rose: equal angles, radius varies linearly with value
              segmentRadius = radiusScale(d.value)
            }

            const pathData = arcGenerator({
              startAngle: startAngle - Math.PI / 2,
              endAngle: endAngle - Math.PI / 2,
              innerRadius: innerRadius,
              outerRadius: segmentRadius,
            })

            return (
              <g key={d.category}>
                <path
                  d={pathData ?? ""}
                  fill={color}
                  fillOpacity={isHovered ? 0.9 : 0.7}
                  stroke={color}
                  strokeWidth={isHovered ? 2 : 1}
                  className={cn(
                    "cursor-pointer transition-all duration-200",
                    hoveredIndex !== null && !isHovered && "opacity-50"
                  )}
                  onMouseEnter={() => setHoveredIndex(index)}
                  onMouseLeave={() => setHoveredIndex(null)}
                />
              </g>
            )
          })}

          {/* Labels */}
          {showLabels &&
            data.map((d, index) => {
              const angle =
                (angleScale(d.category) ?? 0) +
                angleScale.bandwidth() / 2 -
                Math.PI / 2
              const labelRadius = outerRadius + 20
              const x = Math.cos(angle) * labelRadius
              const y = Math.sin(angle) * labelRadius

              return (
                <text
                  key={`label-${index}`}
                  x={x}
                  y={y}
                  textAnchor="middle"
                  dominantBaseline="middle"
                  className="fill-foreground text-xs font-medium"
                  style={{
                    transform: `rotate(${angle > Math.PI / 2 && angle < (3 * Math.PI) / 2 ? 180 : 0}deg)`,
                    transformOrigin: `${x}px ${y}px`,
                  }}
                >
                  {d.category}
                </text>
              )
            })}
        </g>
      </svg>

      {/* Tooltip */}
      {hoveredIndex !== null && (
        <div className="mt-2 text-center">
          <div className="border-border/50 bg-background mx-auto inline-block rounded-lg border px-3 py-2 text-sm shadow-lg">
            <div className="font-medium">{data[hoveredIndex].category}</div>
            <div className="text-muted-foreground">
              {valueFormatter(data[hoveredIndex].value)}
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

"use client"

import * as React from "react"
import { scaleLinear, scalePoint } from "d3-scale"
import { curveMonotoneX, line } from "d3-shape"

import { cn } from "@/lib/utils"

export interface ParallelCoordinatesDataPoint {
  id: string
  values: Record<string, number>
  group?: string
}

export interface ParallelCoordinatesProps {
  data: ParallelCoordinatesDataPoint[]
  dimensions: string[]
  className?: string
  /** Visual style variant */
  variant?: "standard" | "curved"
  /** Show dimension labels */
  showLabels?: boolean
  /** Show tick values on axes */
  showValues?: boolean
  /** Line opacity (0-1) */
  lineOpacity?: number
  /** Single color for all lines (overrides group colors) */
  color?: string
  /** Color scheme for groups */
  colorScheme?: string[]
  /** Custom value formatter */
  valueFormatter?: (value: number, dimension: string) => string
}

const DEFAULT_COLOR = "var(--chart-1)"

const DEFAULT_COLOR_SCHEME = [
  "var(--chart-1)",
  "var(--chart-2)",
  "var(--chart-3)",
  "var(--chart-4)",
  "var(--chart-5)",
]

// Default value formatter with smart number formatting
const defaultValueFormatter = (v: number, _dim?: string): string => {
  if (Math.abs(v) >= 1000000) return `${(v / 1000000).toFixed(1)}M`
  if (Math.abs(v) >= 1000) return `${(v / 1000).toFixed(1)}K`
  if (Number.isInteger(v)) return v.toString()
  return v.toFixed(1)
}

export function ParallelCoordinates({
  data,
  dimensions,
  className,
  variant = "standard",
  showLabels = true,
  showValues = true,
  lineOpacity = 0.5,
  color,
  colorScheme = DEFAULT_COLOR_SCHEME,
  valueFormatter = defaultValueFormatter,
}: ParallelCoordinatesProps) {
  const [hoveredId, setHoveredId] = React.useState<string | null>(null)
  const [tooltipData, setTooltipData] = React.useState<{
    id: string
    x: number
    y: number
  } | null>(null)
  const svgRef = React.useRef<SVGSVGElement>(null)

  // Dynamic width based on number of dimensions
  const width = Math.max(400, dimensions.length * 100)
  const height = 350
  const margin = { top: 40, right: 40, bottom: 30, left: 40 }
  const innerWidth = width - margin.left - margin.right
  const innerHeight = height - margin.top - margin.bottom

  // Get unique groups
  const groups = React.useMemo(() => {
    return [...new Set(data.map((d) => d.group ?? "default"))]
  }, [data])

  const getColor = (group?: string) => {
    if (color) return color
    if (groups.length === 1) return DEFAULT_COLOR
    const index = groups.indexOf(group ?? "default")
    return colorScheme[index % colorScheme.length]
  }

  // X scale for dimensions
  const xScale = scalePoint<string>().domain(dimensions).range([0, innerWidth])

  // Y scales for each dimension
  const yScales = React.useMemo(() => {
    const scales: Record<
      string,
      ReturnType<typeof scaleLinear<number, number>>
    > = {}

    dimensions.forEach((dim) => {
      const values = data
        .map((d) => d.values[dim])
        .filter((v) => v !== undefined)
      const minVal = Math.min(...values)
      const maxVal = Math.max(...values)
      const padding = (maxVal - minVal) * 0.1 || 1

      scales[dim] = scaleLinear()
        .domain([minVal - padding, maxVal + padding])
        .range([innerHeight, 0])
        .nice()
    })

    return scales
  }, [data, dimensions, innerHeight])

  // Line generator
  const lineGenerator = React.useMemo(() => {
    const generator = line<{ x: number; y: number }>()
      .x((d) => d.x)
      .y((d) => d.y)

    if (variant === "curved") {
      generator.curve(curveMonotoneX)
    }

    return generator
  }, [variant])

  // Generate path for each data point
  const getPath = (d: ParallelCoordinatesDataPoint) => {
    const points = dimensions
      .map((dim) => {
        const x = xScale(dim)
        const y = yScales[dim]?.(d.values[dim])
        if (x === undefined || y === undefined) return null
        return { x, y }
      })
      .filter((p): p is { x: number; y: number } => p !== null)

    return lineGenerator(points)
  }

  const handleMouseEnter = (
    d: ParallelCoordinatesDataPoint,
    e: React.MouseEvent
  ) => {
    setHoveredId(d.id)
    if (svgRef.current) {
      const rect = svgRef.current.getBoundingClientRect()
      setTooltipData({
        id: d.id,
        x: e.clientX - rect.left,
        y: e.clientY - rect.top,
      })
    }
  }

  if (!data || data.length === 0) {
    return (
      <div
        className={cn(
          "text-muted-foreground flex h-[350px] items-center justify-center",
          className
        )}
      >
        No data available
      </div>
    )
  }

  return (
    <div className={cn("relative w-full", className)}>
      {/* Legend */}
      {groups.length > 1 && !color && (
        <div className="mb-4 flex flex-wrap items-center justify-center gap-x-6 gap-y-2">
          {groups.map((group) => (
            <div key={group} className="flex items-center gap-2">
              <div
                className="h-0.5 w-4 rounded"
                style={{ backgroundColor: getColor(group) }}
              />
              <span className="text-muted-foreground text-sm">{group}</span>
            </div>
          ))}
        </div>
      )}

      <svg
        ref={svgRef}
        viewBox={`0 0 ${width} ${height}`}
        className="h-auto w-full overflow-visible"
      >
        <g transform={`translate(${margin.left}, ${margin.top})`}>
          {/* Axes */}
          {dimensions.map((dim) => {
            const x = xScale(dim) ?? 0
            const scale = yScales[dim]
            const ticks = scale?.ticks(5) ?? []

            return (
              <g key={dim} transform={`translate(${x}, 0)`}>
                {/* Axis line */}
                <line
                  y1={0}
                  y2={innerHeight}
                  strokeWidth={1}
                  className="stroke-border"
                />

                {/* Ticks */}
                {showValues &&
                  ticks.map((tick, i) => (
                    <g key={i} transform={`translate(0, ${scale(tick)})`}>
                      <line x1={-4} x2={0} className="stroke-border" />
                      <text
                        x={-8}
                        textAnchor="end"
                        dominantBaseline="middle"
                        className="fill-muted-foreground text-[9px]"
                      >
                        {valueFormatter(tick, dim)}
                      </text>
                    </g>
                  ))}

                {/* Dimension label */}
                {showLabels && (
                  <text
                    y={-15}
                    textAnchor="middle"
                    className="fill-foreground text-xs font-medium"
                  >
                    {dim}
                  </text>
                )}
              </g>
            )
          })}

          {/* Lines */}
          {data.map((d) => {
            const path = getPath(d)
            if (!path) return null

            const lineColor = getColor(d.group)
            const isHovered = hoveredId === d.id

            return (
              <path
                key={d.id}
                d={path}
                fill="none"
                stroke={lineColor}
                strokeWidth={isHovered ? 2.5 : 1.5}
                strokeOpacity={
                  hoveredId === null ? lineOpacity : isHovered ? 1 : 0.1
                }
                className="cursor-pointer transition-all duration-150"
                onMouseEnter={(e) => handleMouseEnter(d, e)}
                onMouseLeave={() => {
                  setHoveredId(null)
                  setTooltipData(null)
                }}
              />
            )
          })}
        </g>
      </svg>

      {/* Tooltip */}
      {tooltipData && hoveredId && (
        <div
          className="bg-foreground text-background pointer-events-none absolute z-50 -translate-x-1/2 -translate-y-full rounded-lg px-3 py-2 text-xs shadow-lg"
          style={{ left: tooltipData.x, top: tooltipData.y - 10 }}
        >
          <div className="mb-1 font-semibold">{tooltipData.id}</div>
          <div className="grid grid-cols-2 gap-x-3 gap-y-0.5 opacity-90">
            {dimensions.map((dim) => {
              const item = data.find((d) => d.id === hoveredId)
              return (
                <React.Fragment key={dim}>
                  <span>{dim}:</span>
                  <span>{valueFormatter(item?.values[dim] ?? 0, dim)}</span>
                </React.Fragment>
              )
            })}
          </div>
        </div>
      )}
    </div>
  )
}

"use client"

import * as React from "react"
import { contourDensity } from "d3-contour"
import { geoPath } from "d3-geo"
import { scaleLinear, scaleSequential } from "d3-scale"
import { interpolateBlues } from "d3-scale-chromatic"

import { cn } from "@/lib/utils"

import {
  ChartZoomResetButton,
  ChartZoomSelectionRect,
  useChartZoom,
} from "../chart-zoom"

export interface DensityDataPoint {
  x: number
  y: number
}

export interface DensityChartProps {
  data: DensityDataPoint[]
  className?: string
  showPoints?: boolean
  showContours?: boolean
  bandwidth?: number
  thresholds?: number
  pointRadius?: number
  pointColor?: string
  colorScale?: (t: number) => string
  xAxisLabel?: string
  yAxisLabel?: string
}

export function DensityChart({
  data,
  className,
  showPoints = true,
  showContours = true,
  bandwidth = 20,
  thresholds = 10,
  pointRadius = 3,
  pointColor = "#1e40af",
  colorScale = interpolateBlues,
  xAxisLabel,
  yAxisLabel,
}: DensityChartProps) {
  const svgRef = React.useRef<SVGSVGElement>(null)
  const [hoveredPoint, setHoveredPoint] = React.useState<number | null>(null)
  const [zoomDomain, setZoomDomain] = React.useState<[number, number] | null>(
    null
  )
  const isZoomed = zoomDomain !== null

  const width = 500
  const height = 400
  const margin = { top: 20, right: 20, bottom: 50, left: 60 }
  const innerWidth = width - margin.left - margin.right
  const innerHeight = height - margin.top - margin.bottom

  // Apply the active zoom window (if any) by filtering the point cloud
  // down to the selected x-range before it reaches the scales/density
  // generator.
  const plotData = React.useMemo(() => {
    if (!zoomDomain) return data
    const [lo, hi] = zoomDomain
    return data.filter((d) => d.x >= lo && d.x <= hi)
  }, [data, zoomDomain])

  // X Scale
  const xExtent = React.useMemo(() => {
    const xValues = plotData.map((d) => d.x)
    const min = Math.min(...xValues)
    const max = Math.max(...xValues)
    const padding = (max - min) * 0.1
    return [min - padding, max + padding]
  }, [plotData])

  const xScale = scaleLinear().domain(xExtent).range([0, innerWidth]).nice()

  // Y Scale
  const yExtent = React.useMemo(() => {
    const yValues = plotData.map((d) => d.y)
    const min = Math.min(...yValues)
    const max = Math.max(...yValues)
    const padding = (max - min) * 0.1
    return [min - padding, max + padding]
  }, [plotData])

  const yScale = scaleLinear().domain(yExtent).range([innerHeight, 0]).nice()

  // Contour density
  const contours = React.useMemo(() => {
    if (!showContours) return []

    const densityGenerator = contourDensity<DensityDataPoint>()
      .x((d) => xScale(d.x))
      .y((d) => yScale(d.y))
      .size([innerWidth, innerHeight])
      .bandwidth(bandwidth)
      .thresholds(thresholds)

    return densityGenerator(plotData)
  }, [
    plotData,
    xScale,
    yScale,
    innerWidth,
    innerHeight,
    bandwidth,
    thresholds,
    showContours,
  ])

  // Color scale for contours
  const densityColorScale = scaleSequential(colorScale).domain([
    0,
    Math.max(...contours.map((c) => c.value)),
  ])

  // Path generator
  const pathGenerator = geoPath()

  // Axis ticks
  const xTicks = xScale.ticks(6)
  const yTicks = yScale.ticks(6)

  // Drag-to-zoom: converts the pixel drag range into a data-domain range
  // and narrows the view to it. Re-zooming while already zoomed narrows
  // further (inverted against the current, already-zoomed scale).
  const zoom = useChartZoom({
    svgRef,
    marginLeft: margin.left,
    innerWidth,
    onZoom: ({ x0, x1 }) => {
      const lo = xScale.invert(x0)
      const hi = xScale.invert(x1)
      const hasPointsInRange = plotData.some((d) => d.x >= lo && d.x <= hi)
      if (hasPointsInRange) setZoomDomain([lo, hi])
    },
    onReset: () => setZoomDomain(null),
  })

  return (
    <div className={cn("relative w-full", className)}>
      <svg
        ref={svgRef}
        viewBox={`0 0 ${width} ${height}`}
        className="h-auto w-full overflow-visible select-none"
        onMouseDown={zoom.handlers.onMouseDown}
        onMouseMove={zoom.handlers.onMouseMove}
        onMouseUp={zoom.handlers.onMouseUp}
        onMouseLeave={zoom.handlers.onMouseLeave}
        onDoubleClick={zoom.handlers.onDoubleClick}
      >
        <g transform={`translate(${margin.left}, ${margin.top})`}>
          {/* Grid */}
          {xTicks.map((tick) => (
            <line
              key={`x-grid-${tick}`}
              x1={xScale(tick)}
              x2={xScale(tick)}
              y1={0}
              y2={innerHeight}
              stroke="hsl(var(--border))"
              strokeDasharray="3 3"
              strokeOpacity={0.5}
            />
          ))}
          {yTicks.map((tick) => (
            <line
              key={`y-grid-${tick}`}
              x1={0}
              x2={innerWidth}
              y1={yScale(tick)}
              y2={yScale(tick)}
              stroke="hsl(var(--border))"
              strokeDasharray="3 3"
              strokeOpacity={0.5}
            />
          ))}

          {/* Contours */}
          {showContours &&
            contours.map((contour, i) => (
              <path
                key={`contour-${i}`}
                d={pathGenerator(contour) ?? ""}
                fill={densityColorScale(contour.value)}
                fillOpacity={0.6}
                stroke={densityColorScale(contour.value)}
                strokeWidth={0.5}
              />
            ))}

          {/* Points */}
          {showPoints &&
            plotData.map((d, i) => {
              const isHovered = hoveredPoint === i
              return (
                <circle
                  key={`point-${i}`}
                  cx={xScale(d.x)}
                  cy={yScale(d.y)}
                  r={isHovered ? pointRadius * 1.5 : pointRadius}
                  fill={pointColor}
                  fillOpacity={showContours ? 0.7 : 1}
                  stroke="#fff"
                  strokeWidth={1}
                  className="cursor-pointer transition-all duration-200"
                  onMouseEnter={() => setHoveredPoint(i)}
                  onMouseLeave={() => setHoveredPoint(null)}
                />
              )
            })}

          {/* Drag-to-zoom selection rectangle — drawn above the contours
              and points so the selection stays visible while dragging. */}
          <ChartZoomSelectionRect range={zoom.dragRange} height={innerHeight} />

          {/* X Axis */}
          <g transform={`translate(0, ${innerHeight})`}>
            <line x1={0} x2={innerWidth} stroke="hsl(var(--border))" />
            {xTicks.map((tick) => (
              <g key={tick} transform={`translate(${xScale(tick)}, 0)`}>
                <line y2={5} stroke="hsl(var(--border))" />
                <text
                  y={18}
                  textAnchor="middle"
                  className="fill-muted-foreground text-xs"
                >
                  {tick}
                </text>
              </g>
            ))}
            {xAxisLabel && (
              <text
                x={innerWidth / 2}
                y={40}
                textAnchor="middle"
                className="fill-foreground text-xs font-medium"
              >
                {xAxisLabel}
              </text>
            )}
          </g>

          {/* Y Axis */}
          <g>
            <line y1={0} y2={innerHeight} stroke="hsl(var(--border))" />
            {yTicks.map((tick) => (
              <g key={tick} transform={`translate(0, ${yScale(tick)})`}>
                <line x2={-5} stroke="hsl(var(--border))" />
                <text
                  x={-10}
                  textAnchor="end"
                  dominantBaseline="middle"
                  className="fill-muted-foreground text-xs"
                >
                  {tick}
                </text>
              </g>
            ))}
            {yAxisLabel && (
              <text
                transform={`translate(-45, ${innerHeight / 2}) rotate(-90)`}
                textAnchor="middle"
                className="fill-foreground text-xs font-medium"
              >
                {yAxisLabel}
              </text>
            )}
          </g>
        </g>
      </svg>

      {/* Tooltip */}
      {hoveredPoint !== null && plotData[hoveredPoint] && (
        <div className="mt-2 text-center">
          <div className="border-border/50 bg-background mx-auto inline-block rounded-lg border px-3 py-2 text-sm shadow-lg">
            <div className="text-muted-foreground">
              x: {plotData[hoveredPoint].x.toFixed(2)}, y:{" "}
              {plotData[hoveredPoint].y.toFixed(2)}
            </div>
          </div>
        </div>
      )}

      <ChartZoomResetButton
        visible={isZoomed}
        onReset={() => setZoomDomain(null)}
      />
    </div>
  )
}

"use client"

import * as React from "react"
import {
  forceCenter,
  forceCollide,
  forceLink,
  forceManyBody,
  forceSimulation,
  type SimulationLinkDatum,
  type SimulationNodeDatum,
} from "d3-force"

import { cn } from "@/lib/utils"

export interface NetworkNode extends SimulationNodeDatum {
  id: string
  label?: string
  group?: string
  size?: number
  color?: string
}

export interface NetworkLink extends SimulationLinkDatum<NetworkNode> {
  source: string | NetworkNode
  target: string | NetworkNode
  value?: number
  color?: string
}

export interface NetworkGraphProps {
  nodes: NetworkNode[]
  links: NetworkLink[]
  className?: string
  nodeRadius?: number
  linkWidth?: number
  showLabels?: boolean
  showArrows?: boolean
  charge?: number
  linkDistance?: number
  colorScheme?: string[]
}

export function NetworkGraph({
  nodes: initialNodes,
  links: initialLinks,
  className,
  nodeRadius = 8,
  linkWidth = 1.5,
  showLabels = true,
  showArrows = false,
  charge = -300,
  linkDistance = 100,
  colorScheme = [
    "var(--chart-5)",
    "var(--chart-4)",
    "var(--chart-3)",
    "var(--chart-2)",
    "var(--chart-1)",
  ],
}: NetworkGraphProps) {
  const svgRef = React.useRef<SVGSVGElement>(null)
  const [nodes, setNodes] = React.useState<NetworkNode[]>([])
  const [links, setLinks] = React.useState<NetworkLink[]>([])
  const [hoveredNode, setHoveredNode] = React.useState<string | null>(null)

  const width = 500
  const height = 400

  // Get unique groups for coloring
  const groups = React.useMemo(() => {
    return [...new Set(initialNodes.map((n) => n.group ?? "default"))]
  }, [initialNodes])

  const getGroupColor = (group?: string) => {
    const index = groups.indexOf(group ?? "default")
    return colorScheme[index % colorScheme.length]
  }

  // Run force simulation
  React.useEffect(() => {
    const nodesCopy = initialNodes.map((n) => ({ ...n }))
    const linksCopy = initialLinks.map((l) => ({ ...l }))

    const simulation = forceSimulation<NetworkNode>(nodesCopy)
      .force(
        "link",
        forceLink<NetworkNode, NetworkLink>(linksCopy)
          .id((d) => d.id)
          .distance(linkDistance)
      )
      .force("charge", forceManyBody().strength(charge))
      .force("center", forceCenter(width / 2, height / 2))
      .force("collide", forceCollide(nodeRadius * 2))

    simulation.on("tick", () => {
      setNodes([...nodesCopy])
      setLinks([...linksCopy])
    })

    simulation.alpha(1).restart()

    return () => {
      simulation.stop()
    }
  }, [
    initialNodes,
    initialLinks,
    charge,
    linkDistance,
    nodeRadius,
    width,
    height,
  ])

  return (
    <div className={cn("w-full", className)}>
      <svg
        ref={svgRef}
        viewBox={`0 0 ${width} ${height}`}
        className="h-auto w-full overflow-visible"
      >
        {/* Arrow marker definition */}
        {showArrows && (
          <defs>
            <marker
              id="arrowhead"
              viewBox="0 -5 10 10"
              refX={20}
              refY={0}
              markerWidth={6}
              markerHeight={6}
              orient="auto"
            >
              <path d="M0,-5L10,0L0,5" fill="var(--muted)" />
            </marker>
          </defs>
        )}

        {/* Links */}
        <g>
          {links.map((link, index) => {
            const sourceNode = link.source as NetworkNode
            const targetNode = link.target as NetworkNode
            if (
              !sourceNode.x ||
              !sourceNode.y ||
              !targetNode.x ||
              !targetNode.y
            )
              return null

            const isConnectedToHovered =
              hoveredNode === sourceNode.id || hoveredNode === targetNode.id

            return (
              <line
                key={`link-${index}`}
                x1={sourceNode.x}
                y1={sourceNode.y}
                x2={targetNode.x}
                y2={targetNode.y}
                stroke={link.color ?? "var(--muted)"}
                strokeWidth={link.value ? linkWidth * link.value : linkWidth}
                strokeOpacity={
                  hoveredNode ? (isConnectedToHovered ? 1 : 0.2) : 0.6
                }
                markerEnd={showArrows ? "url(#arrowhead)" : undefined}
                className="transition-opacity duration-200"
              />
            )
          })}
        </g>

        {/* Nodes */}
        <g>
          {nodes.map((node) => {
            if (!node.x || !node.y) return null
            const color = node.color ?? getGroupColor(node.group)
            const isHovered = hoveredNode === node.id
            const isConnected = links.some(
              (l) =>
                (typeof l.source === "object" ? l.source.id : l.source) ===
                  node.id ||
                (typeof l.target === "object" ? l.target.id : l.target) ===
                  node.id
            )
            const radius = node.size ?? nodeRadius

            return (
              <g key={node.id}>
                <circle
                  cx={node.x}
                  cy={node.y}
                  r={isHovered ? radius * 1.3 : radius}
                  fill={color}
                  stroke="#fff"
                  strokeWidth={2}
                  className={cn(
                    "cursor-pointer transition-all duration-200",
                    hoveredNode && !isHovered && !isConnected && "opacity-30"
                  )}
                  onMouseEnter={() => setHoveredNode(node.id)}
                  onMouseLeave={() => setHoveredNode(null)}
                />
                {showLabels && (
                  <text
                    x={node.x}
                    y={node.y + radius + 14}
                    textAnchor="middle"
                    className={cn(
                      "fill-foreground text-[10px] transition-opacity duration-200",
                      hoveredNode && !isHovered && "opacity-30"
                    )}
                  >
                    {node.label ?? node.id}
                  </text>
                )}
              </g>
            )
          })}
        </g>
      </svg>

      {/* Legend */}
      {groups.length > 1 && (
        <div className="mt-3 flex flex-wrap justify-center gap-4">
          {groups.map((group) => (
            <div key={group} className="flex items-center gap-1.5 text-sm">
              <div
                className="h-3 w-3 rounded-full"
                style={{ backgroundColor: getGroupColor(group) }}
              />
              <span className="text-muted-foreground">{group}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

"use client"

import * as React from "react"
import { cluster, hierarchy } from "d3-hierarchy"
import { linkHorizontal, linkVertical } from "d3-shape"

import { cn } from "@/lib/utils"

export interface DendrogramNode {
  name: string
  value?: number
  children?: DendrogramNode[]
  color?: string
}

export interface DendrogramProps {
  data: DendrogramNode
  className?: string
  orientation?: "horizontal" | "vertical"
  nodeRadius?: number
  showLabels?: boolean
  showValues?: boolean
  linkColor?: string
  colorScheme?: string[]
}

export function Dendrogram({
  data,
  className,
  orientation = "horizontal",
  nodeRadius = 5,
  showLabels = true,
  showValues = false,
  linkColor = "var(--muted)",
  colorScheme = [
    "var(--chart-5)",
    "var(--chart-4)",
    "var(--chart-3)",
    "var(--chart-2)",
    "var(--chart-1)",
  ],
}: DendrogramProps) {
  const [hoveredNode, setHoveredNode] = React.useState<string | null>(null)

  const isHorizontal = orientation === "horizontal"
  const width = isHorizontal ? 600 : 400
  const height = isHorizontal ? 400 : 500
  const margin = isHorizontal
    ? { top: 20, right: 120, bottom: 20, left: 40 }
    : { top: 40, right: 20, bottom: 120, left: 20 }

  const innerWidth = width - margin.left - margin.right
  const innerHeight = height - margin.top - margin.bottom

  // Create hierarchy and apply cluster layout
  const root = React.useMemo(() => {
    const h = hierarchy(data)
    const clusterLayout = cluster<DendrogramNode>().size(
      isHorizontal ? [innerHeight, innerWidth] : [innerWidth, innerHeight]
    )

    return clusterLayout(h)
  }, [data, innerWidth, innerHeight, isHorizontal])

  // Get all nodes and links
  const nodes = root.descendants()
  const links = root.links()

  // Link generator
  const linkGenerator = isHorizontal
    ? linkHorizontal<any, any>()
        .x((d: any) => d.y)
        .y((d: any) => d.x)
    : linkVertical<any, any>()
        .x((d: any) => d.x)
        .y((d: any) => d.y)

  // Get color based on depth
  const getNodeColor = (depth: number) => {
    return colorScheme[depth % colorScheme.length]
  }

  // Check if node or any of its descendants is hovered
  const isNodeHighlighted = (node: (typeof nodes)[number]): boolean => {
    if (node.data.name === hoveredNode) return true
    if (node.ancestors().some((a) => a.data.name === hoveredNode)) return true
    if (node.descendants().some((d) => d.data.name === hoveredNode)) return true
    return false
  }

  return (
    <div className={cn("w-full", className)}>
      <svg
        viewBox={`0 0 ${width} ${height}`}
        className="h-auto w-full overflow-visible"
      >
        <g transform={`translate(${margin.left}, ${margin.top})`}>
          {/* Links */}
          {links.map((link, index) => {
            const isHighlighted =
              hoveredNode === null ||
              isNodeHighlighted(link.source) ||
              isNodeHighlighted(link.target)

            return (
              <path
                key={`link-${index}`}
                d={linkGenerator(link) ?? ""}
                fill="none"
                stroke={linkColor}
                strokeWidth={isHighlighted ? 2 : 1}
                strokeOpacity={
                  hoveredNode === null ? 0.6 : isHighlighted ? 1 : 0.15
                }
                className="transition-all duration-200"
              />
            )
          })}

          {/* Nodes */}
          {nodes.map((node, index) => {
            const x = isHorizontal ? node.y : node.x
            const y = isHorizontal ? node.x : node.y
            const isLeaf = !node.children
            const color = node.data.color ?? getNodeColor(node.depth)
            const isHovered = hoveredNode === node.data.name
            const isHighlighted =
              hoveredNode === null || isNodeHighlighted(node)

            return (
              <g
                key={`node-${index}`}
                transform={`translate(${x}, ${y})`}
                className={cn(
                  "cursor-pointer transition-opacity duration-200",
                  !isHighlighted && "opacity-20"
                )}
                onMouseEnter={() => setHoveredNode(node.data.name)}
                onMouseLeave={() => setHoveredNode(null)}
              >
                <circle
                  r={isHovered ? nodeRadius * 1.5 : nodeRadius}
                  fill={isLeaf ? color : "#fff"}
                  stroke={color}
                  strokeWidth={2}
                  className="transition-all duration-200"
                />

                {showLabels && (
                  <text
                    x={isHorizontal ? (isLeaf ? 10 : -10) : 0}
                    y={isHorizontal ? 0 : isLeaf ? 15 : -15}
                    textAnchor={
                      isHorizontal ? (isLeaf ? "start" : "end") : "middle"
                    }
                    dominantBaseline={
                      isHorizontal ? "middle" : isLeaf ? "hanging" : "auto"
                    }
                    className="fill-foreground text-[11px]"
                  >
                    {node.data.name}
                  </text>
                )}

                {showValues && node.data.value !== undefined && (
                  <text
                    x={isHorizontal ? (isLeaf ? 10 : -10) : 0}
                    y={isHorizontal ? 12 : isLeaf ? 28 : -28}
                    textAnchor={
                      isHorizontal ? (isLeaf ? "start" : "end") : "middle"
                    }
                    className="fill-muted-foreground text-[9px]"
                  >
                    {node.data.value}
                  </text>
                )}
              </g>
            )
          })}
        </g>
      </svg>

      {/* Tooltip */}
      {hoveredNode && (
        <div className="mt-2 text-center">
          <div className="border-border/50 bg-background mx-auto inline-block rounded-lg border px-3 py-2 text-sm shadow-lg">
            <div className="font-medium">{hoveredNode}</div>
            {nodes.find((n) => n.data.name === hoveredNode)?.data.value !==
              undefined && (
              <div className="text-muted-foreground">
                Value:{" "}
                {nodes.find((n) => n.data.name === hoveredNode)?.data.value}
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  )
}

"use client"

import * as React from "react"
import { scaleLinear } from "d3-scale"

import { cn } from "@/lib/utils"

export interface SplomDataPoint {
  id: string
  values: Record<string, number>
  group?: string
}

export interface SplomChartProps {
  data: SplomDataPoint[]
  dimensions: string[]
  className?: string
  /** Visual style variant: standard (full matrix), upper (triangle), compact (smaller cells) */
  variant?: "standard" | "upper" | "compact"
  /** Size of each cell in pixels (auto-adjusted for compact variant) */
  cellSize?: number
  /** Radius of scatter points */
  pointRadius?: number
  /** Show dimension labels on axes */
  showLabels?: boolean
  /** Show histograms on diagonal (standard/upper variants only) */
  showHistograms?: boolean
  /** Number of histogram bins */
  histogramBins?: number
  /** Single color for all points */
  color?: string
  /** Color scheme for groups (when using group property) */
  colorScheme?: string[]
  /** Custom value formatter */
  valueFormatter?: (value: number) => string
}

const DEFAULT_COLOR = "var(--chart-1)"

const DEFAULT_COLOR_SCHEME = [
  "var(--chart-1)",
  "var(--chart-2)",
  "var(--chart-3)",
  "var(--chart-4)",
  "var(--chart-5)",
]

export function SplomChart({
  data,
  dimensions,
  className,
  variant = "standard",
  cellSize: propCellSize,
  pointRadius: propPointRadius,
  showLabels = true,
  showHistograms: propShowHistograms,
  histogramBins = 10,
  color,
  colorScheme = DEFAULT_COLOR_SCHEME,
  valueFormatter = (v) => v.toFixed(1),
}: SplomChartProps) {
  const [hoveredPoint, setHoveredPoint] = React.useState<string | null>(null)
  const [tooltipPos, setTooltipPos] = React.useState({ x: 0, y: 0 })
  const [activeGroup, setActiveGroup] = React.useState<string | null>(null)
  const containerRef = React.useRef<HTMLDivElement>(null)

  // Variant-specific defaults
  const getVariantDefaults = () => {
    switch (variant) {
      case "compact":
        return { cellSize: 60, pointRadius: 2, showHistograms: false }
      case "upper":
        return { cellSize: 100, pointRadius: 3, showHistograms: true }
      case "standard":
      default:
        return { cellSize: 100, pointRadius: 3, showHistograms: true }
    }
  }

  const defaults = getVariantDefaults()
  const cellSize = propCellSize ?? defaults.cellSize
  const pointRadius = propPointRadius ?? defaults.pointRadius
  const showHistograms = propShowHistograms ?? defaults.showHistograms

  const n = dimensions.length
  const cellPadding = variant === "compact" ? 8 : 15
  const margin = { top: 20, right: 20, bottom: 30, left: 50 }
  const matrixSize = n * cellSize
  const width = matrixSize + margin.left + margin.right
  const height = matrixSize + margin.top + margin.bottom

  // Get unique groups
  const groups = React.useMemo(() => {
    return [...new Set(data.map((d) => d.group ?? "default"))]
  }, [data])

  const getColor = (group?: string) => {
    if (color) return color
    if (groups.length === 1) return DEFAULT_COLOR
    const index = groups.indexOf(group ?? "default")
    return colorScheme[index % colorScheme.length]
  }

  const isGroupVisible = (group?: string) =>
    activeGroup === null || activeGroup === (group ?? "default")

  // Create scales for each dimension
  const scales = React.useMemo(() => {
    const result: Record<
      string,
      ReturnType<typeof scaleLinear<number, number>>
    > = {}

    dimensions.forEach((dim) => {
      const values = data
        .map((d) => d.values[dim])
        .filter((v) => v !== undefined)
      const min = Math.min(...values)
      const max = Math.max(...values)
      const pad = (max - min) * 0.1 || 1

      result[dim] = scaleLinear()
        .domain([min - pad, max + pad])
        .range([cellPadding, cellSize - cellPadding])
    })

    return result
  }, [data, dimensions, cellSize])

  // Generate histogram data for diagonal cells
  const getHistogramData = (dim: string) => {
    const values = data.map((d) => d.values[dim]).filter((v) => v !== undefined)
    const min = Math.min(...values)
    const max = Math.max(...values)
    const binWidth = (max - min) / histogramBins

    const bins = Array(histogramBins).fill(0) as number[]
    values.forEach((v) => {
      const binIndex = Math.min(
        Math.floor((v - min) / binWidth),
        histogramBins - 1
      )
      bins[binIndex]++
    })

    const maxBinCount = Math.max(...bins)
    return { bins, min, max, binWidth, maxBinCount }
  }

  // Determine if cell should be rendered based on variant
  const shouldRenderCell = (row: number, col: number): boolean => {
    if (variant === "upper") return col > row
    return true // standard and compact render all cells
  }

  // Determine if diagonal should be rendered
  const shouldRenderDiagonal = (): boolean => {
    return true // All variants render diagonal
  }

  const handleMouseMove = (e: React.MouseEvent, pointId: string) => {
    if (containerRef.current) {
      const rect = containerRef.current.getBoundingClientRect()
      setTooltipPos({
        x: e.clientX - rect.left,
        y: e.clientY - rect.top,
      })
    }
    setHoveredPoint(pointId)
  }

  if (!data || data.length === 0) {
    return (
      <div
        className={cn(
          "text-muted-foreground flex h-[400px] items-center justify-center",
          className
        )}
      >
        No data available
      </div>
    )
  }

  return (
    <div ref={containerRef} className={cn("relative w-full", className)}>
      {/* Legend — click a group to isolate it (hides other groups' points
          across every matrix cell), click again to restore all */}
      {groups.length > 1 && !color && (
        <div className="mb-4 flex flex-wrap items-center justify-center gap-x-6 gap-y-2">
          {groups.map((group) => (
            <button
              key={group}
              type="button"
              aria-pressed={!isGroupVisible(group)}
              onClick={() =>
                setActiveGroup((prev) => (prev === group ? null : group))
              }
              className={cn(
                "flex cursor-pointer items-center gap-2 transition-opacity hover:opacity-80",
                !isGroupVisible(group) && "opacity-40"
              )}
            >
              <div
                className="h-3 w-3 rounded-full"
                style={{ backgroundColor: getColor(group) }}
              />
              <span className="text-muted-foreground text-sm">{group}</span>
            </button>
          ))}
        </div>
      )}

      <svg
        viewBox={`0 0 ${width} ${height}`}
        className="h-auto w-full overflow-visible"
      >
        <g transform={`translate(${margin.left}, ${margin.top})`}>
          {/* Matrix cells */}
          {dimensions.map((yDim, row) =>
            dimensions.map((xDim, col) => {
              const x = col * cellSize
              const y = row * cellSize

              // Skip cells based on variant
              if (!shouldRenderCell(row, col) && row !== col) return null

              // Diagonal: histogram or label
              if (row === col) {
                if (!shouldRenderDiagonal()) return null

                if (showHistograms) {
                  const { bins, maxBinCount } = getHistogramData(xDim)
                  const barWidth = (cellSize - 2 * cellPadding) / bins.length
                  const heightScale =
                    maxBinCount > 0
                      ? (cellSize - 2 * cellPadding) / maxBinCount
                      : 0

                  return (
                    <g
                      key={`${row}-${col}`}
                      transform={`translate(${x}, ${y})`}
                    >
                      {/* Cell background */}
                      <rect
                        x={0}
                        y={0}
                        width={cellSize}
                        height={cellSize}
                        fill="#f8fafc"
                        stroke="#e2e8f0"
                        strokeWidth={1}
                        className="dark:fill-zinc-900 dark:stroke-zinc-700"
                      />
                      {/* Histogram bars */}
                      {bins.map((count, i) => (
                        <rect
                          key={i}
                          x={cellPadding + i * barWidth + 1}
                          y={cellSize - cellPadding - count * heightScale}
                          width={Math.max(0, barWidth - 2)}
                          height={count * heightScale}
                          fill={color ?? DEFAULT_COLOR}
                          fillOpacity={0.5}
                        />
                      ))}
                      {/* Dimension label */}
                      <text
                        x={cellSize / 2}
                        y={cellSize / 2}
                        textAnchor="middle"
                        dominantBaseline="middle"
                        className="fill-foreground text-[10px] font-medium"
                      >
                        {xDim}
                      </text>
                    </g>
                  )
                }

                // Just label without histogram
                return (
                  <g key={`${row}-${col}`} transform={`translate(${x}, ${y})`}>
                    <rect
                      x={0}
                      y={0}
                      width={cellSize}
                      height={cellSize}
                      fill="#f8fafc"
                      stroke="#e2e8f0"
                      strokeWidth={1}
                      className="dark:fill-zinc-900 dark:stroke-zinc-700"
                    />
                    <text
                      x={cellSize / 2}
                      y={cellSize / 2}
                      textAnchor="middle"
                      dominantBaseline="middle"
                      className="fill-foreground text-xs font-medium"
                    >
                      {xDim}
                    </text>
                  </g>
                )
              }

              // Skip off-diagonal cells for upper/lower variants
              if (!shouldRenderCell(row, col)) return null

              // Off-diagonal: scatter plot
              return (
                <g key={`${row}-${col}`} transform={`translate(${x}, ${y})`}>
                  {/* Cell background */}
                  <rect
                    x={0}
                    y={0}
                    width={cellSize}
                    height={cellSize}
                    fill="white"
                    stroke="#e2e8f0"
                    strokeWidth={1}
                    className="dark:fill-zinc-950 dark:stroke-zinc-700"
                  />
                  {/* Points — points belonging to a group hidden via legend
                      isolate are fully skipped, not just dimmed */}
                  {data.map((d) => {
                    const xVal = d.values[xDim]
                    const yVal = d.values[yDim]
                    if (xVal === undefined || yVal === undefined) return null
                    if (!isGroupVisible(d.group)) return null

                    const cx = scales[xDim](xVal)
                    const cy = cellSize - scales[yDim](yVal) + cellPadding
                    const pointColor = getColor(d.group)
                    const isHovered = hoveredPoint === d.id

                    return (
                      <circle
                        key={d.id}
                        cx={cx}
                        cy={cy}
                        r={isHovered ? pointRadius * 1.5 : pointRadius}
                        fill={pointColor}
                        fillOpacity={
                          hoveredPoint === null ? 0.7 : isHovered ? 1 : 0.15
                        }
                        className="cursor-pointer transition-all duration-150"
                        onMouseMove={(e) => handleMouseMove(e, d.id)}
                        onMouseLeave={() => setHoveredPoint(null)}
                      />
                    )
                  })}
                </g>
              )
            })
          )}

          {/* Row labels (left) */}
          {showLabels &&
            dimensions.map((dim, i) => (
              <text
                key={`row-${i}`}
                x={-12}
                y={i * cellSize + cellSize / 2}
                textAnchor="end"
                dominantBaseline="middle"
                className="fill-muted-foreground text-[11px]"
              >
                {dim}
              </text>
            ))}

          {/* Column labels (bottom) */}
          {showLabels &&
            dimensions.map((dim, i) => (
              <text
                key={`col-${i}`}
                x={i * cellSize + cellSize / 2}
                y={matrixSize + 20}
                textAnchor="middle"
                className="fill-muted-foreground text-[11px]"
              >
                {dim}
              </text>
            ))}
        </g>
      </svg>

      {/* Tooltip */}
      {hoveredPoint && (
        <div
          className="bg-foreground text-background pointer-events-none absolute z-50 -translate-x-1/2 -translate-y-full rounded-lg px-3 py-2 text-xs shadow-lg"
          style={{ left: tooltipPos.x, top: tooltipPos.y - 10 }}
        >
          <div className="mb-1 font-semibold">{hoveredPoint}</div>
          <div className="grid grid-cols-2 gap-x-3 gap-y-0.5 opacity-90">
            {dimensions.map((dim) => {
              const item = data.find((d) => d.id === hoveredPoint)
              return (
                <React.Fragment key={dim}>
                  <span>{dim}:</span>
                  <span>{valueFormatter(item?.values[dim] ?? 0)}</span>
                </React.Fragment>
              )
            })}
          </div>
        </div>
      )}
    </div>
  )
}

"use client"

import * as React from "react"
import { scaleBand, scalePoint } from "d3-scale"

import { cn } from "@/lib/utils"

export interface ParcatsDataPoint {
  id: string
  categories: Record<string, string>
  value?: number
}

export interface ParcatsChartProps {
  data: ParcatsDataPoint[]
  dimensions: string[]
  className?: string
  /** Visual style variant: standard (uniform width), ribbon (proportional to value) */
  variant?: "standard" | "ribbon"
  /** Show category counts */
  showCounts?: boolean
  /** Flow line opacity (0-1) */
  lineOpacity?: number
  /** Single color for all flows */
  color?: string
  /** Color by first dimension categories */
  colorByCategory?: boolean
  /** Color scheme for categories */
  colorScheme?: string[]
}

const DEFAULT_COLOR = "var(--chart-1)"

const DEFAULT_COLOR_SCHEME = [
  "var(--chart-1)",
  "var(--chart-2)",
  "var(--chart-3)",
  "var(--chart-4)",
  "var(--chart-5)",
]

export function ParcatsChart({
  data,
  dimensions,
  className,
  variant = "standard",
  showCounts = true,
  lineOpacity = 0.5,
  color,
  colorByCategory = false,
  colorScheme = DEFAULT_COLOR_SCHEME,
}: ParcatsChartProps) {
  const [hoveredPath, setHoveredPath] = React.useState<string | null>(null)
  const [hoveredCategory, setHoveredCategory] = React.useState<{
    dim: string
    cat: string
  } | null>(null)
  // Pinned category — set by clicking a category box (or legend swatch),
  // keeps only ribbons passing through it highlighted until clicked again.
  const [pinnedCategory, setPinnedCategory] = React.useState<{
    dim: string
    cat: string
  } | null>(null)
  const [tooltipPos, setTooltipPos] = React.useState({ x: 0, y: 0 })
  const containerRef = React.useRef<HTMLDivElement>(null)

  // Dynamic width based on dimensions
  const width = Math.max(400, dimensions.length * 150)
  // Dynamic height based on max categories
  const maxCategories = React.useMemo(() => {
    let max = 0
    dimensions.forEach((dim) => {
      const cats = new Set(data.map((d) => d.categories[dim]))
      max = Math.max(max, cats.size)
    })
    return max
  }, [data, dimensions])
  const height = Math.max(300, maxCategories * 45 + 80)
  const margin = { top: 40, right: 40, bottom: 30, left: 40 }
  const innerWidth = width - margin.left - margin.right
  const innerHeight = height - margin.top - margin.bottom

  // Calculate value extent for ribbon width scaling
  const valueExtent = React.useMemo(() => {
    if (variant !== "ribbon") return { min: 1, max: 1 }
    const values = data.map((d) => d.value ?? 1)
    return { min: Math.min(...values), max: Math.max(...values) }
  }, [data, variant])

  // Get stroke width based on value (for ribbon variant)
  const getStrokeWidth = (
    value: number | undefined,
    highlighted: boolean
  ): number => {
    if (variant !== "ribbon") {
      return highlighted ? 2.5 : 1.5
    }
    const v = value ?? 1
    const range = valueExtent.max - valueExtent.min || 1
    const normalized = (v - valueExtent.min) / range
    const baseWidth = 2 + normalized * 16 // Range: 2-18px
    return highlighted ? baseWidth * 1.2 : baseWidth
  }

  // Get unique categories for each dimension
  const categoryData = React.useMemo(() => {
    const result: Record<string, string[]> = {}
    dimensions.forEach((dim) => {
      result[dim] = [...new Set(data.map((d) => d.categories[dim]))].sort()
    })
    return result
  }, [data, dimensions])

  // Get first dimension categories for coloring
  const firstDimCategories = categoryData[dimensions[0]] ?? []

  const getCategoryColor = (category: string) => {
    if (color) return color
    if (!colorByCategory) return DEFAULT_COLOR
    const index = firstDimCategories.indexOf(category)
    return colorScheme[index % colorScheme.length]
  }

  const getPathColor = (d: ParcatsDataPoint) => {
    if (color) return color
    if (colorByCategory) {
      return getCategoryColor(d.categories[dimensions[0]])
    }
    return DEFAULT_COLOR
  }

  // X scale for dimensions
  const xScale = scalePoint<string>().domain(dimensions).range([0, innerWidth])

  // Y scales for each dimension (band scale for categories)
  const yScales = React.useMemo(() => {
    const scales: Record<string, ReturnType<typeof scaleBand<string>>> = {}

    dimensions.forEach((dim) => {
      scales[dim] = scaleBand<string>()
        .domain(categoryData[dim])
        .range([0, innerHeight])
        .padding(0.15)
    })

    return scales
  }, [dimensions, categoryData, innerHeight])

  // Count occurrences for each category
  const categoryCounts = React.useMemo(() => {
    const counts: Record<string, Record<string, number>> = {}
    dimensions.forEach((dim) => {
      counts[dim] = {}
      categoryData[dim].forEach((cat) => {
        counts[dim][cat] = data.filter((d) => d.categories[dim] === cat).length
      })
    })
    return counts
  }, [data, dimensions, categoryData])

  // Generate paths for each data point
  const paths = React.useMemo(() => {
    return data.map((d) => {
      const points = dimensions.map((dim) => {
        const x = xScale(dim) ?? 0
        const yBand = yScales[dim]
        const cat = d.categories[dim]
        const y = (yBand(cat) ?? 0) + yBand.bandwidth() / 2
        return { x, y }
      })

      // Create smooth bezier curve path
      let pathD = `M ${points[0].x} ${points[0].y}`
      for (let i = 1; i < points.length; i++) {
        const prev = points[i - 1]
        const curr = points[i]
        const midX = (prev.x + curr.x) / 2
        pathD += ` C ${midX} ${prev.y}, ${midX} ${curr.y}, ${curr.x} ${curr.y}`
      }

      return {
        id: d.id,
        d: pathD,
        color: getPathColor(d),
        categories: d.categories,
        value: d.value,
      }
    })
  }, [data, dimensions, xScale, yScales, color, colorByCategory])

  // Toggle the pinned category — clicking the same category again restores
  // all ribbons.
  const togglePinnedCategory = React.useCallback((dim: string, cat: string) => {
    setPinnedCategory((prev) =>
      prev?.dim === dim && prev?.cat === cat ? null : { dim, cat }
    )
  }, [])

  // Check if path matches the pinned category (takes priority so hovering
  // elsewhere doesn't clear the pin) or the hovered path/category.
  const isPathHighlighted = (path: (typeof paths)[0]) => {
    if (pinnedCategory) {
      return path.categories[pinnedCategory.dim] === pinnedCategory.cat
    }
    if (hoveredPath === path.id) return true
    if (hoveredCategory) {
      return path.categories[hoveredCategory.dim] === hoveredCategory.cat
    }
    return false
  }

  const handleMouseMove = (e: React.MouseEvent, pathId: string) => {
    if (containerRef.current) {
      const rect = containerRef.current.getBoundingClientRect()
      setTooltipPos({
        x: e.clientX - rect.left,
        y: e.clientY - rect.top,
      })
    }
    setHoveredPath(pathId)
  }

  if (!data || data.length === 0) {
    return (
      <div
        className={cn(
          "text-muted-foreground flex h-[380px] items-center justify-center",
          className
        )}
      >
        No data available
      </div>
    )
  }

  return (
    <div ref={containerRef} className={cn("relative w-full", className)}>
      {/* Legend - only show when colorByCategory is true. Click a swatch to
          pin/isolate that category's ribbons, click again to restore all. */}
      {colorByCategory && !color && (
        <div className="mb-4 flex flex-wrap items-center justify-center gap-x-6 gap-y-2">
          {firstDimCategories.map((cat) => {
            const isActive =
              !pinnedCategory ||
              (pinnedCategory.dim === dimensions[0] &&
                pinnedCategory.cat === cat)
            return (
              <button
                key={cat}
                type="button"
                aria-pressed={
                  pinnedCategory?.dim === dimensions[0] &&
                  pinnedCategory?.cat === cat
                }
                onClick={() => togglePinnedCategory(dimensions[0], cat)}
                className={cn(
                  "flex cursor-pointer items-center gap-2 transition-opacity hover:opacity-80",
                  !isActive && "opacity-40"
                )}
              >
                <div
                  className="h-3 w-3 rounded-full"
                  style={{ backgroundColor: getCategoryColor(cat) }}
                />
                <span className="text-muted-foreground text-sm">{cat}</span>
              </button>
            )
          })}
        </div>
      )}

      <svg
        viewBox={`0 0 ${width} ${height}`}
        className="h-auto w-full overflow-visible"
      >
        <g transform={`translate(${margin.left}, ${margin.top})`}>
          {/* Flow paths - render first so they appear behind boxes */}
          {paths.map((path) => {
            const hasHighlight =
              pinnedCategory !== null ||
              hoveredPath !== null ||
              hoveredCategory !== null
            const highlighted = hasHighlight ? isPathHighlighted(path) : true

            return (
              <path
                key={path.id}
                d={path.d}
                fill="none"
                stroke={path.color}
                strokeWidth={getStrokeWidth(path.value, highlighted)}
                strokeOpacity={
                  hasHighlight ? (highlighted ? 0.85 : 0.08) : lineOpacity
                }
                strokeLinecap="round"
                className="cursor-pointer transition-all duration-150"
                onMouseMove={(e) => handleMouseMove(e, path.id)}
                onMouseLeave={() => setHoveredPath(null)}
              />
            )
          })}

          {/* Category rectangles and labels */}
          {dimensions.map((dim) => {
            const x = xScale(dim) ?? 0
            const yBand = yScales[dim]

            return (
              <g key={dim}>
                {/* Dimension label */}
                <text
                  x={x}
                  y={-18}
                  textAnchor="middle"
                  className="fill-foreground text-xs font-medium"
                >
                  {dim}
                </text>

                {/* Category boxes */}
                {categoryData[dim].map((cat) => {
                  const y = yBand(cat) ?? 0
                  const h = yBand.bandwidth()
                  const count = categoryCounts[dim][cat]
                  const isHovered =
                    hoveredCategory?.dim === dim && hoveredCategory?.cat === cat
                  const isPinned =
                    pinnedCategory?.dim === dim && pinnedCategory?.cat === cat
                  const isActive = isHovered || isPinned

                  const boxColor =
                    colorByCategory && dim === dimensions[0]
                      ? getCategoryColor(cat)
                      : "var(--muted)"

                  return (
                    <g
                      key={`${dim}-${cat}`}
                      className="cursor-pointer"
                      onMouseEnter={() => setHoveredCategory({ dim, cat })}
                      onMouseLeave={() => setHoveredCategory(null)}
                      onClick={() => togglePinnedCategory(dim, cat)}
                    >
                      <rect
                        x={x - 35}
                        y={y}
                        width={70}
                        height={h}
                        fill={boxColor}
                        fillOpacity={isActive ? 1 : 0.85}
                        stroke={
                          isActive ? "var(--muted-foreground)" : "var(--border)"
                        }
                        strokeWidth={isActive ? 2 : 1}
                        rx={4}
                        className="transition-all duration-150 dark:fill-zinc-800 dark:stroke-zinc-600"
                      />
                      <text
                        x={x}
                        y={y + h / 2 - (showCounts ? 5 : 0)}
                        textAnchor="middle"
                        dominantBaseline="middle"
                        className="fill-foreground pointer-events-none text-[11px] font-medium"
                      >
                        {cat}
                      </text>
                      {showCounts && (
                        <text
                          x={x}
                          y={y + h / 2 + 10}
                          textAnchor="middle"
                          dominantBaseline="middle"
                          className="fill-muted-foreground pointer-events-none text-[9px]"
                        >
                          ({count})
                        </text>
                      )}
                    </g>
                  )
                })}
              </g>
            )
          })}
        </g>
      </svg>

      {/* Tooltip */}
      {hoveredPath && (
        <div
          className="bg-foreground text-background pointer-events-none absolute z-50 -translate-x-1/2 -translate-y-full rounded-lg px-3 py-2 text-xs shadow-lg"
          style={{ left: tooltipPos.x, top: tooltipPos.y - 10 }}
        >
          <div className="mb-1 font-semibold">{hoveredPath}</div>
          <div className="flex items-center gap-1 opacity-90">
            {dimensions.map((dim, i) => (
              <React.Fragment key={dim}>
                <span>
                  {paths.find((p) => p.id === hoveredPath)?.categories[dim]}
                </span>
                {i < dimensions.length - 1 && (
                  <span className="opacity-50">→</span>
                )}
              </React.Fragment>
            ))}
          </div>
        </div>
      )}
    </div>
  )
}

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

export interface TernaryDataPoint {
  id: string
  a: number // Bottom-left axis (0-100 or 0-1)
  b: number // Bottom-right axis
  c: number // Top axis
  label?: string
  color?: string
  group?: string
  size?: number
}

export interface TernaryChartProps {
  data: TernaryDataPoint[]
  className?: string
  /** Visual style variant: standard (full grid), minimal (points only), filled (convex hull) */
  variant?: "standard" | "minimal" | "filled"
  /** Axis labels [A, B, C] */
  labels?: [string, string, string]
  /** Show grid lines */
  showGrid?: boolean
  /** Show axis labels */
  showLabels?: boolean
  /** Show tick value labels on axes */
  showTickValues?: boolean
  /** Number of grid divisions */
  gridLines?: number
  /** Data point radius */
  pointRadius?: number
  /** Single color for all points (overrides group colors) */
  color?: string
  /** Enable coloring by group */
  colorByGroup?: boolean
  /** Color scheme for groups when colorByGroup is true */
  colorScheme?: string[]
  /** Auto-normalize values to sum=1 */
  normalize?: boolean
}

const DEFAULT_COLOR = "#3b82f6"

const DEFAULT_COLOR_SCHEME = [
  "#3b82f6",
  "#10b981",
  "#f59e0b",
  "#ef4444",
  "#8b5cf6",
]

export function TernaryChart({
  data,
  className,
  variant = "standard",
  labels = ["A", "B", "C"],
  showGrid = true,
  showLabels = true,
  showTickValues = true,
  gridLines = 5,
  pointRadius = 6,
  color,
  colorByGroup = false,
  colorScheme = DEFAULT_COLOR_SCHEME,
  normalize = true,
}: TernaryChartProps) {
  const [hoveredPoint, setHoveredPoint] = React.useState<string | null>(null)
  const [tooltipPos, setTooltipPos] = React.useState({ x: 0, y: 0 })
  // Isolated group — set by clicking a legend swatch, hides points outside
  // that group until clicked again.
  const [isolatedGroup, setIsolatedGroup] = React.useState<string | null>(null)
  const containerRef = React.useRef<HTMLDivElement>(null)

  const width = 500
  const height = 450
  const margin = { top: 50, right: 50, bottom: 70, left: 50 }

  // Triangle dimensions
  const triangleHeight = height - margin.top - margin.bottom
  const triangleWidth = triangleHeight * (2 / Math.sqrt(3))
  const centerX = width / 2
  const topY = margin.top
  const bottomY = margin.top + triangleHeight

  // Triangle vertices
  const vertices = React.useMemo(
    () => ({
      top: { x: centerX, y: topY }, // C vertex
      bottomLeft: { x: centerX - triangleWidth / 2, y: bottomY }, // A vertex
      bottomRight: { x: centerX + triangleWidth / 2, y: bottomY }, // B vertex
    }),
    [centerX, topY, bottomY, triangleWidth]
  )

  // Get unique groups
  const groups = React.useMemo(() => {
    return [...new Set(data.map((d) => d.group ?? "default"))]
  }, [data])

  const getGroupColor = React.useCallback(
    (group?: string) => {
      if (color) return color
      if (!colorByGroup) return DEFAULT_COLOR
      const index = groups.indexOf(group ?? "default")
      return colorScheme[index % colorScheme.length]
    },
    [color, colorByGroup, groups, colorScheme]
  )

  const isGroupVisible = React.useCallback(
    (group?: string) =>
      isolatedGroup === null || isolatedGroup === (group ?? "default"),
    [isolatedGroup]
  )

  // Toggle the isolated group — clicking the same legend entry again
  // restores all groups.
  const toggleIsolatedGroup = React.useCallback((group: string) => {
    setIsolatedGroup((prev) => (prev === group ? null : group))
  }, [])

  // Points currently visible under the active isolation (all points when
  // nothing is isolated). Used for both rendering and the convex hull so
  // the filled variant reflects the isolated subset.
  const visibleData = React.useMemo(
    () => data.filter((d) => isGroupVisible(d.group)),
    [data, isGroupVisible]
  )

  // Convert ternary coordinates to Cartesian
  const ternaryToCartesian = React.useCallback(
    (a: number, b: number, c: number) => {
      // Normalize if needed
      const sum = a + b + c
      const na = normalize ? a / sum : a
      const nb = normalize ? b / sum : b
      const nc = normalize ? c / sum : c

      // Ternary to Cartesian transformation
      const x =
        vertices.bottomLeft.x +
        nb * (vertices.bottomRight.x - vertices.bottomLeft.x) +
        nc * (vertices.top.x - vertices.bottomLeft.x)
      const y =
        vertices.bottomLeft.y + nc * (vertices.top.y - vertices.bottomLeft.y)

      return { x, y }
    },
    [normalize, vertices]
  )

  // Generate grid lines
  const gridLineData = React.useMemo(() => {
    const lines: { x1: number; y1: number; x2: number; y2: number }[] = []

    for (let i = 1; i < gridLines; i++) {
      const t = i / gridLines

      // Lines parallel to bottom edge (constant C)
      const c1Start = ternaryToCartesian(1 - t, 0, t)
      const c1End = ternaryToCartesian(0, 1 - t, t)
      lines.push({ x1: c1Start.x, y1: c1Start.y, x2: c1End.x, y2: c1End.y })

      // Lines parallel to left edge (constant B)
      const b1Start = ternaryToCartesian(1 - t, t, 0)
      const b1End = ternaryToCartesian(0, t, 1 - t)
      lines.push({ x1: b1Start.x, y1: b1Start.y, x2: b1End.x, y2: b1End.y })

      // Lines parallel to right edge (constant A)
      const a1Start = ternaryToCartesian(t, 1 - t, 0)
      const a1End = ternaryToCartesian(t, 0, 1 - t)
      lines.push({ x1: a1Start.x, y1: a1Start.y, x2: a1End.x, y2: a1End.y })
    }

    return lines
  }, [gridLines, ternaryToCartesian])

  // Generate tick labels
  const tickLabels = React.useMemo(() => {
    const ticks: { x: number; y: number; value: string; anchor: string }[] = []

    for (let i = 0; i <= gridLines; i++) {
      const t = i / gridLines
      const value = Math.round(t * 100)

      // A axis (bottom-left to top)
      const aPos = ternaryToCartesian(1 - t, 0, t)
      ticks.push({
        x: aPos.x - 15,
        y: aPos.y,
        value: `${value}`,
        anchor: "end",
      })

      // B axis (bottom-left to bottom-right)
      const bPos = ternaryToCartesian(1 - t, t, 0)
      ticks.push({
        x: bPos.x,
        y: bPos.y + 18,
        value: `${value}`,
        anchor: "middle",
      })

      // C axis (top to bottom-right)
      const cPos = ternaryToCartesian(0, 1 - t, t)
      ticks.push({
        x: cPos.x + 15,
        y: cPos.y,
        value: `${value}`,
        anchor: "start",
      })
    }

    return ticks
  }, [gridLines, ternaryToCartesian])

  // Calculate convex hull for filled variant
  const convexHullPath = React.useMemo(() => {
    if (variant !== "filled" || visibleData.length < 3) return null

    const points = visibleData.map((d) => ternaryToCartesian(d.a, d.b, d.c))

    // Simple convex hull using gift wrapping algorithm
    const hull: typeof points = []
    let pointOnHull = points.reduce((lowest, p) =>
      p.y > lowest.y ? p : lowest
    )
    let startPoint = pointOnHull
    let endpoint: (typeof points)[0]

    do {
      hull.push(pointOnHull)
      endpoint = points[0]

      for (const point of points) {
        if (
          endpoint === pointOnHull ||
          cross(pointOnHull, endpoint, point) < 0
        ) {
          endpoint = point
        }
      }

      pointOnHull = endpoint
    } while (endpoint !== startPoint && hull.length < points.length)

    if (hull.length < 3) return null

    return (
      hull.map((p, i) => `${i === 0 ? "M" : "L"} ${p.x} ${p.y}`).join(" ") +
      " Z"
    )
  }, [variant, visibleData, ternaryToCartesian])

  // Cross product helper for convex hull
  function cross(
    o: { x: number; y: number },
    a: { x: number; y: number },
    b: { x: number; y: number }
  ) {
    return (a.x - o.x) * (b.y - o.y) - (a.y - o.y) * (b.x - o.x)
  }

  const handleMouseMove = (e: React.MouseEvent, pointId: string) => {
    if (containerRef.current) {
      const rect = containerRef.current.getBoundingClientRect()
      setTooltipPos({
        x: e.clientX - rect.left,
        y: e.clientY - rect.top,
      })
    }
    setHoveredPoint(pointId)
  }

  if (!data || data.length === 0) {
    return (
      <div
        className={cn(
          "text-muted-foreground flex h-[450px] items-center justify-center",
          className
        )}
      >
        No data available
      </div>
    )
  }

  const showGridLines = showGrid && variant !== "minimal"
  const effectiveColor = color ?? DEFAULT_COLOR

  return (
    <div ref={containerRef} className={cn("relative w-full", className)}>
      {/* Legend - only show when colorByGroup is enabled. Click a swatch to
          isolate that group's points, click again to restore all. */}
      {colorByGroup && !color && groups.length > 1 && (
        <div className="mb-4 flex flex-wrap items-center justify-center gap-x-6 gap-y-2">
          {groups.map((group) => {
            const isActive = isGroupVisible(group)
            return (
              <button
                key={group}
                type="button"
                aria-pressed={!isActive}
                onClick={() => toggleIsolatedGroup(group)}
                className={cn(
                  "flex cursor-pointer items-center gap-2 transition-opacity hover:opacity-80",
                  !isActive && "opacity-40"
                )}
              >
                <div
                  className="h-3 w-3 rounded-full"
                  style={{ backgroundColor: getGroupColor(group) }}
                />
                <span className="text-muted-foreground text-sm">{group}</span>
              </button>
            )
          })}
        </div>
      )}

      <svg
        viewBox={`0 0 ${width} ${height}`}
        className="h-auto w-full overflow-visible"
      >
        {/* Triangle outline */}
        <polygon
          points={`${vertices.top.x},${vertices.top.y} ${vertices.bottomLeft.x},${vertices.bottomLeft.y} ${vertices.bottomRight.x},${vertices.bottomRight.y}`}
          className="fill-muted/20 stroke-border"
          strokeWidth={1.5}
        />

        {/* Grid lines */}
        {showGridLines &&
          gridLineData.map((line, i) => (
            <line
              key={`grid-${i}`}
              x1={line.x1}
              y1={line.y1}
              x2={line.x2}
              y2={line.y2}
              className="stroke-border"
              strokeWidth={0.5}
              strokeOpacity={0.5}
            />
          ))}

        {/* Filled variant - convex hull */}
        {variant === "filled" && convexHullPath && (
          <path
            d={convexHullPath}
            fill={effectiveColor}
            fillOpacity={0.15}
            stroke={effectiveColor}
            strokeWidth={1}
            strokeOpacity={0.3}
          />
        )}

        {/* Axis labels */}
        {showLabels && (
          <>
            <text
              x={vertices.bottomLeft.x - 25}
              y={vertices.bottomLeft.y + 35}
              textAnchor="middle"
              className="fill-foreground text-sm font-medium"
            >
              {labels[0]}
            </text>
            <text
              x={vertices.bottomRight.x + 25}
              y={vertices.bottomRight.y + 35}
              textAnchor="middle"
              className="fill-foreground text-sm font-medium"
            >
              {labels[1]}
            </text>
            <text
              x={vertices.top.x}
              y={vertices.top.y - 15}
              textAnchor="middle"
              className="fill-foreground text-sm font-medium"
            >
              {labels[2]}
            </text>
          </>
        )}

        {/* Tick labels */}
        {showGridLines &&
          showTickValues &&
          tickLabels.map((tick, i) => (
            <text
              key={`tick-${i}`}
              x={tick.x}
              y={tick.y}
              textAnchor={tick.anchor as "start" | "middle" | "end"}
              dominantBaseline="middle"
              className="fill-muted-foreground text-[10px]"
            >
              {tick.value}
            </text>
          ))}

        {/* Data points */}
        {visibleData.map((d) => {
          const pos = ternaryToCartesian(d.a, d.b, d.c)
          const pointColor = d.color ?? getGroupColor(d.group)
          const isHovered = hoveredPoint === d.id
          const radius = d.size ?? pointRadius

          return (
            <circle
              key={d.id}
              cx={pos.x}
              cy={pos.y}
              r={isHovered ? radius * 1.3 : radius}
              fill={pointColor}
              fillOpacity={hoveredPoint ? (isHovered ? 1 : 0.3) : 0.85}
              stroke="#fff"
              strokeWidth={1.5}
              className="cursor-pointer transition-all duration-150"
              onMouseMove={(e) => handleMouseMove(e, d.id)}
              onMouseLeave={() => setHoveredPoint(null)}
            />
          )
        })}
      </svg>

      {/* Tooltip */}
      {hoveredPoint && (
        <div
          className="bg-foreground text-background pointer-events-none absolute z-50 -translate-x-1/2 -translate-y-full rounded-lg px-3 py-2 text-xs shadow-lg"
          style={{ left: tooltipPos.x, top: tooltipPos.y - 10 }}
        >
          {(() => {
            const point = data.find((d) => d.id === hoveredPoint)
            if (!point) return null
            const sum = point.a + point.b + point.c
            return (
              <>
                <div className="mb-1 font-semibold">
                  {point.label ?? hoveredPoint}
                </div>
                <div className="space-y-0.5 opacity-90">
                  <div>
                    {labels[0]}: {((point.a / sum) * 100).toFixed(1)}%
                  </div>
                  <div>
                    {labels[1]}: {((point.b / sum) * 100).toFixed(1)}%
                  </div>
                  <div>
                    {labels[2]}: {((point.c / sum) * 100).toFixed(1)}%
                  </div>
                </div>
              </>
            )
          })()}
        </div>
      )}
    </div>
  )
}

"use client"

import * as React from "react"
import { scaleBand, scaleLinear, scalePoint } from "d3-scale"
import { area, curveLinear, curveMonotoneX, line } from "d3-shape"

import { cn } from "@/lib/utils"

import { ChartLegendLayout, useSeriesHighlight } from "../chart-legend"
import {
  ChartZoomResetButton,
  ChartZoomSelectionRect,
  getBandScaleIndexRange,
  useChartZoom,
} from "../chart-zoom"

export interface RangeDataPoint {
  category: string
  low: number
  high: number
  mid?: number
  forecast?: boolean
}

export interface RangeSeries {
  name: string
  data: RangeDataPoint[]
  color?: string
}

export interface RangeChartProps {
  /** Single series data (simple usage) */
  data?: RangeDataPoint[]
  /** Multiple series data (advanced usage) */
  series?: RangeSeries[]
  className?: string
  /** Show the legend */
  showLegend?: boolean
  /** Which side of the plot to place the legend on */
  legendPosition?: "top" | "bottom" | "left" | "right"
  /** Visual style variant: area (shaded), bars (discrete rectangles), horizontal (horizontal bars) */
  variant?: "area" | "bars" | "horizontal"
  /** Use smooth curves or straight lines (only for area variant) */
  curve?: "smooth" | "linear"
  /** Show the mid-line through data points (only for area variant) */
  showMidLine?: boolean
  /** Show grid lines */
  showGrid?: boolean
  /** Show data point markers */
  showMarkers?: boolean
  /** Show error bar caps (I-bar style) for bars/horizontal variants */
  showErrorBars?: boolean
  /** Fill opacity for the range area (0-1) */
  fillOpacity?: number
  /** Default color when using single series */
  color?: string
  /** Array of colors for multiple series */
  colors?: string[]
  /** Label for low values in tooltip */
  lowLabel?: string
  /** Label for high values in tooltip */
  highLabel?: string
  /** Label for mid values in tooltip */
  midLabel?: string
  /** Custom value formatter */
  valueFormatter?: (value: number) => string
}

const DEFAULT_COLORS = [
  "var(--chart-1)",
  "var(--chart-2)",
  "var(--chart-3)",
  "var(--chart-4)",
  "var(--chart-5)",
  "var(--chart-1)",
  "var(--chart-2)",
  "var(--chart-3)",
]

export function RangeChart({
  data,
  series,
  className,
  showLegend = true,
  legendPosition = "right",
  variant = "area",
  curve = "smooth",
  showMidLine = true,
  showGrid = true,
  showMarkers = true,
  showErrorBars = false,
  fillOpacity = 0.25,
  color = "var(--chart-1)",
  colors = DEFAULT_COLORS,
  lowLabel = "Low",
  highLabel = "High",
  midLabel = "Value",
  valueFormatter = (v) => v.toLocaleString(),
}: RangeChartProps) {
  const [hoveredPoint, setHoveredPoint] = React.useState<{
    seriesIndex: number
    pointIndex: number
  } | null>(null)
  const [tooltipPos, setTooltipPos] = React.useState({ x: 0, y: 0 })
  const svgRef = React.useRef<SVGSVGElement>(null)
  const [zoomDomain, setZoomDomain] = React.useState<[number, number] | null>(
    null
  )
  const isZoomed = zoomDomain !== null
  // Legend highlight: click a series to emphasize it (others fade but stay
  // drawn), hover to preview — Plotly-style. `focused` = hover ?? selection.
  const highlight = useSeriesHighlight()

  // Normalize data to series format
  const normalizedSeries: RangeSeries[] = React.useMemo(() => {
    if (series && series.length > 0) {
      return series.map((s, i) => ({
        ...s,
        color: s.color ?? colors[i % colors.length],
      }))
    }
    if (data && data.length > 0) {
      return [{ name: "Series", data, color }]
    }
    return []
  }, [data, series, color, colors])

  // Reset any active zoom if the underlying data set changes.
  React.useEffect(() => {
    setZoomDomain(null)
  }, [data, series])

  // Determine if horizontal orientation
  const isHorizontal = variant === "horizontal"
  const isBarsVariant = variant === "bars" || variant === "horizontal"

  // Calculate dimensions - horizontal variant has dynamic height based on categories
  const categoryCount = React.useMemo(() => {
    const allCategories = new Set<string>()
    normalizedSeries.forEach((s) =>
      s.data.forEach((d) => allCategories.add(d.category))
    )
    return allCategories.size
  }, [normalizedSeries])

  const width = 500
  const height = isHorizontal ? Math.max(250, categoryCount * 50 + 80) : 300
  const margin = isHorizontal
    ? { top: 20, right: 30, bottom: 40, left: 100 }
    : { top: 20, right: 30, bottom: 50, left: 55 }
  const innerWidth = width - margin.left - margin.right
  const innerHeight = height - margin.top - margin.bottom

  // Full, unzoomed category order — establishes the stable index space
  // that drag-to-zoom windows are computed against.
  const fullCategories = React.useMemo(() => {
    const allCategories = new Set<string>()
    normalizedSeries.forEach((s) => {
      s.data.forEach((d) => allCategories.add(d.category))
    })
    // Preserve order from first series
    if (normalizedSeries.length > 0) {
      return normalizedSeries[0].data.map((d) => d.category)
    }
    return Array.from(allCategories)
  }, [normalizedSeries])

  // Categories currently in view — narrowed to the active zoom window.
  const categories = zoomDomain
    ? fullCategories.slice(zoomDomain[0], zoomDomain[1] + 1)
    : fullCategories

  // Apply the active zoom window (if any) by filtering each series' data
  // down to just the categories currently in view. Legend isolate is kept
  // separate — it only affects which series are rendered, not this data.
  const plotSeries = React.useMemo((): RangeSeries[] => {
    if (!zoomDomain) return normalizedSeries
    const selected = new Set(categories)
    return normalizedSeries.map((s) => ({
      ...s,
      data: s.data.filter((d) => selected.has(d.category)),
    }))
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [normalizedSeries, zoomDomain, categories])

  // Value extent calculation
  const valueExtent = React.useMemo(() => {
    const allValues: number[] = []
    plotSeries.forEach((s) => {
      s.data.forEach((d) => {
        allValues.push(d.low, d.high)
        if (d.mid !== undefined) allValues.push(d.mid)
      })
    })
    if (allValues.length === 0) return { min: 0, max: 100 }

    const min = Math.min(...allValues)
    const max = Math.max(...allValues)
    const padding = (max - min) * 0.1 || 10
    return { min: Math.min(0, min - padding), max: max + padding }
  }, [plotSeries])

  // Band scale for bars/horizontal variants
  const bandScale = React.useMemo(() => {
    return scaleBand<string>()
      .domain(categories)
      .range(isHorizontal ? [0, innerHeight] : [0, innerWidth])
      .padding(0.3)
  }, [categories, innerWidth, innerHeight, isHorizontal])

  // Point scale for area variant
  const pointScale = React.useMemo(() => {
    return scalePoint<string>()
      .domain(categories)
      .range([0, innerWidth])
      .padding(0.1)
  }, [categories, innerWidth])

  // Value scale (linear)
  const valueScale = React.useMemo(() => {
    return scaleLinear()
      .domain([valueExtent.min, valueExtent.max])
      .range(isHorizontal ? [0, innerWidth] : [innerHeight, 0])
      .nice()
  }, [valueExtent, innerWidth, innerHeight, isHorizontal])

  const valueTicks = valueScale.ticks(6)
  const curveType = curve === "smooth" ? curveMonotoneX : curveLinear

  // Bar width calculation for multi-series
  const barWidth = React.useMemo(() => {
    if (!isBarsVariant) return 0
    const bandwidth = bandScale.bandwidth()
    return normalizedSeries.length > 1
      ? bandwidth / normalizedSeries.length - 2
      : bandwidth
  }, [bandScale, normalizedSeries.length, isBarsVariant])

  // Helper to get category position
  const getCategoryPos = (category: string): number => {
    if (isBarsVariant) {
      return bandScale(category) ?? 0
    }
    return pointScale(category) ?? 0
  }

  // Get bandwidth (0 for point scale)
  const getBandwidth = (): number => {
    return isBarsVariant ? bandScale.bandwidth() : 0
  }

  // Generate paths for each series (only for area variant)
  const seriesPaths = React.useMemo(() => {
    if (isBarsVariant) return []

    return plotSeries.map((s) => {
      // Split data into regular and forecast sections
      const regularData = s.data.filter((d) => !d.forecast)
      const forecastData = s.data.filter((d) => d.forecast)

      // Find the last regular point and first forecast point for connection
      const lastRegular =
        regularData.length > 0 ? regularData[regularData.length - 1] : null
      const firstForecast = forecastData.length > 0 ? forecastData[0] : null

      // Include connection point in forecast if there's data before it
      const forecastWithConnection =
        lastRegular && firstForecast
          ? [lastRegular, ...forecastData]
          : forecastData

      // Area generator for range band
      const areaGenerator = area<RangeDataPoint>()
        .x((d) => pointScale(d.category) ?? 0)
        .y0((d) => valueScale(d.low))
        .y1((d) => valueScale(d.high))
        .curve(curveType)

      // Line generator for mid-line
      const lineGenerator = line<RangeDataPoint>()
        .x((d) => pointScale(d.category) ?? 0)
        .y((d) => valueScale(d.mid ?? (d.low + d.high) / 2))
        .curve(curveType)

      return {
        regularArea:
          regularData.length > 0 ? (areaGenerator(regularData) ?? "") : "",
        forecastArea:
          forecastWithConnection.length > 1
            ? (areaGenerator(forecastWithConnection) ?? "")
            : "",
        regularLine:
          regularData.length > 0 ? (lineGenerator(regularData) ?? "") : "",
        forecastLine:
          forecastWithConnection.length > 1
            ? (lineGenerator(forecastWithConnection) ?? "")
            : "",
      }
    })
  }, [plotSeries, pointScale, valueScale, curveType, isBarsVariant])

  // A band scale over the categories currently in view — used purely to
  // translate a pixel drag range into a data-index window. Mirrors the
  // padding of whichever scale (`bandScale` or `pointScale`) is actually
  // driving the rendered layout for the current variant.
  const zoomIndexScale = React.useMemo(() => {
    return scaleBand<string>()
      .domain(categories)
      .range([0, innerWidth])
      .padding(isBarsVariant ? 0.3 : 0.1)
  }, [categories, innerWidth, isBarsVariant])

  // Drag-to-zoom: converts the pixel drag range into a data-index range
  // and narrows the view to it. Disabled for the horizontal variant since
  // its categorical axis runs vertically — a horizontal drag there
  // wouldn't correspond to a category window.
  const zoom = useChartZoom({
    svgRef,
    marginLeft: margin.left,
    innerWidth,
    disabled: isHorizontal,
    onZoom: ({ x0, x1 }) => {
      const [start, end] = getBandScaleIndexRange(zoomIndexScale, x0, x1)
      const currentOffset = zoomDomain ? zoomDomain[0] : 0
      setZoomDomain([currentOffset + start, currentOffset + end])
    },
    onReset: () => setZoomDomain(null),
  })

  const handleMouseMove = (e: React.MouseEvent<SVGSVGElement>) => {
    if (!svgRef.current) return
    const rect = svgRef.current.getBoundingClientRect()
    const scaleX = width / rect.width
    const scaleY = height / rect.height
    const x = (e.clientX - rect.left) * scaleX - margin.left
    const y = (e.clientY - rect.top) * scaleY - margin.top

    // Find closest point
    let closestSeriesIndex = -1
    let closestPointIndex = -1
    let closestDist = Infinity

    normalizedSeries.forEach((s, si) => {
      plotSeries[si].data.forEach((d, pi) => {
        let px: number, py: number
        const catPos = getCategoryPos(d.category)
        const bandwidth = getBandwidth()

        if (isHorizontal) {
          px = valueScale(d.mid ?? (d.low + d.high) / 2)
          py =
            catPos +
            bandwidth / 2 +
            (normalizedSeries.length > 1 ? si * (barWidth + 2) : 0)
        } else if (isBarsVariant) {
          px =
            catPos +
            bandwidth / 2 +
            (normalizedSeries.length > 1 ? si * (barWidth + 2) : 0)
          py = valueScale(d.mid ?? (d.low + d.high) / 2)
        } else {
          px = catPos
          py = valueScale(d.mid ?? (d.low + d.high) / 2)
        }

        const dist = Math.sqrt((x - px) ** 2 + (y - py) ** 2)
        if (dist < closestDist && dist < 50) {
          closestDist = dist
          closestSeriesIndex = si
          closestPointIndex = pi
        }
      })
    })

    if (closestSeriesIndex >= 0 && closestPointIndex >= 0) {
      const s = plotSeries[closestSeriesIndex]
      const d = s.data[closestPointIndex]
      let tooltipX: number, tooltipY: number
      const catPos = getCategoryPos(d.category)
      const bandwidth = getBandwidth()

      if (isHorizontal) {
        tooltipX = valueScale(d.high) + margin.left
        tooltipY = catPos + bandwidth / 2 + margin.top
      } else if (isBarsVariant) {
        tooltipX = catPos + bandwidth / 2 + margin.left
        tooltipY = valueScale(d.high) + margin.top
      } else {
        tooltipX = catPos + margin.left
        tooltipY = valueScale(d.mid ?? (d.low + d.high) / 2) + margin.top
      }

      setTooltipPos({ x: tooltipX, y: tooltipY })
      setHoveredPoint({
        seriesIndex: closestSeriesIndex,
        pointIndex: closestPointIndex,
      })
    } else {
      setHoveredPoint(null)
    }
  }

  const handleMouseLeave = () => {
    setHoveredPoint(null)
  }

  const handleSvgMouseMove = (e: React.MouseEvent<SVGSVGElement>) => {
    handleMouseMove(e)
    zoom.handlers.onMouseMove(e)
  }

  const handleSvgMouseLeave = (e: React.MouseEvent<SVGSVGElement>) => {
    handleMouseLeave()
    zoom.handlers.onMouseLeave(e)
  }

  // Error bar cap size
  const errorBarCapSize = 6

  if (normalizedSeries.length === 0) {
    return (
      <div
        className={cn(
          "text-muted-foreground flex h-[300px] items-center justify-center",
          className
        )}
      >
        No data available
      </div>
    )
  }

  // Legend — click a series to highlight it (others fade), click again to
  // restore; hover previews. Positioned on `legendPosition` via layout below.
  const isVerticalLegend =
    legendPosition === "left" || legendPosition === "right"
  const legend = (
    <div
      className={cn(
        "flex gap-x-6 gap-y-2",
        isVerticalLegend
          ? "flex-col items-start"
          : "flex-wrap items-center justify-center",
        legendPosition === "top" && "pb-4",
        legendPosition === "bottom" && "pt-4",
        legendPosition === "left" && "pr-4",
        legendPosition === "right" && "pl-4"
      )}
    >
      {normalizedSeries.map((s) => {
        const isActive = highlight.isActive(s.name)
        return (
          <button
            key={s.name}
            type="button"
            aria-pressed={!isActive}
            onClick={() => highlight.toggle(s.name)}
            onMouseEnter={() => highlight.setHovered(s.name)}
            onMouseLeave={() => highlight.setHovered(null)}
            className={cn(
              "flex items-center gap-2 text-sm transition-opacity",
              normalizedSeries.length > 1 && "cursor-pointer hover:opacity-80",
              !isActive && "opacity-40"
            )}
          >
            <div
              className="h-3 w-3 shrink-0 rounded-full"
              style={{ backgroundColor: s.color }}
            />
            <span className="text-muted-foreground">{s.name}</span>
          </button>
        )
      })}
    </div>
  )

  return (
    <div className={cn("relative w-full", className)}>
      {/* Plot + legend layout — legend sits on `legendPosition` side, click a
          series to highlight it (others fade), click again to restore */}
      <ChartLegendLayout
        position={legendPosition}
        show={showLegend && normalizedSeries.length > 1}
        legend={legend}
      >
        <svg
          ref={svgRef}
          viewBox={`0 0 ${width} ${height}`}
          className="h-auto w-full overflow-visible select-none"
          onMouseMove={handleSvgMouseMove}
          onMouseLeave={handleSvgMouseLeave}
          onMouseDown={zoom.handlers.onMouseDown}
          onMouseUp={zoom.handlers.onMouseUp}
          onDoubleClick={zoom.handlers.onDoubleClick}
        >
          <defs>
            {/* Gradient definitions for each series */}
            {normalizedSeries.map((s, i) => (
              <linearGradient
                key={`gradient-${i}`}
                id={`range-gradient-${i}`}
                x1="0"
                y1="0"
                x2="0"
                y2="1"
              >
                <stop
                  offset="0%"
                  stopColor={s.color}
                  stopOpacity={fillOpacity * 1.5}
                />
                <stop
                  offset="100%"
                  stopColor={s.color}
                  stopOpacity={fillOpacity * 0.5}
                />
              </linearGradient>
            ))}
          </defs>

          <g transform={`translate(${margin.left}, ${margin.top})`}>
            {/* Drag-to-zoom selection rectangle */}
            <ChartZoomSelectionRect
              range={zoom.dragRange}
              height={innerHeight}
            />

            {/* Grid lines */}
            {showGrid && isHorizontal
              ? valueTicks.map((tick) => (
                  <line
                    key={tick}
                    x1={valueScale(tick)}
                    x2={valueScale(tick)}
                    y1={0}
                    y2={innerHeight}
                    stroke="#e5e7eb"
                    strokeWidth={1}
                    className="dark:stroke-zinc-700"
                  />
                ))
              : showGrid &&
                valueTicks.map((tick) => (
                  <line
                    key={tick}
                    x1={0}
                    x2={innerWidth}
                    y1={valueScale(tick)}
                    y2={valueScale(tick)}
                    stroke="#e5e7eb"
                    strokeWidth={1}
                    className="dark:stroke-zinc-700"
                  />
                ))}

            {/* Axis lines */}
            {isHorizontal ? (
              <line
                x1={0}
                x2={0}
                y1={0}
                y2={innerHeight}
                stroke="#d1d5db"
                strokeWidth={1}
                className="dark:stroke-zinc-600"
              />
            ) : (
              <line
                x1={0}
                x2={innerWidth}
                y1={innerHeight}
                y2={innerHeight}
                stroke="#d1d5db"
                strokeWidth={1}
                className="dark:stroke-zinc-600"
              />
            )}

            {/* Render each series */}
            {normalizedSeries.map((s, seriesIndex) => {
              const paths = seriesPaths[seriesIndex]
              const isSeriesHovered = hoveredPoint?.seriesIndex === seriesIndex
              // Fade — never remove — the non-highlighted series, and keep the
              // existing "hover a point dims the other series" behavior.
              const opacity = highlight.isDimmed(s.name)
                ? 0.3
                : hoveredPoint !== null && !isSeriesHovered
                  ? 0.3
                  : 1
              const bandwidth = getBandwidth()
              const seriesOffset =
                normalizedSeries.length > 1 ? seriesIndex * (barWidth + 2) : 0

              return (
                <g
                  key={s.name}
                  style={{ opacity, transition: "opacity 150ms" }}
                >
                  {/* AREA VARIANT: Render area paths */}
                  {!isBarsVariant && (
                    <>
                      {/* Regular area band */}
                      {paths?.regularArea && (
                        <path
                          d={paths.regularArea}
                          fill={`url(#range-gradient-${seriesIndex})`}
                          stroke="none"
                        />
                      )}

                      {/* Forecast area band (slightly more transparent) */}
                      {paths?.forecastArea && (
                        <path
                          d={paths.forecastArea}
                          fill={s.color}
                          fillOpacity={fillOpacity * 0.5}
                          stroke="none"
                        />
                      )}

                      {/* Regular mid-line */}
                      {showMidLine && paths?.regularLine && (
                        <path
                          d={paths.regularLine}
                          fill="none"
                          stroke={s.color}
                          strokeWidth={2.5}
                          strokeLinecap="round"
                        />
                      )}

                      {/* Forecast mid-line (dashed) */}
                      {showMidLine && paths?.forecastLine && (
                        <path
                          d={paths.forecastLine}
                          fill="none"
                          stroke={s.color}
                          strokeWidth={2}
                          strokeDasharray="6 4"
                          strokeLinecap="round"
                        />
                      )}

                      {/* Data point markers for area */}
                      {showMarkers &&
                        plotSeries[seriesIndex].data.map((d, pointIndex) => {
                          const x = pointScale(d.category) ?? 0
                          const y = valueScale(d.mid ?? (d.low + d.high) / 2)
                          const isPointHovered =
                            hoveredPoint?.seriesIndex === seriesIndex &&
                            hoveredPoint?.pointIndex === pointIndex

                          return (
                            <circle
                              key={d.category}
                              cx={x}
                              cy={y}
                              r={isPointHovered ? 6 : 4}
                              fill={s.color}
                              stroke="white"
                              strokeWidth={2}
                              style={{ transition: "r 100ms" }}
                              className="cursor-pointer"
                            />
                          )
                        })}
                    </>
                  )}

                  {/* BARS/HORIZONTAL VARIANT: Render discrete bars */}
                  {isBarsVariant &&
                    plotSeries[seriesIndex].data.map((d, pointIndex) => {
                      const catPos = getCategoryPos(d.category)
                      const isPointHovered =
                        hoveredPoint?.seriesIndex === seriesIndex &&
                        hoveredPoint?.pointIndex === pointIndex

                      if (isHorizontal) {
                        // Horizontal bars
                        const x = valueScale(d.low)
                        const y = catPos + seriesOffset
                        const barLength = valueScale(d.high) - valueScale(d.low)
                        const midX = valueScale(d.mid ?? (d.low + d.high) / 2)

                        return (
                          <g key={d.category}>
                            {/* Range bar */}
                            <rect
                              x={x}
                              y={y}
                              width={barLength}
                              height={barWidth}
                              fill={s.color}
                              fillOpacity={fillOpacity + 0.2}
                              rx={3}
                              className="cursor-pointer"
                            />

                            {/* Mid marker */}
                            {showMarkers && (
                              <circle
                                cx={midX}
                                cy={y + barWidth / 2}
                                r={isPointHovered ? 5 : 4}
                                fill={s.color}
                                stroke="white"
                                strokeWidth={2}
                              />
                            )}

                            {/* Error bars (I-bar caps) */}
                            {showErrorBars && (
                              <>
                                <line
                                  x1={x}
                                  x2={x}
                                  y1={y + barWidth / 2 - errorBarCapSize}
                                  y2={y + barWidth / 2 + errorBarCapSize}
                                  stroke={s.color}
                                  strokeWidth={2}
                                />
                                <line
                                  x1={x + barLength}
                                  x2={x + barLength}
                                  y1={y + barWidth / 2 - errorBarCapSize}
                                  y2={y + barWidth / 2 + errorBarCapSize}
                                  stroke={s.color}
                                  strokeWidth={2}
                                />
                              </>
                            )}
                          </g>
                        )
                      } else {
                        // Vertical bars
                        const x = catPos + seriesOffset
                        const yHigh = valueScale(d.high)
                        const yLow = valueScale(d.low)
                        const barHeight = yLow - yHigh
                        const midY = valueScale(d.mid ?? (d.low + d.high) / 2)

                        return (
                          <g key={d.category}>
                            {/* Range bar */}
                            <rect
                              x={x}
                              y={yHigh}
                              width={barWidth}
                              height={barHeight}
                              fill={s.color}
                              fillOpacity={fillOpacity + 0.2}
                              rx={3}
                              className="cursor-pointer"
                            />

                            {/* Mid marker */}
                            {showMarkers && (
                              <circle
                                cx={x + barWidth / 2}
                                cy={midY}
                                r={isPointHovered ? 5 : 4}
                                fill={s.color}
                                stroke="white"
                                strokeWidth={2}
                              />
                            )}

                            {/* Error bars (I-bar caps) */}
                            {showErrorBars && (
                              <>
                                <line
                                  x1={x + barWidth / 2 - errorBarCapSize}
                                  x2={x + barWidth / 2 + errorBarCapSize}
                                  y1={yHigh}
                                  y2={yHigh}
                                  stroke={s.color}
                                  strokeWidth={2}
                                />
                                <line
                                  x1={x + barWidth / 2 - errorBarCapSize}
                                  x2={x + barWidth / 2 + errorBarCapSize}
                                  y1={yLow}
                                  y2={yLow}
                                  stroke={s.color}
                                  strokeWidth={2}
                                />
                              </>
                            )}
                          </g>
                        )
                      }
                    })}
                </g>
              )
            })}

            {/* Axis labels */}
            {isHorizontal ? (
              <>
                {/* Y axis category labels (left side for horizontal) */}
                {categories.map((cat) => {
                  const catPos = getCategoryPos(cat)
                  const bandwidth = getBandwidth()
                  return (
                    <text
                      key={cat}
                      x={-12}
                      y={catPos + bandwidth / 2}
                      textAnchor="end"
                      dominantBaseline="middle"
                      fontSize={12}
                      className="fill-foreground"
                    >
                      {cat}
                    </text>
                  )
                })}

                {/* X axis value labels (bottom for horizontal) */}
                {valueTicks.map((tick) => (
                  <text
                    key={tick}
                    x={valueScale(tick)}
                    y={innerHeight + 25}
                    textAnchor="middle"
                    fontSize={11}
                    className="fill-muted-foreground"
                  >
                    {valueFormatter(tick)}
                  </text>
                ))}
              </>
            ) : (
              <>
                {/* X axis category labels (bottom for vertical) */}
                {categories.map((cat) => {
                  const catPos = getCategoryPos(cat)
                  const bandwidth = getBandwidth()
                  return (
                    <text
                      key={cat}
                      x={isBarsVariant ? catPos + bandwidth / 2 : catPos}
                      y={innerHeight + 25}
                      textAnchor="middle"
                      fontSize={12}
                      className="fill-foreground"
                    >
                      {cat}
                    </text>
                  )
                })}

                {/* Y axis value labels (left for vertical) */}
                {valueTicks.map((tick) => (
                  <text
                    key={tick}
                    x={-12}
                    y={valueScale(tick)}
                    textAnchor="end"
                    dominantBaseline="middle"
                    fontSize={11}
                    className="fill-muted-foreground"
                  >
                    {valueFormatter(tick)}
                  </text>
                ))}
              </>
            )}
          </g>
        </svg>

        {/* Tooltip */}
        {hoveredPoint !== null && (
          <div
            className="bg-foreground text-background pointer-events-none absolute z-50 -translate-x-1/2 -translate-y-full rounded-lg px-3 py-2 text-xs shadow-lg"
            style={{
              left: tooltipPos.x,
              top: tooltipPos.y - 12,
            }}
          >
            {(() => {
              const s = plotSeries[hoveredPoint.seriesIndex]
              const d = s.data[hoveredPoint.pointIndex]
              const mid = d.mid ?? (d.low + d.high) / 2
              return (
                <>
                  <div className="mb-1 flex items-center gap-2 font-semibold">
                    <div
                      className="h-2 w-2 rounded-full"
                      style={{ backgroundColor: s.color }}
                    />
                    {s.name} - {d.category}
                    {d.forecast && (
                      <span className="text-[10px] opacity-70">(Forecast)</span>
                    )}
                  </div>
                  <div className="space-y-0.5 opacity-90">
                    <div>
                      {highLabel}: {valueFormatter(d.high)}
                    </div>
                    <div>
                      {midLabel}: {valueFormatter(mid)}
                    </div>
                    <div>
                      {lowLabel}: {valueFormatter(d.low)}
                    </div>
                  </div>
                </>
              )
            })()}
          </div>
        )}

        <ChartZoomResetButton
          visible={isZoomed}
          onReset={() => setZoomDomain(null)}
        />
      </ChartLegendLayout>
    </div>
  )
}
